window.BASIRA_UNITS=[{"id": "u1", "axis": "الوطن", "axisN": 1, "unitN": 1, "title": "الوحدة الأولى", "theme": "عُمان في القلب والضمير", "pages": "13–30", "lessons": [{"type": "القراءة", "title": "الخطاب السامي للسلطان قابوس – طيّب الله ثراه – في مجلس عمان", "page": 13, "hook": "ما الثروة الحقيقية لأي وطن: النفط، أم المال، أم شيء آخر؟ الخطاب يجيبك بوضوح.", "about": "خطاب ألقاه السلطان قابوس بن سعيد – طيّب الله ثراه – في مجلس عمان في 1/نوفمبر/2002م. يتحدث عن الشورى، وبناء الإنسان العماني، ودور القطاع الخاص، وقيمة العمل، وثوابت السياسة الخارجية، والموقف من الإرهاب.", "idea": "بناء عمان يقوم على الشورى والإنسان العماني المتعلم العامل، وعلى سياسة خارجية تنشد السلام القائم على العدل.", "cards": [{"icon": "🕌", "title": "الاستهلال ومنهج الشورى", "text": "بدأ الخطاب بحمد الله الذي ارتضى الشورى للمؤمنين، والدعاء بمواصلة مسيرة النهضة. واللقاء السنوي بمجلس عمان يؤكد منهج الشورى ويرسّخه في المجتمع، وللنهوض بعمان ركيزتان أساسيتان.", "quote": "إن الفهمَ المشتركَ والفكرَ المستنيرَ هما الركيزتانِ الأساسيتانِ للنُّهوض بعُمانَ وخدمة أهلها على أسسٍ سليمةٍ"}, {"icon": "🎓", "title": "الإنسان أغلى ثروة", "text": "الأمم تُبنى بسواعد أهلها، ورقيّها يكون بالعلم والخبرة والتدريب والتأهيل؛ لأن الثروة الحقيقية للأمة هي مواردها البشرية. لذلك دعت القيادة إلى رعاية هذه الموارد وتذليل الصعوبات أمامها.", "quote": "إن الأمم لا تبنى إلاّ بسواعد أهلها"}, {"icon": "🏢", "title": "دور القطاع الخاص", "text": "استوعب الجهاز الإداري للدولة معظم القوى الوطنية خلال الأعوام الثلاثين الماضية، فصار العبء على القطاع الخاص: أن يأخذ زمام المبادرة، ويرفع نسبة العمالة العمانية، ويحلّ العمانيون فيه محلّ الوافدين."}, {"icon": "🛠️", "title": "العمل عبادة", "text": "على الحكومة وأعضاء مجلس عمان توعية السكان بقيمة العمل وضرورة احترامه. فالعمل الجادّ ليس هواية يمارسها الفرد متى شاء، بل يُؤدّى بإخلاص وإتقان وأمانة.", "quote": "بل العملُ جزءٌ لا يتجزأُ من العبادة"}, {"icon": "🕊️", "title": "ثوابت السياسة الخارجية", "text": "الوقوف إلى جانب الحق والعدل، وتعزيز وشائج الأخوة وروابط الصداقة، والمساهمة في توطيد الأمن والسلام الدوليين. والسلام لا يدوم إلا إذا قام على العدالة والتعاون والتفاهم بين الأمم.", "quote": "إلا إذا كان قائما على قواعدَ راسخةٍ من العدالة، وأسسٍ ثابتةٍ من التعاون والتفاهم بين جميع الأمم"}, {"icon": "🚫", "title": "الإرهاب والختام", "text": "الإرهاب بكل صنوفه، وأيًّا كانت الجهة التي تمارسه، اعتداء على السلام؛ لذا تدينه عمان وتستنكره وتدعو إلى التصدي له ومعالجة أسبابه. وختم بالإشارة إلى القمة الثانية والعشرين لمجلس التعاون في مسقط، وبالدعاء.", "quote": "اللهمَّ زدنا ولا تنقصنا ، وأعطنا ولا تحرمنا"}, {"icon": "🌱", "title": "قيم نتعلمها", "text": "الشورى طريق الحكم الرشيد، والعلم والتدريب سبيل الرقيّ، والعمل الجاد واجب وعبادة، والسلام لا يقوم إلا على العدل، والإرهاب مرفوض أيًّا كان مصدره."}], "vocab": [{"w": "زِمَام", "m": "مقدَّم الشيء الموجِّه له (الجذر: ز م م)"}, {"w": "المِضْمَار", "m": "ميدان السباق (الجذر: ض م ر)"}, {"w": "الحِقْبَة", "m": "الفترة (الجذر: ح ق ب)"}, {"w": "وَشَائِج", "m": "جمع وشيجة، وتعني الرابطة (الجذر: و ش ج)"}, {"w": "الحَيَوِيّ", "m": "الضروري، المهم"}, {"w": "مَعَالِم", "m": "مظاهر"}, {"w": "أَوْزِعْنَا", "m": "ألهِمنا، اجعلنا"}], "tip": "💡 سؤال مشهور: «دفع عجلة التطور إلى الأمام» صورة جمالية؛ صوّر التطور جسمًا ذا عجلات، والقوى البشرية (الإنسان العماني) هي التي تدفعه بسرعة وقوة فيتقدم باستمرار.", "keyPoints": ["الخطاب أُلقي في مجلس عمان في 1/نوفمبر/2002م، واستُهلّ بحمد الله الذي ارتضى الشورى للمؤمنين.", "الركيزتان الأساسيتان للنهوض بعمان: الفهم المشترك والفكر المستنير.", "الثروة الحقيقية لأية أمة مواردها البشرية، والقطاع الخاص مدعوّ إلى رفع نسبة العمالة العمانية.", "العمل جزء لا يتجزأ من العبادة، يؤدى بإخلاص وإتقان وأمانة.", "السلام لا يُحفظ إلا على قواعد من العدالة والتعاون والتفاهم، والإرهاب اعتداء على السلام تدينه عمان."], "check": [{"q": "ما الركيزتان الأساسيتان للنهوض بعمان كما حدّدهما الخطاب؟", "opts": ["العلم والخبرة", "الفهم المشترك والفكر المستنير", "الحق والعدل"], "a": 1, "explain": "ورد في الخطاب نصًّا: «إن الفهم المشترك والفكر المستنير هما الركيزتان الأساسيتان». أما العلم والخبرة فطريق رقيّ الأمم، والحق والعدل من ثوابت السياسة الخارجية."}, {"q": "(إذا كان قائمًا على قواعد راسخة) مضادّ كلمة (راسخة):", "opts": ["ثابتة", "قوية", "متزعزعة"], "a": 2, "explain": "الراسخ: الثابت المتمكن، و(ثابتة) و(قوية) قريبتان منه في المعنى؛ فالمضادّ هو (متزعزعة)."}]}, {"type": "الأنشطة النحوية", "title": "مراجعة عامة", "page": 19, "hook": "قبل أن نبني قواعد جديدة، لنتأكد أن الأساس متين: سبع معلومات درستِها من قبل، هل ما زالت حاضرة؟", "about": "درس يسترجع أهم القواعد السابقة: أقسام الكلمة، ونوعي الجملة، وأقسام الفعل، والمعارف، والإعراب والبناء. ويطبّقها على أبيات لبدر شاكر السياب وأحمد شوقي، وآيات كريمة، ونص من رواية «البؤساء» لفيكتور هيجو.", "idea": "مراجعة أسس النحو التي يُبنى عليها كل ما يأتي في هذا العام.", "cards": [{"icon": "🧩", "title": "أقسام الكلمة", "text": "الكلمة العربية ثلاثة أقسام: اسم، وفعل، وحرف. في شطر السياب ست كلمات: قد (حرف)، انتصف (فعل)، الليل (اسم)، الفاء (حرف)، اطو (فعل)، الكتاب (اسم).", "quote": "قد انتصف الليل فاطو الكتاب"}, {"icon": "🧱", "title": "نوعا الجملة", "text": "الجملة الاسمية ركناها المبتدأ والخبر، والفعلية ركناها الفعل والفاعل. في «فعيناك لا تقرءان السطور»: المبتدأ (عيناك) والخبر (لا تقرءان السطور). وفي «قد انتصف الليل»: الفعل (انتصف) والفاعل (الليل).", "quote": "فعيناك لا تقرءان السطور"}, {"icon": "🔎", "title": "انتبهي للحرف المتصدّر", "text": "نوع الجملة يُعرف بركنيها لا بما يتصدّرها. «فأنت ترى مقلتيها هناك» اسمية: المبتدأ (أنت) والخبر (ترى مقلتيها هناك). و«وترنو إلى الأنجم النائية» فعلية: الفعل (ترنو) والفاعل ضمير مستتر وجوبًا تقديره (أنت).", "quote": "فأنت ترى مقلتيها هناك"}, {"icon": "⏳", "title": "أقسام الفعل زمنًا", "text": "الفعل ماضٍ ومضارع وأمر. في أبيات شوقي: (أقدِمْ، اصنعْ، قلْ) أمر مبني على السكون، و(كان) ماضٍ مبني على الفتح، و(يقعُ، يخلفُ) مضارع مرفوع بالضمة، و(يكنْ) مضارع مجزوم بالسكون.", "quote": "أَقْدِمْ فليس على الإقدامِ مُمْتَنِعُ ... واصنعْ به المجدَ فهو البارعُ الصَّنَعُ"}, {"icon": "🔑", "title": "المعارف الستة", "text": "الاسم معرفة أو نكرة، والمعارف ستة: الضمير، والعلَم، واسم الإشارة، والاسم الموصول، والمعرّف بأل، والمضاف إلى معرفة. من نص «البؤساء»: كوزيت (علَم)، هذه (إشارة)، الذي (موصول)، الرسالة (بأل)، زوجته (مضاف إلى معرفة)، هو (ضمير).", "quote": "كان المال هو الذي يطلبانه"}, {"icon": "⚖️", "title": "الإعراب والبناء", "text": "الإعراب: تغيّر آخر الكلمة بتغيّر موقعها في الجملة، والبناء: لزوم آخرها حالة واحدة. علامات الإعراب الأصلية: الضمة والفتحة والكسرة والسكون، ولها علامات فرعية تنوب عنها."}, {"icon": "🎯", "title": "منصوبات من القرآن", "text": "في الآيات الست أسماء منصوبة لأسباب مختلفة: مفعول مطلق، ومفعول لأجله، ومفعول به، ومفعول فيه، وحال، وخبر كان، وصفة؛ وعلامة نصبها كلها الفتحة الظاهرة.", "quote": "﴿وَلَا تَقْتُلُوٓا۟ أَوْلَـٰدَكُمْ خَشْيَةَ إِمْلَـٰقٍ﴾"}], "table": {"title": "أمثلة الدرس وإعرابها", "head": ["المثال", "الحكم/الإعراب", "السبب"], "rows": [["أقْدِمْ / اصنعْ / قلْ", "فعل أمر مبني على السكون", "الأمر مبني دائمًا"], ["كان", "فعل ماضٍ مبني على الفتح", "الماضي مبني"], ["يقعُ / يخلفُ", "فعل مضارع مرفوع بالضمة", "لم يسبقه ناصب ولا جازم"], ["لم يكنْ", "فعل مضارع مجزوم بالسكون", "سبقته (لم) الجازمة"], ["فتحًا ﴿فتحنا لك فتحًا مبينًا﴾", "مفعول مطلق منصوب", "مصدر من لفظ الفعل (فتحنا)"], ["خشيةَ ﴿خشيةَ إملاقٍ﴾", "مفعول لأجله منصوب", "يبيّن سبب الفعل"], ["أصابعَ ﴿يجعلون أصابعهم﴾", "مفعول به منصوب", "وقع عليه فعل الفاعل"], ["اليومَ ﴿اليوم أكملت لكم دينكم﴾", "مفعول فيه (ظرف زمان) منصوب", "يبيّن زمن الفعل"], ["ملومًا ﴿فتقعد ملومًا محسورًا﴾", "حال منصوبة", "تبيّن هيئة صاحبها"], ["كثيبًا / مهيلًا ﴿وكانت الجبال كثيبًا مهيلًا﴾", "كثيبًا: خبر كان، مهيلًا: صفة", "خبر كان منصوب، والصفة تتبع موصوفها"]]}, "tip": "💡 لا تنخدعي بـ(قد) أو (الفاء) أول الجملة! ابحثي عن الركنين: مبتدأ وخبر = اسمية، فعل وفاعل = فعلية.", "keyPoints": ["أقسام الكلمة: اسم، فعل، حرف.", "الجملة الاسمية: مبتدأ وخبر، والفعلية: فعل وفاعل، ونوعها يُعرف بركنيها لا بما يتصدّرها.", "الأمر والماضي مبنيان، والمضارع يُرفع ويُنصب ويُجزم.", "المعارف ستة: الضمير، العلم، اسم الإشارة، الاسم الموصول، المعرّف بأل، المضاف إلى معرفة.", "علامات الإعراب الأصلية: الضمة للرفع، والفتحة للنصب، والكسرة للجر، والسكون للجزم."], "check": [{"q": "جملة «فأنت ترى مقلتيها هناك» نوعها:", "opts": ["اسمية", "فعلية", "فعلية لأنها بدأت بالفاء"], "a": 0, "explain": "الفاء حرف لا يحدد النوع. الركنان: (أنت) مبتدأ، و(ترى مقلتيها هناك) خبر؛ إذن هي اسمية."}, {"q": "(خشيةَ) في ﴿وَلَا تَقْتُلُوٓا۟ أَوْلَـٰدَكُمْ خَشْيَةَ إِمْلَـٰقٍ﴾ تُعرب:", "opts": ["مفعولًا مطلقًا", "مفعولًا لأجله", "حالًا"], "a": 1, "explain": "نسأل: لماذا نُهوا عن قتل الأولاد؟ خشيةَ الإملاق؛ فهي تبيّن السبب، أي مفعول لأجله منصوب بالفتحة."}]}, {"type": "النصوص الأدبية", "title": "في الحنين إلى عمان", "page": 23, "hook": "شاعر بعيد في زنجبار، يلمع البرق فوقه... فيشتعل قلبه شوقًا إلى عمان.", "about": "الأبيات مطلع قصيدة أبي مسلم البهلاني الرواحي المعروفة بالنونية، واسمها «الفتح والرضوان في السيف والإيمان»، أرسلها من زنجبار إلى أهل عمان يستنهضهم ويحثهم على الاتحاد ونبذ الفرقة. والمطلع من المقدمات الطللية التي اعتاد الشعراء قديمًا ابتداء قصائدهم بها.", "author": {"name": "أبو مسلم البهلاني الرواحي (1273هـ – 1339هـ)", "bio": "ناصر بن سالم بن عديم الرواحي، من أشهر شعراء عمان في العصر الحديث، وأحد رواد الصحافة العمانية المهاجرة؛ أصدر صحيفة (النجاح) في زنجبار. ولد في قرية محرم بولاية سمائل، وانتقل إلى زنجبار عام 1295هـ، ومن آثاره (نثار الجوهر) في الفقه وديوان شعر."}, "idea": "حنين الشاعر المغترب إلى وطنه عمان، يهيّجه لمعان البرق وهطول المطر.", "cards": [{"icon": "⚡", "title": "البرق جيشٌ في السماء (1–2)", "text": "يبدأ بالبوارق يسوقها حادٍ له رنين، ويخاطب صاحب الحزن: ما لعينك ناعسة؟ ثم يجعل البروق سيوفًا شقّت الأرجاء، تسوق خميسًا (جيشًا) ميدانه الجو، وهو السحاب.", "quote": "تلك البوارقُ حاديهِنَّ مِرنانُ ... فما لِطَرْفِكَ ياذا الشَّجْوِ وَسْنانُ"}, {"icon": "🌧️", "title": "مطر يعمّ ربوع الوطن (3–6)", "text": "انفجر المطر غزيرًا حتى تساوت التلال والأرض المنخفضة، وسقى أماكن الوطن وغطّى سهلها ووعرها. ويستعذب الشاعر ترديد أسماء المعاهد: رضوى، وسرّ، وجوف، وجرنان، وعندام، وجعلان.", "quote": "تبجَّسَتْ بِهَزِيمِ الوَدْقِ مُنْبَثِقًا ... حتى تساوتْ به أُكْمٌ وقيعانُ"}, {"icon": "💧", "title": "دموع لا تُسكب في الغربة (7–10)", "text": "هيّج البرق حزنه فسهرت عينه واشتعلت نيران شجوه، وصار جفنه سحابًا يمطر دموعًا. لكنه يبخل بدمعه أن يسيل على أرض ليست وطنه، ويطلب من البرق أن يحمل رمقه إلى معاهده.", "quote": "إني أشِحُّ بدمعي أن يسِحَّ على ... أرضٍ وما هي لي يا برقُ أوطانُ"}, {"icon": "❤️", "title": "الوطن ساكن في الضمير (11–15)", "text": "المعاهد لم تنتقل من قلبه؛ ابتعد بجسده لا بروحه، وحبّ الوطن ميثاق وإيمان. ويعزو بُعده عن وطنه إلى القضاء والقدر الذي لا يغلبه إنسان.", "quote": "لها على القلبِ ميثاقٌ يَبُوءُ به ... إنْ باءَ بالحبِّ في الأوطانِ إيمانُ"}, {"icon": "🧭", "title": "التسليم بالقدر", "text": "يختم الشاعر بتفسير غربته: لم يتركها باختياره، بل بحكم لا يستطيع مغالبته.", "quote": "نزحتُ عنها بحكمٍ لا أُغالبُه ... لا يَغْلِبُ القدرَ المحتومَ إنسانُ"}, {"icon": "😢", "title": "العاطفة", "text": "عاطفة عارمة من الشوق والحنين إلى الوطن الذي أبعدته الأقدار عنه. والبرق يبهجه ويحمل أشواقه، وفي الوقت نفسه يثير أحزانه ويبعثه على البكاء الشديد."}, {"icon": "🎨", "title": "الصور والأسلوب والموسيقا", "text": "نسج صورة البرق من تشبيهات واستعارات، وفي البيت الخامس طباق (السهل / الأوعار). بدأ باسم الإشارة (تلك البوارق) ففخّم الموقف، وراوح بين الخبر والإنشاء، والقصيدة من البحر البسيط ورويّها النون."}], "vocab": [{"w": "الحادي", "m": "اسم فاعل من حدا الإبل يحدوها أي ساقها بالغناء (ح د و)"}, {"w": "المِرنان", "m": "الصوت الذي له رنين، وسحابة مرنان أي مُصوِّتة (ر ن ن)"}, {"w": "تَبَجَّسَتْ", "m": "انفجرت (ب ج س)"}, {"w": "الوَدْق", "m": "المطر (و د ق)"}, {"w": "أُكْم", "m": "جمع أكَمة وإكام وآكام، وتعني: التل (أ ك م)"}, {"w": "قيعان", "m": "جمع قاع: أرض مستوية مطمئنة عمّا يحيط بها من الجبال والآكام (ق ي ع)"}, {"w": "الشَّواجِن", "m": "جمع شاجن، وهو الوادي الكثير الشجر أو الطريق في الوادي (ش ج ن)"}, {"w": "الشَّجْو", "m": "الحزن (ش ج و)"}, {"w": "المعاهد", "m": "الأماكن القديمة (ع هـ د)"}, {"w": "بطنان", "m": "البطنان من الشيء: وسطه (ب ط ن)"}, {"w": "باءَ بالشيء", "m": "رجع (ب و ء)"}, {"w": "الأوعار", "m": "جمع وعر: المكان الصعب"}], "tip": "💡 الخميس في اللغة: الجيش، لكن «الجيش» الذي قصده الشاعر في البيت الثاني هو السحب والغيوم التي يسوقها البرق.", "keyPoints": ["الشاعر أبو مسلم البهلاني الرواحي، والقصيدة نونيته «الفتح والرضوان في السيف والإيمان».", "المطلع مقدمة طللية على نهج القدماء، والبرق هو مثير الحنين.", "في البيت الخامس طباق بين (السهل) و(الأوعار).", "بدأ باسم الإشارة (تلك البوارق) للتفخيم، وراوح بين الجمل الخبرية والإنشائية.", "القصيدة من البحر البسيط، ورويّها النون، وعاطفتها الشوق والحنين. المطلوب حفظ الأبيات (7–15)."], "check": [{"q": "«تُزْجي خَميسًا له في الجوِّ ميدانُ» الجيش (الخميس) الذي قصده الشاعر:", "opts": ["فلول البرتغاليين", "السحب والغيوم", "أبناء وطنه"], "a": 1, "explain": "البروق تسوق هذا الخميس، وميدانه الجو؛ والذي يسوقه البرق في الجو هو السحاب."}, {"q": "في البيت الخامس «وجلَّلَ السهلَ والأوعارَ» محسّن بديعي هو:", "opts": ["جناس", "سجع", "طباق"], "a": 2, "explain": "السهل ضد الوعر (المكان الصعب)، والجمع بين الكلمة وضدها طباق، يبيّن أن المطر عمّ كل الأماكن."}]}, {"type": "التعبير", "title": "المذكرات اليومية", "page": 28, "hook": "دفتر صغير يحفظ يومكِ العادي... ليصير غدًا ذكرى غالية.", "about": "درس في التعبير الكتابي الوظيفي يعرّفك فنّ المذكرات اليومية، ويدرّبك على كتابتها خطوة خطوة، ويقدّم نموذجًا من يوميات مي زيادة.", "idea": "المذكرات اليومية سجلّ شخصي لأحداث يومك ومشاعرك، يُكتب بصدق وحرية.", "cards": [{"icon": "📔", "title": "ما المذكرات اليومية؟", "text": "سجلّ يومي للأنشطة الشخصية ومشاعر الكاتب وانطباعه وتأمّله في الحياة. والأصل فيها ألا تكون للنشر."}, {"icon": "📚", "title": "متى تُنشر؟", "text": "قد تُنشر إذا اشتملت على آراء أو وصف أحداث تهمّ الناس، مثل: مذكرات عبدالله الطائي، و«مذكرات أميرة عربية» للسيدة سالمة بنت سعيد بن سلطان، و«يوميات نائب في الأرياف» لتوفيق الحكيم، و«مذكرات طالب بعثة» للويس عوض."}, {"icon": "🔐", "title": "خصائصها", "text": "تحتوي على مقدار كبير من الخصوصية والذاتية، وكتابتها تمنح شعورًا بالراحة، وتثير تساؤلات جديدة حول التجارب التي مررتِ بها، وقد تتخذ شكل القصة."}, {"icon": "✍️", "title": "تدرّبي هكذا", "text": "اكتبي خمسة سطور عن أفضل ما حدث لك في الأسبوع الماضي، وخمسة عن أسوئه. ثم اكتبي عشرين سطرًا عن تجربة مهمة في حياتك، وتذكّري أنك تكتبين لنفسك لا للآخرين، فكوني حرّة."}, {"icon": "🧭", "title": "مهارات الكتابة", "text": "اختاري مناسبة معينة ووضّحي موقفك منها حتى يكون لها مغزى. وراعي: تحديد الغاية من الكتابة، وعناصر المذكرات (الزمان، المكان، الحدث، الشخصيات)، ودقة الانتباه والتركيز، والإلمام بالفكرة أو الموضوع."}, {"icon": "🌸", "title": "نموذج مي زيادة", "text": "تبدأ بتحديد الزمان، وتخاطب دفترها، ثم تصف حدثًا: نهوضها من المرض والتفاف رفيقاتها حولها، وتعبّر عن مشاعرها وتساؤلاتها الداخلية.", "quote": "يا دفتري الصَغير! أهملتُكَ لأني قَضيْتُ هذا الأسبوعَ في السرير."}, {"icon": "📝", "title": "تذكّري", "text": "الورقة خير صديق فاكتبي كلما أمكنك، وأحداث اليوم العادية هي ذكريات الغد الغالية فاحتفظي بما تكتبين، وإذا عجزتِ عن التعبير فقد حان وقت القراءة؛ فهي تزوّدك بمعجم لغوي متنامٍ."}], "table": {"title": "عناصر المذكرات اليومية في نموذج مي زيادة", "head": ["العنصر", "ما يقابله في النموذج"], "rows": [["تحديد الزمان", "يوم الأحد 12 مارس"], ["تحديد المكان", "لم تذكره صراحة؛ قضت الأسبوع في السرير ثم نهضت بين رفيقاتها"], ["وصف الحدث", "شفاؤها من المرض والتفاف رفيقاتها حولها وثناؤهن عليها"], ["الشخصيات ذات العلاقة", "الكاتبة وبعض رفيقاتها"]]}, "tip": "💡 لا تخلطي بين المذكرات والتقرير: المذكرات ذاتية فيها مشاعرك وتأملاتك، والأصل فيها ألا تُنشر.", "keyPoints": ["المذكرات اليومية سجلّ يومي للأنشطة الشخصية ومشاعر الكاتب وانطباعه وتأمله في الحياة.", "الأصل فيها ألا تكون للنشر، وقد تُنشر إذا اشتملت على آراء أو أحداث تهمّ الناس.", "عناصرها: تحديد الزمان، وتحديد المكان، ووصف الحدث، وتحديد الشخصيات ذات العلاقة.", "«مذكرات أميرة عربية» للسيدة سالمة بنت سعيد بن سلطان، و«يوميات نائب في الأرياف» لتوفيق الحكيم."], "check": [{"q": "الأصل في المذكرات اليومية:", "opts": ["أن تُنشر في الصحف", "ألا تكون للنشر", "أن تُقرأ في الإذاعة المدرسية"], "a": 1, "explain": "يقول الكتاب: «والأصل فيها ألا تكون للنشر، ولكنها قد تُنشر إذا اشتملت على آراء أو وصف أحداث قد تهم الناس»."}, {"q": "«مذكرات أميرة عربية» من تأليف:", "opts": ["مي زيادة", "السيدة سالمة بنت سعيد بن سلطان", "لويس عوض"], "a": 1, "explain": "ذكر الكتاب: «مذكرات أميرة عربية للسيدة سالمة بنت سعيد بن سلطان»، أما لويس عوض فصاحب «مذكرات طالب بعثة»."}]}], "activities": [{"kind": "order", "lesson": 1, "title": "رتّبي أفكار الخطاب السامي كما وردت فيه", "items": ["حمد الله الذي ارتضى الشورى والدعاء لمسيرة النهضة", "دلالة اللقاء السنوي على ترسيخ منهج الشورى", "الموارد البشرية ودعوة القطاع الخاص لتشغيل العمانيين", "ثوابت السياسة الخارجية وأسس السلام", "إدانة الإرهاب والدعوة إلى التصدي له", "الترحيب بالقمة الثانية والعشرين لمجلس التعاون والدعاء"]}, {"kind": "mcq", "lesson": 1, "q": "ما الركيزتان الأساسيتان للنهوض بعمان كما حدّدهما الخطاب السامي؟", "opts": ["العلم والخبرة", "الفهم المشترك والفكر المستنير", "التدريب والتأهيل", "الحق والعدل"], "a": 1, "explain": "1) نرجع إلى الفقرة الأولى من الخطاب. 2) ورد فيها نصًّا: «إن الفهم المشترك والفكر المستنير هما الركيزتان الأساسيتان للنهوض بعمان». 3) أما العلم والخبرة والتدريب والتأهيل فهي طرق رقيّ الأمم، والحق والعدل من ثوابت السياسة الخارجية."}, {"kind": "match", "lesson": 3, "title": "صِلي كل كلمة من قصيدة «في الحنين إلى عمان» بمعناها", "pairs": [["الوَدْق", "المطر"], ["تبجّست", "انفجرت"], ["الشَّجْو", "الحزن"], ["المعاهد", "الأماكن القديمة"], ["الخميس", "الجيش"], ["باء بالشيء", "رجع"]]}, {"kind": "classify", "lesson": 2, "title": "صنّفي الأفعال الآتية (من أبيات شوقي والسيّاب) إلى مبنية ومعربة", "groups": ["فعل مبني", "فعل معرب"], "items": [["أقدِمْ", 0], ["اصنعْ", 0], ["قلْ", 0], ["كان", 0], ["انتصفَ", 0], ["يكنْ (بعد لم)", 1], ["يقعُ", 1], ["يخلفُها", 1]]}, {"kind": "fill", "lesson": 2, "q": "في قوله تعالى ﴿وَلَا تَقْتُلُوا أَوْلَادَكُمْ خَشْيَةَ إِمْلَاقٍ﴾ تُعرب كلمة (خشيةَ) ____ منصوبًا بالفتحة الظاهرة.", "opts": ["مفعولًا مطلقًا", "مفعولًا لأجله", "حالًا"], "a": 1, "explain": "1) نسأل: لماذا نُهوا عن قتل الأولاد؟ الجواب: خشيةَ الإملاق. 2) الكلمة مصدر قلبي يبيّن سبب الفعل، فهي مفعول لأجله. 3) وهذا ما يثبته جدول التدريب في الكتاب: خشية = مفعول لأجله، علامة نصبه الفتحة الظاهرة."}, {"kind": "tf", "lesson": 3, "q": "يرى أبو مسلم في البيت التاسع أنه لا بأس أن يسيل دمعه على أي أرض ما دام حزينًا.", "a": false, "explain": "1) البيت: «إني أشِحّ بدمعي أن يسحّ على أرضٍ وما هي لي يا برقُ أوطانُ». 2) (أشِحّ) أي أبخل وأضنّ؛ فهو يأبى أن تسيل دموعه على أرض ليست وطنه. 3) إذن العبارة خاطئة."}, {"kind": "tf", "lesson": 4, "q": "الأصل في المذكرات اليومية ألا تكون للنشر، لكنها قد تُنشر إذا اشتملت على آراء أو أحداث تهمّ الناس.", "a": true, "explain": "1) يعرّف الكتاب المذكرات اليومية بأنها سجل يومي للأنشطة الشخصية ومشاعر الكاتب. 2) ويقول: «والأصل فيها ألا تكون للنشر، ولكنها قد تُنشر إذا اشتملت على آراء أو وصف أحداث قد تهمّ الناس». 3) فالعبارة صحيحة."}, {"kind": "mcq", "lesson": 4, "q": "أيٌّ مما يأتي ليس من عناصر كتابة المذكرات اليومية كما حدّدها الكتاب؟", "opts": ["تحديد الزمان", "وصف الحدث", "ذكر المصادر والمراجع", "تحديد الشخصيات ذات العلاقة"], "a": 2, "explain": "1) العناصر في الكتاب أربعة: تحديد الزمان، وتحديد المكان، ووصف الحدث، وتحديد الشخصيات ذات العلاقة. 2) ذكر المصادر والمراجع من سمات البحوث والتقارير لا المذكرات الشخصية. 3) إذن الإجابة: ذكر المصادر والمراجع."}], "test": [{"q": "بمَ استهلّ السلطان قابوس – طيّب الله ثراه – خطابه السامي في مجلس عمان؟", "opts": ["بالترحيب بقادة مجلس التعاون", "بحمد الله الذي ارتضى الشورى للمؤمنين والصلاة على النبي", "بالحديث عن القطاع الخاص", "بإدانة الإرهاب"], "a": 1, "explain": "1) أول الخطاب بعد البسملة: «الحمد لله الذي ارتضى الشورى للمؤمنين، والصلاة والسلام على أشرف الأنبياء والمرسلين». 2) أما الترحيب بالقمة فجاء في الختام، والقطاع الخاص والإرهاب في وسط الخطاب.", "lesson": 1}, {"q": "(وإن رقيّها في مدارج الحضارة) كلمة (مدارج) جمع، مفرده:", "opts": ["دَرَج", "دارج", "مُدرِّج", "مَدْرَج"], "a": 3, "explain": "1) (مدارج) على وزن (مفاعل)، وهو جمع لما كان على وزن (مَفْعَل). 2) فمفردها (مَدْرَج) أي الطريق والمسلك الذي يُرتقى فيه. 3) أما (دَرَج) و(دارج) و(مُدرِّج) فليست مفرداتها.", "lesson": 1}, {"q": "(إذا كان قائمًا على قواعد راسخة) مضادّ كلمة (راسخة) في المعنى:", "opts": ["ثابتة", "متزعزعة", "قوية", "واثقة"], "a": 1, "explain": "1) الراسخ هو الثابت المتمكّن. 2) ضدّ الثبات التزعزع والاضطراب. 3) (ثابتة) و(قوية) مرادفتان تقريبًا، و(واثقة) بعيدة عن المعنى؛ فالمضادّ (متزعزعة).", "lesson": 1}, {"q": "في عبارة «مواردها البشرية القادرة على دفع عجلة التطور إلى الأمام» صوّر الخطاب التطوّر بـ:", "opts": ["جسم ذي عجلات تدفعه القوى البشرية", "بناء شامخ يرفعه العلم", "نهر يجري بلا توقف", "شجرة مثمرة"], "a": 0, "explain": "1) كلمة (عجلة) جعلت للتطور عجلات، فهو كالعربة. 2) والذي يدفعها هو الموارد البشرية، أي الإنسان العماني. 3) فالصورة: تشبيه التطور بجسم ذي عجلات تدفعه القوى البشرية فيتقدّم باستمرار، كما في دليل المعلم.", "lesson": 1}, {"q": "ما نوع الجملة «فأنتَ ترى مقلتيها هناك»؟", "opts": ["فعلية فعلها ترى", "اسمية، المبتدأ أنت والخبر جملة ترى مقلتيها", "فعلية لأنها بدأت بالفاء", "شبه جملة"], "a": 1, "explain": "1) لا نحكم على الجملة بالحرف الذي يتصدّرها (الفاء). 2) نبحث عن ركنيها: (أنت) ضمير منفصل مبتدأ، وجملة (ترى مقلتيها هناك) في محل رفع خبر. 3) إذن هي جملة اسمية.", "lesson": 2}, {"q": "«ما لم يكنْ لامرئٍ في خاطرٍ يقعُ» الفعل (يكنْ):", "opts": ["فعل مضارع مجزوم وعلامة جزمه السكون", "فعل أمر مبني على السكون", "فعل مضارع مرفوع بالضمة", "فعل ماضٍ مبني على الفتح"], "a": 0, "explain": "1) (يكن) يبدأ بحرف مضارعة (الياء) فهو مضارع. 2) سبقه حرف الجزم (لم). 3) فهو مضارع معرب مجزوم وعلامة جزمه السكون.", "lesson": 2}, {"q": "في قوله تعالى ﴿فَتَقْعُدَ مَلُومًا مَّحْسُورًا﴾ تُعرب (ملومًا):", "opts": ["خبر كان", "مفعولًا به", "مفعولًا مطلقًا", "حالًا منصوبة"], "a": 3, "explain": "1) (تقعد) فعل تام لازم لا ينصب مفعولًا به. 2) (ملومًا) اسم مفعول نكرة يبيّن هيئة الفاعل حين القعود. 3) فهي حال منصوبة وعلامة نصبها الفتحة الظاهرة، كما في جدول التدريب.", "lesson": 2}, {"q": "في نص «البؤساء» كلمة (زوجته) من المعارف، ونوعها:", "opts": ["علَم", "معرّف بأل", "مضاف إلى معرفة", "اسم موصول"], "a": 2, "explain": "1) (زوج) في الأصل نكرة. 2) أضيفت إلى الضمير (الهاء)، والضمير معرفة. 3) فاكتسبت التعريف بالإضافة؛ فهي مضاف إلى معرفة، كما في دليل المعلم.", "lesson": 2}, {"q": "«شقّتْ صوارمُها الأرجاءَ واهتزعتْ … تُزجي خميسًا له في الجوِّ ميدانُ» الخميس الذي قصده الشاعر هو:", "opts": ["فلول البرتغاليين", "أبناء وطنه", "السحب والغيوم", "الهموم والأحزان"], "a": 2, "explain": "1) الخميس في اللغة: الجيش. 2) البوارق في البيت هي التي (تُزجي) أي تسوق هذا الجيش، و(ميدانه الجو). 3) والذي يسوقه البرق في الجو هو السحاب؛ فالخميس: السحب والغيوم.", "lesson": 3}, {"q": "(وجلّل السهلَ والأوعارَ) كلمة (الأوعار) جمع (وعر) وتعني:", "opts": ["المكان الصعب", "المكان المخيف", "المال القليل", "الغضب والشدة"], "a": 0, "explain": "1) الوعر ضد السهل. 2) والمعنى أن المطر غطّى الأماكن السهلة والصعبة جميعًا. 3) وإجابة دليل المعلم: المكان الصعب.", "lesson": 3}, {"q": "ما البحر الذي نُظمت عليه قصيدة «في الحنين إلى عمان»، وما حرف رويّها؟", "opts": ["الطويل، والراء", "البسيط، والنون", "الكامل، والنون", "البسيط، والميم"], "a": 1, "explain": "1) تذكر الإضاءة النقدية أن موسيقا القصيدة الخارجية في «بحرها البسيط وحرف الروي (النون) الذي له رنين خاص». 2) ولهذا تُعرف القصيدة بالنونية.", "lesson": 3}, {"q": "أيّ الكتب الآتية من المذكرات التي ذكرها الكتاب أمثلةً على المذكرات المنشورة؟", "opts": ["البؤساء لفيكتور هيجو", "الشوقيات لأحمد شوقي", "مذكرات أميرة عربية للسيدة سالمة بنت سعيد بن سلطان", "دلائل الإعجاز لعبدالقاهر الجرجاني"], "a": 2, "explain": "1) ذكر الكتاب من المذكرات المنشورة: مذكرات عبدالله الطائي، ومذكرات أميرة عربية للسيدة سالمة بنت سعيد بن سلطان، ويوميات نائب في الأرياف، ومذكرات طالب بعثة. 2) البؤساء رواية، والشوقيات ديوان شعر، ودلائل الإعجاز كتاب في البلاغة.", "lesson": 4}], "game": {"type": "board", "q": [{"q": "أقسام الكلمة العربية:", "opts": ["ماضٍ ومضارع", "اسم وفعل وحرف", "مبتدأ وخبر"], "a": 1}, {"q": "ركنا الجملة الفعلية:", "opts": ["الفعل والمفعول", "المبتدأ والخبر", "الفعل والفاعل"], "a": 2}, {"q": "فعل الأمر دائمًا:", "opts": ["مجزوم", "مبني", "معرب"], "a": 1}, {"q": "عدد أنواع المعارف:", "opts": ["ثلاثة", "ستة", "أربعة"], "a": 1}, {"q": "(الذي) من المعارف، نوعه:", "opts": ["اسم موصول", "اسم إشارة", "ضمير"], "a": 0}, {"q": "علامة الجزم الأصلية:", "opts": ["الكسرة", "السكون", "الفتحة"], "a": 1}, {"q": "﴿إنا فتحنا لك فتحًا﴾: فتحًا", "opts": ["مفعول مطلق", "حال", "مفعول به"], "a": 0}, {"q": "معنى (الوَدْق):", "opts": ["المطر", "الرعد", "البرق"], "a": 0}, {"q": "شاعر «في الحنين إلى عمان»:", "opts": ["أبو مسلم البهلاني", "عبدالله الطائي", "أحمد شوقي"], "a": 0}, {"q": "ركيزتا النهوض: الفهم المشترك و…", "opts": ["المال الوفير", "القطاع الخاص", "الفكر المستنير"], "a": 2}, {"q": "العمل في الخطاب السامي:", "opts": ["جزء من العبادة", "عبء على الدولة", "هواية للفرد"], "a": 0}, {"q": "الأصل في المذكرات اليومية:", "opts": ["أن تُنشر", "أن تُلقى", "ألا تُنشر"], "a": 2}]}}, {"id": "u2", "axis": "الوطن", "axisN": 1, "unitN": 2, "title": "الوحدة الثانية", "theme": "أغنية الخليج وجمال البيان", "pages": "31–48", "lessons": [{"type": "النصوص الأدبية", "title": "أغنية الخليج", "page": 31, "hook": "عاد الشاعر إلى الخليج، فلم يحمل له هدية إلا «رعشتي شوق وقافية»!", "about": "قصيدة لغازي القصيبي يتحدث فيها عن حبه للخليج وفرحته بالعودة إليه، ويأمل أن يبقى الخليج عربي الهوية يفتخر بلغة القرآن. والأبيات من ديوانه «معركة بلا راية».", "author": {"name": "غازي القصيبي (1940)", "bio": "ولد غازي عبد الرحمن القصيبي في الأحساء، ونشأ في البحرين، ويُعدّ من شعراء الخليج البارزين في العصر الحديث. حصل على ليسانس الحقوق من جامعة القاهرة، والماجستير من كاليفورنيا، والدكتوراه من لندن، وتجلّت غربته في شعره."}, "idea": "حب الشاعر للخليج وفرحته بالعودة إليه، وأمله أن يبقى عربيًّا معتزًّا بلغة القرآن.", "cards": [{"icon": "🌙", "title": "عودة ونبش للذكريات (1–4)", "text": "يعود الشاعر على موعد مع القمر، ويخاطب الخليج «ساحر الموج والشطآن والجزر». هديته شوق وشعر حمّله معاناة سفره، ويمرح فوق الرمل ينبشه عن ذكريات صباه ولياليه.", "quote": "أتيتُ أرقُبُ ميعادي مع القمرِ ... يا ساحرَ الموجِ والشطآنِ والجُزُرِ"}, {"icon": "🏖️", "title": "الشاطئ يستيقظ (5–8)", "text": "يوقظ الشاطئ الغافي بقبلة، ويذكّره بشاعره الولهان الذي جاب الدنيا فلم تفتح له الشواطئ إلا مرفأ الضجر، حتى لاح له الخليج فانطلقت أشواقه بجنون الصحراء حين تلقى المطر.", "quote": "ولُحْتَ يا أزرقَ العينَينِ فانطلقت ... أشواقُه بجنونِ البيدِ في المطرِ"}, {"icon": "🐚", "title": "كل شيء يذكّره بالخليج (9–12)", "text": "ما همس المحار، ولا ترنّم ملاح، ولا لاح شراع، ولا احترق بنار الشمس، إلا تذكّر الخليج: صوته الدافئ، وأغاني الغوص، وهواري الصيد، فيبترد بذكراه.", "quote": "خليجُ ما وَشْوَشَ المحَّارُ في أُذُني ... إلا سمعتُك صوتًا دافئَ الخَدَرِ"}, {"icon": "🌊", "title": "مناجاة ودعاء (13–14)", "text": "يناجي الخليج كأنه موجة بيضاء تنقلها أصابع الشوق من قلبه إلى عينه، ويدعو أن يبقى وجهه سالمًا رغم العواصف، لا يعلوه إلا بسمة النصر.", "quote": "أُعيذُ وجْهَكَ أن تغزو ملامحَهُ ... رَغْمَ العواصِفِ إلا بسمةُ الظَّفَرِ"}, {"icon": "🏳️", "title": "«عهدتُه عربيًا» (15–17)", "text": "يكرّر «عهدته» ثلاث مرات: لم يعرف لسانه لكنة غريبة، وفي جبهته كبرياء الصحراء فلا يركع لقدر، ولا ينام ويصحو إلا على لغة القرآن.", "quote": "عهدتُه عربيًا ملءَ جبهته ... كِبْرٌ من البيدِ لم يَرْكَع على قَدَرِ"}, {"icon": "💙", "title": "العاطفة", "text": "حب عميق للخليج وشوق إليه، وفرح بالعودة بعد الغربة، واعتزاز بعروبته ولغة القرآن. وقد امتزجت ذات الشاعر بالوطن حتى صار الحب أبديًّا."}, {"icon": "🎨", "title": "الأسلوب والصور", "text": "ثنائية الذات والوطن. النداء «يا ساحر الموج» ثم حذف حرف النداء «خليجُ» ليلغي المسافة بينه وبين وطنه. القصر بالنفي (ما، لا) والإثبات (إلا)، وتكرار «عهدته»، وطباق (احترقت/ابتردت)، وصور من استعارة وتشبيه من أول القصيدة إلى آخرها."}], "vocab": [{"w": "البِيد", "m": "جمع بيداء بمعنى الصحراء أي الفلاة (ب ي د)"}, {"w": "وَشْوَشَ", "m": "تكلّم كلامًا خفيًّا أو همسًا (و ش و ش)"}, {"w": "الخَدَر", "m": "عراه فتور واسترخاء (خ د ر)"}, {"w": "لُكْنة", "m": "صعب عليه الإفصاح بالعربية لعجمة في لسانه، فهو ألكن وهي لكناء، وجمعها لُكْن (ل ك ن)"}, {"w": "ذَرَعَ الدنيا", "m": "طافها وجاب أقطارها"}, {"w": "أذبنا النجوم بأكؤسنا", "m": "توارت النجوم عنا بظهور الفجر"}], "tip": "💡 «خليجُ» بلا (يا): حذف حرف النداء يدل على القرب، كأن الشاعر لا يريد مسافة بينه وبين وطنه.", "keyPoints": ["الشاعر غازي القصيبي، والأبيات من ديوان «معركة بلا راية».", "تقوم القصيدة على ثنائية: ذات الشاعر (عواطفه ومشاعره) والوطن (عناصره وملامحه).", "أسلوب القصر بالنفي (ما، لا) والإثبات (إلا) يربط كل عنصر من البحر بالخليج.", "في البيت الثاني عشر طباق: احترقتُ / ابتردتُ.", "تكرار «عهدته» في الأبيات الثلاثة الأخيرة يؤكد عروبة الخليج واعتزازه بلغة القرآن."], "check": [{"q": "«من بعدِ أن ذَرَعَ الدنيا» معنى (ذرع الدنيا):", "opts": ["طافها وجاب أقطارها", "مدّ إليها ذراعيه", "عمّر فيها طويلًا"], "a": 0, "explain": "الشاعر يصف غربته الطويلة وتنقّله بين البلاد؛ فذرع الدنيا: طافها وجاب أقطارها، كما في دليل المعلم."}, {"q": "الطباق في البيت الثاني عشر بين:", "opts": ["الشمس / ثانية", "احترقتُ / ابتردتُ", "خلّفتُ / ذِكَري"], "a": 1, "explain": "الاحتراق ضد الابتراد (طلب البرودة)، والجمع بينهما طباق يُبرز أثر ذكرى الخليج في نفسه."}]}, {"type": "الأنشطة النحوية", "title": "الحال: تعريفها، وشروطها", "page": 36, "hook": "كيف رجع موسى عليه السلام إلى قومه؟ جواب «كيف» هذا هو بطل درسنا: الحال.", "about": "يعرّف الدرس الحال، ويبيّن شرطيها: الاشتقاق والتنكير، ثم المواضع التي ترد فيها الحال جامدة، والألفاظ المسموعة التي ترد فيها معرفة، مع نماذج في الإعراب.", "idea": "الحال وصف منصوب يبيّن هيئة صاحبه، والأصل فيها أن تكون مشتقة نكرة.", "cards": [{"icon": "📌", "title": "تعريف الحال", "text": "الحال: وصف منصوب يبيّن هيئة صاحبه. (غضبان، أسفًا) بيّنتا هيئة موسى حين رجع. ومثلها: جالسًا (المتنبي)، منبوذًا (النمّام)، متوقدةً ملتهبةً (الرمال). والكلمة التي تبيّن الحالُ هيئتها تُسمّى: صاحب الحال.", "quote": "﴿فَرَجَعَ مُوسَىٰ إِلَىٰ قَوْمِهِ غَضْبَانَ أَسِفًا﴾"}, {"icon": "✅", "title": "شرطا الحال", "text": "الأصل في الحال: (1) أن تكون اسمًا مشتقًّا: اسم فاعل أو اسم مفعول أو صفة مشبهة... (2) أن تكون نكرة. والمشتق ما أُخذ من غيره، والجامد ما لم يؤخذ من غيره مثل: شجرة، قلم، أسد.", "quote": "يعيش النمّام في مجتمعه منبوذًا"}, {"icon": "🌙", "title": "جامدة: مشبَّه بها", "text": "ترد الحال جامدة إذا وقعت مشبَّهًا به، وتؤوَّل بمشتق: بدت مشبَّهةً بالقمر، وغصن البان، والعنبر، والغزال.", "quote": "بدت قمرا ومالت غصن بان ... وفاحت عنبرا ورنت غزالا"}, {"icon": "🤝", "title": "جامدة: تدل على مفاعلة", "text": "المفاعلة: مشاركة بين طرفين في القيام بالفعل. (فاه إلى فيّ) تؤوَّل: مُشافِهَيْن، و(يدًا بيد): مُقابِضَيْن، و(عينه إلى عيني): مواجِهَيْن، و(غرفته إلى غرفتي): ملاصِقَيْن.", "quote": "ساومت التاجر فاه إلى فيَّ ، ثم سلمته النقود يدا بيد"}, {"icon": "🔢", "title": "جامدة: ترتيب أو موصوفة بمشتق", "text": "تدل على ترتيب: (اثنين اثنين) تؤوَّل: مترتّبين. وتوصف بمشتق: (قرآنًا) وُصفت بـ(عربيًّا)، والعربي اسم منسوب مشتق؛ وفي هذا الموضع لا تؤوَّل الحال الجامدة بالمشتق.", "quote": "﴿إِنَّآ أَنزَلْنَٰهُ قُرْءَٰنًا عَرَبِيًّا لَّعَلَّكُمْ تَعْقِلُونَ﴾"}, {"icon": "🔑", "title": "الحال المعرفة", "text": "لا تجيء الحال معرفة إلا في ألفاظ مسموعة لا يقاس عليها: (وحدي) أي منفردًا، و(طاقتي) أي مطيقًا، و(جهدي) أي جاهدًا، و(ادخلوا الأول فالأول) أي مترتّبين.", "quote": "جلست في الغرفة وحدي ، وسعيت طاقتي في أداء واجباتي"}, {"icon": "✏️", "title": "نموذج في الإعراب", "text": "كئيبًا: حال أولى منصوبة، كاسفًا: حال ثانية، بالُه: فاعل لاسم الفاعل (كاسفًا)، قليلَ: حال ثالثة. وفي «يدخل الطلاب الصف واحدًا واحدًا»: الأولى حال، والثانية توكيد لفظي.", "quote": "إنما الميْتُ من يعيش كئيبا ... كاسفا باله قليل الرجاء"}], "table": {"title": "أمثلة الحال في الدرس", "head": ["المثال", "الحكم/الإعراب", "السبب"], "rows": [["غضبانَ أسِفًا", "حالان مشتقتان نكرتان", "تبيّنان هيئة موسى حين رجع"], ["جالسًا / منبوذًا", "حال مشتقة (اسم فاعل / اسم مفعول)", "تبيّن هيئة المتنبي / النمّام"], ["بدت قمرًا", "حال جامدة تؤوَّل: مشبّهةً بالقمر", "وقعت مشبّهًا به"], ["يدًا بيد", "حال جامدة تؤوَّل: مقابِضَيْن، و(بيد) نعت لها", "دلّت على مفاعلة"], ["اثنين اثنين", "حال جامدة تؤوَّل: مترتّبين", "دلّت على ترتيب"], ["قرآنًا عربيًّا", "حال جامدة لا تؤوَّل", "وُصفت بمشتق"], ["وحدي / طاقتي", "حال معرفة تؤوَّل: منفردًا / مطيقًا", "ألفاظ مسموعة أُضيفت إلى ياء المتكلم"], ["كئيبًا / كاسفًا / قليلَ", "حال أولى وثانية وثالثة", "تعدّدت الحال لصاحب واحد"], ["واحدًا واحدًا", "الأولى حال، والثانية توكيد لفظي", "الحال تدل على ترتيب"]]}, "tip": "💡 لكشف الحال اسألي «كيف؟». وتذكّري: الحال الجامدة تؤوَّل بمشتق في ثلاثة مواضع (التشبيه، المفاعلة، الترتيب)، ولا تؤوَّل إذا وُصفت بمشتق.", "keyPoints": ["الحال: وصف منصوب يبيّن هيئة صاحبه.", "شرطا الحال: أن تكون اسمًا مشتقًّا، وأن تكون نكرة.", "ترد جامدة إذا وقعت مشبّهًا به، أو دلّت على مفاعلة، أو على ترتيب، أو وُصفت بمشتق.", "لا تجيء الحال معرفة إلا في ألفاظ مسموعة لا يقاس عليها: وحدي، طاقتي، جهدي، الأول فالأول.", "قد تتعدد الحال لصاحب واحد: كئيبًا (أولى)، كاسفًا (ثانية)، قليلَ (ثالثة)."], "check": [{"q": "«سلمته النقود يدًا بيدٍ» الحال (يدًا):", "opts": ["مشتقة نكرة", "جامدة تدل على مفاعلة", "جامدة تدل على ترتيب"], "a": 1, "explain": "(يد) اسم جامد، والمعنى مشاركة بين طرفين في التسليم والتسلّم؛ فهي حال جامدة تدل على مفاعلة وتؤوَّل: مقابِضَيْن."}, {"q": "«جلست في الغرفة وحدي» (وحدي) حال جاءت:", "opts": ["معرفة في لفظ مسموع", "نكرة مشتقة", "موصوفة بمشتق"], "a": 0, "explain": "(وحد) أُضيف إلى ياء المتكلم فاكتسب التعريف، وهو من الألفاظ المسموعة التي لا يقاس عليها، ويؤوَّل: منفردًا."}]}, {"type": "البلاغة", "title": "مقدمة في علم البلاغة", "page": 43, "hook": "لماذا احتاج العرب، وهم أهل الفصاحة، إلى علم يعلّمهم البلاغة؟", "about": "يتتبع الدرس نشأة علم البلاغة ودافعها، ويفرّق بين الفصاحة والبلاغة، ويعرض فروع البلاغة الثلاثة، ثم يعرّف علم البديع وقسمي محسّناته.", "idea": "نشأت البلاغة لبيان إعجاز القرآن، ولها ثلاثة علوم: المعاني والبيان والبديع.", "cards": [{"icon": "🏜️", "title": "عرب بالفطرة", "text": "لم يكن العرب في جاهليتهم بحاجة إلى من يعرّفهم القواعد البلاغية؛ فقد كانوا بفطرتهم فصحاء بلغاء، يأتون بالقصائد والخطب عفو الخاطر دون تكلّف."}, {"icon": "📖", "title": "القرآن شرارة البداية", "text": "تحدّى الله العرب بفصاحة القرآن وإعجازه البياني. ثم دخلت أمم كثيرة في الإسلام فاختلط العرب بغيرهم، فضعفت السليقة وشاب اللحن والعجمة الألسنة، فاحتاجوا إلى من يبصّرهم بالإعجاز البياني."}, {"icon": "🧑‍🏫", "title": "رواد العلم", "text": "ألّف أبو عبيدة معمر بن المثنى «مجاز القرآن»، ولعله أول كتاب في هذا العلم. وبلغ العلم نضجه على يد عبدالقاهر الجرجاني (ت 471هـ) واضع حجر أساسه ومؤسسه، في كتابيه: «دلائل الإعجاز» في علم المعاني، و«أسرار البلاغة» في علم البيان."}, {"icon": "🗣️", "title": "الفصاحة", "text": "لغةً: البيان والظهور. واصطلاحًا: الألفاظ البيّنة الظاهرة المتبادرة إلى الفهم، والمأنوسة الاستعمال بين الكتّاب والشعراء لمكان حسنها.", "quote": "﴿وَأَخِي هَٰرُونُ هُوَ أَفْصَحُ مِنِّي لِسَانًا﴾"}, {"icon": "🎯", "title": "البلاغة", "text": "لغةً: الوصول والانتهاء؛ يقال: بلغ فلانٌ مراده إذا وصل إليه. وعلم البلاغة: العلم الذي يبحث في القواعد والأسس التي إذا توافرت في الكلام صار فصيحًا مبينًا معبّرًا عن مراد المتكلم."}, {"icon": "🌳", "title": "ثلاثة فروع", "text": "علم المعاني: مطابقة الكلام لمقتضى حال المخاطب. علم البيان: تقديم المعنى الواحد بصور تعبيرية مختلفة. علم البديع: وجوه تحسين الكلام وتزيينه."}, {"icon": "✨", "title": "علم البديع ومحسّناته", "text": "لغةً: بدع الشيء: أنشأه على غير مثال سابق. واصطلاحًا: يبحث في محسّنات الكلام. والمحسّنات قسمان: معنوية ترجع إلى تحسين المعنى أساسًا (الطباق، المقابلة)، ولفظية ترجع إلى تحسين اللفظ أساسًا (السجع، الجناس، الاقتباس، التضمين).", "quote": "﴿بَدِيعُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ﴾"}], "table": {"title": "علوم البلاغة الثلاثة", "head": ["العلم", "يبحث في", "من موضوعاته"], "rows": [["المعاني", "مطابقة الكلام لمقتضى حال المخاطب وأحوال السامعين", "الخبر والإنشاء، الإيجاز والإطناب والمساواة"], ["البيان", "طرائق تقديم المعنى الواحد بصور تعبيرية مختلفة", "التشبيه، الاستعارة، المجاز، الكناية"], ["البديع", "وجوه تحسين الكلام وتزيينه لفظًا أو معنى", "الطباق، المقابلة، الجناس، التورية"]]}, "tip": "💡 احفظي بالكتابين: «دلائل الإعجاز» ← المعاني، «أسرار البلاغة» ← البيان، وكلاهما لعبدالقاهر الجرجاني.", "keyPoints": ["القرآن الكريم هو الشرارة القادحة لعلوم اللسان، وضعف السليقة وانتشار اللحن دفعا إلى تدوين البلاغة.", "«مجاز القرآن» لأبي عبيدة لعله أول كتاب، والمؤسس عبدالقاهر الجرجاني (ت 471هـ).", "الفصاحة لغةً: البيان والظهور، والبلاغة لغةً: الوصول والانتهاء.", "فروع البلاغة: المعاني، والبيان، والبديع.", "المحسنات المعنوية: الطباق والمقابلة، واللفظية: السجع والجناس والاقتباس والتضمين."], "check": [{"q": "يُعدّ مؤسس علم البلاغة وواضع حجر أساسه:", "opts": ["أبو عبيدة معمر بن المثنى", "عبدالقاهر الجرجاني", "سيد قطب"], "a": 1, "explain": "بلغ علم البلاغة نضجه على يد عبدالقاهر الجرجاني، واضع حجر أساسه ومؤسسه في كتابيه «دلائل الإعجاز» و«أسرار البلاغة». أما أبو عبيدة فلعل كتابه أول ما أُلّف."}, {"q": "أيّ مما يأتي من المحسّنات اللفظية؟", "opts": ["الطباق", "المقابلة", "الجناس"], "a": 2, "explain": "اللفظية: السجع والجناس والاقتباس والتضمين، أما الطباق والمقابلة فمحسّنان معنويان."}]}, {"type": "الاستماع", "title": "من مكارم الأخلاق", "page": 47, "hook": "خليفة يملأ المصباح بنفسه، وقائد عظيم يمشي الخيلاء... أيّهما العظيم حقًّا؟", "about": "درس استماع من ثلاثة نصوص (نصوصها في دليل المعلم): آيات من سورة الفرقان في صفات عباد الرحمن مع شرح سيد قطب في «في ظلال القرآن»، ثم موقفا عمر بن عبد العزيز وابن عباس، ثم خبر المهلب بن أبي صفرة ومروان بن أبي حفصة.", "idea": "العظماء يستمدون عظمتهم من أخلاقهم لا من مناصبهم، ومن أفعالهم لا من أنسابهم.", "cards": [{"icon": "🎧", "title": "آداب الاستماع", "text": "اقرئي أسئلة التقويم أولًا وتأمّليها دون أن تجيبي، ثم استمعي جيدًا إلى النص وأجيبي، واتبعي الخطوات نفسها مع النصين الثاني والثالث."}, {"icon": "🕋", "title": "صفات عباد الرحمن", "text": "يمشون على الأرض هونًا (التواضع)، ويقولون للجاهلين سلامًا (الحلم والصفح)، ويبيتون لربهم سجّدًا وقيامًا (قيام الليل)، ويخافون عذاب جهنم، ويعتدلون في الإنفاق.", "quote": "﴿وَعِبَادُ الرَّحْمَٰنِ الَّذِينَ يَمْشُونَ عَلَى الْأَرْضِ هَوْنًا وَإِذَا خَاطَبَهُمُ الْجَاهِلُونَ قَالُوا سَلَامًا﴾"}, {"icon": "📜", "title": "في ظلال القرآن", "text": "يشرح سيد قطب: مشيتهم سهلة هيّنة بلا تكلّف ولا خيلاء، لا يلتفتون إلى حماقة الحمقى، وليلهم للتقوى ومراقبة الله، وهم نموذج القصد والاعتدال والتوازن.", "quote": "﴿وَالَّذِينَ إِذَا أَنفَقُوا لَمْ يُسْرِفُوا وَلَمْ يَقْتُرُوا وَكَانَ بَيْنَ ذَٰلِكَ قَوَامًا﴾"}, {"icon": "🪔", "title": "عمر بن عبد العزيز: التواضع", "text": "كاد السراج ينطفئ وعنده ضيف، فأبى أن يستخدم ضيفه أو يوقظ غلامه المرهق، وقام فملأ المصباح زيتًا بنفسه.", "quote": "ذهبتُ وأنا عمرُ، ورجعتُ وأنا عمرُ، ما نقص مني شيء"}, {"icon": "🤲", "title": "ابن عباس: الحلم", "text": "غلّظ عليه رجل فسبّه، فقابل الإساءة بالإحسان قائلًا: هل للرجل حاجة فنقضيها له؟ فنكس الرجل رأسه استحياءً وندمًا."}, {"icon": "⚔️", "title": "المهلب: جانب التواضع", "text": "قائد عسكري فذّ حقق انتصارات كبيرة بحنكته ودهائه، لكنه لبس حلّة فاخرة ومشى بها الخيلاء، فلما نُصح ردّ مستكبرًا: «أما تعرفني؟»."}, {"icon": "🪙", "title": "مروان: جانب الاعتدال", "text": "شاعر مبدع من شعراء الدولة العباسية، أغدق عليه الخلفاء العطاء، لكنه كان لا يشتري إلا رأسًا يأكله؛ لأنه يعرف سعره فيأمن خيانة الغلام، ولا يستطيع الغلام أن يأكل منه دون أن يُكشف."}], "table": {"title": "خريطة المفاهيم (من دليل المعلم)", "head": ["صفة عباد الرحمن", "شخصية حققت الصفة", "شخصية جانبت الصفة"], "rows": [["التواضع", "عمر بن عبدالعزيز", "المهلب بن أبي صفرة"], ["الحلم", "ابن عباس", "—"], ["قيام الليل", "—", "—"], ["الخوف من جهنم", "—", "—"], ["الإنفاق باعتدال", "—", "مروان بن أبي حفصة"]]}, "tip": "💡 التفوّق في مجال ما لا يشفع لصاحبه أن يتخلّق بأخلاق غير حميدة: المهلب قائد فذّ، ومروان شاعر مبدع، لكن كلًّا منهما جانب صفة من صفات عباد الرحمن.", "keyPoints": ["صفات عباد الرحمن: التواضع، والحلم والصفح، وإحياء قيام الليل، والخوف من عذاب جهنم، والاعتدال في الإنفاق.", "عمر بن عبد العزيز تحلّى بالتواضع، وابن عباس تحلّى بالحلم.", "المهلب بن أبي صفرة قائد عسكري جانب التواضع، ومروان بن أبي حفصة شاعر عباسي جانب الاعتدال في الإنفاق.", "العظماء يستمدون عظمتهم من أخلاقهم لا من مناصبهم، ومن أفعالهم لا من أنسابهم."], "check": [{"q": "الصفة التي تحلّى بها ابن عباس – رضي الله عنهما – في النص:", "opts": ["الحلم", "الكرم", "قيام الليل"], "a": 0, "explain": "سبّه رجل فقابل الإساءة بالإحسان وعرض قضاء حاجته؛ وهذا هو الحلم، كما في خريطة المفاهيم في دليل المعلم."}, {"q": "مروان بن أبي حفصة كان:", "opts": ["قائدًا عسكريًّا", "خليفة عادلًا", "شاعرًا من شعراء الدولة العباسية"], "a": 2, "explain": "النص يقول: «ومروان شاعر مبدع من شعراء الدولة العباسية»، أما القائد العسكري فهو المهلب، والخليفة العادل عمر بن عبد العزيز."}]}], "activities": [{"kind": "match", "lesson": 1, "title": "صِلي كل كلمة من «أغنية الخليج» بمعناها", "pairs": [["البيد", "الصحراء أي الفلاة"], ["وشوش", "تكلّم كلامًا خفيًّا أو همسًا"], ["الخَدَر", "فتور واسترخاء"], ["لُكنة", "عُجمة في اللسان تصعّب الإفصاح بالعربية"], ["ذرع الدنيا", "طافها وجاب أقطارها"]]}, {"kind": "classify", "lesson": 2, "title": "صنّفي الحال في الجمل الآتية: مشتقة أم جامدة؟", "groups": ["حال مشتقة", "حال جامدة"], "items": [["يُنشد المتنبي قصائده جالسًا", 0], ["يعيش النمّام منبوذًا", 0], ["فقد بان محمودًا أخي حين ودّعا", 0], ["إذا متُّ ظمآنًا فلا نزل القطر", 0], ["كرّ الفارس على أعدائه أسدًا", 1], ["سلّمته النقود يدًا بيد", 1], ["يمشي الجنود ثلاثةً ثلاثةً", 1], ["ساكنت صديقي غرفتَه إلى غرفتي", 1]]}, {"kind": "order", "lesson": 3, "title": "رتّبي مراحل نشأة علم البلاغة كما عرضها الدرس", "items": ["العرب في الجاهلية فصحاء بلغاء بالفطرة", "دخول الأمم في الإسلام وشيوع اللحن والعجمة", "تأليف أبي عبيدة كتاب «مجاز القرآن»", "نضج العلم على يد عبدالقاهر الجرجاني"]}, {"kind": "mcq", "lesson": 2, "q": "في قول المتنبي «بدتْ قمرًا ومالتْ غصنَ بانٍ» جاءت الحال (قمرًا) جامدة لأنها:", "opts": ["دلّت على مفاعلة", "وقعت مشبَّهًا به", "دلّت على ترتيب", "وُصفت بمشتق"], "a": 1, "explain": "1) (قمرًا) اسم جامد لا مشتق. 2) الشاعر شبّه محبوبته بالقمر، فالحال هنا هي المشبَّه به. 3) لذلك تؤوَّل بالمشتق: بدت مشبهةً بالقمر. فالموضع: وقوع الحال مشبهًا به."}, {"kind": "fill", "lesson": 2, "q": "«جلست في الغرفة وحدي» الحال (وحدي) جاءت ____ لأنها من الألفاظ المسموعة، وتؤوَّل بـ(منفردًا).", "opts": ["نكرة مشتقة", "معرفة", "جملة اسمية"], "a": 1, "explain": "1) (وحد) أضيفت إلى ياء المتكلم فاكتسبت التعريف. 2) الأصل في الحال أن تكون نكرة، لكنها جاءت معرفة في ألفاظ مسموعة لا يقاس عليها. 3) وتؤوَّل بنكرة مشتقة: منفردًا."}, {"kind": "tf", "lesson": 3, "q": "الطباق والمقابلة من المحسّنات اللفظية، والسجع والجناس من المحسّنات المعنوية.", "a": false, "explain": "1) المحسّنات المعنوية ترجع إلى تحسين المعنى، ومنها الطباق والمقابلة. 2) المحسّنات اللفظية ترجع إلى تحسين اللفظ، ومنها السجع والجناس والاقتباس والتضمين. 3) العبارة عكست التقسيم؛ فهي خاطئة."}, {"kind": "mcq", "lesson": 4, "q": "أيّ الصفات الآتية حقّقها عمر بن عبد العزيز حين قام بنفسه فأصلح السراج؟", "opts": ["الاعتدال في الإنفاق", "الشجاعة والإقدام", "التواضع", "الفصاحة"], "a": 2, "explain": "1) رفض عمر أن يستخدم ضيفه أو يوقظ غلامه، وقام بنفسه وهو أمير المؤمنين. 2) وقال: ذهبت وأنا عمر ورجعت وأنا عمر ما نقص مني شيء. 3) فهذا تواضع، وهو من صفات عباد الرحمن «الذين يمشون على الأرض هونًا»."}, {"kind": "tf", "lesson": 1, "q": "حذف القصيبي حرف النداء في قوله «خليجُ يا موجةً بيضاء» ليُظهر قربه من وطنه وكأنه لا يريد مسافة بينهما.", "a": true, "explain": "1) نادى الشاعر الخليج أولًا بـ(يا): «يا ساحر الموج». 2) ثم حذف (يا) من «خليجُ ما وشوش…» و«خليجُ يا موجة…». 3) وتقول الإضاءة النقدية إن حرف النداء كأنه يمثل مسافة لا يريدها الشاعر بينه وبين وطنه؛ فالعبارة صحيحة."}], "test": [{"q": "من ديوان أيّ مما يأتي أُخذت قصيدة «أغنية الخليج»؟", "opts": ["أشعار من جزيرة اللؤلؤ", "قطرات من ظمأ", "أنتِ الرياض", "معركة بلا راية"], "a": 3, "explain": "1) في نهاية القصيدة في الكتاب: «من ديوان معركة بلا راية». 2) أما الدواوين الأخرى فهي من دواوين القصيبي الأربعة، لكن القصيدة ليست منها.", "lesson": 1}, {"q": "«من بعدِ أن ذَرَعَ الدنيا فما فتحتْ له الشواطئُ إلا مرفأَ الضجرِ» معنى (ذرع الدنيا):", "opts": ["طوّقها بذراعيه", "طافها وجاب أقطارها", "عمّر فيها طويلًا", "مدّ إليها ذراعيه"], "a": 1, "explain": "1) السياق يتحدث عن أسفار الشاعر وغربته الطويلة قبل عودته. 2) فـ(ذرع الدنيا) أي قطعها وطاف بلادها. 3) وهي إجابة دليل المعلم: طافها وجاب أقطارها.", "lesson": 1}, {"q": "«ولا احترقتُ بنار الشمس ثانيةً … إلا ابتردتُ بما خلّفتُ في ذِكَري» المحسّن البديعي في البيت:", "opts": ["جناس بين الشمس وثانية", "طباق بين احترقت وابتردت", "سجع", "مقابلة بين الشطرين"], "a": 1, "explain": "1) الطباق: الجمع بين الكلمة وضدها. 2) (احترقت) تدل على الحرارة، و(ابتردت) تدل على البرودة، وهما ضدّان. 3) فهو طباق يُبرز أثر ذكرى الخليج في تخفيف معاناة الغربة.", "lesson": 1}, {"q": "عيّني البيت الدالّ على أن الشعر عند القصيبي وليد المعاناة النفسية:", "opts": ["هديّتي رعشتا شوقٍ وقافيةٍ … حمّلتُها كلّ ما عانيتُ في سفري", "أمرّ بالشاطئ الغافي فأوقظُه … بقبلةٍ وأناديه إلى السمرِ", "عهدتُه عربيًّا ما لوى فمَه … بلكنةٍ هاجرتْ من شاطئ التترِ", "خليجُ يا موجةً بيضاءَ تنقلُها … أصابعُ الشوق من قلبي إلى بصري"], "a": 0, "explain": "1) (القافية) هنا كناية عن الشعر. 2) والشاعر حمّل شعره «كل ما عانيت في سفري». 3) إذن الشعر عنده يولد من المعاناة، والبيت هو البيت الثاني.", "lesson": 1}, {"q": "الحال هي:", "opts": ["اسم مرفوع يبيّن هيئة صاحبه", "وصف منصوب يبيّن هيئة صاحبه", "اسم منصوب يبيّن سبب الفعل", "اسم مجرور يبيّن زمان الفعل"], "a": 1, "explain": "1) خلص الدرس من الملاحظتين إلى أن الحال تبيّن الهيئة، وأنها منصوبة. 2) فالتعريف: «الحال: وصف منصوب يبيّن هيئة صاحبه». 3) أما ما يبيّن سبب الفعل فهو المفعول لأجله.", "lesson": 2}, {"q": "«ساومتُ التاجرَ فاهُ إلى فيّ» الحال (فاه إلى فيّ) جامدة تؤوَّل بـ:", "opts": ["مترتّبين", "ملاصقين", "مشافهين", "مشبّهًا الفم"], "a": 2, "explain": "1) الحال تدل على مفاعلة؛ أي مشاركة المتكلم والتاجر في الحديث مباشرة. 2) لذلك تؤوَّل بالمشتق: مُشافِهَين. 3) أما (ملاصقين) فلـ(غرفته إلى غرفتي)، و(مترتّبين) لـ(اثنين اثنين).", "lesson": 2}, {"q": "في قوله تعالى ﴿فَتَمَثَّلَ لَهَا بَشَرًا سَوِيًّا﴾ الحال (بشرًا):", "opts": ["مشتقة نكرة", "جامدة تؤوَّل بمترتّب", "جامدة موصوفة بمشتق لا تؤوَّل", "معرفة مسموعة"], "a": 2, "explain": "1) (بشرًا) اسم جامد غير مشتق. 2) وُصف بالمشتق (سويًّا). 3) والحال الجامدة الموصوفة بمشتق لا تؤوَّل بالمشتق، كما في ﴿قرآنًا عربيًّا﴾، وهي إجابة دليل المعلم.", "lesson": 2}, {"q": "«إنما الميتُ من يعيش كئيبًا … كاسفًا بالُه قليلَ الرجاءِ» إعراب (قليلَ):", "opts": ["حال ثالثة منصوبة وهي مضاف", "نعت منصوب لكاسفًا", "خبر يعيش", "مفعول به منصوب"], "a": 0, "explain": "1) صاحب الحال هو الفاعل المستتر في (يعيش). 2) تعددت أحواله: كئيبًا (أولى)، كاسفًا (ثانية)، قليلَ (ثالثة). 3) و(قليلَ) مضاف، و(الرجاءِ) مضاف إليه، كما في نموذج الإعراب.", "lesson": 2}, {"q": "مَن واضع حجر أساس علم البلاغة ومؤسسه؟", "opts": ["أبو عبيدة معمر بن المثنى", "عبدالقاهر الجرجاني", "الجاحظ", "المتنبي"], "a": 1, "explain": "1) ألّف أبو عبيدة «مجاز القرآن» ولعله أول كتاب في العلم. 2) لكن العلم بلغ نضجه على يد الشيخ عبدالقاهر الجرجاني (ت 471هـ) «واضع حجر أساس علم البلاغة ومؤسسه» في كتابيه دلائل الإعجاز وأسرار البلاغة.", "lesson": 3}, {"q": "العلم الذي يبحث في طرائق تقديم المعنى الواحد بصور تعبيرية مختلفة كالتشبيه والاستعارة والكناية هو:", "opts": ["علم المعاني", "علم البديع", "علم البيان", "علم العروض"], "a": 2, "explain": "1) علم المعاني يبحث في مطابقة الكلام لمقتضى الحال (الخبر والإنشاء والإيجاز…). 2) علم البديع يبحث في تحسين الكلام (الطباق والجناس…). 3) أما التشبيه والاستعارة والمجاز والكناية فمن مباحث علم البيان.", "lesson": 3}, {"q": "الفصاحة في اصطلاح أهل البلاغة هي:", "opts": ["الوصول والانتهاء", "إنشاء الشيء على غير مثال سابق", "الألفاظ البيّنة الظاهرة المتبادرة إلى الفهم المأنوسة الاستعمال", "مطابقة الكلام لمقتضى الحال"], "a": 2, "explain": "1) (الوصول والانتهاء) معنى البلاغة لغةً. 2) (الإنشاء على غير مثال) معنى البديع لغةً. 3) (مطابقة الكلام لمقتضى الحال) من مباحث علم المعاني. 4) فالفصاحة اصطلاحًا: الألفاظ البيّنة الظاهرة المتبادرة إلى الفهم والمأنوسة الاستعمال بين الكتّاب والشعراء.", "lesson": 3}, {"q": "اتّصف مروان بن أبي حفصة بصفة تجافي صفات عباد الرحمن، هي:", "opts": ["الكبر والخيلاء", "البخل والشح", "الجبن", "الكذب"], "a": 1, "explain": "1) مروان شاعر عباسي أغدق عليه الخلفاء العطاء. 2) لكنه كان لا يأكل اللحم إلا رأسًا يشتريه ليأمن خيانة غلامه، رغم كثرة ماله. 3) فهو بخيل، وهذا يخالف صفة «إذا أنفقوا لم يسرفوا ولم يقتروا». أما الكبر والخيلاء فصفة المهلب.", "lesson": 4}], "game": {"type": "dive", "q": [{"q": "شاعر «أغنية الخليج»:", "opts": ["أحمد شوقي", "أبو مسلم البهلاني", "غازي القصيبي"], "a": 2}, {"q": "معنى (البيد):", "opts": ["الصحاري", "الجزر", "البحار"], "a": 0}, {"q": "طباق البيت الثاني عشر: احترقت و…", "opts": ["الشمس", "ابتردت", "ثانية"], "a": 1}, {"q": "الحال وصف…", "opts": ["مرفوع", "مجرور", "منصوب"], "a": 2}, {"q": "الأصل في الحال أن تكون:", "opts": ["معرفة جامدة", "نكرة مشتقة", "جملة اسمية"], "a": 1}, {"q": "(يدًا بيد) تؤوَّل بـ:", "opts": ["ملاصقين", "مترتّبين", "مقابضين"], "a": 2}, {"q": "(اثنين اثنين) تدل على:", "opts": ["مفاعلة", "تشبيه", "ترتيب"], "a": 2}, {"q": "أول كتاب في البلاغة لعله:", "opts": ["دلائل الإعجاز", "أسرار البلاغة", "مجاز القرآن"], "a": 2}, {"q": "التشبيه والكناية من علم:", "opts": ["البديع", "المعاني", "البيان"], "a": 2}, {"q": "من المحسنات المعنوية:", "opts": ["السجع", "الطباق", "الجناس"], "a": 1}, {"q": "صفة ابن عباس في النص:", "opts": ["الحلم", "الكرم", "الشجاعة"], "a": 0}, {"q": "المهلب بن أبي صفرة كان:", "opts": ["شاعرًا", "قائدًا عسكريًّا", "خليفة"], "a": 1}]}}, {"id": "u3", "axis": "الوطن", "axisN": 1, "unitN": 3, "title": "الوحدة الثالثة", "theme": "عمان في عيون الرحّالة", "pages": "49–72", "lessons": [{"type": "القراءة", "title": "عمان كما رآها الرحالة الأوروبيون", "page": 49, "hook": "رحالة غريب في سوق لا يعرف فيه أحدًا... فيُدعى إلى الشاي والغداء والعشاء! ماذا كتب عن عمان؟", "about": "نص يعرض شهادات رحالة أوروبيين زاروا عمان عبر تاريخها، وما سجّلوه عن أخلاق العمانيين وتسامحهم وكرمهم. أعدّ المادة وترجمها هلال بن سعيد الحجري.", "author": {"name": "هلال بن سعيد الحجري (إعداد وترجمة)", "bio": "أستاذ مساعد في الأدب المقارن بقسم اللغة العربية في جامعة السلطان قابوس، حصل على الدكتوراه من جامعة وريك بالمملكة المتحدة حول موضوع أدب الرحالة البريطانيين في عمان من 1800 إلى 1970."}, "idea": "عمان بأهميتها السياسية والتاريخية والجغرافية كانت محط أنظار الرحالة الأوروبيين، فسجّلوا إعجابهم بتسامح أهلها ولطفهم وكرمهم.", "cards": [{"icon": "🧭", "title": "أقدم الرحلات", "text": "أول أوروبي وضع قدمه في عمان (نيركس) العميد تحت إمرة (الإسكندر) الأكبر؛ وصل إلى رأس مسندم ومخا، وسمع عن سوق عماني ضخم يُحتمل أنه سوق صحار. ثم زارها (ماركو بولو) الإيطالي سنة 1295م، وبعد تحرير عمان من الاحتلال البرتغالي (1650م) قدم إليها كثيرون، خاصة البريطانيون."}, {"icon": "🤝", "title": "جون أوفينجتون (1693م)", "text": "زار مسقط وأُعجب بأخلاق أهلها: مهذّبون جدًّا، وفي غاية اللطف مع الغرباء، ويستطيع المرء أن يسافر مئات الأميال دون كلام مسيء. ورسم صورة لتسامحهم الديني.", "quote": "و مع أنهم معجبون بدينهم، و متمسكون بمبادئهم، فإنهم لا يفرضونها على أحد"}, {"icon": "🕊️", "title": "جيمس سيلك بكنغهام (1816م)", "text": "الصحفي والمؤلف الإنجليزي أُعجب بهدوء مسقط وسماحة أهلها ولطفهم واحترامهم للأوروبيين، ورأى أن الهدوء والتسامح يُعزيان إلى النزعة المسالمة للناس لا إلى تميّز الشرطة، وأخبر عن الأمان والضيافة.", "quote": "كلَّ شيءٍ في الحقيقة هنا مُواتٍ للحُريّةِ الشخصيّة"}, {"icon": "🏛️", "title": "جورج كيبل (1824م)", "text": "توقف في مسقط في طريق عودته من الهند إلى إنجلترا، وزار قصر السيد سعيد بن سلطان، فلفتت انتباهه الروح الأبوية: في المجلس اليومي يجلس كل واحد حيث يريد، والإمام ينصت ويستمع إلى الشكاوى.", "quote": "فالإمامُ بأرْيَحيّتِه يُنْصِتُ إليهم و يستمعُ إلى شكاواهم"}, {"icon": "🌟", "title": "ويليام جيفورد بالجريف (1863م)", "text": "زار هرمز وعبر ساحل الباطنة من صحار إلى مسقط، ولخّص صورة العمانيين بأنهم الأفضل بين العرب، وأن التسامح بأقصى درجاته مكفول عندهم لكل الأجناس والديانات والعادات.", "quote": "الأفضلُ سَجيّةً، و الأحْسنُ مَعْشَرًا، و الأكثرُ أنسًا، من جميعِ الأجناسِ العربيّة"}, {"icon": "🏜️", "title": "مايلز وثيسيجر: الحماية والكرم", "text": "مايلز (1874–1885م) معتمد سياسي وقنصل بريطاني امتنّ لرفقائه العرب؛ فقد اعتبروا حمايته أهم من حماية أنفسهم. وثيسيجر (1945–1950م) عبر الربع الخالي مرتين، وانبهر بالكرم الباذخ وقارنه بقلة اكتراث قومه بالغرباء.", "quote": "لكنّني لم أكنْ وحيدًا أبدًا بين العرب"}, {"icon": "💎", "title": "قيم ودروس", "text": "التسامح الديني والتعايش السلمي بين الأديان، واللطف مع الغريب، والكرم، وحماية الضيف. وكتابات الرحالة وثائق مهمة للدارسين؛ لأنها نتاج معايشة طويلة للناس في كل مناحي حياتهم."}], "table": {"title": "الرحالة وما لفت انتباههم", "head": ["الرحالة", "السنة", "ما سجّله عن عمان"], "rows": [["نيركس", "عهد الإسكندر الأكبر", "أول أوروبي في عمان، وسمع بسوق ضخم (صحار)"], ["ماركو بولو", "1295م", "الرحالة الإيطالي المشهور زار عمان"], ["جون أوفينجتون", "1693م", "اللطف مع الغرباء والتسامح الديني"], ["جيمس سيلك بكنغهام", "1816م", "هدوء مسقط، والأمان، والحرية الشخصية"], ["جورج كيبل", "1824م", "الروح الأبوية في مجلس السيد سعيد بن سلطان"], ["ويليام جيفورد بالجريف", "1863م", "أفضل الأجناس العربية سجية، والتسامح بأقصى درجاته"], ["صموئيل باريت مايلز", "1874–1885م", "حماية رفقائه له وتضحيتهم بأنفسهم"], ["ويلفريد ثيسيجر", "1945–1950م", "الكرم الباذخ، وعبر الربع الخالي مرتين"]]}, "vocab": [{"w": "سَجِيّة", "m": "الطبيعة والخُلُق، والجمع: سجايا"}, {"w": "تحرَّوا الحقيقة", "m": "تحرّى في الأمور: قصد أفضلها، وتحرّى الحقيقة: اجتهد في طلبها ودقّق"}, {"w": "توافدوا", "m": "تُطلب في المعجم في مادة (وفد)"}, {"w": "سماحة", "m": "تُطلب في المعجم في مادة (سمح)"}], "tip": "💡 ملامح الحياة العمانية في النص (من دليل المعلم): استقبال السلطان للرعية، وحماية الأجانب، والأسواق الشعبية وشرب الشاي، والكرم ودعوة الغرباء إلى الطعام.", "keyPoints": ["أول أوروبي وطئ عمان: نيركس، العميد تحت إمرة الإسكندر الأكبر، ثم ماركو بولو سنة 1295م.", "أوفينجتون صوّر تسامح العمانيين الديني: متمسكون بمبادئهم ولا يفرضونها على أحد.", "بكنغهام أُعجب بهدوء مسقط وسماحة أهلها، وكيبل لفتته الروح الأبوية في مجلس السيد سعيد بن سلطان.", "مايلز امتنّ لرفقائه العرب لأنهم اعتبروا حمايته أهم من حماية أنفسهم.", "ثيسيجر عبر الربع الخالي مرتين، وانبهر بكرم العمانيين الباذخ."], "check": [{"q": "أول أوروبي وضع قدمه في عمان هو:", "opts": ["ماركو بولو", "نيركس", "جون أوفينجتون"], "a": 1, "explain": "النص: «أول أوروبي وضع قدمه في عمان كان (نيركس) العميد تحت إمرة (الإسكندر) الأكبر». أما ماركو بولو فزارها بعده سنة 1295م."}, {"q": "«إن أسوأ غربة أن تكون غريبًا في حشد من الناس» سبب نصب (غريبًا):", "opts": ["حال", "خبر تكون", "مفعول به"], "a": 1, "explain": "(تكون) فعل ناقص، اسمه ضمير مستتر (أنت)، و(غريبًا) خبره منصوب بالفتحة."}]}, {"type": "الأنشطة النحوية", "title": "الحال: صورها، وصاحبها", "page": 54, "hook": "جاء محمد راكضًا... أو يركض... أو وهو يركض... أو في سيارة! أربع صور لحال واحدة.", "about": "يكمل الدرس موضوع الحال: صورها (مفردة، وجملة اسمية أو فعلية، وشبه جملة)، والرابط الذي يربط الحال الجملة بصاحبها، ثم صاحب الحال: مواقعه الإعرابية، والأصل فيه التعريف، ومسوّغات مجيئه نكرة.", "idea": "تأتي الحال مفردة أو جملة أو شبه جملة، والجملة تحتاج إلى رابط، وصاحب الحال الأصل فيه أن يكون معرفة.", "cards": [{"icon": "🧩", "title": "صور الحال", "text": "كل عبارة ملوّنة بيّنت هيئة محمد في مجيئه، فهي حال: (راكضًا) مفردة، و(يركض) جملة فعلية، و(وهو يركض) جملة اسمية، و(في سيارة) شبه جملة. وشبه الجملة: جار ومجرور أو ظرف.", "quote": "جاء محمد راكضا . جاء محمد يركض . جاء محمد وهو يركض . جاء محمد في سيارة ."}, {"icon": "📖", "title": "صور في القرآن والشعر", "text": "(واحدًا) في «إن انطلاقك واحدًا» حال مفردة، و(يبكون) جملة فعلية، و(ونحن عصبة) جملة اسمية، و(في زينته) شبه جملة.", "quote": "﴿وَجَآءُوٓ أَبَاهُمْ عِشَآءً يَبْكُونَ﴾"}, {"icon": "🔗", "title": "رابط الحال الجملة", "text": "الحال الجملة لا بد لها من رابط يربطها بصاحبها: الضمير وحده (يركض: ضمير مستتر، يبكون: واو الجماعة)، أو الواو والضمير معًا (وهو يركض، ونحن عصبة)، أو الواو وحدها.", "quote": "أقلعت السفينة والبحر هادئ"}, {"icon": "👤", "title": "مواقع صاحب الحال", "text": "يأتي صاحب الحال مبتدأ (الإنسانُ – ساعيًا…)، أو فاعلًا (الجرد… عوابسًا)، أو مفعولًا به (العالمَ متواضعًا)، أو مضافًا إليه (البرامج… هادفةً). وقد يكون نائب فاعل، أو مفعولًا فيه أو معه أو لأجله، أو اسمًا مجرورًا.", "quote": "يحترم الناس العالم متواضعا"}, {"icon": "⭐", "title": "الأصل: صاحب الحال معرفة", "text": "الأصل في صاحب الحال أن يكون معرفة، كما في: الإنسان، والجرد، والعالم، والبرامج. فإن جاء نكرة فلا بد من مسوّغ."}, {"icon": "🔓", "title": "مسوّغات تنكير صاحب الحال", "text": "(1) تقدّم الحال عليه: «يتفوق مثابرًا طالبٌ». (2) تخصيصه بوصف أو إضافة: «شدّتني قصةٌ قصيرةٌ مثيرةً». (3) سبقه بنفي أو شبهه (النهي والاستفهام): «ما ضاع دعاءٌ صادقًا». (4) كون الحال جملة مقترنة بالواو.", "quote": "﴿أَوْ كَالَّذِى مَرَّ عَلَىٰ قَرْيَةٍ وَهِىَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا﴾"}, {"icon": "✏️", "title": "من التدريبات", "text": "في بيت كعب بن مالك: (صريعًا) حال مفردة، و(وهو عاثر) حال جملة اسمية. وفي بيت ابن الرومي: (والرأس أسود) حال جملة اسمية رابطها الواو.", "quote": "فكب أبو جهل صريعًا لوجهه ... وعتبة قد غادرنه و هو عاثر"}], "table": {"title": "صور الحال وصاحبها في أمثلة الدرس", "head": ["المثال", "الحكم", "السبب/الرابط"], "rows": [["جاء محمد راكضًا", "حال مفردة", "ليست جملة ولا شبه جملة"], ["جاء محمد يركض", "حال جملة فعلية", "الرابط: الضمير المستتر العائد على محمد"], ["جاء محمد وهو يركض", "حال جملة اسمية", "الرابط: الواو والضمير (هو)"], ["جاء محمد في سيارة", "حال شبه جملة", "جار ومجرور"], ["عشاءً يبكون", "حال جملة فعلية", "الرابط: الضمير (واو الجماعة)"], ["ونحن عصبة", "حال جملة اسمية", "الرابط: الواو والضمير (نحن)"], ["أقلعت السفينة والبحر هادئ", "حال جملة اسمية", "الرابط: الواو وحدها"], ["يتفوق مثابرًا طالبٌ", "صاحب الحال نكرة (طالب)", "تقدّمت الحال عليه"], ["شدّتني قصةٌ قصيرةٌ مثيرةً", "صاحب الحال نكرة (قصة)", "خُصِّص بوصف"], ["ما ضاع دعاءٌ صادقًا", "صاحب الحال نكرة (دعاء)", "سُبق بنفي"], ["مرّ على قريةٍ وهي خاويةٌ", "صاحب الحال نكرة (قرية)", "الحال جملة مقترنة بالواو"]]}, "tip": "💡 رأيتِ صاحب حال نكرة؟ لا تحكمي بالخطأ فورًا، بل ابحثي عن المسوّغ: تقدّم الحال، أو وصف/إضافة، أو نفي وشبهه، أو حال جملة بالواو.", "keyPoints": ["صور الحال: مفردة، وجملة (اسمية أو فعلية)، وشبه جملة (جار ومجرور أو ظرف).", "رابط الحال الجملة: الضمير وحده، أو الواو والضمير معًا، أو الواو وحدها.", "صاحب الحال قد يكون مبتدأ أو فاعلًا أو مفعولًا به أو مضافًا إليه أو غير ذلك.", "الأصل في صاحب الحال أن يكون معرفة.", "يأتي نكرة إذا: تقدّمت الحال عليه، أو خُصِّص بوصف أو إضافة، أو سُبق بنفي أو شبهه، أو كانت الحال جملة مقترنة بالواو."], "check": [{"q": "في «جاء محمد وهو يركض» رابط الحال بصاحبها:", "opts": ["الضمير وحده", "الواو والضمير معًا", "الواو وحدها"], "a": 1, "explain": "الحال جملة اسمية (وهو يركض)، وفيها رابطان: واو الحال، والضمير المنفصل (هو) العائد على محمد."}, {"q": "«ما ضاع دعاءٌ صادقًا» سوّغ مجيء صاحب الحال (دعاء) نكرة:", "opts": ["سبقه بنفي", "تقدّم الحال عليه", "تخصيصه بوصف"], "a": 0, "explain": "(دعاء) نكرة سُبقت بحرف النفي (ما)، وهذا من مسوّغات مجيء صاحب الحال نكرة."}]}, {"type": "النقد الأدبي", "title": "مقدمة في النقد الأدبي", "page": 63, "hook": "كما يميّز الصيرفي الدرهم الجيد من الزائف، يميّز الناقد جمال النص من قبحه.", "about": "يعرّف الدرس النقد الأدبي لغة واصطلاحًا، ويتتبع نشأته وتطوره عند العرب، ويبيّن أهميته وطبيعته ومكانة الذوق فيه، ثم يعرّف العمل الأدبي وصورتيه: الخارجية والداخلية.", "idea": "النقد فن تفسير الأعمال الأدبية بذوق الناقد وفكره للكشف عن مواطن الجمال والقبح فيها.", "cards": [{"icon": "🔍", "title": "تعريف النقد", "text": "لغةً: نقد الشيء ليختبره أو ليميّز جيده من رديئه، ونقد الدراهم والدنانير: ميّز جيدها من رديئها. واصطلاحًا: فن تفسير الأعمال الأدبية، وهو محاولة منضبطة يشترك فيها ذوق الناقد وفكره للكشف عن مواطن الجمال أو القبح."}, {"icon": "🐣", "title": "الأدب أولًا", "text": "الأدب سابق للنقد في الظهور؛ فلولا وجود الأدب لما كان هناك نقد أدبي، لأن قواعد النقد مستقاة من دراسة الأدب."}, {"icon": "🕰️", "title": "فترتان ومرحلتان", "text": "الفترة الأولى: من العصر الجاهلي إلى بداية عصر النهضة (القرن التاسع عشر)، وفيها مرحلتان: الأولى حتى مطلع العصر العباسي (رواية شفهية بلا تدوين)، والثانية من العصر العباسي حتى العصر الحديث (عُرف التدوين). والفترة الثانية: النقد الحديث من عصر النهضة إلى اليوم."}, {"icon": "🌍", "title": "العصر الحديث", "text": "انفتح العرب على ثقافة العالم، فتأثروا بفنون أدبية لم يعرفها أدبنا القديم كالقصة والمسرحية، كما تأثروا بمذاهب الأدب والنقد في العالم."}, {"icon": "⚖️", "title": "أهميته وطبيعته", "text": "الناقد ينظر في النصوص شعرية ونثرية، ويكشف مواطن الجمال والقبح معلّلًا ما يقوله. ولا يوجد نقد صائب تمامًا وآخر خاطئ تمامًا، بل نقد أقدر على تأويل العمل وتفسيره، واختلاف مناهج النقد اختلاف في وجهات النظر."}, {"icon": "👅", "title": "الذوق المصقول", "text": "للذوق أهميته لأنه أقرب المقاييس إلى طبيعة الأدب، والمعتبر هو الذوق المصقول: ذوق ناقد يكبح هواه، خبير بالأدب، ومعه قدر وافر من المعرفة والثقافة والبصر الثاقب.", "quote": "فالأدب ونقده ذوق وفن ، قبل أن يكون معرفة وعلما"}, {"icon": "📄", "title": "العمل الأدبي وصورتاه", "text": "العمل الأدبي نتاج أديب (شاعر أو ناثر) بعد معاناة وإحساس بشيء حوله. وله صورتان: خارجية (الشكل والكلمات والتراكيب)، وداخلية (العناصر الحقيقية التي نحكم بها على جودته). وعناصره كلٌّ لا يتجزأ."}], "table": {"title": "صورتا العمل الأدبي", "head": ["الصورة", "تتمثل في", "وظيفتها"], "rows": [["الخارجية", "الشكل الذي اختاره الأديب وعاءً لتجربته (القصيدة، الأسلوب القصصي…)، والكلمات والعبارات والتراكيب والفقرات أو الأبيات", "الإطار الخارجي المادي أو الشكل المحسوس"], ["الداخلية", "العناصر الأخرى التي يتألف منها العمل عدا إطاره الخارجي، وهي مكوّناته الحقيقية", "نحكم بها على جودة العمل أو رداءته، وعمق التجربة أو ضحالتها، وصدقها أو كذبها"]]}, "tip": "💡 سؤال مكرر: «أيهما أسبق: الأدب أم النقد؟» الأدب؛ لأن قواعد النقد مستقاة من دراسة الأدب.", "keyPoints": ["النقد اصطلاحًا: فن تفسير الأعمال الأدبية، يشترك فيه ذوق الناقد وفكره للكشف عن مواطن الجمال أو القبح.", "الأدب أسبق من النقد في الظهور.", "المرحلة الأولى (من الجاهلي إلى مطلع العباسي) اعتمدت على الرواية الشفهية، والثانية عرفت التدوين.", "الذوق المعتبر في النقد هو الذوق المصقول المدعوم بالمعرفة والثقافة.", "للعمل الأدبي صورتان: خارجية (الشكل)، وداخلية (بها نحكم على الجودة)."], "check": [{"q": "أيهما أسبق في النشأة؟", "opts": ["النقد", "الأدب", "ظهرا معًا"], "a": 1, "explain": "الأدب سابق للنقد؛ فلولا وجود الأدب لما كان هناك نقد، لأن قواعد النقد مستقاة من دراسة الأدب."}, {"q": "الصورة التي نحكم بها على جودة العمل الأدبي وصدق تجربته:", "opts": ["الصورة الخارجية", "الشكل المحسوس", "الصورة الداخلية"], "a": 2, "explain": "العناصر الداخلية هي المكوّنات الحقيقية للعمل، وبها نحكم على جودته أو رداءته وعمق تجربته وصدقها؛ أما الخارجية فهي الشكل والإطار المحسوس."}]}, {"type": "التعبير", "title": "التلخيص (1)", "page": 66, "hook": "صفحة كاملة في ثلث حجمها، بكلماتك أنتِ، دون أن تضيع فكرة واحدة: هذا هو التلخيص.", "about": "درس في التعبير الكتابي الوظيفي يعرّف التلخيص، ويشرح خطوتيه: استخلاص الأفكار وإعادة تنظيمها، ومعايير الحكم على جودته، ثم يطبّق ذلك على مقالة «اصنع حياتك» للدكتور أحمد أمين.", "idea": "التلخيص إعادة إنتاج للأفكار الرئيسة بلغة الملخِّص وبعدد أقل من الكلمات، لا مجرد اختصار.", "cards": [{"icon": "📝", "title": "ما التلخيص؟", "text": "فن يقوم على إعادة إنتاج الأفكار الرئيسة في نص ما بلغة الملخِّص وبعدد أقل من الكلمات. ليس مجرد اختصار، بل إعادة إنتاج بتنظيم جديد ولغة جديدة، وركناه: استخلاص الأفكار الرئيسة، وإعادة تنظيمها في قالب لغوي جديد."}, {"icon": "🔍", "title": "أولًا: استخلاص الأفكار", "text": "الكاتب يبني الفقرة بخطوتين: جملة رئيسة، ثم جمل داعمة (تفسيرًا أو تفصيلًا أو تمثيلًا). ونحن نسير بعكس اتجاهه: نستبعد الجمل الداعمة كليًّا أو جزئيًّا، ونُبقي الجملة الرئيسة.", "quote": "الإنسان كائن بالغ التعقيد من الناحية النفسية"}, {"icon": "🔁", "title": "ثانيًا: إعادة التنظيم", "text": "(1) صوغي كل فكرة بلغتك، بأقل عدد من الكلمات وأكبر عدد من التغييرات اللفظية، مثل: «تصعب الإحاطة بالجوانب النفسية للإنسان». (2) اربطي الأفكار بتسلسل منطقي، ويجوز تقديم فكرة على أخرى بشرط ألا يتغير معنى النص.", "quote": "النفس الإنسانية أمر معقد"}, {"icon": "📏", "title": "معيار الحجم", "text": "يُفضَّل ألا يتجاوز التلخيص ثلث (1/3) حجم النص الأصلي؛ فإذا كان النص في 300 كلمة، فالأفضل أن يكون الملخص في حدود 100 كلمة."}, {"icon": "🎯", "title": "معيار النوع", "text": "يُفضَّل أن يعبّر الملخص عن جميع الأفكار الرئيسة في النص، إضافة إلى الأفكار الداعمة ذات الطبيعة التفسيرية التي توضح المفاهيم والمصطلحات الواردة في الأفكار الرئيسة."}, {"icon": "🗣️", "title": "معيار اللغة", "text": "قلّلي الألفاظ المتكررة من النص الأصلي إلى أدنى حد، واسألي نفسك: هل أستطيع تغيير هذه اللفظة دون تغيير المعنى؟ واربطي الأفكار بأدوات جديدة: بدل «ومما سبق نستنتج» قولي «وبناء على ما تقدم»."}, {"icon": "🌱", "title": "تطبيق: «اصنع حياتك»", "text": "من أفكار مقالة أحمد أمين: الإنسان قادر إلى حدّ ما أن يصنع حياته، وإرادته تتغلب على عقبات الوراثة والبيئة. ومن نصائحه: ألا تيأسي، وأن يكون لك مثل أعلى، والثقة بالنفس، والابتسام للحياة."}], "table": {"title": "معايير جودة التلخيص", "head": ["المعيار", "المطلوب"], "rows": [["الحجم", "ألا يتجاوز ثلث حجم النص الأصلي (300 كلمة ← نحو 100 كلمة)"], ["النوع", "جميع الأفكار الرئيسة + الأفكار الداعمة التفسيرية"], ["اللغة", "أقل قدر من ألفاظ النص الأصلي، وأدوات ربط جديدة"]]}, "tip": "💡 خطأ شائع: حذف كلمات من النص ونسخ الباقي! التلخيص الصحيح يعيد صياغة الأفكار بلغتك أنتِ.", "keyPoints": ["التلخيص: إعادة إنتاج الأفكار الرئيسة في نص ما بلغة الملخِّص وبعدد أقل من الكلمات.", "ركناه: استخلاص الأفكار الرئيسة، وإعادة تنظيمها في قالب لغوي جديد.", "نستخلص الفكرة بالإبقاء على الجملة الرئيسة واستبعاد الجمل الداعمة.", "معايير الجودة: الحجم (لا يتجاوز الثلث)، والنوع (كل الأفكار الرئيسة)، واللغة (تقليل ألفاظ الأصل وأدوات ربط جديدة)."], "check": [{"q": "يُفضَّل ألا يتجاوز حجم التلخيص:", "opts": ["نصف النص الأصلي", "ثلث النص الأصلي", "ربع النص الأصلي"], "a": 1, "explain": "معيار الحجم: ألا يتجاوز التلخيص ثلث حجم النص الأصلي؛ فنص من 300 كلمة يُلخَّص في نحو 100 كلمة."}, {"q": "عند استخلاص الفكرة من الفقرة نُبقي على:", "opts": ["الجمل الداعمة", "الأمثلة والتفاصيل", "الجملة الرئيسة"], "a": 2, "explain": "نسير بعكس اتجاه الكاتب: نستبعد الجمل الداعمة كليًّا أو جزئيًّا، ونُبقي الجملة الرئيسة."}]}, {"type": "اقرأ واستمتع", "title": "إلى أمي", "page": 71, "hook": "خبز، وقهوة، ولمسة... ثلاثة أشياء صغيرة تختصر الحنين كله.", "about": "قصيدة لمحمود درويش من «الأعمال الكاملة» (دار العودة، 1987م)، يعبّر فيها عن حنينه إلى أمه وإلى طفولته في كنفها.", "idea": "حنين الشاعر إلى أمه، وتعلّقه بها، ورغبته في العودة إلى طفولته في حضنها.", "cards": [{"icon": "☕", "title": "حنين إلى التفاصيل", "text": "يحنّ الشاعر إلى أبسط ما في أمه: خبزها وقهوتها ولمستها، فتكبر فيه الطفولة يومًا بعد يوم. ويعشق عمره لأنه يخجل من دمع أمه إن مات.", "quote": "أحنُّ إلى خبز أُمي / وقهوة أُمي / ولمسة أُمي .."}, {"icon": "🧣", "title": "«خذيني»", "text": "يطلب من أمه إن عاد يومًا أن تأخذه وشاحًا لهدبها، وأن تغطي عظامه بعشب تعمّد من طهر كعبها، وأن تشدّ وثاقه بخصلة شعر أو بخيط يلوّح في ذيل ثوبها.", "quote": "خذيني ، إذا عدتُ يوماً / وشاحا لهدبكْ"}, {"icon": "🐦", "title": "العودة إلى العش", "text": "يتمنى أن يكون وقودًا لتنّور نارها وحبل غسيل على سطح دارها؛ لأنه فقد الوقوف بدون صلاة نهارها. وقد هرم، فيطلب أن تردّ إليه نجوم الطفولة ليرجع مع صغار العصافير إلى عشّ انتظارها.", "quote": "هَرِمْتُ ، فردّي نجوم الطفولة / حتى أُشارك / صغار العصافير / درب الرجوع .. / لعُشِ انتظارِك !"}], "keyPoints": ["الشاعر: محمود درويش، والقصيدة من «الأعمال الكاملة» (دار العودة، 1987م).", "العاطفة: حنين جارف إلى الأم والطفولة.", "تكرار كلمة (أمي) في المطلع يعمّق الإحساس بالحنين."], "check": [{"q": "بمَ افتتح الشاعر قصيدته؟", "opts": ["بالحنين إلى خبز أمه وقهوتها ولمستها", "بوصف وطنه", "بالحديث عن الحرب"], "a": 0, "explain": "المطلع: «أحنُّ إلى خبز أمي / وقهوة أمي / ولمسة أمي»."}, {"q": "لماذا يعشق الشاعر عمره؟", "opts": ["لأنه حقق أحلامه", "لأنه يخجل من دمع أمه إن مات", "لأنه عاد إلى وطنه"], "a": 1, "explain": "يقول: «وأعشق عمري لأني / إذا متُّ، / أخجل من دمع أمي!»."}]}], "activities": [{"kind": "match", "lesson": 1, "title": "صِلي كل رحّالة بما ورد عنه في النص", "pairs": [["نيركس", "أول أوروبي وطئ عمان تحت إمرة الإسكندر"], ["جون أوفينجتون", "العمانيون لا يفرضون مبادئهم على أحد"], ["جيمس بكنغهام", "هدوء مسقط وسماحة أهلها ولطفهم"], ["جورج كيبل", "الروح الأبوية في مجلس السيد سعيد بن سلطان"], ["صموئيل مايلز", "امتنانه لحماسة رفقائه وتضحيتهم من أجله"], ["ويلفريد ثيسيجر", "عبر الربع الخالي مرتين وانبهر بالكرم"]]}, {"kind": "classify", "lesson": 2, "title": "صنّفي الحال فيما يأتي بحسب صورتها", "groups": ["مفردة", "جملة", "شبه جملة"], "items": [["جاء محمد راكضًا", 0], ["فكبّ أبو جهل صريعًا لوجهه", 0], ["ثم تعود باسمًا", 0], ["جاء محمد يركض", 1], ["﴿وجاؤوا أباهم عشاءً يبكون﴾", 1], ["أقلعت السفينة والبحر هادئ", 1], ["جاء محمد في سيارة", 2], ["﴿فخرج على قومه في زينته﴾", 2]]}, {"kind": "order", "lesson": 4, "title": "رتّبي خطوات التلخيص كما عرضها الدرس", "items": ["تمييز الجملة الرئيسة في كل فقرة", "استبعاد الجمل الداعمة والإبقاء على الرئيسة", "إعادة صياغة كل فكرة بلغة الملخِّص وبكلمات أقل", "ربط الأفكار الرئيسة في تسلسل منطقي بأدوات ربط جديدة"]}, {"kind": "mcq", "lesson": 2, "q": "«ما ضاعَ دعاءٌ صادقًا» جاء صاحب الحال (دعاء) نكرة؛ لأنه:", "opts": ["تأخّر عن الحال", "خُصِّص بوصف", "سُبق بنفي", "الحال جملة مقترنة بالواو"], "a": 2, "explain": "1) صاحب الحال (دعاء) نكرة، والأصل فيه التعريف. 2) نبحث عن المسوّغ: سبقته (ما) النافية. 3) إذن المسوّغ: سبق النكرة بنفي، وهو المسوّغ الثالث في الدرس."}, {"kind": "fill", "lesson": 2, "q": "في جملة «جاء محمدٌ وهو يركضُ» الرابط بين الحال وصاحبها هو ____.", "opts": ["الضمير وحده", "الواو والضمير معًا", "الواو وحدها"], "a": 1, "explain": "1) الحال (وهو يركض) جملة اسمية. 2) فيها واو الحال، وفيها الضمير المنفصل (هو) العائد على محمد. 3) فالرابط: الواو والضمير معًا، كما نصّ الدرس."}, {"kind": "tf", "lesson": 3, "q": "النقد الأدبي أسبق في الظهور من الأدب؛ لأن الأديب يحتاج إلى قواعد النقد قبل أن يكتب.", "a": false, "explain": "1) ينصّ الدرس على أن «الأدب سابق للنقد في الظهور». 2) والعلة: لولا وجود الأدب لما كان هناك نقد؛ لأن قواعد النقد مستقاة من دراسة الأدب. 3) فالعبارة خاطئة."}, {"kind": "mcq", "lesson": 4, "q": "نص أصلي يقع في 300 كلمة؛ ما الحجم المفضّل لتلخيصه؟", "opts": ["في حدود 200 كلمة", "في حدود 150 كلمة", "في حدود 100 كلمة", "في حدود 30 كلمة"], "a": 2, "explain": "1) معيار الحجم: يُفضَّل ألا يتجاوز التلخيص ثلث حجم النص الأصلي. 2) ثلث 300 = 100. 3) وهو المثال نفسه في الكتاب: «فإذا كان النص الأصلي يقع في (300) كلمة … فمن المفضّل أن يكون الملخّص في حدود (100) كلمة»."}, {"kind": "tf", "lesson": 1, "q": "أتاح للكولونيل صموئيل مايلز التنقّلَ في عمان كونُه معتمدًا سياسيًّا وقنصلًا بريطانيًّا في مسقط.", "a": true, "explain": "1) يقول النص: «لكونه معتمدًا سياسيًّا وقنصلًا بريطانيًّا في مسقط، استطاع أن يتجول في اتجاهات عدة في عمان». 2) فالعبارة صحيحة."}], "test": [{"q": "مَن أول أوروبي وضع قدمه في عمان كما تخبرنا المصادر في النص؟", "opts": ["ماركو بولو", "نيركس العميد تحت إمرة الإسكندر الأكبر", "جون أوفينجتون", "ويلفريد ثيسيجر"], "a": 1, "explain": "1) يقول النص: «أول أوروبي وضع قدمه في عمان كان (نيركس) العميد تحت إمرة (الإسكندر) الأكبر». 2) ثم زارها بعده ماركو بولو سنة 1295م، وجاء أوفينجتون سنة 1693م، وثيسيجر في القرن العشرين.", "lesson": 1}, {"q": "رسم جون أوفينجتون صورة لتسامح العمانيين الديني، خلاصتها أنهم:", "opts": ["لا يهتمون بدينهم", "يفرضون مبادئهم على الغرباء", "معجبون بدينهم متمسكون بمبادئهم ولا يفرضونها على أحد", "يمنعون الغرباء من دخول بلادهم"], "a": 2, "explain": "1) قال أوفينجتون: «ومع أنهم معجبون بدينهم ومتمسكون بمبادئهم فإنهم لا يفرضونها على أحد». 2) فالتمسك بالدين مع احترام الآخر هو صورة التسامح الديني.", "lesson": 1}, {"q": "(هم الأفضل سجيّةً) معنى (سجيّة):", "opts": ["الطبيعة والخُلُق", "المال والثروة", "القوة والشجاعة", "السفر والترحال"], "a": 0, "explain": "1) في نشاط المفردات بالكتاب: «سجيّة: السجيّة الطبيعة والخلق، (ج) سجايا». 2) والمعنى: هم الأفضل طبعًا وخلقًا.", "lesson": 1}, {"q": "«إنّ أسوأ غربةٍ أن تكونَ غريبًا في حشد من الناس» سبب نصب (غريبًا):", "opts": ["حال منصوبة", "مفعول به", "خبر تكون منصوب", "تمييز منصوب"], "a": 2, "explain": "1) (تكون) فعل مضارع ناقص من أخوات كان، منصوب بأن، واسمه ضمير مستتر تقديره أنت. 2) (غريبًا) خبرها. 3) فهو منصوب لأنه خبر تكون.", "lesson": 1}, {"q": "في قوله تعالى ﴿وَجَاءُوا أَبَاهُمْ عِشَاءً يَبْكُونَ﴾ نوع الحال (يبكون):", "opts": ["مفردة", "جملة اسمية", "شبه جملة", "جملة فعلية"], "a": 3, "explain": "1) (يبكون) فعل مضارع وفاعله واو الجماعة. 2) فالحال جملة فعلية. 3) ورابطها الضمير وحده (واو الجماعة العائدة على إخوة يوسف).", "lesson": 2}, {"q": "«أقلعت السفينةُ والبحرُ هادئٌ» الرابط بين الحال وصاحبها:", "opts": ["الواو وحدها", "الضمير وحده", "الواو والضمير معًا", "لا رابط لها"], "a": 0, "explain": "1) الحال جملة اسمية (والبحر هادئ). 2) ليس فيها ضمير يعود على السفينة. 3) فالرابط هو الواو وحدها، وهو مثال الكتاب لهذه الحالة.", "lesson": 2}, {"q": "«يحترم الناسُ العالِمَ متواضعًا» صاحب الحال وموقعه الإعرابي:", "opts": ["الناس – فاعل", "العالمَ – مفعول به", "الناس – مبتدأ", "العالمَ – مضاف إليه"], "a": 1, "explain": "1) المتواضع هو العالِم لا الناس؛ فصاحب الحال (العالم). 2) (العالمَ) وقع عليه فعل الاحترام فهو مفعول به منصوب. 3) فالإجابة: العالم – مفعول به.", "lesson": 2}, {"q": "«يتفوّقُ مثابرًا طالبٌ» سوّغ مجيء صاحب الحال (طالب) نكرةً:", "opts": ["تخصيصه بالإضافة", "سبقه بالنفي", "تقدّم الحال عليه", "اقتران الحال بالواو"], "a": 2, "explain": "1) صاحب الحال (طالب) نكرة متأخرة. 2) والحال (مثابرًا) تقدمت عليه. 3) فالمسوّغ: تقدّم الحال على صاحبها النكرة، وهو المسوّغ الأول.", "lesson": 2}, {"q": "«قد تركت الصحاح مرضى يميدون نحولًا وأنت خوط يميد» (وأنت خوط يميد) حال:", "opts": ["مفردة صاحبها الصحاح", "جملة فعلية صاحبها واو الجماعة", "شبه جملة", "جملة اسمية صاحبها تاء الفاعل في (تركت)"], "a": 3, "explain": "1) (أنت) مبتدأ و(خوط) خبر، فالحال جملة اسمية. 2) رابطها الواو والضمير (أنت). 3) وصاحبها المخاطَب بالضمير (أنت)، وهو تاء الفاعل في (تركت)، كما في دليل المعلم.", "lesson": 2}, {"q": "تعتمد المرحلة الأولى من النقد الأدبي عند العرب (من الجاهلي حتى مطلع العباسي) على:", "opts": ["الرواية الشفهية", "التدوين", "مذاهب النقد الغربية", "فنون القصة والمسرحية"], "a": 0, "explain": "1) يقول الدرس: «ففي هذه المرحلة لم يكن التدوين قد ظهر وكان الاعتماد على الرواية الشفهية». 2) أما التدوين فعُرف في المرحلة الثانية، والتأثر بالقصة والمسرحية ومذاهب النقد العالمية كان في العصر الحديث.", "lesson": 3}, {"q": "تتمثّل الصورة الخارجية للعمل الأدبي في:", "opts": ["صدق التجربة وعمقها", "الشكل الذي اختاره الأديب والكلمات والتراكيب", "العواطف والمشاعر الداخلية", "ذوق الناقد"], "a": 1, "explain": "1) الصورة الخارجية: الشكل الذي اختاره الأديب وعاءً لتجربته، والكلمات والعبارات والتراكيب والفقرات أو الأبيات، وهي الإطار المادي المحسوس. 2) أما صدق التجربة وعمقها فمما يُحكم عليه بالصورة الداخلية.", "lesson": 3}, {"q": "يقوم التلخيص على ركنين أساسيين هما:", "opts": ["نقل الجمل الطويلة كما هي ثم حذف الأمثلة", "الحذف العشوائي والاختصار", "شرح النص وإضافة آراء الملخِّص", "استخلاص الأفكار الرئيسة وإعادة تنظيمها في قالب لغوي جديد"], "a": 3, "explain": "1) يقول الدرس: التلخيص «ليس مجرد عملية اختصار للنص»، بل «إعادة إنتاج للنص بتنظيم جديد ولغة جديدة». 2) «وهو يقوم على ركنين أساسيين هما: استخلاص الأفكار الرئيسة، وإعادة تنظيمها في قالب لغوي جديد».", "lesson": 4}], "game": {"type": "route", "q": [{"q": "أول أوروبي وطئ عمان:", "opts": ["نيركس", "ماركو بولو"], "a": 0}, {"q": "عبر الربع الخالي مرتين:", "opts": ["بكنغهام", "ثيسيجر"], "a": 1}, {"q": "زار قصر السيد سعيد بن سلطان:", "opts": ["جورج كيبل", "نيركس"], "a": 0}, {"q": "تحرّرت عمان من البرتغاليين سنة:", "opts": ["1295م", "1650م"], "a": 1}, {"q": "(في سيارة) حال:", "opts": ["شبه جملة", "مفردة"], "a": 0}, {"q": "(وهو يركض) رابطها:", "opts": ["الواو والضمير", "الضمير وحده"], "a": 0}, {"q": "الأصل في صاحب الحال:", "opts": ["التنكير", "التعريف"], "a": 1}, {"q": "(شدّتني قصةٌ قصيرةٌ مثيرةً) المسوّغ:", "opts": ["التخصيص بوصف", "النفي"], "a": 0}, {"q": "أيهما أسبق ظهورًا؟", "opts": ["النقد", "الأدب"], "a": 1}, {"q": "الذوق المعتبر في النقد:", "opts": ["الذوق الخاص", "الذوق المصقول"], "a": 1}, {"q": "حجم التلخيص المفضّل:", "opts": ["ثلث النص", "نصف النص"], "a": 0}, {"q": "شاعر «إلى أمي»:", "opts": ["أمل دنقل", "محمود درويش"], "a": 1}]}}, {"id": "u4", "axis": "قضايا معاصرة", "axisN": 2, "unitN": 1, "title": "الوحدة الأولى", "theme": "صون الفكر وفجر السلام", "pages": "73–96", "lessons": [{"type": "القراءة", "title": "الملكية الفكرية", "page": 75, "hook": "قصيدة كتبتِها، أو تصميم ابتكرتِه، أو برنامج صنعتِه… هل هو ملكٌ لكِ كما يملك الناس بيوتهم؟", "about": "نص معلوماتي يبدأ بالحقوق والواجبات وأنواع الحقوق وحق الملكية، ثم يعرّف الملكية الفكرية بنوعيها ووسائل حمايتها ومجالاتها، وانضمام السلطنة إلى المنظمة العالمية للملكية الفكرية (الوايبو). والنص مأخوذ بتصرف من كتب جمال الخولي وجورج جبور وجابر بن مرهون فليفل.", "idea": "للإنسان حق في ثمرة فكره كما له حق في ممتلكاته المادية، وتحمي القوانين الوطنية والدولية هذا الحق.", "cards": [{"icon": "⚖️", "title": "العقد الاجتماعي", "text": "تقوم المجتمعات الحضارية على التعاون واحترام حقوق الفرد والجماعة، وينظّم ذلك: الشرائع السماوية، والقوانين الوضعية، والعرف العام. والالتزام بالواجبات يسمى «المسؤولية»، ومن أخلّ بها تعرّض للمساءلة، وفي مقابلها حقوق هي وسيلة الأفراد للحياة.", "quote": "هذا العقد الاجتماعي تنظمه الشرائع السماوية، والقوانين الوضعية، والعرف العام."}, {"icon": "🗂️", "title": "أنواع الحقوق", "text": "الحقوق نوعان: عامة تشمل أفراد المجتمع كافة (كالسياسية والاجتماعية)، وخاصة يكتسبها أفراد بعينهم (كحقوق الأسرة والحقوق المالية). والحقوق المالية ثلاث فئات: عينية، وشخصية (التزام)، ومعنوية (ذهنية أو أدبية)."}, {"icon": "🏠", "title": "حق الملكية", "text": "من أهم الحقوق العينية الأصلية. عناصره ثلاثة: الاستعمال، والاستغلال، والتصرف، ويسميها الفقه الإسلامي «المُلك التام». حرصت الشريعة على تأكيده، وأوصى به الإعلان العالمي لحقوق الإنسان، ونصّ عليه مشروع الإعلان العربي لحقوق الإنسان.", "quote": "وتُعرَّف الملكية بأنها: سلطة التمتع المطلق بشيء مادي معين، التي يحوزها صاحب هذا الشيء."}, {"icon": "💡", "title": "نوعا الملكية الفكرية", "text": "الملكية الصناعية: براءات الاختراع، والنماذج والرسوم الصناعية، وأسماء المحلات التجارية، والإشارات المميزة. والملكية الأدبية والفنية: القصص، والأشعار، والكتابات العلمية، والنصوص المسرحية، والأفلام، والتأليف، والموسيقى، والرسم، والنحت. ويصعب الفصل بينهما لأن الأعمال الفنية يزداد استخدامها في الصناعة."}, {"icon": "🛡️", "title": "لماذا نحميها؟ وكيف؟", "text": "تُحمى الملكيتان لحماية الفرد ماديًّا ومعنويًّا، وحماية حقوق المؤلفين والمخترعين والمكتشفين والمبتكرين. وتتحقق الحماية بوسيلتين: الأولى الحصول على تصريح من مالك الحق الفكري، والثانية أن يدفع المنتفع ثمنًا لهذا الانتفاع."}, {"icon": "🇴🇲", "title": "السلطنة والوايبو", "text": "في 19 نوفمبر 1996م أودعت سلطنة عمان وثائق طلب الانضمام إلى المنظمة العالمية للملكية الفكرية (الوايبو)، وفي 19 فبراير 1997م أصبحت عضوًا فيها، وصدر المرسوم السلطاني 74/96 الذي يعلن التزام السلطنة بقانون الملكية الفكرية."}, {"icon": "🤝", "title": "قيمٌ نتعلّمها", "text": "احترام الملكية الفكرية دليل رقيّ في التعامل، ويشيع الأمن والثقة فيطمئن كل فرد على نتاج فكره. أما نقل فقرة دون توثيق أو طبع شعار دون ترخيص فانتهاك لحقوق الآخرين يضيّعها وينشر الفوضى."}], "table": {"title": "الحقوق المالية الثلاث", "head": ["النوع", "معناه كما في النص", "مثال"], "rows": [["الحقوق العينية", "سلطة يقرها القانون على شيء مادي معين يباشرها صاحبها دون وساطة", "حق الملكية"], ["الحقوق الشخصية أو الالتزام", "رابطة قانونية بين شخصين: دائن ومدين، يطالب الدائن مدينه بعمل أو بامتناع عن عمل", "الدَّين بين شخصين"], ["الحقوق المعنوية أو الذهنية أو الأدبية", "سلطة لشخص على شيء غير مادي هو ثمرة فكره أو خياله أو نشاطه", "حق المؤلف، والفنان، والمخترع، والتاجر في اسمه وعلامته التجارية"]]}, "vocab": [{"w": "الوَضْعِيَّة (و ض ع)", "m": "القوانين الوضعية: هي التي وضعها البشر"}, {"w": "تَكْفُلُها (ك ف ل)", "m": "تضمنها"}, {"w": "الحق العَيْنيّ (ع ي ن)", "m": "الحق المادي الملموس المرئي بالعين المجردة"}, {"w": "العَقْد (في: العقد الاجتماعي)", "m": "الاتفاق الذي يُعقد بين طرفين"}, {"w": "الحِيازة", "m": "الضم والتملك"}], "tip": "💡 فرّقي جيدًا: العيني على شيء «مادي»، والمعنوي على شيء «غير مادي» هو ثمرة الفكر. ووسيلتا الحماية: «التصريح» ثم «دفع الثمن».", "keyPoints": ["ينظم العقد الاجتماعي: الشرائع السماوية، والقوانين الوضعية، والعرف العام.", "الحقوق المالية: عينية، وشخصية (التزام)، ومعنوية (ذهنية أو أدبية).", "عناصر حق الملكية: الاستعمال والاستغلال والتصرف = «المُلك التام».", "الملكية الفكرية: صناعية، وأدبية فنية؛ وتُحمى بالتصريح ودفع الثمن.", "طلب الانضمام للوايبو 19/11/1996م، والعضوية 19/2/1997م، والمرسوم السلطاني 74/96."], "check": [{"q": "عناصر حق الملكية التي يسميها الفقه الإسلامي «المُلك التام» هي:", "opts": ["الاستعمال والاستغلال والتصرف", "التصريح ودفع الثمن", "الشرائع والقوانين والعرف"], "a": 0, "explain": "نصّ الدرس: الملكية حق عيني يتمثل في ثلاثة عناصر: الاستعمال والاستغلال والتصرف، وهي التي يطلق عليها الفقه الإسلامي «المُلك التام». أما التصريح ودفع الثمن فوسيلتا حماية الملكية الفكرية."}, {"q": "متى أصبحت سلطنة عمان عضوًا في المنظمة العالمية للملكية الفكرية؟", "opts": ["19 نوفمبر 1996م", "19 فبراير 1997م", "عام 1929م"], "a": 1, "explain": "في 19 نوفمبر 1996م أودعت السلطنة وثائق طلب الانضمام فقط، ثم أصبحت عضوًا في 19 فبراير 1997م."}]}, {"type": "الأنشطة النحوية", "title": "المعاجم اللغوية (تعريف بها، وتدريب على استعمالها)", "page": 81, "hook": "صادفتِ كلمة «يسترفد» في بيت شعر… من أين تبدئين البحث عنها في لسان العرب؟", "about": "درس لغوي يعرّف بالمعاجم العربية ونوعيها، ويشرح الاتجاهات الثلاثة في ترتيب معاجم الألفاظ، ثم يدرّب على البحث فيها برد الكلمة إلى جذرها ومعرفة نظام ترتيب المعجم.", "idea": "لكي تستفيدي من المعجم تحتاجين أمرين: معرفة جذر الكلمة، ومعرفة نظام ترتيب المعجم الذي بين يديك.", "cards": [{"icon": "📚", "title": "لماذا المعاجم؟", "text": "المعاجم مراجع لا غنى عنها، يستوي في الحاجة إليها الناشئ المتعلم والمعلم والباحث المنقب. وتنوعها وتجددها وانتشار استعمالها بين الأفراد دليل على حيوية الأمة وحيوية لغتها."}, {"icon": "🔎", "title": "نوعا المعاجم", "text": "معاجم الألفاظ: تكشف معنى لفظة نجهلها، وتفيد أيضًا في ضبط الألفاظ، والكشف عن أعلام الأشخاص والقبائل والأماكن. ومعاجم المعاني: تساعدنا على إيجاد لفظ لمعنى يدور في أذهاننا ولا ندري كيف نعبّر عنه بدقة."}, {"icon": "👄", "title": "الاتجاه الأول: مخارج الحروف", "text": "ترتيب الأبواب بحسب مخارج الحروف مع مراعاة أوائل الجذور. رائده «معجم العين» للخليل بن أحمد الفراهيدي الأزدي العماني (توفي 175هـ): بدأ بحروف الحلق، فاللسان، فالأسنان، فالشفتين، وسمّى كل حرف بابًا.", "quote": "فمثلا (عكف) في باب العين، و(قذف) في باب القاف، و(لكم) في باب اللام."}, {"icon": "🔤", "title": "الاتجاه الثاني: أوائل الجذور", "text": "ترتيب هجائي (الهمزة، فالباء، فالتاء…) بحسب أوائل الجذور. من معاجمه: مقاييس اللغة والمجمل لابن فارس، وجمهرة اللغة لابن دريد، وأساس البلاغة للزمخشري، والمصباح المنير للفيومي، وحديثًا «المعجم الوسيط» لمجمع اللغة العربية بالقاهرة.", "quote": "فالجذر (س أ ل) يرد في باب السين، والجذر (ط ر ق) يرد في باب الطاء."}, {"icon": "🔚", "title": "الاتجاه الثالث: أواخر الجذور", "text": "ترتيب هجائي بحسب الحرف الأخير من الجذر. أول من استعمله الجوهري (توفي 393هـ) في «الصحاح»، وسار عليه ابن منظور المصري (توفي 711هـ) في «لسان العرب»، والفيروزأبادي (توفي 817هـ) في «القاموس المحيط»، والزَّبيدي (توفي 1205هـ) في «تاج العروس».", "quote": "فالجذر (م ل أ) يكون في باب الهمزة، والجذر (ص ب ر) يكون في باب الراء."}, {"icon": "🧭", "title": "طريقة البحث: أمران", "text": "الأول: ردّ الكلمة إلى أصلها (جذرها) بتجريدها من حروف الزيادة، مع معرفة ما أصابها من إعلال أو إبدال أو إدغام. والثاني: معرفة طريقة ترتيب المفردات في المعجم المستخدم. والمعرفة النظرية قليلة الجدوى إن لم تُدعَم بالتطبيق."}, {"icon": "🌟", "title": "ميزة أساس البلاغة", "text": "معجم أساس البلاغة للزمخشري (توفي 538هـ) من المعاجم المتداولة، وقد عُني مؤلفه بذكر المعاني المجازية للألفاظ إلى جانب معانيها الحقيقية."}], "table": {"title": "أين أبحث عن الكلمة؟ (أمثلة الكتاب)", "head": ["الكلمة", "الجذر", "معجم أوائل الجذور (الوسيط/أساس البلاغة/المصباح)", "لسان العرب (أواخر الجذور)"], "rows": [["سمك", "س م ك", "باب السين فصل الميم فالكاف", "باب الكاف فصل السين فالميم"], ["لعق", "ل ع ق", "باب اللام فصل العين فالقاف", "باب القاف فصل اللام فالعين"], ["الدهناء", "د هـ ن", "باب الدال فصل الهاء فالنون", "باب النون فصل الدال فالهاء"], ["الترادف", "ر د ف", "باب الراء فصل الدال فالفاء", "باب الفاء فصل الراء فالدال"], ["المقال", "ق و ل", "—", "—"], ["السماء", "س م و", "—", "—"]]}, "tip": "💡 في معاجم الأواخر (الصحاح، لسان العرب، القاموس المحيط، تاج العروس): الباب = الحرف الأخير، ثم الفصل = الحرف الأول. وجرّدي الكلمة من الزوائد أولًا: «المقال» جذرها (ق و ل) لا (م ق ل).", "keyPoints": ["المعاجم نوعان: معاجم ألفاظ، ومعاجم معانٍ.", "مخارج الحروف: معجم العين للخليل بن أحمد الفراهيدي العماني.", "أوائل الجذور: مقاييس اللغة، المجمل، جمهرة اللغة، أساس البلاغة، المصباح المنير، المعجم الوسيط.", "أواخر الجذور: أولها الصحاح للجوهري، ثم لسان العرب، والقاموس المحيط، وتاج العروس.", "البحث يتطلب: رد الكلمة إلى جذرها، ومعرفة نظام ترتيب المعجم."], "check": [{"q": "أول من رتّب معجمه بحسب أواخر الجذور هو:", "opts": ["الخليل بن أحمد في العين", "الجوهري في الصحاح", "الزمخشري في أساس البلاغة"], "a": 1, "explain": "نصّ الدرس: «وأول من استعملها الجوهري (توفي 393هـ) في معجمه الصحاح». الخليل رتّب بمخارج الحروف، والزمخشري بأوائل الجذور."}, {"q": "نبحث عن كلمة «الترادف» في لسان العرب في:", "opts": ["باب الراء فصل الدال فالفاء", "باب الدال فصل الراء فالفاء", "باب الفاء فصل الراء فالدال"], "a": 2, "explain": "1) الجذر (ر د ف). 2) لسان العرب يرتب بأواخر الجذور، فالباب: الفاء. 3) ثم الفصل: الراء فالدال. أما «باب الراء فصل الدال فالفاء» فمكانها في المعجم الوسيط."}]}, {"type": "النصوص الأدبية", "title": "فجر السلام", "page": 86, "hook": "انتهت الحرب العالمية الثانية… فهل يطلع فجر سلام حقيقي، أم يكون فجرًا كاذبًا؟", "about": "قصيدة للشاعر محمود غنيم كتبها في أعقاب الحرب العالمية الثانية، ونشرها في مجلة الثقافة بتاريخ 29 من مايو سنة 1945، يبدي فيها أملًا مشوبًا بالحذر أن تكون نهاية الحرب إيذانًا بفجر جديد يعم فيه السلام المخلّص للإنسانية من شقائها.", "author": {"name": "محمود غنيم (1902–1972م)", "bio": "وُلد بمحافظة المنوفية بمصر، ودرس في معهد القضاء الشرعي وكلية دار العلوم، وحصل على الدبلوم عام 1929. يُعدّ من رواد المسرح الشعري بعد شوقي، واختير عضوًا بلجنة الشعر، واتجه نحو تطويع الشعر التقليدي لمقتضيات العصر مع المحافظة على شكله."}, "idea": "يستغيث الشاعر بالسلام لينقذ العالم من ويلات الحرب، ويدعو إلى قيم جديدة تجعل البطولة في الإصلاح لا في سفك الدماء.", "cards": [{"icon": "🌅", "title": "المحور الأول (1–4): استغاثة بالسلام", "text": "يخاطب الشاعر السلام طالبًا منه تخليص العالم من كروبه، لكن خطابه مشوب بالحذر والخوف من أن يكون السلام أملًا بعيد المنال؛ والجملة الاعتراضية «إن تحقق» تكشف تخوّفه من عدم تحققه.", "quote": "أَدْرِكْ بفَجْرِكَ عالَماً مَكْرُوبا ... عَوَّذْتُ فَجْرَكَ أنْ يكونَ كَذُوبا\nيا أيُّها السِّلْمُ المُطِلُّ على الوَرَى ... طُوبى لعَهْدِكَ - إنْ تَحَقَّقَ - طُوبى"}, {"icon": "🌸", "title": "السلام زهرٌ ونسيم", "text": "طال ليل الحرب حتى تساقطت النفوس تعبًا، ولفحت نارها الوجوه؛ فيدعو الشاعر السلام أن يطوف بها كما يفوح الزهر ويهبّ النسيم، دلالة على المعاني الإيجابية التي يحملها السلام للبشرية.", "quote": "لَفَحَتْ لَظَى الحربِ الوجُوهَ ، فَطُفْ بها ... كالزهرِ نَفْحاً ، والنسيمِ هُبُوبا"}, {"icon": "⚙️", "title": "المحور الثاني (5–8): دمار الحرب", "text": "الحرب كالرحى تطحن الفريقين، فنتائجها مهلكة للغالب والمغلوب. وأمم بنت الحضارة لم تقصّر في تخريبها، والقوي فرض رقابته على الضعيف، والقوت صار سببًا في إبادة الممالك والشعوب.", "quote": "طَحَنَتْ فريقَيْها الحروبُ بضِرْسِها ... لا غالباً رحمتْ ولا مغلوبا"}, {"icon": "🏅", "title": "المحور الثالث (9–14): البطولة الحقّة", "text": "يرفض الشاعر أن يُنعت القاتل الفاتك بالبطولة، ويدعو إلى جعل سفك الدماء ذنوبًا لا مفاخر؛ فالباسل الحقيقي مصلح يملأ الحياة طيبًا: عالم متضلّع، أو شاعر موهوب.", "quote": "لا تجعلوا سَفْكَ الدِّماءِ مناقِباً ... للفاتحين ، بل اجعلوه ذُنُوبا\nما الباسلُ المغوارُ إلا مُصْلِحٌ ... مَلأَ الحياةَ على البريَّةِ طِيبا"}, {"icon": "📜", "title": "سلامٌ حقيقي لا ورقي (15–17)", "text": "يريد الشاعر جوهر السلام لا لفظه ولا صكّه المكتوب، ويعتذر عن شكّ من عرفوا السياسة لعوبًا بالكلام؛ فكم من مواثيق سلام عبثت بها رياح السياسة.", "quote": "إنا نُريدُ من السلامِ لُبابَهُ ... لا لَفْظَهُ ، أو صَكَّهُ المكتوبا"}, {"icon": "❤️", "title": "العاطفة", "text": "أمل في طلوع فجر السلام مشوب بالحذر والخوف من أن يكون كاذبًا، مع إدانة للحرب وتشهير بها وبمن يمجّدون القتلة، وإعلاء لقيم السلام."}, {"icon": "🎨", "title": "الصور والأسلوب", "text": "ينبني النص على ثنائية متضادة: الحرب والسلام. وأسلوبه يقوم على الخطاب المباشر، وصوره وألفاظه مستمدة من الشعر القديم: «طال الليل»، «كالزهر نفحًا»، «طحنت الحروب بضرسها»، «يحكي الوحوش»؛ ومعجمه قديم: الورى، طوبى، السرى، لغوبا، لظى، حتّام، بذّ."}], "table": {"title": "محاور القصيدة (دليل المعلم)", "head": ["المحور", "الأبيات", "فكرته"], "rows": [["الأول", "1–4", "الشاعر يستغيث بالسلام رمزًا للخلاص والمنقذ من الكروب"], ["الثاني", "5–8", "الدمار والخراب الذي تخلّفه الحرب"], ["الثالث", "9–17", "بناء قيم جديدة على أنقاض قيم قديمة"]]}, "vocab": [{"w": "مَكْرُوبًا (ك ر ب)", "m": "مغمومًا، محزونًا"}, {"w": "الوَرَى (و ر ي)", "m": "الخلق"}, {"w": "طُوبَى (ط ي ب)", "m": "كل مستطاب وخير"}, {"w": "السُّرَى (س ر ي)", "m": "سير عامة الليل"}, {"w": "لُغُوبًا (ل غ ب)", "m": "تعبًا"}, {"w": "لم تَأْلُ (أ ل و)", "m": "لم تُقصّر ولم تُبطئ"}, {"w": "يُبِيد (ب ي د)", "m": "يهلك"}, {"w": "فاتِكًا (ف ت ك)", "m": "شديد الفتك (القوة والغلبة)"}, {"w": "بَذَّ (ب ذ ذ)", "m": "فاق"}, {"w": "سامُوا (س و م)", "m": "سامه القتل: أولاه إياه وألحقه به"}, {"w": "المِغْوار (غ و ر)", "m": "صيغة مبالغة: المقاتل الكثير الغارات على أعدائه"}, {"w": "خامَرَ (خ م ر)", "m": "خالط"}], "tip": "💡 «لم تألُه تخريبًا» معناها: لم تقصّر في تخريبه، لا «لم تتألم». والمطلوب حفظه: الأبيات من 9 إلى 16.", "keyPoints": ["المحاور: الاستغاثة بالسلام (1–4)، دمار الحرب (5–8)، بناء قيم جديدة (9–17).", "الجملة الاعتراضية «إن تحقق» تدل على تخوّف الشاعر من عدم تحقق السلام.", "شبّه السلام بالزهر نفحًا والنسيم هبوبًا، وشبّه الحرب بالرحى تطحن الفريقين.", "البطل الحقيقي عند الشاعر هو المصلح: العالم المتضلع أو الشاعر الموهوب.", "بناء النص بلاغيًّا ومعجميًّا وإيقاعيًّا مستمد من الديوان الشعري القديم."], "check": [{"q": "بمَ شبّه الشاعر السلام في البيت الرابع؟", "opts": ["بالزهر في نفحه والنسيم في هبوبه", "بالرحى التي تطحن", "بالليل الطويل"], "a": 0, "explain": "قال: «فَطُفْ بها كالزهرِ نَفْحاً، والنسيمِ هُبُوبا»؛ فالمشبه السلام، والمشبه به الزهر والنسيم، والدلالة قيمة المعاني الإيجابية التي يحملها السلام. أما الرحى فصورة الحرب."}, {"q": "ماذا أفادت الجملة الاعتراضية «- إن تحقق -» في البيت الثاني؟", "opts": ["ثقة الشاعر بأن السلام تحقق", "تخوّف الشاعر من عدم تحقق السلام", "مدح الفاتحين"], "a": 1, "explain": "الشاعر يبارك عهد السلام بشرط تحققه، وهذا الشرط يكشف خوفه من ألا يتحقق، كما في دليل المعلم."}]}, {"type": "التعبير", "title": "محضر الاجتماعات", "page": 91, "hook": "اجتمعت جماعة اللغة العربية واتفقت على رحلة ومسابقات… فمن يحفظ هذه القرارات حتى لا تضيع؟", "about": "درس في التعبير الكتابي الوظيفي يعرّف محضر الاجتماع، ويبيّن نوعي الاجتماعات ومراحل إدارتها الثلاث وعناصر المحضر، ثم يعرض نموذجًا لمحضر الاجتماع الأول لجماعة اللغة العربية.", "idea": "المحضر توثيق مكتوب لما دار في الاجتماع من مداولات وقرارات، يكتبه المقرر وفق عناصر محددة.", "cards": [{"icon": "📝", "title": "ما المحضر؟", "text": "تسجيل لما يدور في جلسة عمل لمجموعة من المختصين من إدارة أو أكثر، يتولاه أحدهم ويسمى «المقرّر». وفي كل اجتماع رسمي رئيس للاجتماع، وأمين للسر يدوّن المداولات والقرارات، ويسمى عمله «محضر اجتماع»."}, {"icon": "🔁", "title": "نوعا الاجتماعات", "text": "الدورية: تُعقد بصورة دورية أسبوعية أو شهرية أو سنوية، ويغلب عليها الطابع الرسمي، كاللجان الدائمة والمجالس. وغير الدورية: تُعقد كلما دعت الحاجة، دون وقت محدد، لبحث مشاكل أو مواضيع طارئة."}, {"icon": "🎯", "title": "قبل الانعقاد: الهدف والمدعوون", "text": "حدّدي هدف الاجتماع، ثم من سيُدعى إليه. وشروط المدعو: صلته بالموضوع، وخبرته وإلمامه به، ورغبته في المشاركة، وقدرته على العمل الجماعي، وألا يفرض رأيه على الآخرين، وألا يعجز عن الحديث أمامهم."}, {"icon": "📋", "title": "قبل الانعقاد: جدول الأعمال", "text": "يعدّه رئيس الاجتماع والمقرر، ويتضمن: الهدف، والتاريخ، والمدة، ومكان الانعقاد، وأسماء المشاركين، ومواضيع المناقشة الروتينية، ومواضيع النقاش الصعبة أو القابلة للجدل، وأي أعمال أخرى تستجد."}, {"icon": "🗣️", "title": "أثناء الانعقاد: الأدوار", "text": "العضو: يعرف الهدف، ويقرأ المعلومات مسبقًا، ويحضر في موعده أو يعتذر ويُنيب غيره، ويستأذن قبل الكلام بموضوعية. والرئيس: يفتتح في الموعد مرحّبًا ويحصر الغائبين، ويطرح الموضوعات، ويوجّه النقاش، ويبلوره نحو الإجماع، ويختتم بتلخيص النتائج والشكر وتكليف المهام."}, {"icon": "🖊️", "title": "بعد الانعقاد: التوثيق", "text": "يجب فور انتهاء الاجتماع إعداد محضر مطبوع يتضمن سبعة عناصر (انظري الجدول)، تبدأ بعنوان يحدد الموضوع والتاريخ والمكان، وتنتهي بتحديد نهاية الاجتماع وموعد الاجتماع التالي."}, {"icon": "📄", "title": "نموذج الكتاب", "text": "محضر الاجتماع الأول لجماعة اللغة العربية: يبدأ بالحمد والصلاة، ثم الزمان والمكان والرئيس والحضور، ثم عرض جدول الأعمال، ثم القرارات، ثم موعد الاجتماع القادم، وتوقيع المقرر ورئيس الجماعة.", "quote": "وبعد مناقشة جدول الأعمال خرج المجتمعون بالقرارات الآتية"}], "table": {"title": "عناصر محضر الاجتماع ومثالها في النموذج", "head": ["العنصر", "مثاله في نموذج الكتاب"], "rows": [["1- عنوان يشير إلى الموضوع والتاريخ والمكان", "محضر الاجتماع الأول لجماعة اللغة العربية، الساعة العاشرة صباحًا يوم الأحد، في مقر النشاط"], ["2- أسماء المشاركين", "وبحضور أعضاء الجماعة: 1- … 2- … 3- … 4- …"], ["3- اعتذارات من لم يحضروا", "لم ترد في النموذج"], ["4- اسم رئيس الاجتماع", "برئاسة مشرف الجماعة الأستاذ: …"], ["5- جدول الأعمال", "تشكيل مجلس الجماعة، تحديد مهام الأعضاء، وضع برنامج العمل، مناقشة الرحلة، ما يستجد من أعمال"], ["6- ملخص ما اتُّفق عليه في كل بند", "اختيار رئيس للجماعة ونائب له، برنامج العمل، رحلة إلى الجبل الأخضر"], ["7- نهاية الاجتماع وموعد الاجتماع التالي", "واتفق على أن يكون الاجتماع القادم يوم …"]]}, "tip": "💡 لا تنسي «اعتذارات الغائبين» و«موعد الاجتماع التالي» و«التوقيعات»؛ فهي عناصر يكثر إغفالها. وصيغ القرارات في النموذج: اختير، اقترح، اتفق.", "keyPoints": ["المحضر: تسجيل ما يدور في جلسة عمل، ويكتبه المقرر (أمين السر).", "الاجتماعات: دورية (طابع رسمي، مواعيد منتظمة)، وغير دورية (عند الحاجة).", "مراحل إدارة الاجتماع: قبل الانعقاد، وأثناءه، وبعده (التوثيق).", "جدول الأعمال يعدّه رئيس الاجتماع والمقرر.", "للمحضر سبعة عناصر، أولها العنوان وآخرها موعد الاجتماع التالي."], "check": [{"q": "الاجتماعات التي تُعقد كلما دعت الحاجة لبحث مواضيع طارئة هي:", "opts": ["الاجتماعات الدورية", "الاجتماعات غير الدورية", "اللجان الدائمة"], "a": 1, "explain": "غير الدورية ليس لها وقت محدد، وتعقد عند الحاجة. أما الدورية فمنتظمة، ومن أمثلتها اللجان الدائمة."}, {"q": "من يعدّ جدول أعمال الاجتماع؟", "opts": ["رئيس الاجتماع والمقرر", "الأعضاء المدعوون", "أي حاضر يتطوع"], "a": 0, "explain": "نصّ الكتاب في المرحلة الأولى: «إعداد جدول أعمال الاجتماع: (رئيس الاجتماع والمقرر)»."}]}], "activities": [{"kind": "mcq", "lesson": 1, "q": "ما معنى كلمة «العقد» في قوله: (العقد الاجتماعي)؟", "opts": ["ما ترتديه الفتاة حول عنقها للزينة", "الاتفاق الذي يُعقد بين طرفين", "وصل طرفي الحبل بعقدة تمسكهما", "الأعداد من العشرين إلى التسعين"], "a": 1, "explain": "1) السياق يتحدث عن تنظيم العلاقات بين أفراد المجتمع بالحقوق والواجبات. 2) فالعقد هنا معنويّ لا حسيّ؛ أي اتفاق يلتزم به الطرفان. 3) أما القلادة ووصل الحبل والعقود العددية فمعانٍ أخرى للكلمة لا تناسب السياق."}, {"kind": "classify", "lesson": 1, "title": "صنّفي ما يأتي بحسب نوع الملكية الفكرية التي ينتمي إليها", "groups": ["الملكية الصناعية", "الملكية الأدبية والفنية"], "items": [["براءات الاختراع", 0], ["النماذج والرسوم الصناعية", 0], ["أسماء المحلات التجارية", 0], ["الإشارات المميزة", 0], ["القصص والأشعار", 1], ["النصوص المسرحية", 1], ["الموسيقى", 1], ["الرسم والنحت", 1]]}, {"kind": "tf", "lesson": 1, "q": "أصبحت سلطنة عُمان عضوًا في المنظمة العالمية للملكية الفكرية (الوايبو) في 19 فبراير 1997م.", "a": true, "explain": "1) في 19 نوفمبر 1996م أودعت السلطنة وثائق طلب الانضمام. 2) وفي 19 فبراير 1997م أصبحت عضوًا في المنظمة. 3) وصدر المرسوم السلطاني (74/96) معلنًا التزامها بقانون الملكية الفكرية؛ فالعبارة صحيحة."}, {"kind": "match", "lesson": 2, "title": "صِلي كل معجم بمؤلفه", "pairs": [["معجم العين", "الخليل بن أحمد الفراهيدي"], ["الصحاح", "الجوهري"], ["لسان العرب", "ابن منظور"], ["القاموس المحيط", "الفيروزأبادي"], ["أساس البلاغة", "الزمخشري"], ["مقاييس اللغة", "ابن فارس"]]}, {"kind": "classify", "lesson": 2, "title": "صنّفي المعاجم بحسب طريقة ترتيبها", "groups": ["مخارج الحروف", "الهجائي بأوائل الجذور", "الهجائي بأواخر الجذور"], "items": [["معجم العين", 0], ["أساس البلاغة", 1], ["المصباح المنير", 1], ["المعجم الوسيط", 1], ["مقاييس اللغة", 1], ["الصحاح", 2], ["لسان العرب", 2], ["القاموس المحيط", 2], ["تاج العروس", 2]]}, {"kind": "mcq", "lesson": 2, "q": "أين نبحث عن كلمة «يسترفد» في لسان العرب؟", "opts": ["باب الراء فصل الفاء فالدال", "باب الياء فصل السين فالتاء", "باب الدال فصل الراء فالفاء", "باب الفاء فصل الراء فالدال"], "a": 2, "explain": "1) نجرّد الكلمة من الزوائد (الياء والسين والتاء) فيبقى الجذر (ر ف د). 2) لسان العرب يرتب الجذور بحسب أواخرها، فالباب هو حرفها الأخير: الدال. 3) والفصل هو الحرف الأول: الراء، ثم الحرف الثاني: الفاء. 4) فنبحث في «باب الدال فصل الراء فالفاء»."}, {"kind": "fill", "lesson": 3, "q": "رُحْماكَ طالَ الليلُ واتَّصَلَ ____ ... حتى تساقَطَتِ النفوسُ لُغُوبا", "opts": ["المدى", "السُّرى", "الأسى"], "a": 1, "explain": "1) هذا البيت الثالث من القصيدة كما في الكتاب. 2) «السُّرى» هو سير عامة الليل، ويناسب قوله «طال الليل». 3) والمعنى أن ليل الحرب طال والسير فيه اتصل حتى سقطت النفوس من التعب (لغوبا)."}, {"kind": "order", "lesson": 4, "title": "رتّبي عناصر محضر الاجتماع كما وردت في الدرس", "items": ["عنوان يشير إلى موضوع الاجتماع وتاريخه ومكانه", "قائمة بأسماء المشاركين", "اعتذارات من لم يحضروا", "اسم رئيس الاجتماع", "جدول الأعمال", "ملخص ما اتُّفق عليه في كل بند", "تحديد نهاية الاجتماع وموعد الاجتماع التالي"]}], "test": [{"lesson": 1, "q": "«رابطة قانونية بين شخصين: دائن ومدين، يطالب بمقتضاها الدائن مدينه بأن يقوم بعمل أو يمتنع عن عمل». هذا تعريف:", "opts": ["الحقوق العينية", "الحقوق المعنوية", "حق الملكية", "الحقوق الشخصية أو الالتزام"], "a": 3, "explain": "1) قسّم النص الحقوق المالية ثلاث فئات. 2) العينية: سلطة على شيء مادي معين. 3) المعنوية: سلطة على شيء غير مادي هو ثمرة الفكر. 4) أما الرابطة بين دائن ومدين فهي «الحقوق الشخصية أو الالتزام»."}, {"lesson": 1, "q": "عناصر حق الملكية التي يسميها الفقه الإسلامي «الملك التام» هي:", "opts": ["الاستعمال والاستغلال والتصرف", "الحيازة والبيع والهبة", "التصريح ودفع الثمن والتوثيق", "الاختراع والنشر والتسجيل"], "a": 0, "explain": "1) نصّ الدرس على أن الملكية حق عيني يخوّل صاحبه الاستئثار بكل منافع الشيء. 2) ويتمثل ذلك في ثلاثة عناصر: الاستعمال والاستغلال والتصرف. 3) وهذه العناصر هي ما يطلق عليه الفقه الإسلامي «الملك التام»."}, {"lesson": 1, "q": "لماذا يصعب الفصل بين الملكية الصناعية والملكية الأدبية الفنية؟", "opts": ["لأن القوانين لا تحمي إلا الملكية الصناعية", "لأن الأعمال الفنية يزداد استخدامها في الصناعة يومًا بعد يوم", "لأن الملكية الأدبية لا قيمة مادية لها", "لأن المنظمة العالمية ألغت التقسيم بينهما"], "a": 1, "explain": "1) يقول النص: «لا يمكن بالطبع الفصل بين الملكية الصناعية وبين الملكية الأدبية الفنية». 2) وعلّل ذلك بقوله: «إذ إن الأعمال الفنية يزداد استخدامها في الصناعة يومًا بعد يوم». 3) أما بقية الخيارات فلم ترد في النص."}, {"lesson": 2, "q": "ما جذر كلمة «المقال» الذي نبحث عنه في المعجم؟", "opts": ["م ق ل", "ق ا ل", "ق و ل", "ق ل ل"], "a": 2, "explain": "1) الميم في أول الكلمة زائدة (ميم المصدر الميمي). 2) والألف ليست أصلية بل منقلبة عن واو، بدليل: قال يقول قَوْلًا. 3) فالجذر (ق و ل)، وهو ما أثبته الكتاب في جدول التدريب."}, {"lesson": 2, "q": "نبحث عن كلمة «الدهناء» في لسان العرب في:", "opts": ["باب الدال فصل الهاء فالنون", "باب النون فصل الدال فالهاء", "باب الهمزة فصل الدال فالهاء", "باب الهاء فصل الدال فالنون"], "a": 1, "explain": "1) جذر الكلمة (د هـ ن)، والألف والهمزة زائدتان. 2) لسان العرب يرتب بحسب أواخر الجذور، فالباب: النون. 3) والفصل: الحرف الأول (الدال)، ثم الهاء. 4) أما «باب الدال فصل الهاء فالنون» فهو مكانها في المعجم الوسيط."}, {"lesson": 2, "q": "أول من رتّب معجمه هجائيًّا بحسب أواخر الجذور هو:", "opts": ["ابن منظور في لسان العرب", "الخليل بن أحمد في العين", "الزمخشري في أساس البلاغة", "الجوهري في الصحاح"], "a": 3, "explain": "1) نصّ الدرس: «وأول من استعملها الجوهري (ت 393هـ) في معجمه الصحاح». 2) وسار عليها بعده ابن منظور والفيروزأبادي والزبيدي. 3) أما الخليل فرتّب بمخارج الحروف، والزمخشري بأوائل الجذور."}, {"lesson": 2, "q": "المعجم الذي عُني مؤلفه بذكر المعاني المجازية للألفاظ إلى جانب معانيها الحقيقية هو:", "opts": ["أساس البلاغة", "تاج العروس", "جمهرة اللغة", "القاموس المحيط"], "a": 0, "explain": "1) ذكر الدرس أن «معجم أساس البلاغة من المعاجم المتداولة». 2) «وقد عني مؤلفه (الزمخشري) بذكر المعاني المجازية للألفاظ إلى جانب معانيها الحقيقية». 3) فالإجابة: أساس البلاغة."}, {"lesson": 3, "q": "ماذا أفادت الجملة الاعتراضية «- إن تحقق -» في قول الشاعر: «طُوبى لعَهْدِكَ - إنْ تَحَقَّقَ - طُوبى»؟", "opts": ["الدعاء على الحرب", "تخوّف الشاعر من عدم تحقق السلام", "التأكيد أن السلام قد تحقق فعلًا", "مدح الفاتحين"], "a": 1, "explain": "1) الجملة الاعتراضية جاءت بين «طوبى لعهدك» وتكرار «طوبى» لتقييد الفرحة بالسلام. 2) فالشاعر يبارك عهد السلام بشرط أن يتحقق. 3) وهذا الشرط يكشف خوفه من ألا يتحقق، كما نصّ دليل المعلم."}, {"lesson": 3, "q": "بمَ شبّه الشاعر السلام في قوله: «فَطُفْ بها كالزهرِ نَفْحًا، والنسيمِ هُبُوبا»؟", "opts": ["بالفجر الكاذب", "بالرحى التي تطحن", "بالزهر في رائحته والنسيم في هبوبه", "بالليل الطويل"], "a": 2, "explain": "1) المشبه: السلام (المخاطَب بقوله: فطُف). 2) المشبه به: الزهر في نفحه، والنسيم في هبوبه. 3) والدلالة: قيمة المعاني الإيجابية التي يحملها السلام للبشرية بعد أن لفحت لظى الحرب الوجوه."}, {"lesson": 3, "q": "ما معنى «لُغُوبا» في قوله: «حتى تساقَطَتِ النفوسُ لُغُوبا»؟", "opts": ["شوقًا", "خوفًا", "جوعًا", "تعبًا"], "a": 3, "explain": "1) ورد في معجم اللغويات: لغوبا (ل غ ب) = تعبًا. 2) والمعنى أن الليل (الحرب) طال حتى تساقطت النفوس من شدة التعب والإعياء."}, {"lesson": 4, "q": "الاجتماعات التي تُعقد كلما دعت الحاجة إليها لبحث مشكلات أو موضوعات طارئة هي:", "opts": ["الاجتماعات الدورية", "الاجتماعات غير الدورية", "اللجان الدائمة", "الاجتماعات السنوية"], "a": 1, "explain": "1) الاجتماعات نوعان. 2) الدورية: تُعقد بصورة منتظمة أسبوعية أو شهرية أو سنوية، ومنها اللجان الدائمة. 3) غير الدورية: ليس لها وقت محدد، وتُعقد عند الحاجة لبحث أمور طارئة."}, {"lesson": 4, "q": "يُسمّى من يدوّن ما ذُكر في الاجتماع من مداولات وقرارات:", "opts": ["رئيس الاجتماع", "عضو الاجتماع", "المقرّر (أمين السر)", "المدعوّ"], "a": 2, "explain": "1) في كل اجتماع رسمي لا بد من رئيس للاجتماع وأمين للسر. 2) أمين السر يدوّن المداولات والقرارات. 3) ويسمّى العمل الذي أنجزه المقرّر «محضر اجتماع»."}], "game": {"type": "roots", "words": [{"w": "مَكْرُوبًا", "root": "ك ر ب", "pick": ["م", "ك", "و", "ر", "ا", "ب"], "entry": "مادة (كرب): المعجم الوسيط باب الكاف، ولسان العرب باب الباء"}, {"w": "لُغُوبًا", "root": "ل غ ب", "pick": ["و", "ل", "ت", "غ", "ا", "ب"], "entry": "مادة (لغب): المعجم الوسيط باب اللام، ولسان العرب باب الباء"}, {"w": "فاتِكًا", "root": "ف ت ك", "pick": ["ا", "ف", "ق", "ت", "ل", "ك"], "entry": "مادة (فتك): المعجم الوسيط باب الفاء، ولسان العرب باب الكاف"}, {"w": "سامُوا", "root": "س و م", "pick": ["ا", "س", "ي", "و", "ن", "م"], "entry": "مادة (سوم): المعجم الوسيط باب السين، ولسان العرب باب الميم"}, {"w": "تَساقَطَتْ", "root": "س ق ط", "pick": ["ت", "س", "ا", "ق", "ن", "ط"], "entry": "مادة (سقط): المعجم الوسيط باب السين، ولسان العرب باب الطاء"}, {"w": "التَّرادُف", "root": "ر د ف", "pick": ["ت", "ر", "ا", "د", "ل", "ف"], "entry": "مادة (ردف): المعجم الوسيط باب الراء، ولسان العرب باب الفاء"}, {"w": "المَقال", "root": "ق و ل", "pick": ["م", "ق", "ا", "و", "ي", "ل"], "entry": "مادة (قول): المعجم الوسيط باب القاف، ولسان العرب باب اللام"}, {"w": "الصَّعِيد", "root": "ص ع د", "pick": ["ا", "ص", "ل", "ع", "ي", "د"], "entry": "مادة (صعد): المعجم الوسيط باب الصاد، ولسان العرب باب الدال"}, {"w": "يَسْتَرْفِدُ", "root": "ر ف د", "pick": ["ي", "س", "ر", "ت", "ف", "د"], "entry": "مادة (رفد): المعجم الوسيط باب الراء، ولسان العرب باب الدال"}, {"w": "أَتَبَلَّدُ", "root": "ب ل د", "pick": ["أ", "ب", "ت", "ل", "ن", "د"], "entry": "مادة (بلد): المعجم الوسيط باب الباء، ولسان العرب باب الدال"}]}}, {"id": "u5", "axis": "قضايا معاصرة", "axisN": 2, "unitN": 2, "title": "الوحدة الثانية", "theme": "حين ينتصر الفن", "pages": "97–118", "lessons": [{"type": "النصوص الأدبية", "title": "الصرح", "page": 97, "hook": "ملكٌ انتصر في الحرب، وملكٌ أسير يبني قصرًا… فمن المنتصر الحقيقي في النهاية؟", "about": "نص سردي من فن القصة القصيرة للكاتب كورت كوزنبرج، يشير إلى أن الانتصار السياسي والعسكري لا يساوي شيئًا أمام انتصار الفن والحضارة، من خلال شخصيتين محوريتين: البينام ومافالدو.", "author": {"name": "كورت كوزنبرج (1904م)", "bio": "وُلد في مدينة غوتبورك في السويد، كاتب رواية وقصة قصيرة جدًّا، له باع طويل في كتابة الدراسات عن الفنون المسرحية، ودرس تاريخ الفنون، وحصل على الدكتوراه في الآداب والفنون عام 1928. اختيرت قصته «الصرح» ضمن روائع القصص الألماني."}, "idea": "الانتصار العسكري زائل، أما الإنجاز الفني والحضاري فيخلّد صاحبه ويهزم الموت.", "cards": [{"icon": "⚔️", "title": "حربٌ بين جارين", "text": "بلدان متجاوران اقتصرت الحرب بينهما أولًا على المناوشات الحدودية، ثم انفجر الموقف حين اعتلى البينام العرش هنا ووصل مافالدو إلى السلطة هناك؛ ملكان شابان طموحان، مولعان بالتفوق، لا يقبلان النصح، فأُحيل مستشاروهما إلى التقاعد واستعرت الحرب.", "quote": "وسادَ سلامٌ ملغومٌ بينهما"}, {"icon": "🍀", "title": "نصرٌ بالحظ", "text": "لم يكن البينام يملك أفضل الجند ولا كان قائدًا محنّكًا، لكنه استغل حظه؛ فانهزمت جيوش مافالدو، ووقع هو ووزراؤه وقادته أسرى، وأحال المنتصر البلدين بلدًا واحدًا.", "quote": "وإنما سرُّ انتصارِه يكمنُ فقط في أنَّ له حظًّا في الحروب"}, {"icon": "🏰", "title": "أمنية الأسير", "text": "لم تعجب البينامَ فكرةُ قتل خصمه ولا نفيه؛ ليبرهن أنه لا يقيم له وزنًا، فجعله أسيرًا تُنفَّذ طلباته. فطلب مافالدو أن يشيّد صرحًا، فقال البينام: «ابنِ لنفسك الدار الأخيرة».", "quote": "إذا كان عليَّ أن أعيش لكي يضع الموتُ نهاية لذلك يومًا فأنا أرغبُ أن أشيّد لي صرحًا"}, {"icon": "👀", "title": "حديث كل لسان", "text": "بنى مافالدو صرحه بهدوء وتمهّل، فتوافدت جموع الشعب وزوار البلدان المجاورة مندهشين، وبالغ العمال في وصف فخامته، ولم يتحدث أحد عن أعمال البينام؛ فنبتت الغيرة في قلبه.", "quote": "الصَّرْحُ صار حديثَ كلِّ لسان"}, {"icon": "🔑", "title": "العقدة والحل", "text": "العقدة: إتمام مافالدو بناء الصرح، ورغبة البينام في سرقة جهده ولو بغرفة واحدة. فرفض مافالدو متمسكًا بالعهد. والحل: سأله البينام عن ثمن التنازل عن صرحه مقابل استقلال بلده، فأجاب: «بلا أي ثمن».", "quote": "بلدي أصبح حصتك ، ولكن صرحي ينبغي إلا يُخلدكَ … فحين تموتُ أنت ، سأحيا أنا"}, {"icon": "🎭", "title": "الشخصيتان", "text": "البينام شخصية نمطية لم تتطور: متعجرفة معتدة بنفسها، لا تؤمن إلا بمنطق القوة، وأفعالها قائمة على الإخضاع والقهر. ومافالدو شخصية نامية تتطور مع الأحداث، قوي الإرادة، حوّل اهتمامه من الهزيمة إلى الإبداع ومواجهة العدم."}, {"icon": "🗺️", "title": "الزمان والمكان", "text": "المكان عام غير محدد («بلدين متجاورين») ليمنح القصة أبعادًا رمزية، مع مكان محدد مغلق هو القصر احتفاءً بالإنجاز المعماري. والزمان غائم بلا معالم، وفيه زمنان داخليان: زمن الحرب والصراع، وزمن البناء."}], "table": {"title": "مقارنة بين الشخصيتين", "head": ["وجه المقارنة", "البينام", "مافالدو"], "rows": [["الصفات المشتركة", "ملك شاب طموح، مولع بالتفوق، لا يقبل النصح", "ملك شاب طموح، مولع بالتفوق، لا يقبل النصح"], ["نوع الشخصية", "نمطية ثابتة لم تتطور", "نامية تتطور مع الأحداث"], ["طريق المجد عنده (دليل المعلم)", "القتل والانتصار العسكري", "الفن والحضارة طريق الخلود"], ["المصير", "ينتصر عسكريًّا ثم تأكله الغيرة", "يحوّل هزيمته إلى انتصار للفن والحياة"]]}, "vocab": [{"w": "يُمْنَى (م ن ي)", "m": "يُبتلى"}, {"w": "التَّرَيُّث (ر ي ث)", "m": "التمهّل"}, {"w": "الغُلَواء (غ ل و)", "m": "غلواء الشيء: سُرعته وأوله"}, {"w": "حَدَجَه (ح د ج)", "m": "نظر إليه نظرة ارتياب واستنكار"}, {"w": "حَرِدَة (ح ر د)", "m": "حرد: اغتاظ فتحرّش بالذي غاظه وهمّ به"}], "tip": "💡 القصة قسمان: قصة مضمِّنة (الصراع العسكري)، وقصة مضمَّنة (الإنجاز الفني الذي يخلّد الإنسان ويتحدى الموت).", "keyPoints": ["مغزى القصة: الانتصار العسكري لا يساوي شيئًا أمام انتصار الفن والحضارة.", "سرّ انتصار البينام: حظه في الحروب واستغلاله له.", "البينام شخصية نمطية ثابتة، ومافالدو شخصية نامية.", "العقدة: رغبة البينام في سرقة جهد مافالدو، والحل: «بلا أي ثمن».", "المكان والزمان غير محددين لإعطاء القصة أبعادًا رمزية عامة."], "check": [{"q": "ما سرّ انتصار البينام على مافالدو؟", "opts": ["امتلاكه أفضل الجند", "حظه في الحروب واستغلاله له", "أنه قائد محنّك"], "a": 1, "explain": "تقول القصة: على المرء ألا يظن أن البينام يمتلك أفضل الجند أو كان قائدًا محنكًا، «وإنما سرُّ انتصاره يكمن فقط في أن له حظًّا في الحروب»."}, {"q": "الشخصية النامية التي تتطور مع الأحداث هي:", "opts": ["البينام", "وزراء البينام", "مافالدو"], "a": 2, "explain": "الإضاءة النقدية: البينام شخصية لم تتطور، أما مافالدو فـ«شخصية نامية تتطور مع الأحداث وتنفعل بالمستجدات»."}]}, {"type": "الأنشطة النحوية", "title": "التمييز: 1- تمييز الذات", "page": 106, "hook": "قالت ليلى: «حملت معي عشرين»، فسألتها فاطمة: «عشرين ماذا؟!»… ما الكلمة الناقصة؟", "about": "درس نحوي يعرّف التمييز، ويشرح نوعه الأول: تمييز الذات (المفرد)، وأشكال المميَّز المفرد الملفوظ: المقدار (كيل، وزن، مساحة)، وشبه المقدار، والعدد، ومتى يجوز جرّ التمييز.", "idea": "التمييز اسم نكرة منصوب يزيل الإبهام عن كلمة مفردة قبله تدل على مقدار أو شبهه أو عدد.", "cards": [{"icon": "🤔", "title": "كلمة مبهمة", "text": "كلمة «عشرين» تحتمل أشياء كثيرة؛ فلا يتضح معناها إلا بما يليها. ومثلها: صاع، رطل، فدان، قبضة يد، خمسين؛ فإذا أضفنا بعدها كلمة تحدد المقصود زال الغموض والإبهام.", "quote": "عشرين !!!! كتابا أم ملفا أم كراسا أم قلما أم ماذا يا ليلى ؟"}, {"icon": "📌", "title": "تعريف التمييز", "text": "الكلمة التي تزيل الإبهام تسمى «تمييزًا»، وتأتي منصوبة نكرة. والكلمة المبهمة قبلها تسمى «المميَّز».", "quote": "التمييز : اسم نكرة منصوب يُذْكَرُ تفسيرًا لمبهمٍ واقعٍ قبلَه."}, {"icon": "⚖️", "title": "المميَّز مقدار", "text": "المقدار ثلاثة: كيل (صاع، إردب، كيلة، قدح)، ووزن (رطل، أوقية)، ومساحة (فدان، قيراط، قصبة).", "quote": "طبخت سعاد وجبة الغداء بصاعٍ أرزًا."}, {"icon": "✋", "title": "المميَّز شبه مقدار", "text": "مثل: قبضة يد، مثقال ذرة، قدر راحة؛ فهي ليست مقاييس دقيقة لكنها تدل على كمية.", "quote": "حملت من الشاطئ قبضةَ يدي أصدافًا."}, {"icon": "🔢", "title": "المميَّز عدد", "text": "العدد مبهم يحتاج إلى تمييز يبيّن المعدود، كما في «خمسين كتابًا»، وفي قوله تعالى: ﴿إِنِّي رَأَيْتُ أَحَدَ عَشَرَ كَوْكَبًا﴾.", "quote": "والخمسون خمسون كتابا."}, {"icon": "🔄", "title": "متى يُجرّ التمييز؟", "text": "يجوز جرّه بالإضافة أو بـ«مِن» إذا كان المميَّز كيلًا أو وزنًا أو مساحة. ويجوز جره بـ«من» فقط إذا كان المميَّز مضافًا لغير التمييز: قبضة يدي أصدافًا، أو قبضة يدي من أصدافٍ.", "quote": "اشتريت من الدكان رطلا زيتا، أو رطلَ زيتٍ، أو رطلا من زيتٍ."}, {"icon": "🧩", "title": "الإعراب", "text": "يُعرب «تمييزًا منصوبًا». ففي ﴿إِنِّي رَأَيْتُ أَحَدَ عَشَرَ كَوْكَبًا﴾: أحد عشر: عدد مركب مبني على فتح الجزأين في محل نصب مفعول به، وكوكبًا: تمييز منصوب وعلامة نصبه الفتحة الظاهرة على آخره."}], "table": {"title": "أمثلة الكتاب", "head": ["المثال", "المميَّز ونوعه", "التمييز"], "rows": [["طبخت سعاد وجبة الغداء بصاعٍ أرزًا", "صاع: كيل", "أرزًا"], ["اشتريت من الدكان رطلًا زيتًا", "رطل: وزن", "زيتًا"], ["جنيت محصول فدانٍ قطنًا", "فدان: مساحة", "قطنًا"], ["حملت من الشاطئ قبضةَ يدي أصدافًا", "قبضة يد: شبه مقدار", "أصدافًا"], ["لدى سعيد مكتبة تضم خمسين كتابًا", "خمسين: عدد", "كتابًا"], ["﴿إِنِّي رَأَيْتُ أَحَدَ عَشَرَ كَوْكَبًا﴾", "أحد عشر: عدد", "كوكبًا"]]}, "tip": "💡 التمييز نكرة دائمًا: «رطلًا زيتًا» لا «رطلًا الزيتَ». وبعد «قبضة يدي» لا يُجرّ التمييز بالإضافة لأن «قبضة» مضافة إلى «يدي»، بل بـ«من» فقط.", "keyPoints": ["التمييز: اسم نكرة منصوب يُذكر تفسيرًا لمبهم واقع قبله.", "تمييز الذات (المفرد): المميَّز فيه اسم مفرد ملفوظ.", "المميَّز: مقدار (كيل، وزن، مساحة)، أو شبه مقدار، أو عدد.", "بعد الكيل والوزن والمساحة يجوز جرّ التمييز بالإضافة أو بـ«من».", "إذا أضيف المميَّز لغير التمييز جاز جرّ التمييز بـ«من» فقط."], "check": [{"q": "نوع المميَّز في «جنيت محصول فدانٍ قطنًا»:", "opts": ["كيل", "وزن", "مساحة"], "a": 2, "explain": "الفدان من المساحات (فدان، قيراط، قصبة)، وتمييزه «قطنًا»."}, {"q": "أيّ ما يأتي يصحّ بدلًا من «اشتريت رطلًا زيتًا»؟", "opts": ["اشتريت رطلَ زيتٍ", "اشتريت رطلًا الزيتَ", "اشتريت رطلًا زيتٌ"], "a": 0, "explain": "المميَّز (رطل) وزن، فيجوز جر التمييز بالإضافة: رطلَ زيتٍ. أما «الزيت» فمعرفة، و«زيتٌ» مرفوع، والتمييز نكرة منصوبة."}]}, {"type": "البلاغة", "title": "السجع", "page": 113, "hook": "اقرئي بصوت مسموع: «إنَّ بعدَ الكدَرِ صفوا، وبعد المطرِ صحوا»… هل سمعتِ الموسيقى؟", "about": "درس بلاغي في السجع، أحد المحسنات اللفظية، يشرح معناه اللغوي والفاصلة، وتسميته في القرآن الكريم، ووروده في النثر غالبًا وفي الشعر نادرًا.", "idea": "السجع توافق الفاصلتين في الحرف الأخير من النثر، فيعطي الكلام نغمة عذبة عند الوقف.", "cards": [{"icon": "🕊️", "title": "المعنى اللغوي", "text": "سَجَعَ يسجَعُ سجعًا: استوى واستقام وأشبه بعضه بعضًا. والسجع: الكلام المقفّى، وجمعه أسجاع وأساجيع. وسجع الحمامُ: هدل على جهة واحدة."}, {"icon": "🎵", "title": "الفاصلة", "text": "الفاصلة هي الكلمة الأخيرة التي نقف عليها. ففي الحديث الشريف جاءت الفواصل (السلام، الطعام، الأرحام، نيام، بسلام) كلها منتهية بالميم، فأعطت الكلام نغمة خاصة عند الوقف.", "quote": "«أفشوا السلام ، وأطعموا الطعام ، وصلوا الأرحام، وصلّوا بالليل والناس نيام تدخلوا جنة ربّكم بسلام»"}, {"icon": "📌", "title": "تعريف السجع", "text": "اتفاق الفاصلتين في الكلام المنثور في الحرف الأخير. ففي قول أبي الفضل الهمذاني انتهت الفاصلتان (صفوا، صحوا) بحرف واحد. ولا يظهر جمال السجع وجرسه إلا بالوقوف على الفواصل مسكّنة.", "quote": "إنَّ بعدَ الكدَرِ صفوا ، وبعد المطرِ صحوا ."}, {"icon": "📖", "title": "الفاصلة القرآنية", "text": "دأب العلماء على تسمية السجع في القرآن الكريم «الفاصلة القرآنية» لقوله تعالى: ﴿كِتَابٌ فُصِّلَتْ آيَاتُهُ﴾، وهو في حقيقته سجع؛ لأن القرآن كلام منثور إلا أنه معجز لا يجاريه كلام.", "quote": "﴿فِيهَا سُرُرٌ مَّرْفُوعَةٌ ۝ وَأَكْوَابٌ مَّوْضُوعَةٌ﴾ (الغاشية)"}, {"icon": "🪶", "title": "السجع في الشعر", "text": "السجع يختص بالنثر؛ فالفاصلة في النثر والقافية في الشعر. لكنه قد يرد في الشعر نادرًا، كما في بيت أبي تمام (رشدي، يدي، ثمدي، زندي)، وبيت مروان بن أبي حفصة (أصابوا، أجابوا، أطابوا).", "quote": "تجلى به رشدي ، وأثْرتْ به يدي ... وفاضَ به ثمْدي ، وأورى به زندي"}], "table": {"title": "أمثلة الدرس", "head": ["المثال", "الفواصل", "نوعه"], "rows": [["الحديث: أفشوا السلام…", "السلام، الطعام، الأرحام، نيام، بسلام", "سجع في النثر"], ["أبو الفضل الهمذاني: إن بعد الكدر صفوا…", "صفوا، صحوا", "سجع في النثر"], ["﴿فِيهَا سُرُرٌ مَّرْفُوعَةٌ ۝ وَأَكْوَابٌ مَّوْضُوعَةٌ﴾", "مرفوعة، موضوعة", "فاصلة قرآنية"], ["﴿مَّا لَكُمْ لَا تَرْجُونَ لِلَّهِ وَقَارًا ۝ وَقَدْ خَلَقَكُمْ أَطْوَارًا﴾", "وقارا، أطوارا", "فاصلة قرآنية"], ["أبو تمام: تجلى به رشدي…", "رشدي، يدي، ثمدي، زندي", "سجع في الشعر"], ["مروان بن أبي حفصة: هم القوم إن قالوا أصابوا…", "أصابوا، أجابوا، أطابوا", "سجع في الشعر"]]}, "tip": "💡 لتكتشفي السجع: قفي على آخر كل جملة بالسكون، ثم قارني الحرف الأخير من الفواصل. وتذكّري: الفاصلة في النثر، والقافية في الشعر.", "keyPoints": ["السجع من المحسنات اللفظية: توافق الفاصلتين في الحرف الأخير من النثر.", "الفاصلة: الكلمة الأخيرة التي يُوقف عليها.", "يسمى السجع في القرآن الكريم «الفاصلة القرآنية».", "السجع يرد في النثر، وقد يرد في الشعر نادرًا."], "check": [{"q": "يُسمّى السجع إذا ورد في القرآن الكريم:", "opts": ["القافية", "الفاصلة القرآنية", "الجناس"], "a": 1, "explain": "دأب العلماء على تسميته الفاصلة القرآنية لقوله تعالى: ﴿كِتَابٌ فُصِّلَتْ آيَاتُهُ﴾. والقافية مصطلح الشعر."}, {"q": "الفاصلتان المسجوعتان في «إنّ بعد الكدر صفوا، وبعد المطر صحوا» هما:", "opts": ["صفوا / صحوا", "الكدر / المطر", "بعد / بعد"], "a": 0, "explain": "الفاصلة هي الكلمة الأخيرة في الجملة: (صفوا) و(صحوا)، وقد اتفقتا في الحرف الأخير."}]}, {"type": "الاستماع", "title": "الجمال والفن", "page": 116, "hook": "لماذا لا تزال ابتسامة الموناليزا تحيّر الناس حتى اليوم؟", "about": "درس استماع: في كتاب الطالبة إرشادات الاستماع وأسئلة الاستماعين الأول والثاني ونشاط صفي لقراءة لوحات كبار الفنانين، أما النص المسموع فهو في دليل المعلم، مأخوذ من «الأصول الجمالية للفن الحديث» لحسن محمد حسن، ويتحدث عن الطبيعة ملهمةً للفنان، وعن الفنان العماني.", "idea": "الطبيعة المعلّم الأول للفنان، لكن الفنان المبدع لا يحاكيها حرفيًّا بل يعيد ابتكارها برؤيته.", "cards": [{"icon": "🌿", "title": "الطبيعة المعلّم الأول", "text": "جمال الطبيعة جمال الفطرة كما برأها الله، وقد بدأ أول عمل فني بتقليد صورها. ومنها عرف الفلاسفة والشعراء والفنانون الإيقاع في الموسيقى والغناء، والانسجام في الألوان، والتنوع في تكوين الأشكال."}, {"icon": "🎨", "title": "من المحاكاة إلى الابتكار", "text": "لم يبقَ موقف الفنان محصورًا في التقليد والمحاكاة، بل اتجه إلى إعادة ابتكار الطبيعة؛ فتأخذ الصورة أبعادًا معدّلة ومحوّرة بالحذف والإضافة، ويحرّك المظهر الثابت ليستلهم معنى جماليًّا يخدم عمله."}, {"icon": "🌸", "title": "الشابي وزهرته", "text": "ناجى الشاعر حبيبته باعتبارها زهرة جميلة، فتخطّى وصف جمالها الظاهري إلى كشف أثرها الوجداني في قلبه؛ فجمال الحبيبة جمال روحها لا جسدها.", "quote": "آه يا زهرتي الجميلةَ لو تَدْرينَ ما جَدَّ في فُؤادي الوحيد"}, {"icon": "🖼️", "title": "سرّ الموناليزا", "text": "يحار متأمل لوحة الموناليزا في سر الابتسامة وغموضها، فيترك الفنان الحكم للمشاهد وفق انطباعه وزاوية رؤيته؛ لأن العمل الفني ليس نقلًا حرفيًّا عن الطبيعة، بل صورة تحمل نزعات الفنان وميوله."}, {"icon": "🧠", "title": "عوامل الإبداع", "text": "يساعد الفنان الأصيل على استنطاق أبعاد جديدة: جمال الطبيعة، وثقافته، ونزعته ورؤاه، ومستوى مواهبه الفكرية والوجدانية. وقد تهيمن المخيلة الجغرافية فتنعكس بيئة الفنان البحرية أو الجبلية أو الغابة على أعماله."}, {"icon": "🇴🇲", "title": "الفنان العماني", "text": "التفت الفنان العماني إلى جمال الطبيعة ووظّفه توظيفًا حديثًا. وترعى جمعية الفنون التشكيلية المواهب الشابة منذ افتتاحها رسميًّا عام 1980م بالدورات وورش العمل والمسابقات السنوية والجوائز."}], "tip": "💡 الإنسان العادي يدرك جمال الطبيعة إدراكًا ثابتًا فتتحقق له اللذة الجمالية المحضة، أما الفنان فيضيف إليه تعديلاته ولمساته فيصنع دلالات جديدة.", "keyPoints": ["الطبيعة المعلّم الأول: منها الإيقاع، والانسجام في الألوان، والتنوع في الأشكال.", "الفنان المبدع يعيد ابتكار الطبيعة بأبعاد معدّلة ومحوّرة، لا يحاكيها حرفيًّا.", "عوامل الإبداع: جمال الطبيعة، وثقافة الفنان، ونزعته ورؤاه، ومستوى مواهبه.", "افتُتحت جمعية الفنون التشكيلية بالسلطنة رسميًّا عام 1980م."], "check": [{"q": "متى افتُتحت جمعية الفنون التشكيلية بالسلطنة رسميًّا؟", "opts": ["عام 1980م", "عام 1997م", "عام 1945م"], "a": 0, "explain": "ورد في نص الاستماع: «منذ افتتاحها رسميًّا عام 1980م وحتى اليوم»."}, {"q": "كيف يدرك الإنسان العادي جمال الطبيعة بحسب النص؟", "opts": ["يعيد ابتكاره بأبعاد جديدة", "يضيف إليه تعديلاته الفنية", "يدركه إدراكًا ثابتًا فتتحقق له اللذة الجمالية المحضة"], "a": 2, "explain": "النص: «والإنسان العادي يلاحظ جمال الطبيعة فيدركه إدراكًا ثابتًا فتتحقق لديه اللذة الجمالية المحضة»، أما الابتكار والتعديل فعمل الفنان."}]}], "activities": [{"kind": "order", "lesson": 1, "title": "رتّبي أحداث قصة «الصرح»", "items": ["اعتلاء البينام ومافالدو الحكم واستعار الحرب", "انتصار البينام بالحظ وأسر مافالدو", "طلب مافالدو أن يبني لنفسه صرحًا", "انشغال الناس بالصرح وغيرة البينام", "رفض مافالدو مشاركة البينام في البناء", "جواب مافالدو: «بلا أي ثمن»"]}, {"kind": "mcq", "lesson": 1, "q": "ما معنى كلمة (صرح) في قول مافالدو: «فأنا أرغب أن أشيّد لي صرحًا»؟", "opts": ["الصريح الخالص مما يشوبه", "الوضوح والخلوص من الالتواء", "القصر العالي", "ساحة الدار"], "a": 2, "explain": "1) الفعل «أشيّد» يعني أبني وأرفع البناء. 2) فالصرح هنا بناء عالٍ، وقد وصفه النص بالقصر الحجري الذي يشمخ ببطء. 3) أما الصراحة والوضوح فمعانٍ أخرى للمادة لا تناسب السياق."}, {"kind": "tf", "lesson": 1, "q": "وافق مافالدو على أن يشارك البينام في بناء الصرح بغرفة صغيرة واحدة.", "a": false, "explain": "1) طلب البينام أن يسهم ولو ببناء طابق أو غرفة صغيرة. 2) فرفض مافالدو قائلًا: «أنا لا أوافق... صرحي ينبغي ألّا يخلّدك». 3) وتمسّك بالعهد الذي يقضي ببناء الصرح دون مشاركة يد غريبة؛ فالعبارة خاطئة."}, {"kind": "classify", "lesson": 2, "title": "صنّفي المميَّز المفرد بحسب نوعه", "groups": ["كيل", "وزن", "مساحة", "شبه مقدار"], "items": [["صاع", 0], ["إردب", 0], ["قدح", 0], ["رطل", 1], ["أوقية", 1], ["فدان", 2], ["قيراط", 2], ["قبضة يد", 3], ["مثقال ذرة", 3]]}, {"kind": "fill", "lesson": 2, "q": "اشتريت من الدكان رطلًا ____.", "opts": ["الزيتَ", "زيتًا", "زيتٌ"], "a": 1, "explain": "1) كلمة (رطلًا) مبهمة تدل على وزن. 2) يأتي بعدها تمييز يفسرها، والتمييز اسم نكرة منصوب. 3) (الزيتَ) معرفة فلا يصلح، و(زيتٌ) مرفوع فلا يصلح. 4) فالصواب (زيتًا)، ويجوز أيضًا: رطلَ زيتٍ، أو رطلًا من زيتٍ."}, {"kind": "match", "lesson": 3, "title": "صِلي كل فقرة بالفقرة التي تسجع معها", "pairs": [["إنّ بعد الكدر صفوًا", "وبعد المطر صحوًا"], ["طاعة الشهوة داء", "وعصيانها دواء"], ["إن أُونِس تكبّر", "وإن أوحش تكدّر"], ["وإن استُنطق تخلّف", "وإن تُرك تكلّف"], ["مجالسته مَهنة", "ومعاتبته مِحنة"], ["طويلُ النجاد", "رفيعُ العماد"]]}, {"kind": "mcq", "lesson": 3, "q": "يُسمّى السجع إذا ورد في القرآن الكريم:", "opts": ["القافية", "الفاصلة القرآنية", "الجناس", "الطباق"], "a": 1, "explain": "1) دأب العلماء على تسمية السجع في القرآن بالفاصلة القرآنية. 2) ودليلهم قوله تعالى: ﴿كِتَابٌ فُصِّلَتْ آيَاتُهُ﴾. 3) وهو في حقيقته سجع لأن القرآن كلام منثور معجز. 4) أما القافية فهي في الشعر."}, {"kind": "tf", "lesson": 4, "q": "يرى نص «الجمال والفن» أن موقف الفنان من جمال الطبيعة محصور في تقليد صورها ومحاكاتها.", "a": false, "explain": "1) يقرّ النص بأن أول عمل فني بدأ بتقليد صور الطبيعة. 2) لكنه يقول: «لم يكن موقف الفنان من جمال الطبيعة محصورًا في التقليد والمحاكاة». 3) بل اتجه إلى إعادة ابتكارها بأبعاد معدّلة ومحوّرة؛ فالعبارة خاطئة."}], "test": [{"lesson": 1, "q": "ما سرّ انتصار البينام على مافالدو كما تذكر القصة؟", "opts": ["أنه كان قائدًا محنّكًا", "أن جنوده أفضل الجند", "أن له حظًّا في الحروب استغله", "أن مستشاريه أشاروا عليه بخطة محكمة"], "a": 2, "explain": "1) يقول النص: «على المرء ألا يظن أن البينام يمتلك أفضل الجند، أو كان قائدًا محنكًا». 2) «وإنما سرّ انتصاره يكمن فقط في أن له حظًّا في الحروب، وأنه استغل الحظ الذي حالفه». 3) أما المستشارون فقد أُحيلوا إلى التقاعد قبل الحرب."}, {"lesson": 1, "q": "ما الذي تمنّى مافالدو فعله بعد أن أصبح أسيرًا؟", "opts": ["أن يُنفى إلى بلد بعيد", "أن يبني لنفسه صرحًا", "أن يستعيد استقلال بلده", "أن يحكم جزءًا من المملكة"], "a": 1, "explain": "1) سأله البينام: «فما الذي تتمنى فعله؟». 2) فأجاب: «إذا كان عليّ أن أعيش لكي يضع الموت نهاية لذلك يومًا فأنا أرغب أن أشيّد لي صرحًا». 3) فقال البينام: «ابنِ لنفسك الدار الأخيرة»."}, {"lesson": 1, "q": "ما معنى «يُمنى» في قوله: «إذ حين يُمنى أحدهما بهزيمة في موقعة»؟", "opts": ["يُبتلى", "يتمنى", "يُسرع", "ينتصر"], "a": 0, "explain": "1) ورد في معجم اللغويات: يُمنى (م ن ي) = يُبتلى. 2) فالمعنى: حين يُبتلى أحد البلدين بهزيمة يحرص على تخفيف التوتر."}, {"lesson": 1, "q": "الشخصية النامية التي تتطور مع الأحداث في قصة «الصرح» هي:", "opts": ["البينام", "وزراء البينام", "العمال", "مافالدو"], "a": 3, "explain": "1) تصف الإضاءة النقدية البينام بأنه شخصية نمطية لم تتطور ولم تكتسب صفات جديدة. 2) أما مافالدو فهو «شخصية نامية تتطور مع الأحداث وتنفعل بالمستجدات». 3) فلم يسقط بالهزيمة بل حوّل اهتمامه إلى الإبداع."}, {"lesson": 1, "q": "بمَ أجاب مافالدو حين سأله البينام: «مقابل أي ثمن تتنازل لي عن صرحك؟»", "opts": ["مقابل استقلال بلدي", "مقابل حريتي", "بلا أي ثمن", "مقابل نصف المملكة"], "a": 2, "explain": "1) اقترح البينام: «مقابل استقلال بلدك، أليس كذلك؟». 2) فأجاب مافالدو: «بلا أي ثمن»، أي إنه لا يتنازل عنه أبدًا. 3) وبجوابه انتهت المحاورة، وهو حلّ القصة الذي يمثل انتصار الفن."}, {"lesson": 2, "q": "التمييز اسم:", "opts": ["نكرة منصوب يُذكر تفسيرًا لمبهم واقع قبله", "معرفة منصوب يبيّن هيئة صاحبه", "نكرة مجرور يأتي بعد حرف الجر دائمًا", "مشتق منصوب يبيّن سبب الفعل"], "a": 0, "explain": "1) نصّ الكتاب: «التمييز: اسم نكرة منصوب يُذكر تفسيرًا لمبهم واقع قبله». 2) أما بيان الهيئة فهو وظيفة الحال، وبيان السبب وظيفة المفعول لأجله."}, {"lesson": 2, "q": "في قوله تعالى: ﴿إِنَّ عِدَّةَ الشُّهُورِ عِندَ اللَّهِ اثْنَا عَشَرَ شَهْرًا﴾، المميَّز ونوعه:", "opts": ["الشهور، وزن", "اثنا عشر، عدد", "عِدّة، كيل", "شهرًا، مساحة"], "a": 1, "explain": "1) التمييز هو (شهرًا)؛ نكرة منصوبة فسّرت مبهمًا قبلها. 2) والكلمة المبهمة قبله هي (اثنا عشر)، وهي المميَّز. 3) ونوع المميَّز: عدد، كما في دليل المعلم (التمييز: شهرًا، والمميز: اثنا عشر)."}, {"lesson": 2, "q": "أيّ الجمل الآتية لا يجوز فيها جرّ التمييز بالإضافة، ويجوز جرّه بـ(من) فقط؟", "opts": ["طبخت سعاد بصاعٍ أرزًا", "اشتريت رطلًا زيتًا", "جنيت محصول فدانٍ قطنًا", "حملت قبضةَ يدي أصدافًا"], "a": 3, "explain": "1) يجوز جرّ التمييز بالإضافة أو بـ(من) إذا كان المميَّز كيلًا أو وزنًا أو مساحة (صاع، رطل، فدان). 2) أما (قبضة) فهي مضافة إلى (يدي)، أي مضافة لغير التمييز. 3) فلا تُضاف مرة أخرى إلى التمييز، ويجوز فقط: قبضة يدي من أصدافٍ."}, {"lesson": 2, "q": "(رطل) في قولنا: «اشتريت رطلًا زيتًا» مميَّز يدل على:", "opts": ["كيل", "وزن", "مساحة", "عدد"], "a": 1, "explain": "1) قسّم الكتاب المقدار إلى: كيل (صاع، إردب، قدح)، ووزن (رطل، أوقية)، ومساحة (فدان، قيراط). 2) فالرطل وزن، وتمييزه (زيتًا)."}, {"lesson": 3, "q": "السجع هو:", "opts": ["توافق الفاصلتين في الحرف الأخير من النثر", "اتفاق اللفظين في النطق واختلافهما في المعنى", "الجمع بين الكلمة وضدها", "توافق آخر الأبيات في الوزن"], "a": 0, "explain": "1) خلاصة الدرس: «السجع من المحسنات اللفظية، وهو توافق الفاصلتين في الحرف الأخير من النثر، وقد يرد في الشعر». 2) الخيار الثاني تعريف الجناس، والثالث الطباق، والرابع يخص الشعر."}, {"lesson": 3, "q": "الفواصل المسجوعة في قول مروان بن أبي حفصة: «هم القوم إن قالوا أصابوا، وإن دُعوا ... أجابوا، وإن أعطَوا أطابوا وأجزلوا» هي:", "opts": ["القوم، قالوا، دُعوا", "قالوا، أعطوا، أجزلوا", "أصابوا، أجابوا، أطابوا", "هم، إن، وإن"], "a": 2, "explain": "1) نقف على الكلمات التي تنتهي بها الجمل القصيرة داخل البيت. 2) نجد (أصابوا، أجابوا، أطابوا) متفقة في آخرها. 3) وقد نصّ الكتاب على أنها فواصل بيت مروان، وهو مثال لورود السجع في الشعر."}, {"lesson": 4, "q": "من العوامل التي تساعد الفنان الأصيل على استنطاق أبعاد فنية جديدة في عمله، كما في نص «الجمال والفن»:", "opts": ["كثرة الأدوات وغلاء ثمنها", "ثقافة الفنان ومستوى مواهبه الفكرية والوجدانية", "نقل الطبيعة نقلًا حرفيًّا", "الابتعاد عن الطبيعة تمامًا"], "a": 1, "explain": "1) ذكر دليل المعلم العوامل: جمال الطبيعة، وثقافة الفنان، ونزعة الفنان ورؤاه، ومستوى مواهبه من الناحية الفكرية والوجدانية. 2) والنص يرفض النقل الحرفي، ويجعل الطبيعة الرافد الحقيقي للإلهام."}], "game": {"type": "memory", "pairs": [["بصاعٍ أرزًا", "تمييز بعد كيل"], ["رطلًا زيتًا", "تمييز بعد وزن"], ["فدانٍ قطنًا", "تمييز بعد مساحة"], ["قبضةَ يدي أصدافًا", "تمييز بعد شبه مقدار"], ["خمسين كتابًا", "تمييز بعد عدد"], ["إنّ بعد الكدر صفوًا", "وبعد المطر صحوًا"], ["السجع", "توافق الفاصلتين في الحرف الأخير"], ["السجع في القرآن الكريم", "الفاصلة القرآنية"]]}}, {"id": "u6", "axis": "قضايا معاصرة", "axisN": 2, "unitN": 3, "title": "الوحدة الثالثة", "theme": "رسائل الحكمة وألوان الفن", "pages": "119–144", "lessons": [{"type": "القراءة", "title": "رسالة إلى ابني", "page": 119, "hook": "ابنٌ يودّع عامه الثالث عشر، وأبٌ يكتب إليه رسالة يفتح فيها عينيه على الحياة… ماذا يقول له؟", "about": "رسالة كتبها فاخر عاقل إلى ابنه وفاءً بوعد قديم، حين ودّع الابن عامه الثالث عشر. يحدّثه فيها عن مرحلة المراهقة، وتغيّر الزمان، وقدرة الإنسان على التكيف بالعلم، وينصحه بإعمال عقله وحريته في صياغة أهدافه.", "idea": "يدعو الأب ابنه المراهق إلى إدراك تغيّر الزمان، والتكيّف معه بالعلم، واستعمال عقله وحريته في صياغة أهدافه بخلق قويم.", "cards": [{"icon": "✉️", "title": "وعدٌ ووفاء", "text": "تمنّى الابن أن يكتب له أبوه رسالة مثل التي كتبها لأخته حين كانت في عمره، فوعده بذلك حين يبلغ عمرًا يقارب عمرها، وها هو يفي بوعده.", "quote": "وهأنذا أكتبُ إليكَ هذه الرِّسالةَ اليومَ ما دمتَ قد ودّعْتَ أمسِ العامَ الثالثَ عشرَ من عُمُرِكَ"}, {"icon": "🌱", "title": "المراهقة", "text": "يودّع الابن طفولته ويستعد لرجولته، ويدوم ذلك أعوامًا لا تقل عن ثلاثة وقد تصل إلى الخمسة أو الستة. يراها الكثيرون صعبة خطيرة، ويراها الكاتب مهمة إذا اتخذ الأهل والمربون موقف الجد المتفائل والتوجيه الذكي.", "quote": "وأعتقدُ أنا أنَّها فترةٌ مهمَّةٌ، وليسَ من الضروريّ أَنْ تكونَ شاقَّةً ولا عسيرةً"}, {"icon": "⏩", "title": "الحقيقة الأولى: تغيّر الزمان", "text": "الزمان دائم التغيّر، لكن تغيّر عصرنا متسارع يكاد يدير الرأس ويضيع التوازن. ولا يقتصر على المعارف والمخترعات، بل يشمل المواقف الاجتماعية والمفاهيم الإنسانية والعلاقات البشرية، وهي أمور بالغة الخطورة.", "quote": "والويلُ كلُّ الويلِ لمن لا يُدركُ هذه الحقيقة،ولا يتواءَمُ معها."}, {"icon": "🦎", "title": "تنازع البقاء والتكيّف", "text": "ناموس الحياة أن البقاء للأصلح، أي الأقوى جسدًا والأوفر قوة. لكن هذه الحقيقة ناقصة إن لم تكمّلها حقيقة أخرى: قدرة الإنسان على التكيف؛ فهو أقدر المخلوقات على التكيف، وأذكاها في تعرّف ما يحيط به."}, {"icon": "🔬", "title": "سلاح العلم", "text": "سلاح الإنسان الأمثل في التكيف قدرته على أن يعلم ويكتشف ويخترع، وهذا سرّ قوة الإنسان الحديث وتقدمه السريع: يتعلم ويعلّم أجياله اللاحقة ويدفع العلم إلى الأمام.", "quote": "إنّ العلمَ والتعلمَ والتعليمَ هي الأقانيمُ الأساسية للحياة الإنسانية المتطلعةِ أبدا إلى ما هو أحسنُ."}, {"icon": "🎯", "title": "العقل والحرية", "text": "منحك الخالق عقلًا وحرية، فلا تتخلَّ عنهما فتصير ريشة في مهب الريح. صُغ أهدافك وحدّدها، وارسم نهجك إليها بمرونة ولباقة، دون تفريط في خلق قويم أو حق صحيح أو واجب أكيد.", "quote": "وتترك نفسَك ريشةً تتقاذفها عواصفُ الحياة ورياح المصادفات؟"}, {"icon": "💎", "title": "دروس مستفادة", "text": "صياغة الأهداف علم وفن؛ فالأهداف الصحيحة لا تكون جامدة ولا متحجرة، والطرق السليمة لا تكون وحيدة ولا خيالية. والأهداف تعلو وتهبط، والطرائق تتغير وتلتوي، والعاصم من ذلك كله: نية حسنة، وضمير حي، وخلق قويم."}], "vocab": [{"w": "الوَيْل (و ي ل)", "m": "حلول الشر، وهي كلمة عذاب"}, {"w": "التَّكَيُّف (ك ي ف)", "m": "التلاؤم"}, {"w": "الأقانيم (ق ن م)", "m": "الأصول، ومفردها: الأقنوم"}, {"w": "الاحتجاج (ح ج ج)", "m": "الإكثار من الجدل، أو الإتيان بالبراهين والأدلة، والمراد هنا الاعتراض"}], "tip": "💡 انتبهي: «صعبة عسيرة خطيرة» رأي الكثيرين في المراهقة، أما الكاتب فيراها «مهمة». و«ريشة تتقاذفها العواصف» تشبيه للإنسان الضعيف الذي تخلّى عن عقله وحريته.", "keyPoints": ["كتب الأب الرسالة وفاءً بوعده حين ودّع ابنه العام الثالث عشر.", "المراهقة عند الكاتب فترة مهمة لا تكون شاقة إذا أحسن الأهل والمربون التوجيه.", "الحقيقة الأولى: تغيّر الزمان وتطور العلم بشكل متسارع.", "سلاح التكيّف: أن يعلم الإنسان ويكتشف ويخترع؛ والعلم والتعلم والتعليم أقانيم الحياة.", "العاصم في صياغة الأهداف: نية حسنة، وضمير حي، وخلق قويم."], "check": [{"q": "يرى الكاتب أن سلاح الإنسان الأمثل في عملية التكيف هو:", "opts": ["قوته الجسدية", "حظه في الحياة", "قدرته على أن يعلم ويكتشف ويخترع"], "a": 2, "explain": "نصّ الرسالة: «أحب لك أن تعلم أن سلاح الإنسان الأمثل في عملية التكيف هذه هو قدرته على أن يعلم، وأن يكتشف، وأن يخترع»."}, {"q": "كيف يرى الكاتب فترة المراهقة؟", "opts": ["فترة مهمة لا تكون شاقة إذا أحسن الأهل التوجيه", "فترة خطيرة يجب الخوف منها", "فترة لا أهمية لها"], "a": 0, "explain": "الكثيرون يرونها صعبة عسيرة خطيرة، أما الكاتب فيقول: «وأعتقد أنا أنها فترة مهمة، وليس من الضروري أن تكون شاقة ولا عسيرة إذا تنبه الأهل والمربون»."}]}, {"type": "الأنشطة النحوية", "title": "التمييز: 2- تمييز النسبة", "page": 124, "hook": "«يزداد الإنسان…» يزداد ماذا؟ طولًا؟ علمًا؟ مالًا؟ الإبهام هنا في الجملة كلها!", "about": "درس نحوي في النوع الثاني من التمييز: تمييز النسبة (الجملة)، يبيّن الفرق بينه وبين تمييز الذات، وأنه يكون محوّلًا عن الفاعل أو المفعول به أو المبتدأ، ومواضع كثرته، والفرق بين الحال والتمييز.", "idea": "تمييز النسبة يزيل الإبهام عن جملة كاملة تتضمن نسبة شيء إلى شيء، لا عن كلمة مفردة.", "cards": [{"icon": "🔍", "title": "مفردة أم جملة؟", "text": "في «مائة فدانٍ نخلًا» نشأ الإبهام من كلمة مفردة ملفوظة (فدان) فهو تمييز ذات. أما في «يزداد الإنسان» فالإبهام في الجملة كلها: أهو عمره أم طوله أم علمه؟ فجاءت «رفعةً» و«تواضعًا» لترفعه.", "quote": "يزداد الإنسان رفعةً كلما ازداد تواضعًا."}, {"icon": "📌", "title": "تعريف تمييز النسبة", "text": "تمييز النسبة أو الجملة: ما كان المميَّز فيه جملة أو نسبة شيء لشيء، لا كلمة مفردة ملفوظة."}, {"icon": "🔄", "title": "المحوَّل: ثلاثة أصول", "text": "تمييز النسبة يكون محوّلًا في الأصل عن: الفاعل: نبغ ابن سينا طبًّا (أصلها: نبغ طبُّ ابن سينا)، أو المفعول به: زرع الفلاح البستان موزًا (أصلها: زرع الفلاح موزَ البستان)، أو المبتدأ: أبو تمام أخصب من البحتري خيالًا (أصلها: خيالُ أبي تمام أخصب من خيال البحتري).", "quote": "نبغ ابن سينا طبًّا ."}, {"icon": "📣", "title": "أين يكثر؟", "text": "يكثر تمييز النسبة في صيغ المدح والذم، والتعجب السماعي والقياسي، وبعد الفعل «امتلأ» وشبهه: «ما أعظم الخليل بن أحمد أستاذًا عبقريًّا!»، «امتلأ التراث العربي كتبًا جليلةً».", "quote": "بئس الكسل سجيةً ، ونعم النشاط طبعًا ."}, {"icon": "⚖️", "title": "الحال أم التمييز؟", "text": "كلاهما نكرة منصوبة، والفرق: 1) الحال تبيّن الهيئة، والتمييز يبيّن الذات أو النسبة. 2) الغالب في الحال الاشتقاق، وفي التمييز الجمود. 3) الحال قد تكون جملة أو شبه جملة، ولا يكون التمييز إلا مفردًا.", "quote": "أقبل محمد علينا راكبًا . اشترى سالم رطلاً عسلاً . تفوق سعيد خلقًا ."}, {"icon": "🧪", "title": "التمييز وحرف الجر «من»", "text": "في تدريب جبران لا يصح إدخال «من» على التمييز إلا في «شبرٌ أرضًا»؛ لأنه تمييز ذات يدل على مقدار مساحة، فنقول: شبرٌ من أرضٍ (دليل المعلم)."}], "table": {"title": "صنّفي مع الكتاب", "head": ["المثال", "نوعه", "السبب أو الأصل"], "rows": [["يجني محمد سنويًّا محصول مائة فدانٍ نخلًا", "تمييز ذات", "المميَّز كلمة مفردة ملفوظة (فدان)"], ["نبغ ابن سينا طبًّا", "نسبة محوّل عن الفاعل", "نبغ طبُّ ابن سينا"], ["زرع الفلاحُ البستانَ موزًا", "نسبة محوّل عن المفعول به", "زرع الفلاح موزَ البستان"], ["أبو تمام أخصبُ من البحتري خيالًا", "نسبة محوّل عن المبتدأ", "خيالُ أبي تمام أخصبُ من خيال البحتري"], ["بئس الكسل سجيةً", "نسبة", "بعد صيغة الذم"], ["ما أعظم الخليل بن أحمد أستاذًا عبقريًّا!", "نسبة", "بعد التعجب"], ["امتلأ التراث العربي كتبًا جليلةً", "نسبة", "بعد الفعل امتلأ"], ["أقبل محمد علينا راكبًا", "حال لا تمييز", "تبيّن الهيئة، ومشتقة، ويصح: أقبل وهو يركب"]]}, "tip": "💡 لتعرفي المحوَّل أعيدي التمييز إلى أصله: إن صار فاعلًا أو مفعولًا به أو مبتدأً فهو محوّل عنه. وإن استطعتِ وضع جملة مكان الكلمة («يركب») فهي حال لا تمييز.", "keyPoints": ["تمييز الذات: المميَّز كلمة مفردة ملفوظة؛ وتمييز النسبة: المميَّز جملة.", "تمييز النسبة يكون محوّلًا عن الفاعل، أو المفعول به، أو المبتدأ.", "يكثر بعد المدح والذم، والتعجب، والفعل امتلأ وشبهه.", "الحال تبيّن الهيئة وغالبًا مشتقة، والتمييز يبيّن الذات أو النسبة وغالبًا جامد.", "الحال قد تكون جملة أو شبه جملة، ولا يكون التمييز إلا مفردًا."], "check": [{"q": "التمييز في «زرع الفلاحُ البستانَ موزًا» محوَّل عن:", "opts": ["الفاعل", "المفعول به", "المبتدأ"], "a": 1, "explain": "أصل الجملة: زرع الفلاحُ موزَ البستان؛ فكلمة (موز) كانت مفعولًا به ثم صارت تمييزًا منصوبًا."}, {"q": "كلمة «راكبًا» في «أقبل محمد علينا راكبًا» تُعرب:", "opts": ["تمييز ذات", "تمييز نسبة", "حالًا"], "a": 2, "explain": "(راكبًا) بيّنت هيئة محمد، وهي مشتقة، ويصح أن تأتي جملة: (يركب)؛ وهذه علامات الحال كما في الكتاب."}]}, {"type": "النقد الأدبي", "title": "عناصر العمل الأدبي: أولًا: الأفكار", "page": 132, "hook": "شاعران تحدثا عن الحرب والوطن، أحدهما بفكرة واحدة بسيطة والآخر بأفكار متشابكة… كيف نحكم بينهما؟", "about": "درس نقدي يعرّف عناصر العمل الأدبي، ويبدأ بأولها: الأفكار، فيبيّن منزلتها في النثر والشعر، والمقاييس النقدية للحكم عليها، ويطبّقها على أبيات زهير بن أبي سلمى في الحرب ونونية أحمد شوقي.", "idea": "لكل عمل أدبي فكرة، ونحكم عليها بمقاييس ثلاثة: حجمها، وجدّتها أو قدمها، ووضوحها.", "cards": [{"icon": "🧱", "title": "عناصر العمل الأدبي", "text": "هي المكونات الحقيقية للعمل الأدبي، ننظر فيها لتفسير أي عمل شعرًا كان أو نثرًا، للوقوف على مواطن الجمال والقبح فيه، وعمق التجربة أو ضحالتها. وتختلف أهميتها من عمل إلى آخر ومن لون أدبي إلى آخر."}, {"icon": "💡", "title": "الفكرة ومنزلتها", "text": "لا يخلو عمل أدبي من فكرة يعرضها الأديب في قالب واضح مشوّق ليقنع بها القارئ. وهي في المنزلة الأولى في النثر الفني (القصة، والمقالة، والخاطرة، والخطبة)، وموجودة في الشعر لكن عناصر أخرى تطغى عليها وتسبقها."}, {"icon": "📏", "title": "مقاييس الفكرة", "text": "1) حجم الفكرة: بسيطة أم مركبة تحتاج إلى إعمال ذهن القارئ؟ 2) جدّة الأفكار أو قدمها: بما تطرحه من جديد يهمّ الناس والمجتمع. 3) وضوح الفكرة: حتى تتضح في ذهن المتلقي فيتأثر بها."}, {"icon": "⚔️", "title": "زهير: فكرة بسيطة", "text": "حين نشبت الحرب بين عبس وذبيان وسعى سيدان إلى الصلح، مدحهما زهير وأخذ ينفّر القوم من الحرب: إذا اشتعلت طحنتهم كما تطحن الرحى الحَبّ، ونتاجها شؤم. فكرة بسيطة واضحة تأخذ مجرياتها من الواقع.", "quote": "متى تبعثوها ، تبعثوها ذميمة ... وتضر إذا ضريتموها ، فتضرم"}, {"icon": "🌴", "title": "شوقي: فكرة مركبة", "text": "عرض شوقي في نونيته أفكارًا كثيرة بينها رابط نفسي: حاضر العالم الإسلامي وصور وفائه للعرب، ثم خواطره عن مصر، ثم ذكرياته وحنينه إليها. فهي فكرة واقعية واضحة لكنها مركبة، كما يفعل كاتب الرواية أو المسرحية أو المقالة.", "quote": "يا نائح الطلح أشباه عوادينا ... نشجى لواديك أم نأسى لوادينا"}, {"icon": "🕊️", "title": "تطبيق: هديل الحمام", "text": "اختلفت نظرة الشعراء إلى هديل الحمام (دليل المعلم): فهو عند أبي كبير الهذلي ألم وتوجع وبكاء، وعند أبي العلاء المعري يتساوى فيه البكاء والغناء، وعند أبي تمام ضحك وسرور.", "quote": "أفِقْ لا تَنُحْ من غير شيء فإنني ... بكيتُ زمانا والفؤادُ صحيحُ"}], "table": {"title": "تطبيق المقاييس على النموذجين", "head": ["المقياس", "أبيات زهير", "نونية شوقي"], "rows": [["الحجم", "فكرة بسيطة", "فكرة مركبة: أفكار كثيرة بينها رابط نفسي"], ["الوضوح والواقعية", "واضحة تأخذ مجرياتها من الواقع", "واقعية واضحة"], ["ما يشبهها في النثر", "كاتب خاطرة اليوم في صحيفة يومية", "كاتب رواية أو مسرحية أو مقالة"]]}, "tip": "💡 لا تخلطي بين المقاييس: «بسيطة/مركبة» مقياس الحجم لا الوضوح؛ ففكرة شوقي مركبة ومع ذلك واضحة.", "keyPoints": ["عناصر العمل الأدبي: مكوناته التي نفسّره بها ونحكم عليه.", "الفكرة في المنزلة الأولى في النثر الفني، وتسبقها عناصر أخرى في الشعر.", "مقاييس الفكرة: الحجم (بساطة/تركيب)، والجدّة أو القدم، والوضوح.", "أبيات زهير في الحرب: فكرة بسيطة واضحة واقعية.", "نونية شوقي: فكرة واقعية واضحة لكنها مركبة."], "check": [{"q": "المقياس الذي يسأل: «هل هي فكرة بسيطة أم مركبة؟» هو:", "opts": ["وضوح الفكرة", "حجم الفكرة", "جدّة الفكرة"], "a": 1, "explain": "المقياس الأول: «حجم الفكرة التي يعرض لها النص الأدبي، فهل هي فكرة بسيطة أم مركبة تحتاج إلى إعمال ذهن القارئ ليستوعبها؟»."}, {"q": "تكون الفكرة في المنزلة الأولى من عناصر العمل الأدبي في:", "opts": ["النثر الفني كالقصة والمقالة والخاطرة والخطبة", "القصيدة الشعرية", "الشعر والنثر بالقدر نفسه"], "a": 0, "explain": "نصّ الدرس: الفكرة تكون في المنزلة الأولى في مجال النثر الفني، وهي موجودة في القصيدة لكن عناصر أخرى تطغى عليها وتسبقها."}]}, {"type": "التعبير", "title": "تعبير شفوي: قراءة الصور والرسوم", "page": 136, "hook": "تقفين أمام لوحة صامتة… لكنها تكاد تتكلم! كيف تفهمين ما تقوله؟", "about": "درس في التعبير الشفوي يعلّم خطوات قراءة اللوحة الفنية والعناصر التي تسهم في قراءتها، ثم يطبّقها على ثلاث لوحات لفنانين عمانيين: أنور سونيا، وفخرية اليحيائي، ورابحة محمود.", "idea": "قراءة اللوحة رحلة من الدهشة الأولى إلى فهم الفكرة والقيمة والرموز، ثم التعبير عنها بأسلوب أدبي.", "cards": [{"icon": "👁️", "title": "أولًا: المونولوج", "text": "حوار داخلي بين المشاهد واللوحة؛ فاللوحة ناطقة بانفعالاتها ومشاعرها لكنها صمّاء لا تحس بمن حولها. وهي قادرة على خلق انطباع إيجابي يبدأ بالإعجاب أو «الدهشة»، أو برغبة التملك.", "quote": "ثمة مونولوج داخلي ما بين المشاهد واللوحة الفنية"}, {"icon": "💭", "title": "ثانيًا: الفكرة أو الموضوع", "text": "الفن ليس وصفًا لحالات شعورية فقط، بل إبداع شروطه: العقل الخلاق لدى الفنان، ونضوجه، وإلمامه بالتقاليد الفنية؛ فهو ينفعل بالموضوع ويترجم انفعالاته بصورة.", "quote": "فهي تجمع بين البصر والبصيرة."}, {"icon": "🧵", "title": "ثالثًا: متابعة العمل الفني", "text": "الدخول في عالم اللوحة: نتابع الخيط لاستخلاص الغاية التعليمية الجمالية المقصودة؛ فكل عمل فني يتضمن «قيمة» يعبّر عنها، وهي تختلف لا محالة عن الفكرة."}, {"icon": "🔣", "title": "رابعًا: قراءة الرموز", "text": "الصورة رمز يحمل بنى ودلالات متناغمة. ننظر أولًا إلى وسط الصورة ومقدمتها وزواياها لرؤية البناء ككل، ثم إلى أبعادها الثلاثة؛ فاللوحة ليست تحفة فقط، بل تعبير عن انفعال الفنان واحتراقاته."}, {"icon": "🧰", "title": "عناصر تسهم في القراءة", "text": "استيعاب لغة الصورة (الموضوع، والأداة، والمادة، والشكل)، وتمثّل موضوعها الرئيس، وتوضيح علاقتها بالواقع، والبحث عن رموزها ودلالاتها، وربط الأحداث، والقدرة على التخيل والإبداع، وقراءة اللون والخطوط الهندسية."}, {"icon": "🎤", "title": "المهمة", "text": "تأمّلي لوحات الفنانين العمانيين، واختاري إحداها، وضعي لها عنوانًا، ثم تحدثي عن إسقاطاتها على نفسك بالشكل الذي تختارين: قصة، أو خاطرة، أو وصف مباشر."}], "table": {"title": "اللوحات الثلاث (الدلالات من دليل المعلم)", "head": ["اللوحة", "الفنان", "ما توحي به"], "rows": [["شجرة، وجسم أبيض خلفها، وتفاحة مؤطرة في برواز", "أنور سونيا", "قصة آدم وحواء وإغواء الشيطان؛ الأبيض لضبابية الرؤية، والأحمر يطغى على البرواز"], ["أيادٍ ممتدة كأنها تطاول عنان السماء", "فخرية اليحيائي", "استغاثة وابتهال ورجاء، وصراع الإنسان من أجل البقاء؛ الأزرق والأحمر يهيمنان"], ["«عمانيات» عن الأزياء العمانية", "رابحة محمود", "ألوان زي الفتاة العمانية التقليدي (الأحمر والأزرق والأخضر)، صاخبة تعج بالحركة والحياة"]]}, "tip": "💡 الدلالات في دليل المعلم «مفاتيح» فقط؛ عبّري بحسب ما تثيره اللوحة في نفسك، ورتّبي أفكارك ترتيبًا منطقيًّا قبل الحديث.", "keyPoints": ["خطوات قراءة اللوحة: المونولوج، ثم الفكرة أو الموضوع، ثم متابعة العمل الفني، ثم قراءة الرموز.", "لغة الصورة: الموضوع، والأداة، والمادة، والشكل.", "كل عمل فني يتضمن «قيمة» تختلف عن الفكرة.", "الصورة الفنية تجمع بين البصر والبصيرة."], "check": [{"q": "الخطوة الأولى من خطوات قراءة اللوحة الفنية هي:", "opts": ["قراءة الرموز", "المونولوج (الحوار الداخلي مع الذات)", "متابعة العمل الفني"], "a": 1, "explain": "رتّب الكتاب الخطوات: أولًا المونولوج، ثانيًا الفكرة أو الموضوع، ثالثًا متابعة العمل الفني، رابعًا قراءة الرموز."}, {"q": "لوحة «عمانيات» التي تتحدث عن الأزياء العمانية للفنانة:", "opts": ["فخرية اليحيائي", "أنور سونيا", "رابحة محمود"], "a": 2, "explain": "اللوحة الثالثة للفنانة رابحة محمود، وقد نصّ الكتاب: «هذه اللوحة تحمل اسم (عمانيات) وتتحدث عن الأزياء العمانية»."}]}, {"type": "اقرأ واستمتع", "title": "معاملة الصديق", "page": 141, "hook": "صديقتك قالت رأيًا رائعًا… هل يحق لكِ أن تنسبيه إلى نفسك؟", "about": "نص نثري لابن المقفع في آداب الصحبة ومعاملة الأصدقاء والجلساء: ماذا نبذل لكل أحد، والأمانة في نسبة الكلام، وآداب الحديث والمجلس.", "idea": "حسن الصحبة يقوم على البذل والإنصاف، والأمانة في القول، والتأدب في الحديث والمجلس.", "cards": [{"icon": "🤲", "title": "لكلٍّ ما يناسبه", "text": "لصديقك دمك ومالك، ولمعارفك عونك وحضورك، وللناس عامة بشاشتك وحنانك، ولعدوك عدلك وإنصافك، أما دينك وعرضك فاضنن بهما عن كل أحد.", "quote": "أُبذُل لصديقك دمك ومالك، ولمعرفتك رفدك ومحضرك، وللعامة بشرَك وتحنُّنَك، ولعدوِّك عدلك وإنصافك، واضنن بدينك وعرضك عن كل أحد."}, {"icon": "🗣️", "title": "أمانة الكلام", "text": "إن أعجبك كلام صاحبك أو رأيه فلا تنتحله تزيّنًا عند الناس، بل انسبه إليه؛ فالانتحال يُسخط صاحبك وفيه عار وسُخف. ومن تمام حسن الخلق أن تسخو نفسك لأخيك بما انتحله من كلامك.", "quote": "واعلم أن انتحالك ذلك مَسخطة لصاحبك، وأن فيه مع ذلك عارا وسُخفا"}, {"icon": "🪑", "title": "أدب الحديث والمجلس", "text": "تروَّ قبل أن تتكلم ولا تقطع حديثًا بدأته، ولا تخلط الجد بالهزل، ولا يغضبك أن ترى صاحبك مع عدوك، وتحفّظ من التطاول على أصحابك، ولا تكثر ادعاء العلم بينهم.", "quote": "ليعرفِ العلماءُ حين تجالسهم أنَّك على أن تسمع أحرصُ منك على أن تقول ."}], "keyPoints": ["ابذلي لكل أحد ما يناسبه، واضنّي بدينك وعرضك.", "انسبي الكلام والرأي إلى صاحبهما؛ فالانتحال عار وسخف.", "كوني على أن تسمعي أحرص منك على أن تقولي، ولا تخلطي الجد بالهزل."], "check": [{"q": "بمَ يضنّ الإنسان عن كل أحد كما ينصح ابن المقفع؟", "opts": ["بدينه وعرضه", "بماله", "بعدله وإنصافه"], "a": 0, "explain": "قال: «واضنن بدينك وعرضك عن كل أحد». أما المال فيبذله للصديق، والعدل والإنصاف للعدو."}, {"q": "إذا رأيتِ صاحبتك مع عدوّك فإن ابن المقفع ينصح بأن:", "opts": ["تغضبي وتقاطعيها", "لا يغضبك ذلك", "تعاتبيها أمام الناس"], "a": 1, "explain": "نصّ: «إن رأيت صاحبك مع عدوك فلا يُغضبنك ذلك، فإنما هو أحد رجلين»."}]}], "activities": [{"kind": "match", "lesson": 1, "title": "صِلي كل كلمة بمعناها كما ورد في الدرس", "pairs": [["الويل", "حلول الشر، وهي كلمة عذاب"], ["التكيّف", "التلاؤم"], ["الأقانيم", "الأصول، ومفردها الأقنوم"], ["الاحتجاج (في النص)", "الاعتراض"]]}, {"kind": "mcq", "lesson": 1, "q": "ما الحقيقة المهمة الأساسية التي أراد الكاتب أن يفتح عيني ابنه عليها أولًا؟", "opts": ["أن المراهقة فترة خطيرة يجب الخوف منها", "تغيّر الزمان وتطور العلم", "أن المال سرّ القوة", "أن الأهداف يجب أن تكون ثابتة لا تتغير"], "a": 1, "explain": "1) يقول الكاتب: «أول ما أحب أن أفتح عينك عليه حقيقة هامة وأساسية: ألا وهي تغيّر الزمان وتطور العلم». 2) والكاتب يرى المراهقة مهمة لا مخيفة. 3) ويرى أن الأهداف الصحيحة لا تكون جامدة؛ فبقية الخيارات تخالف النص."}, {"kind": "classify", "lesson": 2, "title": "صنّفي التمييز في عبارات جبران وغيرها بحسب نوعه", "groups": ["تمييز ذات", "تمييز نسبة"], "items": [["اثنا عشر شهرًا", 0], ["شبرٌ أرضًا", 0], ["تسعون ألفًا", 0], ["اثنتا عشرة عينًا", 0], ["تتصاعد أنفاسك بخورًا", 1], ["يتناثر طهرك ثلجًا", 1], ["تستنبتينها حورًا", 1], ["يقرّ بك الإنسان عينًا", 1]]}, {"kind": "classify", "lesson": 2, "title": "صنّفي تمييز النسبة المحوَّل بحسب أصله", "groups": ["محوَّل عن فاعل", "محوَّل عن مفعول به", "محوَّل عن مبتدأ"], "items": [["نبغ ابن سينا طبًّا", 0], ["اشتعل الرأس شيبًا", 0], ["زرع الفلاح البستان موزًا", 1], ["فجّرنا الأرض عيونًا", 1], ["أبو تمام أخصب من البحتري خيالًا", 2], ["أنا أكثر منك مالًا", 2]]}, {"kind": "mcq", "lesson": 2, "q": "ما نوع الكلمة الملونة في: «أقبل محمد علينا راكبًا»؟", "opts": ["تمييز ذات", "تمييز نسبة", "حال", "مفعول به"], "a": 2, "explain": "1) (راكبًا) بيّنت هيئة محمد حين أقبل، وبيان الهيئة وظيفة الحال. 2) وهي مشتقة (اسم فاعل)، والغالب في الحال الاشتقاق. 3) ويصح أن تأتي جملة: أقبل محمد يركب؛ والتمييز لا يكون جملة. 4) فهي حال منصوبة."}, {"kind": "tf", "lesson": 3, "q": "تأتي الفكرة في المنزلة الأولى من عناصر العمل الأدبي في النثر الفني، أما في الشعر فتطغى عليها عناصر أخرى وتسبقها في الترتيب والأهمية.", "a": true, "explain": "1) نصّ الدرس أن الفكرة تكون في المنزلة الأولى في مجال النثر الفني (القصة، والمقالة، والخاطرة، والخطبة). 2) وأنها موجودة في القصيدة الشعرية، لكن عناصر أخرى تطغى عليها وتسبقها. 3) فالعبارة صحيحة."}, {"kind": "fill", "lesson": 3, "q": "من مقاييس الفكرة في العمل الأدبي: حجم الفكرة، و____، ووضوح الفكرة.", "opts": ["جدّة الأفكار أو قدمها", "طول القصيدة", "غرابة الألفاظ"], "a": 0, "explain": "1) ذكر الدرس ثلاثة مقاييس للفكرة. 2) الأول: حجمها (بسيطة أم مركبة). 3) الثاني: جدّة الأفكار أو قدمها بما تطرحه من جديد يهم الناس. 4) الثالث: وضوحها حتى يتأثر بها المتلقي."}, {"kind": "order", "lesson": 4, "title": "رتّبي خطوات قراءة اللوحة الفنية كما وردت في الدرس", "items": ["المونولوج: الحوار الداخلي مع الذات", "الفكرة أو الموضوع في العمل الفني", "متابعة العمل الفني (الدخول في عالم اللوحة)", "قراءة الرموز"]}], "test": [{"lesson": 1, "q": "بمَ وعد الكاتب ابنه؟", "opts": ["أن يشتري له هدية حين ينجح", "أن يكتب إليه رسالة مثل رسالة أخته حين يبلغ عمرًا يقارب عمرها", "أن يصحبه في رحلة علمية", "أن يعلّمه صياغة الأهداف"], "a": 1, "explain": "1) يقول الكاتب: «لعلك تذكر الرسالة التي كتبتها إلى أختك حين كانت في عمرك... وتمنيت عليّ أن أكتب إليك مثلها». 2) «فوعدتك أن أفعل حين تبلغ عمرًا يقارب عمرها». 3) وها هو يفي بوعده بعد أن ودّع الابن عامه الثالث عشر."}, {"lesson": 1, "q": "يرى الكاتب أن سلاح الإنسان الأمثل في عملية التكيف هو:", "opts": ["قوته الجسدية", "ماله وثروته", "قدرته على أن يعلم ويكتشف ويخترع", "خضوعه لتصاريف الزمان"], "a": 2, "explain": "1) يقول النص: «أحب لك أن تعلم أن سلاح الإنسان الأمثل في عملية التكيف هذه هو قدرته على أن يعلم، وأن يكتشف، وأن يخترع». 2) ولذلك عدّ العلم والتعلم والتعليم الأقانيم الأساسية للحياة الإنسانية."}, {"lesson": 1, "q": "في قوله: «وتترك نفسك ريشةً تتقاذفها عواصف الحياة ورياح المصادفات» صورة بيانية، فيها:", "opts": ["تشبيه الإنسان الضعيف بالريشة الخفيفة تتقاذفها الرياح", "تشبيه الحياة بالبحر", "تشبيه العقل بالسلاح", "تشبيه الأهداف بالطرق"], "a": 0, "explain": "1) المشبه: الإنسان الذي تخلّى عن عقله وحريته، والمشبه به: الريشة. 2) وفي الصورة تشبيه حوادث الزمن ومصاعبه بعواصف ورياح تعبث بتلك الريشة. 3) وهو ما ذكره دليل المعلم في حل السؤال."}, {"lesson": 1, "q": "ما معنى «الأقانيم» في قوله: «إن العلم والتعلم والتعليم هي الأقانيم الأساسية للحياة الإنسانية»؟", "opts": ["الأعداء", "الأصول", "الفروع", "الأمنيات"], "a": 1, "explain": "1) ورد في جدول المفردات: الأقانيم (ق ن م) = الأصول، ومفردها: الأقنوم. 2) فالمعنى أن العلم والتعلم والتعليم أصول الحياة الإنسانية المتطلعة إلى الأحسن."}, {"lesson": 2, "q": "تمييز النسبة هو ما كان المميَّز فيه:", "opts": ["كلمة مفردة ملفوظة تدل على كيل", "عددًا صريحًا", "جملة تتضمن نسبة شيء إلى شيء", "اسمًا مجرورًا بحرف جر"], "a": 2, "explain": "1) تمييز الذات: المميَّز فيه اسم مفرد ملفوظ (كيل، وزن، مساحة، شبه مقدار، عدد). 2) تمييز النسبة (الجملة): المميَّز فيه جملة أو نسبة شيء لشيء. 3) فالكيل والعدد من صور تمييز الذات."}, {"lesson": 2, "q": "التمييز في «نبغ ابن سينا طبًّا» محوَّل عن:", "opts": ["الفاعل", "المفعول به", "المبتدأ", "الخبر"], "a": 0, "explain": "1) نعيد الجملة إلى أصلها: نبغ طبُّ ابن سينا. 2) فكلمة (طب) كانت فاعلًا للفعل (نبغ). 3) ثم حُوِّلت إلى تمييز منصوب؛ فهو تمييز نسبة محوَّل عن الفاعل."}, {"lesson": 2, "q": "أصل جملة «زرع الفلاحُ البستانَ موزًا» هو:", "opts": ["زرع موزُ الفلاحِ البستانَ", "زرع الفلاحُ موزَ البستانِ", "موزُ البستانِ زرعه الفلاحُ", "البستانُ موزُه مزروع"], "a": 1, "explain": "1) ذكر الكتاب أن أصلها: زرع الفلاح موزَ البستان. 2) فكلمة (موز) كانت مفعولًا به. 3) ثم صارت تمييزًا منصوبًا؛ فهو تمييز نسبة محوَّل عن المفعول به."}, {"lesson": 2, "q": "نوع التمييز في قوله تعالى: ﴿إِنَّهَا سَاءَتْ مُسْتَقَرًّا وَمُقَامًا﴾:", "opts": ["تمييز ذات بعد عدد", "حال", "تمييز ذات بعد مساحة", "تمييز نسبة"], "a": 3, "explain": "1) (مستقرًّا) نكرة منصوبة جاءت بعد الفعل (ساءت)، وهو من أفعال الذم. 2) والإبهام في نسبة السوء إلى جهنم كلها لا في كلمة مفردة. 3) فهو تمييز نسبة، كما في دليل المعلم."}, {"lesson": 2, "q": "أيّ العبارات الآتية تمييزها تمييز ذات؟", "opts": ["﴿فَانبَجَسَتْ مِنْهُ اثْنَتَا عَشْرَةَ عَيْنًا﴾", "﴿وَاشْتَعَلَ الرَّأْسُ شَيْبًا﴾", "﴿وَفَجَّرْنَا الْأَرْضَ عُيُونًا﴾", "﴿ذَٰلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا﴾"], "a": 0, "explain": "1) في الخيار الأول (عينًا) فسّرت العدد (اثنتا عشرة)، والعدد مميَّز مفرد ملفوظ؛ فهو تمييز ذات. 2) أما (شيبًا) فمحوَّل عن الفاعل، و(عيونًا) محوَّل عن المفعول به، و(تأويلًا) بعد اسم التفضيل؛ وكلها تمييز نسبة كما في دليل المعلم."}, {"lesson": 3, "q": "المقياس النقدي الذي يسأل: «هل هي فكرة بسيطة أم مركبة تحتاج إلى إعمال ذهن القارئ؟» هو:", "opts": ["وضوح الفكرة", "جدّة الفكرة", "حجم الفكرة", "صدق العاطفة"], "a": 2, "explain": "1) المقياس الأول من مقاييس الفكرة: «حجم الفكرة التي يعرض لها النص الأدبي». 2) وشرحه الكتاب بقوله: «فهل هي فكرة بسيطة، أم مركبة تحتاج إلى إعمال ذهن القارئ ليستوعبها؟»."}, {"lesson": 3, "q": "وصف الدرس الفكرة في نونية أحمد شوقي «يا نائح الطلح» بأنها:", "opts": ["بسيطة غامضة", "واقعية واضحة لكنها مركبة", "خيالية بعيدة عن الواقع", "بسيطة تأخذ مجرياتها من الواقع كأبيات زهير"], "a": 1, "explain": "1) عرض شوقي أفكارًا كثيرة بينها رابط نفسي: حاضر العالم الإسلامي، ووفاءه للعرب، ثم خواطره عن مصر، ثم ذكرياته وحنينه. 2) فقال الكتاب: «فهي فكرة واقعية واضحة ولكنها مركبة تختلف عما ورد في أبيات زهير». 3) أما الفكرة البسيطة فهي فكرة زهير."}, {"lesson": 4, "q": "الخطوة الأولى من خطوات قراءة اللوحة الفنية هي:", "opts": ["قراءة الرموز", "متابعة العمل الفني", "الفكرة أو الموضوع", "المونولوج (الحوار الداخلي مع الذات)"], "a": 3, "explain": "1) رتّب الدرس الخطوات: أولًا المونولوج (الحوار الداخلي مع الذات). 2) ثانيًا الفكرة أو الموضوع. 3) ثالثًا متابعة العمل الفني. 4) رابعًا قراءة الرموز."}], "game": {"type": "sort", "groups": ["تمييز ذات", "تمييز نسبة"], "items": [["اثنا عشر شهرًا", 0], ["شبرٌ أرضًا", 0], ["تسعون ألفًا", 0], ["اثنتا عشرة عينًا", 0], ["مائة فدانٍ نخلًا", 0], ["اشترى سالم رطلًا عسلًا", 0], ["مثقال ذرة خيرًا", 0], ["اشتعل الرأس شيبًا", 1], ["نبغ ابن سينا طبًّا", 1], ["زرع الفلاح البستان موزًا", 1], ["بئس الكسل سجيةً", 1], ["يزداد الإنسان رفعةً", 1], ["تفوّق سعيد خلقًا", 1], ["أنا أكثر منك مالًا", 1]]}}, {"id": "u7", "axis": "العمل والصناعات", "axisN": 3, "unitN": 1, "title": "الوحدة الأولى", "theme": "أخلاق المهنة وصنائع العمران", "pages": "145–168", "lessons": [{"type": "القراءة", "title": "بين الأخلاق والطب", "page": 147, "hook": "طبيبٌ يأمره الخليفة بصنع دواء قتّال فيرفض… فما الذي منعه؟", "about": "مقال يتتبّع الصلة الوثيقة بين الأخلاق والطب منذ أبقراط وجالينوس، ويبيّن كيف أعاد الأطباء المسلمون صياغة قسم أبقراط وجسّدوه في سلوكهم. الكاتب: رزق يوسف علي الشامي.", "idea": "الطب مهنة لا تنفصل عن الأخلاق، وقد جسّد الأطباء المسلمون هذه الصلة قولًا وعملًا.", "cards": [{"icon": "🔗", "title": "علوم متلاحمة", "text": "العلوم مترابطة، وأشدّ التحامها بين الأخلاق والطب والفلسفة، وترجع أصول ذلك إلى ما قبل الميلاد عند اليونانيَّين أبقراط وجالينوس. صبغ جالينوس الطب بالفلسفة، فتبنّى العرب الفكرة: «أطباء فلاسفة» يمثّلهم أبو بكر الرازي، و«فلاسفة أطباء» يمثّلهم ابن سينا."}, {"icon": "📜", "title": "مواثيق الأمم وقسم أبقراط", "text": "عُنيت الحضارات القديمة بأخلاق الطبيب: المعتقدات المصرية القديمة، والزردشتية في فارس، والهندوسية في الهند؛ لكنها لم تنل شهرة قسم أبقراط وتعاليم جالينوس. ويُعدّ قسم أبقراط نواة مبكرة لأخلاق الطبيب المعروفة اليوم بـ«شرف المهنة».", "quote": "وأمّا الأشياءُ التي أعاينُها في أوقاتِ علاجِ المرضى فأُمسكُ عنها"}, {"icon": "⚕️", "title": "ماذا في القسم؟", "text": "إجلال المعلّم بمنزلة الآباء ومواساته، وتعليم الصنعة بغير أجرة ولا شرط، وقصد منفعة المرضى ومنع ما يضرّهم، وعدم إعطاء دواء قتّال، والإمساك عمّا يعاينه الطبيب في أثناء العلاج."}, {"icon": "🕌", "title": "المسلمون وحُنين بن إسحاق", "text": "أعاد الأطباء المسلمون صياغة القسم بما يناسب العقيدة فغدا دستورًا لهم ولطلابهم. أمر المأمونُ حُنينَ بن إسحاق (ت ٢٦٤هـ) أن يصنع له دواءً قتّالًا فأبى، وقال: منعني شيئان: الدين والصناعة.", "quote": "الدينُ يأمرنا بفعلِ الخيرِ والجميلِ مع أعدائنا، فكيفَ بأصحابنا؟"}, {"icon": "🤝", "title": "وصايا الرازي وابن رضوان", "text": "حثّ الرازي الطبيب على التوكّل على الله وحفظ سرّ المريض. واشترط ابن رضوان أن يكون الطبيب مأمونًا ثقةً على الأرواح والأموال، لا يصف دواءً قتّالًا ولا دواءً يُسقط الأجنّة، ويعالج عدوّه بنيّة صادقة كما يعالج صديقه.", "quote": "ينبغي على الطبيبِ أن يكونَ رفيقًا بالناسِ، حافظًا لغيبتِهم، كتومًا لأسرارِهم"}, {"icon": "🏛️", "title": "الصلة في عصرنا", "text": "عادت الصلة تأخذ صورتها القديمة بعدما اعترى الطبَّ بعضُ الخلل وتدهور القيم. وهي اليوم مُثارة في الأوساط الطبية والفقهية: مؤتمرات وفتاوى، لكن الوسط الأكاديمي ما زال محتاجًا إلى توثيقها أكثر."}, {"icon": "🌱", "title": "قيم نتعلّمها", "text": "الأمانة في المهنة، وكتمان الأسرار، والرفق بالناس، وتقديم نفع الإنسان على كل أمر ولو كان أمرَ خليفة؛ فضمير المهني الحيّ هو الوازع الحقيقي."}], "table": {"title": "أعلام النص", "head": ["العَلَم", "ما ورد عنه في النص"], "rows": [["أبقراط", "عالم يوناني، قَسَمه نواة مبكرة لأخلاق الطبيب"], ["جالينوس", "عالم يوناني صبغ الطب بالفلسفة"], ["أبو بكر الرازي", "يمثّل «الأطباء الفلاسفة»، وأوصى بالتوكل وحفظ أسرار المرضى"], ["ابن سينا", "يمثّل «الفلاسفة الأطباء»"], ["حُنين بن إسحاق", "رفض صنع دواء قتّال للمأمون: الدين والصناعة"], ["ابن رضوان", "اشترط أن يكون الطبيب مأمونًا ثقة على الأرواح والأموال"]]}, "vocab": [{"w": "تلتحم", "m": "تلاحمت الأشياء: تضامّت وتلاءمت (ل ح م)"}, {"w": "الذيوع", "m": "الانتشار (ذ ي ع)"}, {"w": "البرء", "m": "الشفاء (ب ر ء)"}, {"w": "منهجًا", "m": "الطريق الواضح"}, {"w": "تدهور في القيم", "m": "انحطاط القيم"}, {"w": "فضلًا عن", "m": "زيادة عن"}], "tip": "💡 لا تعكسي الترتيب: الرازي طبيب صار فيلسوفًا (أطباء فلاسفة)، وابن سينا فيلسوف صار طبيبًا (فلاسفة أطباء).", "keyPoints": ["أشدّ التحام بين العلوم: الأخلاق والطب والفلسفة.", "قسم أبقراط نواة مبكرة لأخلاق الطبيب (شرف المهنة).", "حُنين بن إسحاق رفض صنع دواء قتّال للمأمون لأجل الدين والصناعة.", "الرازي: الطبيب رفيق بالناس، حافظ لغيبتهم، كتوم لأسرارهم.", "ابن رضوان: الطبيب مأمون ثقة، يعالج عدوّه كما يعالج صديقه."], "check": [{"q": "مَن يمثّل «الأطباء الفلاسفة» في النص؟", "opts": ["ابن سينا", "أبو بكر الرازي", "جالينوس"], "a": 1, "explain": "النص: ظهر عند العرب أطباء فلاسفة ويمثّلهم أبو بكر الرازي، وفلاسفة أطباء ويمثّلهم ابن سينا."}, {"q": "بماذا علّل حُنين بن إسحاق رفضه صنع الدواء القتّال؟", "opts": ["الخوف من عقاب الخليفة", "قسم أبقراط وحده", "الدين والصناعة"], "a": 2, "explain": "قال: «منعني شيئان… الدين والصناعة»؛ فالدين يأمر بالخير حتى مع الأعداء، والصناعة موضوعة لنفع الناس."}]}, {"type": "الأنشطة النحوية", "title": "أحكام العدد (1)", "page": 152, "hook": "«أنفق على الحمار درهمًا… وأدفع له درهمين» — لماذا لم يذكر العدد هنا؟", "about": "يدرس أحكام الأعداد من ١ إلى ١٩: تذكيرها وتأنيثها، وموقعها من المعدود، وحال تمييزها، من خلال نصوص لابن بطوطة وابن الجوزي.", "idea": "لكل مجموعة من الأعداد حكم خاص في التذكير والتأنيث وفي تمييزها.", "cards": [{"icon": "🗂️", "title": "العدد تمييز ذات", "text": "العدد يتصل بتمييز الذات؛ لأنه أحد أشكال المميَّز المفرد الملفوظ. وتُصنَّف الأعداد مجموعات: (١، ٢) – (٣–١٠) – (١١، ١٢) – (١٣–١٩) – العقود – المعطوفة – (١٠٠، ١٠٠٠) – كنايات العدد. ودرسنا للمجموعات الأربع الأولى."}, {"icon": "1️⃣", "title": "العددان ١ و٢", "text": "يُذكَّران مع المذكر ويؤنَّثان مع المؤنث، ويسبقهما المعدود ويأتيان صفة له. ويكثر الاكتفاء بالمفرد والمثنى دون ذكر العدد: «أنفق على الحمار درهمًا وأدفع له درهمين».", "quote": "فرسخ واحد — بعد سنتين اثنتين"}, {"icon": "🔄", "title": "من ٣ إلى ١٠: المخالفة", "text": "تؤنَّث مع المذكر وتُذكَّر مع المؤنث، ونرجع إلى مفرد المعدود: جهات ← جهة (مؤنث) فقلنا «ثلاث». دراهم ← درهم (مذكر) فقلنا «أربعة». وتمييزها جمع مجرور يُعرب مضافًا إليه.", "quote": "ثلاث جهات — أربعة دراهم — تسعة أشبار"}, {"icon": "🧩", "title": "كلمة «بِضْع»", "text": "تدل على العدد من ثلاثة إلى تسعة، وتأخذ أحكامه: تُذكَّر مع المؤنث وتؤنَّث مع المذكر. وتُستعمل في العدد المركب أيضًا وتُعامل معاملته.", "quote": "امتلكت شركتنا بضع شاحنات إضافية، ووظفت بضعة عشر عاملًا إضافيًّا"}, {"icon": "🤝", "title": "العددان ١١ و١٢: الموافقة", "text": "يتوافق الجزآن مع المعدود تذكيرًا وتأنيثًا. «أحد عشر» مبني على فتح الجزأين، أما «اثنا عشر» فيُعرب جزؤه الأول إعراب المثنى، ويُبنى جزؤه الثاني على الفتح.", "quote": "أحد عشر شبرًا، وإحدى عشرة جهة، واثنا عشر يومًا، واثنتا عشرة سنة"}, {"icon": "⚖️", "title": "من ١٣ إلى ١٩", "text": "يخالف جزؤها الأول المعدود ويوافقه الثاني، وتُبنى على فتح الجزأين. ومعدود ١١–١٩ مفرد منصوب دائمًا على أنه تمييز ذات.", "quote": "طول كل رمح أربعة عشر ذراعًا"}, {"icon": "✍️", "title": "نموذج إعراب", "text": "اثنا: خبر إنّ مرفوع وعلامة رفعه الألف لأنه ملحق بالمثنى. عشر: مبني على الفتح. شهرًا: تمييز منصوب. وفي ﴿سبع ليالٍ﴾: ليالٍ مضاف إليه مجرور بالكسرة المقدرة على الياء المحذوفة.", "quote": "﴿إِنَّ عِدَّةَ الشُّهُورِ عِندَ اللَّهِ اثْنَا عَشَرَ شَهْرًا﴾"}], "table": {"title": "أمثلة الدرس في جدول", "head": ["المثال", "الحكم", "السبب"], "rows": [["فرسخ واحد", "العدد مذكر بعد المعدود", "١ يوافق المعدود ويأتي صفة له"], ["سنتين اثنتين", "العدد مؤنث بعد المعدود", "٢ يوافق المعدود ويأتي صفة له"], ["ثلاث جهات", "العدد مذكر", "مفرد جهات «جهة» مؤنث، و٣–١٠ تخالف"], ["أربعة دراهم", "العدد مؤنث", "مفرد دراهم «درهم» مذكر"], ["تسعة أشبار", "العدد مؤنث", "مفرد أشبار «شبر» مذكر"], ["أحد عشر شبرًا", "الجزآن مذكران، والتمييز مفرد منصوب", "١١ يوافق المعدود في جزأيه"], ["اثني عشر يومًا", "«اثني» منصوب بالياء و«عشر» مبني على الفتح", "١٢ يُعرب صدره إعراب المثنى"], ["أربعة عشر ذراعًا", "الجزء الأول مؤنث والثاني مذكر", "١٣–١٩: الأول يخالف والثاني يوافق"]]}, "tip": "💡 احكمي بمفرد المعدود لا بجمعه: «دراهم» مفردها «درهم» مذكر ← «أربعة دراهم». وتذكّري: تمييز ٣–١٠ جمع مجرور، وتمييز ١١–١٩ مفرد منصوب.", "keyPoints": ["١ و٢ يوافقان المعدود ويأتيان بعده صفة له.", "٣–١٠ تخالف مفرد المعدود، وتمييزها جمع مجرور مضاف إليه.", "١١ و١٢ يوافق جزآهما المعدود، و«اثنا» يُعرب إعراب المثنى.", "١٣–١٩ يخالف جزؤها الأول ويوافق الثاني، وتُبنى على فتح الجزأين.", "«بضع» من ٣ إلى ٩ وتأخذ أحكامها مفردة ومركبة."], "check": [{"q": "في قوله تعالى: ﴿إني أرى سبع بقرات سمان﴾ جاء العدد «سبع» مذكرًا لأن:", "opts": ["مفرد المعدود «بقرة» مؤنث، والعدد يخالفه", "العدد من ٣ إلى ١٠ يوافق المعدود", "العدد جاء صفة للمعدود"], "a": 0, "explain": "الأعداد من ٣ إلى ١٠ تخالف مفرد المعدود؛ ومفرد «بقرات» بقرة وهي مؤنثة، فذُكِّر العدد (إجابة دليل المعلم)."}, {"q": "اختاري الصواب: «تتضمن السنة ……».", "opts": ["اثنا عشر شهرًا", "اثني عشر شهرًا", "اثنتي عشرة شهرًا"], "a": 1, "explain": "«شهر» مذكر فالجزآن مذكران، والعدد مفعول به فيُنصب صدره بالياء «اثني»، والتمييز مفرد منصوب «شهرًا»."}]}, {"type": "النصوص الأدبية", "title": "الصنائع والعمران", "page": 161, "hook": "لماذا تجدين في المدن الكبيرة مهنًا لا تعرفها القرى الصغيرة؟ ابن خلدون أجاب قبل ستة قرون!", "about": "نص من «المقدمة» يبحث في تطور العمران البشري، ويقرّر أن الصنائع تكمل بكمال العمران الحضري، مستدلًّا بدراسة الواقع. كاتبه عبدالرحمن بن محمد بن خلدون.", "author": {"name": "عبدالرحمن بن محمد بن خلدون (٧٣٢هـ – ٨١٨هـ)", "bio": "وُلد في تونس، ودرس المنطق والفلسفة والتاريخ والفقه، وسبق علماء الغرب في التأليف في فلسفة التاريخ. يعدّه كثير من الأكاديميين المؤسس الحقيقي لعلم الاجتماع، ومن أهم مؤلفاته «المقدمة»."}, "idea": "الصنائع إنما تكمل بكمال العمران الحضري وكثرته.", "cards": [{"icon": "📌", "title": "يبدأ بالنظرية", "text": "صدّر ابن خلدون نصه بعنوان هو بمثابة النظرية أو القانون، فانطلق من النتيجة، ثم أخذ يحلل الأسباب التي تبرهن على صحتها.", "quote": "في أن الصنائع إنما تكمل بكمال العمران الحضري وكثرته"}, {"icon": "🌾", "title": "الضروري قبل الكمالي", "text": "ما لم يكتمل العمران الحضري فهمّ الناس في الضروري من المعاش، وهو تحصيل الأقوات من الحنطة وغيرها. فإذا زادت الأعمال على الضروري صُرف الزائد إلى الكمالات.", "quote": "فإذا تمدنت المدينةُ وتزايدت فيها الأعمال ووفّت بالضروري وزادت عليه، صُرف الزائدُ حينئذٍ إلى الكمالات من المعاش"}, {"icon": "🧠", "title": "الإنسان والحيوان", "text": "يشترك الإنسان مع الحيوان في حاجته إلى القوت، ويتميز عنه بالفكر الذي تقوم عليه الصنائع والعلوم؛ لذلك يتقدّم القوت لضرورته، وتتأخر العلوم والصنائع عنه.", "quote": "ثم إن الصنائعَ والعلوم إنما هي للإنسان من حيث فِكْرُهُ الذي يتميزُ به عن الحيوانات"}, {"icon": "⛺", "title": "العمران البدوي", "text": "لا يحتاج إلا الصنائع البسيطة المستعملة في الضروريات: النجار والحداد والخياط والحائك والجزار. وإذا وُجدت فلا تكون كاملة ولا مستجادة؛ لأنها وسائل وليست مقصودة لذاتها."}, {"icon": "🏙️", "title": "العمران الحضري", "text": "إذا كثر العمران طُلب التأنق في الصنائع، وتزايدت صنائع يدعو إليها الترف: الجزار والدباغ والخرّاز والصائغ، ثم الدهّان والصفّار والحمّامي والطباخ والهرّاس ومعلّم الغناء، والورّاقون الذين ينسخون الكتب ويجلّدونها ويصحّحونها.", "quote": "وإذا زَخَرَ بحرُ العمرانِ وطُلبتْ فيه الكَمالات، كان من جملتها التأنُّق في الصنائع واستجادتها"}, {"icon": "🐦", "title": "الدليل من الواقع", "text": "بلغه أن في أهل مصر من يعلّم الطيور العُجم والحُمُر الإنسية، ومن يمشي على الخيوط في الهواء ويرفع الأثقال؛ وهي صنائع لا توجد بالمغرب؛ لأن عمران أمصاره لم يبلغ عمران مصر والقاهرة."}, {"icon": "🔬", "title": "لغة العالِم الرائد", "text": "لغة النص علمية، فيها جهاز من مصطلحات العلوم الاجتماعية والاقتصادية: العمران الحضري، العمران البدوي، التمدن، المعاش، الأعمال، الكمالات، الصنائع، الثروة، الترف؛ وهذا دليل ريادته لهذه العلوم. وفي «زخر بحر العمران» صوّر العمران بحرًا ممتلئًا فائضًا."}], "table": {"title": "موازنة بين العمرانين", "head": ["وجه الموازنة", "العمران البدوي", "العمران الحضري"], "rows": [["همّ الناس", "الضروري من المعاش (الأقوات)", "الكمالات بعد استيفاء الضروري"], ["الصنائع", "بسيطة: نجار، حداد، خياط، حائك، جزار", "يدعو إليها الترف: دباغ، خرّاز، صائغ، صفّار، ورّاق…"], ["جودتها", "لا توجد كاملة ولا مستجادة", "يُتأنَّق فيها وتكمل بجميع متمماتها"]]}, "vocab": [{"w": "الحِنطة", "m": "القمح، ج: حِنَط (ح ن ط)"}, {"w": "التأنُّق", "m": "تأنّق فيه: أتقنه وجوّده (أ ن ق)"}, {"w": "حائك", "m": "حاك الثوب: نسجه، ج: حاكة (ح و ك)"}, {"w": "زَخَر", "m": "كثر وفاض (ز خ ر)"}, {"w": "الدبّاغ", "m": "معالج الجلود ومصلحها (د ب غ)"}, {"w": "لِمُنتحِلها", "m": "المنتسب إليها (ن ح ل)"}, {"w": "الصفّار", "m": "صانع النحاس الأصفر (ص ف ر)"}, {"w": "الحمّامي", "m": "صاحب الحمّام، والعامل فيه (ح م م)"}], "tip": "💡 انتبهي: «الجزّار» ورد في النص مع صنائع البدو البسيطة، وورد أيضًا أول صنائع الحضر؛ فلا تجعليه خطأً إن رأيتِه في القائمتين.", "keyPoints": ["النظرية: الصنائع تكمل بكمال العمران الحضري وكثرته.", "البدو همّهم الضروري، والحضر يصرفون الزائد إلى الكمالات.", "الإنسان يشارك الحيوان في القوت، ويتميز عنه بالفكر.", "استدل بالواقع: صنائع في مصر لا توجد بالمغرب لقلة عمرانه.", "كثرة المصطلحات الاجتماعية والاقتصادية دليل ريادة ابن خلدون."], "check": [{"q": "أيّ هذه الصنائع من صنائع العمران البدوي البسيطة؟", "opts": ["الصائغ", "الحائك", "الورّاق"], "a": 1, "explain": "ذكر ابن خلدون للبدو: النجار والحداد والخياط والحائك والجزار؛ أما الصائغ والورّاق فمن صنائع الترف في الحضر."}, {"q": "كيف أثبت ابن خلدون صحة نظريته من الواقع؟", "opts": ["بأن أمصار المغرب أكثر عمرانًا من مصر", "بكثرة الحنطة في القاهرة", "بصنائع عجيبة عند أهل مصر لا توجد بالمغرب"], "a": 2, "explain": "ذكر صنائع في مصر كتعليم الطيور والمشي على الخيوط، لا توجد بالمغرب؛ لأن عمران أمصاره لم يبلغ عمران مصر والقاهرة."}]}, {"type": "التعبير", "title": "الخبر الصحفي", "page": 166, "hook": "عنوان واحد قد يجعل القارئ يقرأ خبرك كله… أو يقلب الصفحة!", "about": "درس في التعبير الكتابي الوظيفي: تختارين حدثًا من الأحداث اليومية الجارية (اجتماعيًّا أو سياسيًّا أو رياضيًّا أو ثقافيًّا أو صحيًّا) وتكتبين عنه خبرًا صحفيًّا وفق أسس الصحافة.", "idea": "الخبر الصحفي الناجح يجيب عن ستة أسئلة، في عنوان ومقدمة ومضمون.", "cards": [{"icon": "❓", "title": "القسم الأول: خمسة أسئلة", "text": "من؟ صانعو الحدث. ماذا؟ سرد وقائع الحدث بصيغة الجملة الخبرية. متى؟ زمن الوقوع. أين؟ مكان الحدوث. لماذا؟ الأسباب والمعطيات التي أنتجت الأحداث."}, {"icon": "🔍", "title": "القسم الثاني: كيف؟", "text": "سؤال واحد: الحالة الوصفية التي يتقصّى فيها الصحفي ظروف الحادثة وملابساتها كافة، مع وصف وقائعها."}, {"icon": "🏷️", "title": "العنوان", "text": "معبّر يتطابق فيه المضمون مع العنوان، مثير للانتباه، جذاب، دقيق، مختصر، يركّز على العنصر البارز أو الأمر المثير أو الغريب في الخبر.", "quote": "ارتفاع نسبة الحوادث في السلطنة — ماذا يريد التربويون من الإعلاميين؟! — دور الإعلام في التنوع الثقافي"}, {"icon": "🚪", "title": "المقدمة (الصدر)", "text": "الركن الثاني بعد العنوان والأكثر أهمية؛ لأن القارئ كثيرًا ما يكتفي بها. اعتمدي فيها تكثيف المعلومات والإجابة عن الأسئلة الستة مع إبراز السؤال الأول، ثم اعرضي الوقائع من المهم إلى الأهم حتى الخاتمة التي تشكّل ذروته."}, {"icon": "📄", "title": "المضمون", "text": "يُوزَّع في فقرات، تتناول كل فقرة فكرة من الخبر أو قولًا. ومهما كان الخبر صغيرًا يُستحسن أن يُعرض في فقرتين على الأقل."}, {"icon": "✅", "title": "مواصفات الخبر الناجح", "text": "١- حداثة الخبر وجدّته. ٢- الدقة في صياغته ونقله. ٣- المصداقية. ٤- بساطة اللغة ووضوحها. ٥- علاقته باهتمامات الجمهور."}], "table": {"title": "عناصر الخبر الصحفي", "head": ["العنصر", "وظيفته", "ما يُراعى فيه"], "rows": [["العنوان", "يعبّر عن الخبر والرسالة الإعلامية", "ملخّص أو تساؤل أو إبراز قضية؛ جذاب دقيق مختصر"], ["المقدمة (الصدر)", "تعرّف القارئ بالموضوع", "تكثيف المعلومات وإجابة الأسئلة الستة"], ["المضمون", "عرض تفاصيل الخبر", "فقرات، لكل فقرة فكرة أو قول، وفقرتان على الأقل"]]}, "tip": "💡 رتّبي الوقائع بالتدرّج من المهم إلى الأهم حتى تصلي إلى خاتمة الخبر التي تشكّل ذروته.", "keyPoints": ["الأسئلة الستة: من، ماذا، متى، أين، لماذا + كيف.", "عناصر الخبر: العنوان، المقدمة (الصدر)، المضمون.", "أنواع العناوين: الملخّص، التساؤل، إبراز قضية معينة.", "المقدمة أهم الأركان لأن القارئ كثيرًا ما يكتفي بها.", "الخبر الناجح: حديث، دقيق، صادق، بسيط اللغة، يهمّ الجمهور."], "check": [{"q": "السؤال «كيف؟» في الخبر الصحفي يقع في:", "opts": ["القسم الثاني", "القسم الأول", "العنوان وحده"], "a": 0, "explain": "القسم الأول خمسة أسئلة (من، ماذا، متى، أين، لماذا)، والقسم الثاني سؤال واحد هو «كيف؟»."}, {"q": "لماذا تُعدّ مقدمة الخبر الأكثر أهمية؟", "opts": ["لأنها أطول أجزاء الخبر", "لأنها تأتي بعد المضمون", "لأن القارئ كثيرًا ما يكتفي بها ليتعرف على الموضوع"], "a": 2, "explain": "نصّ الكتاب: «لأن القارئ كثيرًا ما يكتفي بمقدمة الخبر ليتعرف على الموضوع»."}]}], "activities": [{"kind": "mcq", "lesson": 1, "q": "مَن الطبيب الذي أبى أن يصنع للخليفة المأمون دواءً قتّالًا؟", "opts": ["أبو بكر الرازي", "حُنين بن إسحاق", "ابن رضوان", "ابن سينا"], "a": 1, "explain": "ورد في النص أن الخليفة المأمون أمر حُنين بن إسحاق (ت 264هـ) بأن يصنع له دواءً قتّالًا فأبى، وعلّل ذلك بأن الدين يأمر بفعل الخير حتى مع الأعداء، وأن صناعة الطب موضوعة لنفع الناس لا للإضرار بهم. أما الرازي فحثّ على التوكل وكتمان الأسرار، وابن رضوان اشترط الأمانة في الطبيب."}, {"kind": "tf", "lesson": 1, "q": "يمثّل أبو بكر الرازي «الفلاسفة الأطباء»، ويمثّل ابن سينا «الأطباء الفلاسفة».", "a": false, "explain": "العبارة معكوسة. النص يقول: ظهر عند العرب «أطباء فلاسفة» ويمثّلهم أبو بكر الرازي، و«فلاسفة أطباء» ويمثّلهم ابن سينا؛ فالرازي طبيب في الأصل اشتغل بالفلسفة، وابن سينا فيلسوف اشتغل بالطب."}, {"kind": "classify", "lesson": 2, "title": "صنّفي الأعداد بحسب علاقتها بالمعدود في التذكير والتأنيث", "groups": ["العدد يوافق المعدود", "العدد يخالف المعدود"], "items": [["فرسخٌ واحدٌ", 0], ["ثلاث جهات", 1], ["تسعة أشبار", 1], ["سنتين اثنتين", 0], ["أحد عشر شبرًا", 0], ["أربعة دراهم", 1], ["اثنتا عشرة سنةً", 0], ["سبع بقرات", 1]]}, {"kind": "fill", "lesson": 2, "q": "رأى يوسف عليه السلام في منامه ____ والشمس والقمر.", "opts": ["إحدى عشرة كوكبًا", "أحد عشر كوكبًا", "أحد عشر كواكب"], "a": 1, "explain": "المعدود «كوكب» مذكر، والعدد 11 يوافق المعدود في جزأيه، فنقول «أحد عشر» بجزأين مذكرين. وتمييز الأعداد من 11 إلى 99 مفرد منصوب، فنقول «كوكبًا» لا «كواكب». وهي إجابة دليل المعلم للتدريب الأول."}, {"kind": "match", "lesson": 2, "title": "صِلي كل مجموعة من الأعداد بحكمها", "pairs": [["العددان 1 و2", "يوافقان المعدود ويأتيان بعده صفةً له"], ["الأعداد من 3 إلى 10", "تخالف المعدود وتمييزها جمع مجرور"], ["العددان 11 و12", "يوافق جزآهما المعدود تذكيرًا وتأنيثًا"], ["الأعداد من 13 إلى 19", "يخالف جزؤها الأول ويوافق الثاني"], ["كلمة «بضع»", "تدل على العدد من 3 إلى 9 وتأخذ حكمه"]]}, {"kind": "mcq", "lesson": 3, "q": "متى يُصرف الزائد من الأعمال إلى الكمالات من المعاش عند ابن خلدون؟", "opts": ["إذا قلّ الناس في المدينة واكتفوا بالأقوات", "إذا كان العمران بدويًّا قليلًا", "إذا تمدّنت المدينة وتزايدت فيها الأعمال ووفّت بالضروري وزادت عليه", "إذا انتشرت الصنائع البسيطة كالنجارة والحدادة"], "a": 2, "explain": "يقول ابن خلدون: «فإذا تمدّنت المدينة وتزايدت فيها الأعمال ووفّت بالضروري وزادت عليه؛ صُرف الزائد حينئذ إلى الكمالات من المعاش». أما العمران البدوي فهمّه في الضروري فقط، والصنائع البسيطة هي صنائع الضرورة لا الكمالات."}, {"kind": "order", "lesson": 4, "title": "رتّبي مراحل بناء الخبر الصحفي كما وردت في الدرس", "items": ["كتابة عنوان معبّر جذاب دقيق مختصر", "كتابة المقدمة (الصدر) بتكثيف المعلومات والإجابة عن الأسئلة الستة", "عرض الوقائع بالتدرج من المهم إلى الأهم", "الوصول إلى خاتمة الخبر التي تشكّل ذروته"]}, {"kind": "tf", "lesson": 4, "q": "يقسم المختصون أسئلة الخبر الصحفي الستة قسمين: الأول خمسة أسئلة، والثاني سؤال واحد هو «كيف؟».", "a": true, "explain": "نصّ الدرس على أن القسم الأول يتكون من خمسة أسئلة: من؟ ماذا؟ متى؟ أين؟ لماذا؟، والقسم الثاني من سؤال واحد هو «كيف؟» أي الحالة الوصفية التي يتقصّى فيها الصحفي ظروف الحادثة وملابساتها."}], "test": [{"q": "معنى كلمة «الذيوع» في قول الكاتب: «فإنها لم تنل من الشهرة والذيوع ما ناله قسم أبقراط»:", "opts": ["الشفاء", "الانتشار", "التلاحم", "الاختفاء"], "a": 1, "lesson": 1, "explain": "في جدول المفردات: الذيوع من الجذر (ذ ي ع) ومعناه الانتشار. أما الشفاء فمعنى «البُرء»، والتلاحم من «تلتحم»، والاختفاء ضد الذيوع."}, {"q": "مَن الطبيب المسلم الذي شدّد على أن يكون الطبيب كتومًا لأسرار مرضاه حافظًا لغيبتهم؟", "opts": ["ابن رضوان", "حُنين بن إسحاق", "جالينوس", "أبو بكر الرازي"], "a": 3, "lesson": 1, "explain": "يقول الرازي: «واعلم يا بُنيّ أنّه ينبغي على الطبيب أن يكون رفيقًا بالناس، حافظًا لغيبتهم، كتومًا لأسرارهم». أما ابن رضوان فاشترط الأمانة على الأرواح والأموال، وحنين رفض صنع الدواء القتّال، وجالينوس يوناني لا مسلم."}, {"q": "علّل حُنين بن إسحاق امتناعه عن صنع الدواء القتّال للمأمون بأمرين هما:", "opts": ["الخوف من الخليفة والخوف من الناس", "قلة المال وصعوبة الدواء", "قَسَم أبقراط وتعاليم جالينوس", "الدين والصناعة"], "a": 3, "lesson": 1, "explain": "قال حنين: «منعني شيئان يا أمير المؤمنين… الدين والصناعة؛ الدين يأمرنا بفعل الخير والجميل مع أعدائنا فكيف بأصحابنا؟ والصناعة تمنعنا من الإضرار بأبناء جنسنا لأنها موضوعة لنفعهم»."}, {"q": "ما المحسّن البديعي بين كلمتي «يكتمه» و«يُفشونه»؟", "opts": ["جناس ناقص", "سجع", "طباق", "تشبيه"], "a": 2, "lesson": 1, "explain": "الكتمان ضد الإفشاء، والجمع بين الكلمة وضدها في الكلام يسمى طباقًا، وهو يوضّح المعنى ويقوّيه. ولا جناس بينهما لاختلاف الحروف، ولا سجع لأنهما ليسا في نهايتي فاصلتين متوافقتين."}, {"q": "اختاري الصواب لملء الفراغ: «تتضمن السنة ____».", "opts": ["اثنا عشر شهرًا", "اثني عشر شهرًا", "اثنتي عشرة شهرًا", "اثني عشر شهورٍ"], "a": 1, "lesson": 2, "explain": "1) المعدود «شهر» مذكر، فجزءا العدد 12 مذكران: «اثنا/اثني عشر». 2) العدد هنا مفعول به للفعل «تتضمن»، وصدره «اثنا» يُعرب إعراب المثنى فيُنصب بالياء: «اثني». 3) التمييز مفرد منصوب: «شهرًا». وهي إجابة دليل المعلم."}, {"q": "في قوله تعالى: ﴿إني أرى سبعَ بقراتٍ سمان﴾ جاء العدد «سبع» مذكرًا لأن:", "opts": ["مفرد المعدود «بقرة» مؤنث، والعدد من 3 إلى 10 يخالف المعدود", "المعدود جمع، والعدد يوافق الجمع دائمًا", "العدد من 3 إلى 10 يوافق المعدود في التذكير", "العدد جاء صفةً للمعدود"], "a": 0, "lesson": 2, "explain": "الأعداد من 3 إلى 10 تخالف المعدود، ونرجع إلى مفرده لنحكم؛ فمفرد «بقرات» بقرة وهو مؤنث، فجاء العدد «سبع» مذكرًا. وهذا ما في دليل المعلم: «ذكّر العدد لأن معدوده مؤنث». والعدد لا يأتي صفة إلا في 1 و2."}, {"q": "إعراب «طالبًا» في جملة: «وضمّت الثانية خمسة عشر طالبًا»:", "opts": ["مفعول به منصوب", "حال منصوبة", "مضاف إليه مجرور", "تمييز منصوب وعلامة نصبه الفتحة"], "a": 3, "lesson": 2, "explain": "تمييز الأعداد من 11 إلى 19 مفرد منصوب دائمًا على أنه تمييز ذات؛ فـ«طالبًا» تمييز منصوب بالفتحة. أما المفعول به فهو العدد المركب «خمسة عشر» المبني على فتح الجزأين في محل نصب (كما في دليل المعلم)."}, {"q": "إعراب «خمسة عشر» في: «وضمّت الثانية خمسة عشر طالبًا»:", "opts": ["مفعول به منصوب بالفتحة الظاهرة", "فاعل مرفوع بالضمة", "عدد مركب مبني على فتح الجزأين في محل نصب مفعول به", "عدد مركب مبني على فتح الجزأين في محل رفع فاعل"], "a": 2, "lesson": 2, "explain": "الأعداد من 13 إلى 19 مبنية على فتح الجزأين، فلا تظهر عليها حركة إعراب ويُذكر موقعها «في محل». والفاعل في الجملة هو «الثانية» (أي الرحلة الثانية)، والعدد وقع عليه فعل الضمّ فهو في محل نصب مفعول به، و«طالبًا» تمييز منصوب. وهذا إعراب دليل المعلم."}, {"q": "قال الجاحظ: «ثلاث لا يشبعن من ثلاثة: عين من نظر، وأرض من مطر، وأذن من خبر». جاء العدد مذكرًا في المرة الأولى لأن:", "opts": ["معدوده (عين، أرض، أذن) مؤنث", "معدوده (نظر، مطر، خبر) مذكر", "العدد يوافق المعدود دائمًا", "العدد وقع مبتدأ"], "a": 0, "lesson": 2, "explain": "العدد 3 يخالف المعدود: في المرة الأولى معدوداته عين وأرض وأذن وهي مؤنثة فجاء «ثلاث» مذكرًا، وفي المرة الثانية معدوداته نظر ومطر وخبر وهي مذكرة فجاء «ثلاثة» مؤنثًا. وهذه إجابة دليل المعلم للتدريب الثالث."}, {"q": "المحور العام (النظرية) الذي يقوم عليه نص ابن خلدون هو:", "opts": ["أن العمران البدوي أكمل صنائع من الحضري", "أن الإنسان لا يختلف عن الحيوان في شيء", "أن الصنائع إنما تكمل بكمال العمران الحضري وكثرته", "أن أهل المغرب أكثر عمرانًا من أهل مصر"], "a": 2, "lesson": 3, "explain": "صدّر ابن خلدون نصه بعنوان يعدّ بمثابة القانون: «في أن الصنائع إنما تكمل بكمال العمران الحضري وكثرته»، ثم حلل أسبابه. وبقية الخيارات تخالف النص: فالبدوي صنائعه بسيطة، والإنسان يتميز بالفكر، ومصر أكثر عمرانًا من المغرب."}, {"q": "أيّ الصنائع الآتية من صنائع العمران الحضري التي يدعو إليها الترف، لا من صنائع العمران البدوي البسيطة؟", "opts": ["النجار", "الورّاق", "الحائك", "الحداد"], "a": 1, "lesson": 3, "explain": "ذكر ابن خلدون أن العمران البدوي لا يحتاج إلا الصنائع البسيطة: النجار والحداد والخياط والحائك والجزار. أما الورّاقون الذين يعانون انتساخ الكتب وتجليدها وتصحيحها فصناعتهم يدعو إليها الترف في المدينة."}, {"q": "في أي قسم من أسئلة الخبر الصحفي يقع السؤال «كيف؟»، وما المقصود به؟", "opts": ["القسم الأول، ويعني زمن وقوع الحادثة", "القسم الأول، ويعني مكان الحادثة", "القسم الثاني، ويعني أسباب الحادثة", "القسم الثاني، ويعني الحالة الوصفية لظروف الحادثة وملابساتها"], "a": 3, "lesson": 4, "explain": "القسم الثاني يتكون من سؤال واحد هو «كيف؟»، أي الحالة الوصفية التي يتقصّى فيها الصحفي ظروف الحادثة وملابساتها مع وصف وقائعها. أما الزمن فيجيب عنه «متى؟»، والمكان «أين؟»، والأسباب «لماذا؟» وكلها من القسم الأول."}], "game": {"type": "conveyor", "rounds": [{"prompt": "اختاري الصحيح (الأعداد من 3 إلى 10)", "items": [{"t": "ثلاثة أشبار", "ok": true}, {"t": "ثلاث أشبار", "ok": false}, {"t": "ثلاثة جهات", "ok": false}, {"t": "ثلاث جهات", "ok": true}]}, {"prompt": "اختاري الصحيح (العددان 11 و12)", "items": [{"t": "أحد عشر كوكبًا", "ok": true}, {"t": "إحدى عشر كوكبًا", "ok": false}, {"t": "اثنتا عشرة سنةً", "ok": true}, {"t": "اثنا عشرة سنةً", "ok": false}]}, {"prompt": "اختاري الصحيح (الأعداد من 13 إلى 19)", "items": [{"t": "خمسة عشر طالبًا", "ok": true}, {"t": "خمس عشرة طالبًا", "ok": false}, {"t": "ثلاثة عشر طالبةً", "ok": false}, {"t": "ثلاث عشرة طالبةً", "ok": true}]}, {"prompt": "اختاري الصحيح (العددان 1 و2)", "items": [{"t": "فرسخٌ واحدٌ", "ok": true}, {"t": "سنتان اثنان", "ok": false}, {"t": "سنتان اثنتان", "ok": true}, {"t": "رحلتان اثنا", "ok": false}]}, {"prompt": "اختاري التمييز الصحيح", "items": [{"t": "تسعة طلابٍ", "ok": true}, {"t": "تسعة طالبٍ", "ok": false}, {"t": "سبعة عشر دروسًا", "ok": false}, {"t": "سبعة عشر درسًا", "ok": true}]}, {"prompt": "اختاري الاستعمال الصحيح لـ«بضع»", "items": [{"t": "بضع شاحنات", "ok": true}, {"t": "بضعة شاحنات", "ok": false}, {"t": "بضعة عشر عاملًا", "ok": true}, {"t": "بضع عشرة عاملًا", "ok": false}]}, {"prompt": "اختاري العبارة الصحيحة من درس «بين الأخلاق والطب»", "items": [{"t": "حنين رفض صنع الدواء القتّال", "ok": true}, {"t": "جالينوس فصل الطب عن الفلسفة", "ok": false}, {"t": "قسم أبقراط نواة أخلاق الطبيب", "ok": true}, {"t": "الرازي يمثّل الفلاسفة الأطباء", "ok": false}]}, {"prompt": "اختاري العبارة الصحيحة (ابن خلدون والخبر الصحفي)", "items": [{"t": "الصنائع تكمل بكمال العمران الحضري", "ok": true}, {"t": "البدو يحتاجون صنائع الترف", "ok": false}, {"t": "الخبر الصحفي يقوم على أربعة أسئلة", "ok": false}, {"t": "مقدمة الخبر أهم أركانه", "ok": true}]}]}}, {"id": "u8", "axis": "العمل والصناعات", "axisN": 3, "unitN": 2, "title": "الوحدة الثانية", "theme": "لوحات الوصف وأنغام الجناس", "pages": "169–188", "lessons": [{"type": "النصوص الأدبية", "title": "في الوصف", "page": 169, "hook": "قلمٌ تطيعه الرماح، وبركةٌ تنافس البحر، وخبّاز أسرع من لمح البصر… ثلاث لوحات من العصر العباسي!", "about": "ثلاثة نصوص في فن الوصف تمثّل تحوّل الشاعر من وصف الصحراء إلى وصف مظاهر الحضارة في العصر العباسي: أبو تمام يصف القلم، والبحتري يصف بركة المتوكل، وابن الرومي يصف خبّازًا.", "author": {"name": "أبو تمام (١٩٠–٢٣١هـ)، البحتري (٢٠٦–٢٨٤هـ)، ابن الرومي (٢٢١–٢٨٣هـ)", "bio": "أبو تمام حبيب بن أوس الطائي، أثار شعره جدلًا كبيرًا بين النقاد. والبحتري أبو عبادة الوليد بن عبيد الطائي، لازم أبا تمام وعليه تخرّج، ويتسم شعره بسهولة الأسلوب. وابن الرومي أبو الحسن علي بن العباس بن جريج، شاعر مكثر مطبوع برع في الوصف والهجاء."}, "idea": "وصف الشعراء العباسيون مظاهر الحضارة الجديدة: القلم والبركة والخبّاز.", "cards": [{"icon": "✒️", "title": "قلمٌ فصيح وأعجم", "text": "يصف أبو تمام القلم: إذا ركب الأصابع نطق فصيحًا، وإذا تُرك وحده صار أعجم لا ينطق. وحين تمتطيه الأصابع الخمس وتنصبّ عليه شعاب الفكر يبدأ عمله.", "quote": "فصيحٌ إذا استنْطَقْتَهُ وهو راكبٌ — وأعجمُ إنْ خاطبتَه وهو راجِلُ"}, {"icon": "⚔️", "title": "قلمٌ تطيعه الجيوش", "text": "بكلمات القلم تطيع أطرافُ الرماح، وتنهار الجيوش كما تُقوَّض الخيام؛ فالكلمة المكتوبة أقوى من السلاح.", "quote": "أطاعتْه أطرافُ القنا وتَقَوَّضَتْ — لنجواه تقويضَ الخيامِ الجحافِلُ"}, {"icon": "🪶", "title": "مفارقة القلم", "text": "القلم ضئيل نحيل (مرهف، ناحل)، لكن شأنه جليل وأثره عظيم (جليل، سمين). وهذه المفارقة بين صفاته وأفعاله تُبرز أهميته رغم صغر حجمه.", "quote": "رأيتَ جليلاً شأنُه وهو مُرْهَفٌ — ضَنَىً وسَميناً خَطْبُهُ وهو ناحِلُ"}, {"icon": "🌊", "title": "بركةٌ تنافس البحر", "text": "يكفي البركة فخرًا أنها تُعدّ الأولى والبحر ثانيها. ويندفع الماء فيها مسرعًا كالخيل حين تنطلق من حبالها، وصفاؤه كالفضة البيضاء السائلة من السبائك.", "quote": "بِحَسْبِها أنها، في فضلِ رُتْبَتِها — تُعَدُّ واحدةً، والبحرُ ثانيها"}, {"icon": "✨", "title": "الماء بين الريح والنجوم", "text": "إذا هبّت ريح الصَّبا تموّج الماء طرائقَ كالدروع المصقولة، وإذا انعكست النجوم فيه ليلًا ظننتِه سماءً أخرى. واستمد البحتري صوره من عناصر حسية: البحر، الخيل، الفضة، الصبا، الدروع، النجوم، السماء.", "quote": "إذا عَلَتْها الصَّبا، أبْدَتْ لها حُبُكاً — مثلَ الجواشِنِ، مَصقولا حواشيها"}, {"icon": "🍞", "title": "خبّاز ابن الرومي", "text": "لم يُعنَ ابن الرومي بتفاصيل حدث المرور، بل بسرعة الخبّاز في تحويل الرقاقة من كرة إلى قرص كالقمر، وقاسها بصورتين: لمح البصر، والدائرة التي تتسع في الماء حين يُرمى فيه حجر.", "quote": "ما أنْسَ لا أنْسَ خبّازاً مررتُ بهِ — يَدْحُو الرُّقاقةَ وشْكَ اللَّمْحِ بالبَصَرِ"}, {"icon": "🎨", "title": "أدوات الشعراء", "text": "أبو تمام: الطباق (فصيح/أعجم، راكب/راجل…) لبناء الصور وتكثيف الإيقاع، وأساليب الشرط (إذا، إن) وكأن ظروفًا يجب أن تتوفر للقلم. والنصوص تعكس عصرها: انتشار الكتابة والعلم، والتأنق في البناء، والتفنن في الطعام."}], "table": {"title": "الشعراء الثلاثة في لمحة", "head": ["الشاعر", "الموصوف", "أبرز ما في الوصف"], "rows": [["أبو تمام", "القلم", "الطباق، أساليب الشرط، المفارقة بين صغره وعظم أثره"], ["البحتري", "بركة المتوكل", "الماء كالخيل، كالفضة، تموّجه كالدروع، النجوم فيه كسماء"], ["ابن الرومي", "الخبّاز", "السرعة: لمح البصر، والدائرة في صفحة الماء"]]}, "vocab": [{"w": "يدحو", "m": "دحا الشيء: بسطه ووسّعه (د ح و)"}, {"w": "قَوْراء", "m": "قُوِّرت الدار: وُسِّعت، فهي قوراء (ق و ر)"}, {"w": "تنداح", "m": "تتّسع (د و ح)"}, {"w": "حوافل", "m": "شديدة الكثرة (ح ف ل)"}, {"w": "رَفَدَتْه", "m": "دعمته وأمسكته (ر ف د)"}, {"w": "مغانيها", "m": "جمع مغنى وهو المنزل (غ ن ي)"}, {"w": "حُبُكًا", "m": "حبكت الريح الرمل والماء الساكن: جعلت فيه طرائق (ح ب ك)"}, {"w": "الجواشن", "m": "الدرع، مفرده: جوشن (ج و ش ن)"}, {"w": "حواشيها", "m": "الحاشية من كل شيء: جانبه وطرفه (ح ش ي)"}], "tip": "💡 المطلوب حفظه: وصف بركة المتوكل (ستة أبيات) ووصف الخبّاز لابن الرومي (ثلاثة أبيات). وانتبهي: أبيات البركة للبحتري، وإن نسبها مربع «الحفظ» في الكتاب إلى أبي تمام.", "keyPoints": ["أبو تمام يصف القلم، والبحتري بركة المتوكل، وابن الرومي خبّازًا.", "في نص أبي تمام ظاهرتان: الطباق، وكثرة أساليب الشرط.", "البحتري: الماء كالخيل سرعةً، وكالفضة صفاءً، وتموّجه كالجواشن.", "ابن الرومي صوّر سرعة الخبّاز بلمح البصر وبالدائرة في الماء.", "النصوص تعكس الحياة العباسية: العلم والكتابة، والعمارة، وألوان الطعام."], "check": [{"q": "بماذا شبّه البحتري سرعة جريان الماء في البركة؟", "opts": ["بالفضة البيضاء", "بالخيل الجارية من حبل مُجريها", "بالدروع المصقولة"], "a": 1, "explain": "في البيت الثالث: «تنصبّ فيها وفود الماء معجلة كالخيل»؛ أما الفضة فللصفاء، والدروع لتموّج الماء بالصَّبا."}, {"q": "ما الذي لفت انتباه ابن الرومي عند الخبّاز؟", "opts": ["سرعته في بسط الرقاق", "تفاصيل حدث المرور به", "نظافة دكانه"], "a": 0, "explain": "الكتاب ودليل المعلم: لم يُعنَ بتفاصيل الحدث، وإنما شغلته سرعة الخبّاز في بسط الرقاق."}]}, {"type": "الأنشطة النحوية", "title": "أحكام العدد (2)", "page": 174, "hook": "«عشرون بيتًا» و«ألف درهم» و«كم من فئة»… لماذا يُنصب التمييز مرة ويُجرّ مرة؟", "about": "يستكمل أحكام العدد في أربع مجموعات: ألفاظ العقود، والأعداد المعطوفة، والعددين ١٠٠ و١٠٠٠، وكنايات العدد، بأمثلة من شوقي ولسان الدين بن الخطيب والصفدي وابن الجوزي والقرآن الكريم.", "idea": "لكل مجموعة من الأعداد الكبيرة وكناياتها حكم في التذكير والتأنيث وفي تمييزها.", "cards": [{"icon": "🔟", "title": "ألفاظ العقود (٢٠–٩٠)", "text": "لا تتغير تذكيرًا وتأنيثًا، وتُعرب إعراب جمع المذكر السالم لأنها من ملحقاته، ويأتي معدودها مفردًا منصوبًا على أنه تمييز.", "quote": "عِشرونَ بَيتاً أَقفَرَت وَانتابَها — بَعدَ البَشاشَةِ وَحشَةٌ وَظَلامُ"}, {"icon": "➕", "title": "الأعداد المعطوفة", "text": "يأخذ كل جزء حكمه: العقد لا يتغير، و١ و٢ يوافقان المعدود، و٣–٩ تخالفه. وفي الإعراب: العقود كجمع المذكر السالم، و٢ كالمثنى، و(١، ٣–٩) بالحركات الظاهرة. والمعدود مفرد منصوب تمييز.", "quote": "وينساب منه ستةٌ وثلاثون نهرًا"}, {"icon": "🧩", "title": "بضع ونيّف", "text": "قد تُعطف ألفاظ العقود على «بضع» فتأخذ «بضع» أحكامها السابقة. وقد تُعطف على «نيّف»، وهي تدل على العدد من ١ إلى ٩، وتكون مذكرة دائمًا."}, {"icon": "💯", "title": "العددان ١٠٠ و١٠٠٠", "text": "لا يتغيران تذكيرًا وتأنيثًا، ومعدودهما مفرد مجرور يُعرب مضافًا إليه. وفي ٦٠٠ المعدود «مائة» مؤنث فنقول: ستمائة، وفي ٦٠٠٠ المعدود «ألف» مذكر فنقول: ستة آلاف. ومثلهما: مليون، مليار، بليون.", "quote": "قال: خمسمائة درهم، فأمر له بألف درهم"}, {"icon": "🔗", "title": "العطف على المائة والألف", "text": "إذا عُطف عليهما عدد آخر تبع المعدود العدد الأخير دائمًا. ويمكن قراءة الأعداد المعطوفة من اليسار إلى اليمين أو العكس.", "quote": "مائة وثلاثون كتابًا — ثلاثون ومائة كتاب"}, {"icon": "❔", "title": "كم الاستفهامية والخبرية", "text": "كنايات العدد ألفاظ تكني عن العدد دون تحديد. «كم» الاستفهامية يُسأل بها عن العدد، والاسم بعدها منصوب على التمييز. و«كم» الخبرية للإخبار عن معدود كثير، والاسم بعدها مفرد أو جمع مجرور، ويجوز جرّه بـ«من».", "quote": "﴿كَم مِّن فِئَةٍ قَلِيلَةٍ غَلَبَتْ فِئَةً كَثِيرَةً بِإِذْنِ اللَّهِ﴾"}, {"icon": "🏷️", "title": "كأيّن وكذا", "text": "«كأيّن» بمعنى كم الخبرية، واسمها بعدها مجرور بـ«من» في الأغلب، وقد يأتي منصوبًا. و«كذا» تدل على عدد قليل أو كثير، وتمييزها مفرد منصوب أو جمع منصوب: «قرأت كذا صفحة هذا النهار».", "quote": "﴿وَكَأَيِّن مِّن قَرْيَةٍ أَمْلَيْتُ لَهَا وَهِيَ ظَالِمَةٌ﴾"}], "table": {"title": "أمثلة الدرس في جدول", "head": ["المثال", "الحكم/الإعراب", "السبب"], "rows": [["عشرون بيتًا", "العقد ثابت، و«بيتًا» تمييز مفرد منصوب", "حكم ألفاظ العقود"], ["ستةٌ وثلاثون نهرًا", "ستة: فاعل مرفوع، ثلاثون: معطوف مرفوع بالواو، نهرًا: تمييز منصوب", "٦ تخالف «نهر» المذكر، والعقد ملحق بجمع المذكر السالم"], ["اثنتان وأربعون حلوبةً", "«اثنتان» مؤنث، و«أربعون» يلزم هيئة واحدة", "٢ يوافق المعدود المؤنث (دليل المعلم)"], ["مائة سائس — ألف درهم", "التمييز مفرد مجرور مضاف إليه", "حكم العددين ١٠٠ و١٠٠٠"], ["ستمائة — ستة آلاف", "٦ مذكر مع مائة، ومؤنث مع ألف", "مائة مؤنث، وألف مذكر"], ["مائة وثلاثون كتابًا", "كتابًا: مفرد منصوب", "تبع العدد الأخير (٣٠)"], ["ثلاثون ومائة كتاب", "كتاب: مفرد مجرور", "تبع العدد الأخير (مائة)"]]}, "tip": "💡 مع الأعداد الطويلة انظري إلى آخر عدد قبل المعدود: «ألفان ومائتان وأربع وثلاثون نخلة» آخرها «ثلاثون» فالتمييز مفرد منصوب، و«أربع» مذكر لأن «نخلة» مؤنث.", "keyPoints": ["العقود ثابتة، تُعرب كجمع المذكر السالم، وتمييزها مفرد منصوب.", "في المعطوفة: ١ و٢ يوافقان، ٣–٩ تخالف، والعقد ثابت.", "١٠٠ و١٠٠٠ ثابتان، وتمييزهما مفرد مجرور مضاف إليه.", "عند العطف على المائة أو الألف يتبع المعدود العدد الأخير.", "كم الاستفهامية: تمييز منصوب؛ الخبرية وكأيّن: مجرور (وكثيرًا بمن)؛ كذا: منصوب."], "check": [{"q": "نقول «ستمائة» بتذكير العدد ٦ لأن:", "opts": ["المعدود «مائة» مذكر", "العدد يوافق المائة دائمًا", "المعدود «مائة» مؤنث، و٣–٩ تخالف المعدود"], "a": 2, "explain": "نصّ الدرس: في ٦٠٠ يكون المعدود هو العدد «مائة» وهو مؤنث؛ لذلك يُذكَّر معه العدد ٦."}, {"q": "إعراب «مائة» في: «اشترك في المسابقة الأدبية في المدرسة مائة طالب»:", "opts": ["مفعول به منصوب", "فاعل مرفوع وهو مضاف، و«طالب» مضاف إليه", "تمييز منصوب"], "a": 1, "explain": "«مائة» هي التي اشتركت فهي فاعل مرفوع، وتمييز المائة مفرد مجرور يُعرب مضافًا إليه (إجابة دليل المعلم)."}]}, {"type": "البلاغة", "title": "الجناس", "page": 183, "hook": "«وجب الفؤادُ وكان لا يجبُ… ما هكذا كان الذي يجبُ» — الكلمة نفسها، والمعنى مختلف تمامًا!", "about": "درس في البديع يعرّف الجناس، محسّنًا لفظيًّا كالسجع لكنه يختلف عنه، ويميّز بين نوعيه التام والناقص بأمثلة من الشعر والقرآن الكريم والحديث الشريف.", "idea": "الجناس اتحاد الحروف وتغاير المعنى بين لفظتين، وهو تام أو ناقص.", "cards": [{"icon": "🎵", "title": "لون بديعي موسيقي", "text": "الجناس محسّن لفظي كالسجع، لكنه يختلف عنه. يمنح التراكيب جرسًا خاصًّا ووقعًا موسيقيًّا، وهو مع اتصاله بالألفاظ يزيد المعنى بهاءً ووضوحًا."}, {"icon": "📖", "title": "التعريف", "text": "الجناس: اتحاد الحروف وتغاير المعنى بين لفظتين. وهو قسمان: تام إذا كان الاتفاق كليًّا في عدد الحروف ونوعها وترتيبها وضبطها، وناقص إذا كان الاتفاق جزئيًّا."}, {"icon": "💓", "title": "تام: لا يجب / يجب", "text": "«لا يجب» في الشطر الأول من الوجيب وهو خفقان القلب، و«يجب» الثانية من الوجوب. اتحدت اللفظتان في الحروف وعددها وحركاتها، واختلفتا في المعنى.", "quote": "يا إخوتي مذ بانت النجُبُ — وجب الفؤادُ وكان لا يجبُ"}, {"icon": "👑", "title": "تام: يحيا / يحيى", "text": "«يحيا» فعل مضارع من الحياة ضدّ الموت، و«يحيى» اسم علم لممدوح أبي تمام؛ لا اختلاف بينهما في حرف ولا حركة. وفي «العين – عين» لا تؤثر لام التعريف في حصول التشابه.", "quote": "من مات من كرم الزمان فإنه — يحيا لدى يحيى بن عبدالله"}, {"icon": "✂️", "title": "ناقص: الساق / المساق", "text": "الساق: الجارحة المعروفة عند الإنسان، والمساق: المرجع والمآب. ولولا وجود الميم في الثانية لتطابقتا كليًّا؛ فهو جناس ناقص.", "quote": "﴿وَالْتَفَّتِ السَّاقُ بِالسَّاقِ ۝ إِلَىٰ رَبِّكَ يَوْمَئِذٍ الْمَسَاقُ﴾"}, {"icon": "🐎", "title": "ناقص: الخيل / الخير", "text": "تتفق اللفظتان في جميع الحروف إلا الأخير (اللام – الراء). ومثله «عواص – عواصم» بزيادة حرف. فالناقص: اتفاق بين لفظتين في الحروف لكنه غير كلي، مع اختلافهما في المعنى.", "quote": "الخيلُ معقودٌ في نواصيها الخيرُ"}, {"icon": "⚖️", "title": "جناس أم سجع؟", "text": "السجع يظهر في نهايات الفواصل، كالراء الساكنة في آيات سورة المدثر. وقد يجتمعان كما في «خلفًا – تلفًا»: جناس بين اللفظتين، وفيهما سجع بحرف الفاء مع الإطلاق (دليل المعلم).", "quote": "اللهم أعط منفقا خلفا ، وأعط ممسكا تلفا"}], "table": {"title": "أمثلة الدرس", "head": ["المثال", "نوع الجناس", "السبب"], "rows": [["لا يجب / يجب", "تام", "اتفاق كلي؛ الأولى: خفقان القلب، والثانية: الوجوب"], ["يحيا / يحيى", "تام", "لا اختلاف في حرف ولا حركة؛ فعل / اسم علم"], ["العين / عين", "تام", "لام التعريف لا تؤثر؛ الأولى: الباصرة"], ["الساق / المساق", "ناقص", "زيادة الميم"], ["عواص / عواصم", "ناقص", "زيادة حرف واحد"], ["الخيل / الخير", "ناقص", "اختلاف الحرف الأخير (اللام – الراء)"]]}, "tip": "💡 اختلاف المعنى شرط في النوعين، فلا تقولي: «ناقص لأن المعنى مختلف». النقص يكون في الحروف: عددها أو نوعها أو ترتيبها أو ضبطها.", "keyPoints": ["الجناس: اتحاد الحروف وتغاير المعنى بين لفظتين.", "التام: اتفاق كلي في عدد الحروف ونوعها وترتيبها وضبطها.", "الناقص: اتفاق غير كلي في الحروف مع اختلاف المعنى.", "أمثلة التام: يجب/يجب، يحيا/يحيى، العين/عين.", "أمثلة الناقص: الساق/المساق، عواص/عواصم، الخيل/الخير."], "check": [{"q": "نوع الجناس بين «يحيا» و«يحيى» في بيت أبي تمام:", "opts": ["ناقص", "تام", "ليس جناسًا بل سجع"], "a": 1, "explain": "اللفظتان متحدتان في الحروف لا اختلاف بينهما في حرف ولا حركة، ومعناهما مختلف: فعل من الحياة، واسم علم."}, {"q": "الجناس بين «الخيل» و«الخير» ناقص؛ لأن:", "opts": ["المعنى فيهما مختلف", "إحداهما زادت حرفًا", "الحرف الأخير مختلف (اللام – الراء)"], "a": 2, "explain": "جانس الحديث بين لفظتين في جميع الحروف إلا الحرف الأخير؛ أما اختلاف المعنى فشرط في الجناس بنوعيه."}]}, {"type": "الاستماع", "title": "قصة: إليك الجواب يابني", "page": 187, "hook": "أبٌ يجلس كل صباح على الشاطئ، وابنه يسأل: لماذا؟ والجواب يأتي بعد خمسة عشر عامًا…", "about": "درس استماع لقصة يرويها أب لابنه عن ليلة عاصفة في رحلة غوص نجا فيها وحده. نص القصة في دليل المعلم، وفي كتاب الطالبة إرشادات الاستماع وأسئلته.", "idea": "ليلة عاصفة في البحر كشفت معادن الرجال، وتركت في نفس الناجي الوحيد ألمًا لا ينتهي.", "cards": [{"icon": "🎧", "title": "قبل أن تستمعي", "text": "أصغي جيدًا، وتابعي تسلسل الأحداث، واستخلصي عناصر القصة: الأحداث، الأشخاص، الزمان، المكان، العقدة، الحل. وميّزي الانفعالات (حزن، غضب، فرح، تعجّب…) واستجيبي لها."}, {"icon": "🌅", "title": "سؤال الابن", "text": "منذ صغره يسأل الابن أباه: لماذا تجلس كثيرًا على الشاطئ في الصباح الباكر؟ ويجيبه الأب بعد خمسة عشر عامًا: إنها ليلة تغيّرت معها حياته كلها."}, {"icon": "⛵", "title": "رحلة الغوص", "text": "كانوا ثمانية في سفينة صغيرة ومعهم النوخذة أبو راشد، ومعهم الصبي «صالح» الذي فقد أمه يوم وُلد. اصطحبه أبو راشد ليتدرّب على حياة الغوص؛ لأن أباه صديقه، وبعد إلحاح الصبي ورجاء أبيه."}, {"icon": "🌪️", "title": "العاصفة", "text": "في عصر يوم العودة رأى الناس عارضًا قادمًا فظنوه نذير عاصفة، فتأهّبوا ولجأت السفن إلى مكان تحتمي به. ثم انقلب هدوء البحر ثورة، وقضوا الليل يغرفون الماء بالدلاء في صراع مع الهلاك."}, {"icon": "⚓", "title": "لحظة القرار", "text": "طلب أبو راشد من البحارة ترك السفينة واللحاق بالسفن الكبيرة، ورفض أن يسبح معهم؛ فالصبي أمانة في عنقه ولا يجيد السباحة. فاستثار كلامه شهامتهم فاعتصموا معه، إلا الراوي: تذكّر صورة ابنه الرضيع يمدّ يديه إليه، فقفز إلى الماء ونجا."}, {"icon": "💔", "title": "النهاية", "text": "في اليوم الثالث هدأت العاصفة، فوجدت سفن الغوص بقايا حطام السفينة وفيهم أبو راشد والصبي. ولما عرف الناس القصة صاروا يغضّون أبصارهم عن الراوي، فصار يأتي إلى الشاطئ ليعيش تلك الليلة وحده."}, {"icon": "🌱", "title": "قيم القصة", "text": "الوفاء بالأمانة، والشهامة والمروءة والتضامن، وقسوة الطبيعة على الإنسان، وثقل تأنيب الضمير. ومن أنشطة الدرس: «الشدائد والأزمات تظهر معادن الأفراد وتبرز الرجال»."}], "table": {"title": "علّلي (من إجابات دليل المعلم)", "head": ["السؤال", "الإجابة"], "rows": [["اعتقاد الأب بأنه لا همّ للناس إلا الحديث عنه", "نتيجة لشعوره بالذنب وتأنيب الضمير"], ["اعتصام البحارة بالسفينة الصغيرة رغم توافر فرص النجاة", "تضامنًا مع النوخذة، وإحساسهم بالمسؤولية تجاه الصبي"], ["إحساس الأب العائد بالخزي والعار", "لأنه الناجي الوحيد من السفينة"]]}, "keyPoints": ["الحدث الرئيس: عاصفة رحلة الغوص ونجاة الراوي وحده.", "أبو راشد بقي لأن الصبي أمانة في عنقه ولا يجيد السباحة.", "اعتصم البحارة بالسفينة تضامنًا مع النوخذة ومسؤوليةً تجاه الصبي.", "الصورة التي ألحّت على الأب للنجاة: ابنه الرضيع يمدّ يديه إليه.", "يشعر الأب بالخزي لأنه الناجي الوحيد."], "check": [{"q": "لماذا رفض أبو راشد أن يسبح مع البحارة إلى السفن الكبيرة؟", "opts": ["لأن الصبي أمانة في عنقه وهو لا يجيد السباحة", "لأنه ظن أن العاصفة انتهت", "لأنه أراد حماية اللؤلؤ"], "a": 0, "explain": "في القصة: «إن الصبي أمانة في عنقه، وهو لا يجيد السباحة»، فقرّر البقاء معه."}, {"q": "ما الصورة التي ألحّت على الأب فدفعته إلى النجاة بنفسه؟", "opts": ["صورة أبي راشد", "صورة ابنه الرضيع يمدّ يديه إليه", "صورة الشاطئ في الصباح"], "a": 1, "explain": "تذكّر الراوي صورة ابنه الرضيع وقد مدّ يديه إليه، فقفز إلى الماء ولحق بسفينة كبيرة."}]}], "activities": [{"kind": "mcq", "lesson": 1, "q": "ما الصورة التي استخدمها البحتري لوصف سرعة جريان الماء في البركة؟", "opts": ["الفضة البيضاء السائلة من السبائك", "الخيل الجارية حين تنطلق من حبل مُجريها", "الدروع المصقولة الحواشي", "السماء التي رُكّبت فيها النجوم"], "a": 1, "explain": "في البيت الثالث: «تنصبّ فيها وفود الماء مُعجِلةً كالخيل، جاريةً من حبل مُجريها»؛ فشبّه سرعة انصباب الماء بسرعة الخيل المنطلقة. أما الفضة فللبياض والصفاء، والجواشن لتموّج الماء بريح الصبا، والسماء لانعكاس النجوم ليلًا."}, {"kind": "match", "lesson": 1, "title": "صِلي كل كلمة بمعناها كما في معجم اللغويات", "pairs": [["الجواشن", "الدروع"], ["حوافل", "شديدة الكثرة"], ["يدحو", "يبسط ويوسّع"], ["قوراء", "متّسعة"], ["رفدته", "دعمته وأمسكته"], ["مغانيها", "منازلها"]]}, {"kind": "classify", "lesson": 2, "title": "صنّفي الأعداد وكناياتها بحسب حكم التمييز", "groups": ["تمييزه منصوب", "تمييزه مجرور"], "items": [["عشرون بيتًا", 0], ["ستة وثلاثون نهرًا", 0], ["مائة سائسٍ", 1], ["ألف درهمٍ", 1], ["كم كتابًا قرأتِ؟", 0], ["كم من فئةٍ قليلة", 1], ["تسعون عامًا", 0], ["خمسمائة درهمٍ", 1]]}, {"kind": "fill", "lesson": 2, "q": "في مزرعة جدي ألفان ومائتان وأربع وثلاثون ____.", "opts": ["نخلةٍ", "نخلاتٍ", "نخلةً"], "a": 2, "explain": "إذا عُطفت أعداد على الألف أو المائة تبع المعدودُ العددَ الأخير، والأخير هنا «ثلاثون» (لفظ عقد)، وتمييز العقود مفرد منصوب، فنقول «نخلةً». ولاحظي أن «أربع» جاء مذكرًا لأن «نخلة» مؤنث. وهي إجابة دليل المعلم."}, {"kind": "fill", "lesson": 2, "q": "بُعث الرسول ﷺ وهو ابنُ ____.", "opts": ["أربعين عامًا", "أربعون عامًا", "أربعين عامٍ"], "a": 0, "explain": "1) «ابن» مضاف، فالعدد بعده مضاف إليه مجرور. 2) ألفاظ العقود تُعرب إعراب جمع المذكر السالم فتُجرّ بالياء: «أربعين». 3) تمييز العقود مفرد منصوب: «عامًا»."}, {"kind": "tf", "lesson": 3, "q": "في قول أبي تمام: «يحيا لدى يحيى بن عبد الله» جناس ناقص.", "a": false, "explain": "الجناس هنا تام؛ لأن «يحيا» و«يحيى» متفقتان في عدد الحروف ونوعها وترتيبها وحركاتها، مع اختلاف المعنى: فالأولى فعل مضارع من الحياة، والثانية اسم علم للممدوح يحيى بن عبد الله."}, {"kind": "mcq", "lesson": 3, "q": "نوع الجناس بين «الخيل» و«الخير» في الحديث الشريف: «الخيلُ معقودٌ في نواصيها الخيرُ»:", "opts": ["جناس تام لاتفاق الحروف كلها", "ليس جناسًا بل سجع", "جناس ناقص لاختلاف الحرف الأخير", "جناس ناقص لزيادة حرف في إحدى الكلمتين"], "a": 2, "explain": "اللفظتان متفقتان في جميع الحروف إلا الحرف الأخير (اللام في الخيل والراء في الخير)، فالاتفاق غير كلي مع اختلاف المعنى، وهذا جناس ناقص. ولا زيادة حرف هنا؛ فعدد الحروف واحد."}, {"kind": "order", "lesson": 4, "title": "رتّبي أحداث قصة «إليك الجواب يابني»", "items": ["أبو راشد يصطحب الصبي صالحًا في رحلة الغوص", "الناس يرون عارضًا قادمًا فيظنونه نذير عاصفة", "أبو راشد يطلب من البحارة ترك السفينة واللحاق بالسفن الكبيرة", "البحارة يعتصمون بالسفينة، والراوي وحده يلحق بسفينة كبيرة", "الراوي يرى من السفينة الكبيرة أبا راشد والبحارة والصبي يصارعون العاصفة حتى يحول سوادها بينهم"]}], "test": [{"q": "معنى «الجواشن» في قول البحتري: «مثلَ الجواشنِ مصقولًا حواشيها»:", "opts": ["السيوف", "الأمواج", "الدروع", "الحجارة"], "a": 2, "lesson": 1, "explain": "في معجم اللغويات: الجواشن جمع جوشن وهو الدرع. شبّه البحتري ما تُحدثه ريح الصبا في الماء من طرائق متموجة بالدروع المصقولة الأطراف."}, {"q": "العلاقة بين «فصيح» و«أعجم» في قول أبي تمام: «فصيحٌ إذا استنطقتَه وهو راكبٌ … وأعجمُ إنْ خاطبتَه وهو راجلُ»:", "opts": ["جناس تام", "طباق", "سجع", "جناس ناقص"], "a": 1, "lesson": 1, "explain": "الفصيح ضدّ الأعجم، والجمع بين اللفظ وضدّه طباق، وهو الظاهرة الأولى التي تستوقف القارئ في أبيات أبي تمام كما في الإضاءة النقدية، ومثله: راكب/راجل."}, {"q": "ما الجانب الذي لفت انتباه ابن الرومي عند الخبّاز؟", "opts": ["نظافة الخبّاز وثيابه", "تفاصيل حادثة مروره بالخبّاز", "رائحة الخبز وطعمه", "سرعة الخبّاز في بسط الرقاقة وتحوّلها من كرة إلى قرص كالقمر"], "a": 3, "lesson": 1, "explain": "لم يُعنَ ابن الرومي بتفاصيل الحدث، بل شغله سرعة الخبّاز في بسط الرقاق، فصوّر تحوّل الرقاقة من «كرة» في كفّه إلى «قوراء كالقمر» في مدة كلمح البصر (وهو ما يذكره دليل المعلم)."}, {"q": "في قول شوقي: «عشرون بيتًا أَقفرت» جاء التمييز «بيتًا» مفردًا منصوبًا لأن:", "opts": ["ألفاظ العقود تمييزها مفرد منصوب", "ألفاظ العقود تمييزها جمع مجرور", "العدد صفة للمعدود", "التمييز يتبع العدد في إعرابه"], "a": 0, "lesson": 2, "explain": "من أحكام ألفاظ العقود (20–90): لا تتغير تذكيرًا وتأنيثًا، وتُعرب إعراب جمع المذكر السالم، ويأتي معدودها مفردًا منصوبًا على التمييز. أما الجمع المجرور فتمييز الأعداد من 3 إلى 10."}, {"q": "إعراب «وثلاثون» في: «ينساب من جبل الثلج ستةٌ وثلاثون نهرًا»:", "opts": ["معطوف مرفوع وعلامة رفعه الضمة", "تمييز منصوب بالياء", "معطوف مرفوع وعلامة رفعه الواو لأنه ملحق بجمع المذكر السالم", "فاعل مرفوع بالواو"], "a": 2, "lesson": 2, "explain": "الواو حرف عطف، و«ثلاثون» اسم معطوف على «ستة» (الفاعل) فهو مرفوع، وعلامة رفعه الواو لأن ألفاظ العقود ملحقة بجمع المذكر السالم. و«نهرًا» هو التمييز المنصوب. وهذا نموذج الإعراب في الكتاب."}, {"q": "نقول «ستمائة» بتذكير العدد، و«ستة آلاف» بتأنيثه؛ لأن:", "opts": ["المعدود «مائة» مؤنث و«ألف» مذكر، والعدد من 3 إلى 9 يخالف المعدود", "المائة مذكر والألف مؤنث", "العدد يوافق المائة ويخالف الألف بلا سبب", "التذكير والتأنيث جائزان فيهما معًا"], "a": 0, "lesson": 2, "explain": "في «ستمائة» المعدود هو «مائة» وهو مؤنث فذُكّر معه العدد 6، وفي «ستة آلاف» المعدود هو «ألف» وهو مذكر فأُنّث معه العدد 6؛ لأن الأعداد من 3 إلى 9 تخالف معدودها. وهذا نصّ الدرس."}, {"q": "«كم» في قوله تعالى: ﴿كم من فئةٍ قليلةٍ غلبت فئةً كثيرةً بإذن الله﴾:", "opts": ["استفهامية، وتمييزها منصوب", "خبرية، وتمييزها مجرور بـ«من»", "كذا، وتمييزها منصوب", "استفهامية، وتمييزها مجرور بالإضافة"], "a": 1, "lesson": 2, "explain": "الآية إخبار عن كثرة ما غلبت الفئة القليلة الكثيرة، لا سؤال عن العدد؛ فـ«كم» خبرية، وتمييزها يكون مفردًا أو جمعًا مجرورًا، ويجوز جرّه بـ«من» كما هنا: «من فئةٍ»."}, {"q": "في قول عنترة: «فيها اثنتان وأربعون حلوبةً» جاء العدد «اثنتان» مؤنثًا لأن:", "opts": ["المعدود «حلوبة» مؤنث، والعدد 2 يوافق المعدود", "العدد 2 يخالف المعدود", "لفظ العقد «أربعون» مؤنث", "التمييز جمع"], "a": 0, "lesson": 2, "explain": "في الأعداد المعطوفة يأخذ كل جزء حكمه: العدد 2 يوافق المعدود، و«حلوبة» مؤنث فجاء «اثنتان» مؤنثًا، أما العقد «أربعون» فيلزم هيئة واحدة تذكيرًا وتأنيثًا، والتمييز «حلوبةً» مفرد منصوب (دليل المعلم)."}, {"q": "نوع الجناس في: «وجب الفؤادُ وكان لا يجبُ … ما هكذا كان الذي يجبُ»:", "opts": ["جناس ناقص لاختلاف المعنى", "سجع لتوافق الحرف الأخير", "طباق", "جناس تام"], "a": 3, "lesson": 3, "explain": "«يجب» الأولى من الوجيب (خفقان القلب)، والثانية من الوجوب؛ اتفقتا في عدد الحروف ونوعها وترتيبها وحركاتها واختلفتا في المعنى، فالجناس تام. واختلاف المعنى شرط في الجناس بنوعيه، فليس سببًا للنقص."}, {"q": "نوع الجناس بين «الساق» و«المساق» في قوله تعالى: ﴿والتفّت الساق بالساق * إلى ربك يومئذ المساق﴾:", "opts": ["تام لتطابق اللفظتين", "ناقص لزيادة الميم في «المساق»", "ناقص لاختلاف الحرف الأخير", "ليس جناسًا لاتحاد المعنى"], "a": 1, "lesson": 3, "explain": "الساق هي الجارحة المعروفة، والمساق هو المرجع والمآب؛ ولولا وجود الميم في الثانية لتطابقتا كليًّا، فالاتفاق غير كلي مع اختلاف المعنى، فهو جناس ناقص."}, {"q": "في قول الشاعر: «فيالك من حزمٍ وعزمٍ طواهما … جديدُ الردى بين الصفا والصفائحِ» محسّن بديعي بين «حزم» و«عزم» هو:", "opts": ["سجع", "طباق", "جناس", "مقابلة"], "a": 2, "lesson": 3, "explain": "«حزم» و«عزم» لفظتان تتفقان في حرفين وتختلفان في الأول (الحاء والعين) مع اختلاف المعنى، فبينهما جناس (ناقص)، ومثله «الصفا» و«الصفائح». وهذه إجابة دليل المعلم للتدريب الثاني."}, {"q": "لماذا رفض النوخذة أبو راشد أن يترك سفينته ويسبح مع البحارة؟", "opts": ["لأنه أراد حماية ما في السفينة من لؤلؤ", "لأنه كان يظن أن العاصفة انتهت", "لأن السفن الكبيرة رفضت استقباله", "لأن الصبي أمانة في عنقه وهو لا يجيد السباحة"], "a": 3, "lesson": 4, "explain": "في القصة: طلب البحارة من أبي راشد أن يسبح معهم «فكانت المفاجأة الرهيبة: إنه لا يستطيع أن يفعل ذلك؛ فإن الصبي أمانة في عنقه، وهو لا يجيد السباحة، والسفن الكبيرة لا يمكن أن تقترب من هذه المنطقة الوعرة»، فقرر البقاء مع الصبي في السفينة."}], "game": {"type": "tower", "q": [{"q": "«يحيا» و«يحيى» في بيت أبي تمام:", "opts": ["جناس تام", "جناس ناقص", "طباق"], "a": 0}, {"q": "«الساق» و«المساق»:", "opts": ["جناس تام", "سجع", "جناس ناقص"], "a": 2}, {"q": "«المغترّ» و«المعتزّ» في بيت البحتري:", "opts": ["جناس ناقص", "جناس تام", "طباق"], "a": 0}, {"q": "«تهذيبها» و«تهذي بها»:", "opts": ["جناس ناقص", "جناس تام", "سجع"], "a": 1}, {"q": "الجناس التام يتفق فيه اللفظان في:", "opts": ["المعنى فقط", "الحرف الأخير فقط", "الحروف وعددها وترتيبها وحركاتها"], "a": 2}, {"q": "من وصف بركة المتوكل؟", "opts": ["أبو تمام", "ابن الرومي", "البحتري"], "a": 2}, {"q": "شبّه البحتري الماء في بياضه بـ:", "opts": ["الدروع", "الفضة", "الخيل"], "a": 1}, {"q": "الصحيح:", "opts": ["عشرون بيوتٍ", "عشرون بيتًا", "عشرون بيتٍ"], "a": 1}, {"q": "الصحيح:", "opts": ["ستمائة درهمًا", "ستمائة دراهم", "ستمائة درهمٍ"], "a": 2}, {"q": "الصحيح:", "opts": ["ستة آلاف", "ست آلاف", "ستة ألفٍ"], "a": 0}, {"q": "تمييز «كم» الاستفهامية:", "opts": ["جمع مجرور", "مفرد منصوب", "مفرد مجرور"], "a": 1}, {"q": "لماذا لم يترك أبو راشد سفينته؟", "opts": ["خاف من البحر", "انتهت العاصفة", "الصبي أمانة في عنقه"], "a": 2}]}}, {"id": "u9", "axis": "العمل والصناعات", "axisN": 3, "unitN": 3, "title": "الوحدة الثالثة", "theme": "سوق رقمية وعاطفة صادقة", "pages": "189–214", "lessons": [{"type": "القراءة", "title": "التجارة الإلكترونية", "page": 189, "hook": "تشترين من أشهر أسواق العالم وأنتِ في بيتك… فلماذا يثير هذا كل هذا الجدل؟", "about": "مقال (مأخوذ بتصرف من موقع إلكتروني) يعرض نشأة التجارة الإلكترونية وتحدياتها وأنماطها وصورها وبيئتها ومزاياها، وواقعها في الأسواق العربية.", "idea": "التجارة الإلكترونية أحدث إفرازات عصر المعلومات وأكثرها جدلًا، ولا يمكن تجاهلها.", "cards": [{"icon": "🔥", "title": "لماذا هي الأكثر جدلًا؟", "text": "لأنها تنطوي على عناصر وتثير تحديات في سائر الحقول: أمن المعلومات، ووسائل الدفع الإلكتروني، والملكية الفكرية، والتعاقد الإلكتروني، والحجّية، والمعايير؛ فهي الإطار الذي عاد ليؤطّر سائر موضوعات تقنية المعلومات."}, {"icon": "🕰️", "title": "سلّم التطور", "text": "الخصوصية وحماية الحياة الخاصة (أواخر الستينيات) ← جرائم الكمبيوتر ثم الملكية الفكرية للبرامج (النصف الثاني للسبعينيات ومطلع الثمانينيات) ← محتوى المواقع والمعايير وأمن المعلومات والأتمتة المصرفية (مطلع التسعينيات) ← التجارة الإلكترونية (منتصف التسعينيات وأواخرها)."}, {"icon": "🛒", "title": "أنماطها", "text": "عرض البضائع والخدمات عبر الإنترنت، وإجراء البيوع بالوصف مع الدفع بالبطاقات المالية وغيرها، وإنشاء متاجر افتراضية، وأنشطة التزويد والتوزيع والوكالة التجارية، والخدمات المالية، وخدمات الطيران والنقل والشحن."}, {"icon": "🔄", "title": "صورها", "text": "من الأعمال إلى المستهلك (التسوق الإلكتروني)، ومن الأعمال إلى الأعمال (تكاملية التوريد)، ومن الحكومة إلى المستهلك، ومن الحكومة إلى الأعمال. وأكثرها شيوعًا وأهمية: من الأعمال إلى المستهلك، ومن الأعمال إلى الأعمال."}, {"icon": "💻", "title": "بيئتها", "text": "لا تجارة إلكترونية بدون وسائل إلكترونية؛ فهي «كمبيوتر وشبكة وحلول وموقع ومحتوى». ولأن الإنترنت شبكة الشبكات، ارتبط نماء التجارة الإلكترونية، بل وجودها في وقتنا، بشبكة الإنترنت."}, {"icon": "⭐", "title": "مزاياها", "text": "إيجاد وسائل اتّجار توافق عصر المعلومات، والدخول إلى الأسواق العالمية وتحقيق عائد أعلى من الأنشطة التقليدية، وتلبية خيارات الزبون بيسر وسهولة، وتطوير الأداء التجاري والخدمي."}, {"icon": "🌍", "title": "عربيًّا: عوائق ودرس", "text": "اللغة العربية لا تمثل أكثر من ٠٫٥٪ من الاستخدام على الإنترنت، مع عدم الوعي بوسائل الدفع، وضعف الثقة بأمن المعلومات. والدرس: تجاهل التجارة الإلكترونية لا يتناسب مع رغبتنا في الإفادة من عصر التقنية ومواجهة سلبيات العولمة."}], "table": {"title": "صور التجارة الإلكترونية", "head": ["الصورة", "بالإنجليزية", "تشمل"], "rows": [["من الأعمال إلى المستهلك", "Business-to-Consumer", "التسوق الإلكتروني shopping on-line"], ["من الأعمال إلى الأعمال", "Business-to-Business", "تكاملية عمليات التوريد للمنتجات وأداء الخدمات"], ["من الحكومة إلى المستهلك", "Government-to-Consumer", "الخدمات والبرامج الحكومية عبر الوسائط الإلكترونية"], ["من الحكومة إلى الأعمال", "Government-to-Business", "المشتريات الحكومية الإلكترونية"]]}, "vocab": [{"w": "يؤطّر", "m": "جعل له إطارًا، والمقصود هنا: يُنظِّم المعلومات (أ ط ر)"}, {"w": "الإفرازات", "m": "المخرجات والنتائج (ف ر ز)"}, {"w": "المحفّز", "m": "الدافع (ح ف ز)"}, {"w": "الأتمتة", "m": "إدخال المعاملات الآلية في المصارف وأسواق المال"}], "tip": "💡 لا تخلطي بين الأنماط والصور: الأنماط هي الأنشطة (عرض، بيع، متاجر افتراضية…)، والصور هي أطراف العلاقة (أعمال، مستهلك، حكومة).", "keyPoints": ["التجارة الإلكترونية أحدث إفرازات عصر المعلومات وأكثرها إثارة للجدل.", "أشيع صورها: من الأعمال إلى المستهلك، ومن الأعمال إلى الأعمال.", "بيئتها: كمبيوتر وشبكة وحلول وموقع ومحتوى، وارتبطت بالإنترنت.", "مزاياها: اتّجار يوافق العصر، أسواق عالمية، تلبية الزبون، تطوير الأداء.", "عوائقها عربيًّا: اللغة (٠٫٥٪)، وعدم الوعي بوسائل الدفع، وضعف الثقة الأمنية."], "check": [{"q": "ما الصورتان الأكثر شيوعًا وأهمية للتجارة الإلكترونية؟", "opts": ["من الحكومة إلى المستهلك، ومن الحكومة إلى الأعمال", "من الأعمال إلى المستهلك، ومن الأعمال إلى الأعمال", "من المستهلك إلى المستهلك، ومن الأعمال إلى الحكومة"], "a": 1, "explain": "نصّ المقال: العلاقات التجارية بين جهات الأعمال والمستهلك، وبين مؤسسات الأعمال فيما بينها، «هما الصورتان الأكثر شيوعًا وأهمية»."}, {"q": "كم تمثل اللغة العربية من مساحة الاستخدام على الإنترنت بحسب المقال؟", "opts": ["لا أكثر من ٠٫٥٪", "نحو ٥٪", "نحو ٥٠٪"], "a": 0, "explain": "تشير الدراسات في المقال إلى أن العربية لا تمثل أكثر من ٠٫٥٪، وهذا عائق رئيس أمام التسوق الإلكتروني عربيًّا."}]}, {"type": "الأنشطة الصرفية", "title": "الاسم المقصور: تثنيته وجمعه جمعًا سالمًا", "page": 195, "hook": "«فتى» تصير «فتيان»، و«عصا» تصير «عصوان»… فإلى أين تذهب الألف؟", "about": "يعرّف الاسم المقصور، ويبيّن قواعد تثنيته وجمعه جمع مذكر سالمًا وجمع مؤنث سالمًا، بأمثلة من شعر أبي مسلم البهلاني الرواحي وابن هرمة وأمثال أبي عبيد.", "idea": "ألف المقصور لا تبقى عند التثنية والجمع: تُقلب في التثنية وجمع المؤنث، وتُحذف في جمع المذكر.", "cards": [{"icon": "📖", "title": "ما الاسم المقصور؟", "text": "هو الاسم المعرب الذي آخره ألف لازمة لا تفارقه، وإذا فارقته أحيانًا لعلة صرفية طارئة كالتقاء الساكنين لم تُعتبر المفارقة حقيقية. ومن أمثلة الدرس: التقى، الأسى، الدنيا، أعلى، المرتضى، المرتجى.", "quote": "وانتثر يا دمع أجفان التقى — قد أصيب العلم واغتيل العمل"}, {"icon": "❓", "title": "لماذا تتغير الألف؟", "text": "لا يمكن أن تُزاد علامتا التثنية (الألف والنون، أو الياء والنون) مع بقاء الألف على حالها؛ لذا يجب قلبها حرفًا آخر. فمثنى المَلا (الليل أو النهار): الملوان، ومثنى الفتى: الفتيان.", "quote": "ما لبث الفَتَيَانِ أنْ عصفا بهم — ولكل قفل يسَّرا مفتاحا"}, {"icon": "🅰️", "title": "ثالثة أصلها ياء ← ياء", "text": "إن كانت الألف ثالثة وأصلها ياء قُلبت عند التثنية ياءً.", "quote": "ندى ← نديان، هدى ← هديان، غنى ← غنيان"}, {"icon": "🅱️", "title": "ثالثة أصلها واو ← واو", "text": "إن كانت الألف ثالثة وأصلها الواو قُلبت عند التثنية واوًا.", "quote": "علا ← علوان، شذا ← شذوان، عصا ← عصوان"}, {"icon": "4️⃣", "title": "رابعة فأكثر ← ياء", "text": "إن كانت الألف رابعة فأكثر قُلبت عند التثنية ياءً، أيًّا كان أصلها.", "quote": "نعمى ← نعميان، مرتضى ← مرتضيان، مستعلى ← مستعليان"}, {"icon": "👥", "title": "جمع المذكر السالم", "text": "يُشترط أن يستوفي المقصور شروط جمع المذكر السالم، وتُحذف ألفه في كل الحالات مع ترك الفتحة قبلها دليلًا عليها: رضا، علا، مرتضى (أعلامًا لرجال) ← رضَون، علَون، مرتضَون؛ والمبتغى، الأسمى، الأعلى (صفات) ← المبتغَون، الأسمَون، الأعلَون.", "quote": "هم المُصْطَفَوْنَ والمُصَفَّوْنَ بالكرم"}, {"icon": "👭", "title": "جمع المؤنث السالم", "text": "يُشترط أن يكون المقصور قابلًا للجمع بالألف والتاء، ويُراعى فيه ما يُراعى في التثنية: ثالثة أصلها ياء ← ياء، وأصلها واو ← واو، ورابعة فأكثر ← ياء.", "quote": "تسهم الملتقيات الفكرية في تنشيط الحركة الثقافية في المجتمع"}], "table": {"title": "أمثلة الكتاب في جدول", "head": ["المثال", "الصيغة", "القاعدة"], "rows": [["ندى، هدى، غنى", "نديان، هديان، غنيان", "تثنية: ثالثة أصلها ياء ← ياء"], ["علا، شذا، عصا", "علوان، شذوان، عصوان", "تثنية: ثالثة أصلها واو ← واو"], ["نعمى، مرتضى، مستعلى", "نعميان، مرتضيان، مستعليان", "تثنية: رابعة فأكثر ← ياء"], ["رضا، علا، مرتضى (أعلام رجال)", "رضَون، علَون، مرتضَون", "جمع مذكر: تُحذف الألف وتبقى الفتحة"], ["المبتغى، الأسمى، الأعلى (صفات)", "المبتغَون، الأسمَون، الأعلَون", "جمع مذكر: تُحذف الألف وتبقى الفتحة"], ["هدى، ندى (علمان لمؤنث)", "هديات، نديات", "جمع مؤنث: ثالثة أصلها ياء ← ياء"], ["رضا، علا (علمان لمؤنث)", "رضوات، علوات", "جمع مؤنث: ثالثة أصلها واو ← واو"], ["سعدى، ليلى، ملتقى", "سعديات، ليليات، ملتقيات", "جمع مؤنث: رابعة فأكثر ← ياء"]]}, "tip": "💡 في جمع المذكر السالم لا تُقلب الألف بل تُحذف وتبقى الفتحة: ﴿وأنتم الأعلَون﴾ و﴿لمن المصطفَين الأخيار﴾. أما المفرد المقصور فيُعرب بحركات مقدرة للتعذر: «لا يغرنك المرتقى» = فاعل مرفوع بالضمة المقدرة (دليل المعلم).", "keyPoints": ["المقصور: اسم معرب آخره ألف لازمة.", "التثنية: الثالثة تُردّ إلى أصلها (ياء أو واو)، والرابعة فأكثر ← ياء.", "جمع المذكر السالم: تُحذف الألف وتبقى الفتحة (مصطفَون، الأعلَون).", "جمع المؤنث السالم: يُعامل معاملة التثنية (هديات، رضوات، ملتقيات).", "المفرد المقصور يُعرب بحركات مقدرة على الألف للتعذر."], "check": [{"q": "مثنى «عصا»:", "opts": ["عصيان", "عصوان", "عصاان"], "a": 1, "explain": "الألف ثالثة وأصلها واو، فتُقلب واوًا عند التثنية: عصوان (مثال الكتاب)."}, {"q": "جمع «ملتقى» جمع مؤنث سالمًا:", "opts": ["ملتقيات", "ملتقوات", "ملتقات"], "a": 0, "explain": "الألف رابعة فأكثر، فتُقلب ياءً كما في التثنية: ملتقيات (مثال الكتاب)."}]}, {"type": "النقد الأدبي", "title": "عناصر العمل الأدبي – ثانيًا: العاطفة", "page": 203, "hook": "قصيدتان في المدح: واحدة من القلب وأخرى من أجل المال… كيف تكشفين الفرق؟", "about": "درس نقدي يعرّف العاطفة، ركنًا مهمًّا من عناصر العمل الأدبي وبخاصة الشعر، ويشرح مقاييس نقدها: الصدق، والقوة، والثبات، بأمثلة من المعري وعروة بن الورد والشنفرى.", "idea": "العاطفة الأدبية الجيدة صادقة قوية ثابتة.", "cards": [{"icon": "🧠", "title": "حالات النفس الثلاث", "text": "الحالة العقلية، والشعورية، والنشاطية؛ متواصلة متداخلة لا حدود بينها، وكل واحدة متسببة عن الأخريين أو سبب لهما. وأي تبدّل في الحالة الانفعالية يظهر في تصرفات الإنسان: لذة الانتصار تحرّر طاقاته، والقلق والهم يقيّدان حركاته."}, {"icon": "💗", "title": "ما العاطفة؟", "text": "هي الحالة الشعورية أو الانفعالية: مجموع المشاعر التي يحسها الأديب ويثيرها الأثر الفني في المتلقي. والمقصود عاطفة الأديب التي ينقلها بعمله، لا عاطفة القارئ. والقدرة على إثارة العواطف لا تدل حتمًا على سمو النص."}, {"icon": "✅", "title": "١- صدق العاطفة", "text": "أن تنبعث عن سبب صحيح صادق غير زائف ولا مصطنع، حتى تكون عميقة تمنح الأدب قيمة خالدة، كرثاء أبي العلاء المعري لقاضي المعرة الذي أحزنه موته.", "quote": "تعبٌ كلها الحياة، فما أعـ — ـجب إلا من راغب في ازدياد"}, {"icon": "🎭", "title": "العاطفة الزائفة", "text": "إذا كان الباعث تافهًا أو زائفًا كان الأدب سطحيًّا لا أثر له، كمدح من لا يستحق. فمدح أبي تمام صادق، أما مدح ابن هانئ الأندلسي لجوهر الصقلي ومدح أبي نواس ففيه رياء وملق من أجل التكسّب.", "quote": "ما شئت لا ما شاءت الأقدار — فاحكم، فأنت الواحد القهار"}, {"icon": "💪", "title": "٢- قوة العاطفة وروعتها", "text": "ليست القوة ثورة العاطفة وحدّتها؛ فقد تكون هادئة رزينة، كعروة بن الورد العبسي، الشاعر الصعلوك الجاهلي، يحاور زوجه التي لامته على كثرة غزواته ليقنعها بجدوى ما يفعل.", "quote": "أقلي عليّ اللوم يا ابنة منذر — ونامي، وإن لم تشتهي النوم فاسهري"}, {"icon": "🔋", "title": "مصدر القوة", "text": "يصعب وضع مقياس دقيق واحد للقوة؛ لاختلاف طبائع العواطف ونفوس القرّاء. ومصدرها الأول نفس الأديب وطبيعته: فالأديب ضعيف الشعور لا تصل تجربته قوية وإن كانت أفكاره عميقة، وقوي العاطفة يجعل أفكاره اليسيرة مؤثرة."}, {"icon": "🔁", "title": "٣- ثبات العاطفة واستمرارها", "text": "استمرار سلطانها وتأثيرها في نفس الأديب ما دام ينظم أو يكتب أو يخطب. ففي لامية العرب للشنفرى (٦٨ بيتًا) تبدأ العاطفة بالحدة والغضب، وتهدأ عند حديثه عن جوعه، ثم تثور معتزّة، والوحدة الشعورية باقية طيلة القصيدة.", "quote": "أقيموا بني أمي صدور مطيكم — فإني إلى قوم سواكم لأميل"}], "table": {"title": "مقاييس نقد العاطفة", "head": ["المقياس", "معناه", "مثاله في الدرس"], "rows": [["الصدق والصحة", "باعث صحيح صادق غير زائف ولا مصطنع", "رثاء أبي العلاء المعري (وضدّه مدح ابن هانئ وأبي نواس)"], ["القوة والروعة", "تأثير قوي ولو كانت هادئة رزينة", "عروة بن الورد يحاور زوجه"], ["الثبات والاستمرار", "بقاء سلطانها ووحدتها الشعورية في العمل كله", "لامية العرب للشنفرى"]]}, "tip": "💡 انتبهي: يقول الكتاب «هناك خمسة مقاييس» ثم لا يذكر إلا ثلاثة: الصدق، والقوة، والثبات؛ فاحفظي هذه الثلاثة.", "keyPoints": ["العاطفة: الحالة الشعورية للأديب التي ينقلها إلى المتلقي.", "إثارة العواطف لا تدل حتمًا على سمو النص.", "الصدق: باعث صحيح (المعري)، والزيف: مدح المتكسبين (ابن هانئ، أبو نواس).", "القوة ليست الثورة؛ فقد تكون هادئة رزينة (عروة بن الورد).", "الثبات: استمرار الوحدة الشعورية في العمل كله (لامية الشنفرى)."], "check": [{"q": "بأيّ نص مثّل الدرس لثبات العاطفة واستمرارها؟", "opts": ["رثاء أبي العلاء المعري", "لامية العرب للشنفرى", "مدح ابن هانئ لجوهر الصقلي"], "a": 1, "explain": "في لامية الشنفرى تثور العاطفة وتهدأ ثم تثور، لكن الوحدة الشعورية تبقى طيلة القصيدة."}, {"q": "المقصود بقوة العاطفة في الدرس:", "opts": ["ثورتها وحدّتها دائمًا", "قدرتها على إثارة الجمهور مهما كان باعثها", "قد تكون هادئة رزينة، ومصدرها الأول نفس الأديب"], "a": 2, "explain": "الكتاب: «ليس المراد بقوة العاطفة ثورتها وحدّتها؛ فقد تكون هادئة رزينة»، ومصدر قوتها الأول نفس الأديب وطبيعته."}]}, {"type": "التعبير", "title": "تعبير كتابي إبداعي: الوصف", "page": 208, "hook": "غروب الشمس نفسه قد تصفينه بالألوان وحدها… أو بما تركه في قلبك من كآبة!", "about": "درس في التعبير الكتابي الإبداعي يعرّف الوصف ونوعيه، ويبيّن وحدته وطرق ترتيب عناصره، والمهارات التي تُراعى عند الكتابة.", "idea": "الوصف الناجح ملاحظة دقيقة، وعناصر مرتبة، وحواس يقظة.", "cards": [{"icon": "👁️", "title": "ما الوصف؟", "text": "من أبرز الموضوعات الإنشائية؛ لأنه يصل العالم الخارجي بالإنسان، فيصوّر ظواهره وبواطنه. وأبرز ما يعتمد عليه الواصف قوة الملاحظة التي تعينه على إمعان التأمل في الأشياء الموصوفة."}, {"icon": "📷", "title": "الوصف المجرد", "text": "أن تصفي الشيء كما هو دون أن تعيريه شيئًا من شخصك وخيالك، وصفًا واقعيًّا. مثاله: وصف الغروب كما ترينه، وما يتركه الشفق على الآفاق من ألوان، دون وصف أحاسيسك."}, {"icon": "💭", "title": "الوصف النفسي", "text": "تمتزج فيه أحاسيس النفس وما تشعرين به تجاه الموصوف من ميل وإعجاب أو صدّ ونفور، ويستعين كثيرًا بالخيال. مثاله: وصف ما تركه مرأى الشمس شاحبة صفراء في نفسك من انقباض وكآبة."}, {"icon": "🎯", "title": "وحدة الوصف", "text": "إذا لم تكن للوصف وحدة معينة ترتب أجزاءه كالقصة، فمداره شيء تنتظم حوله الأوصاف: شروق الشمس، أو غرق سفينة، أو قرية تأكلها النار، أو كآبة المساء، أو السنة الراحلة."}, {"icon": "🧭", "title": "ترتيب الوصف", "text": "اجمعي العناصر أولًا، ثم رتّبيها بحسب تقاربها وتآلفها بإحدى ثلاث طرق: من القريب إلى البعيد أو العكس؛ أو كالتصوير بوصف أبرز الأشياء أثرًا فيك؛ أو من الكلي إلى الجزئي كما فعل البحتري في وصف إيوان كسرى."}, {"icon": "👂", "title": "أشغلي حواسك", "text": "صوّري ما ترين، وانقلي ما تسمعين، وبثّي ما تشمّين، وأحيطي بما تلمسين؛ فالرجوع إلى الحواس يزيد موضوعك ألوانًا وتنوعًا وتوسعًا."}, {"icon": "✅", "title": "مهارات الوصف", "text": "١- التعبير عن المشاعر والانطباعات تجاه الموصوف بصدق. ٢- الدقة في تحديد الأفكار ووصف الأشياء. ٣- استيعاب التفصيلات الجزئية وإيجازها. ٤- تحديد مكونات الموصوف والظواهر المشاهدة فيه. ٥- القدرة على التشبيه واستخدام الصور قدر الإمكان."}], "table": {"title": "المجرد والنفسي", "head": ["وجه الموازنة", "الوصف المجرد", "الوصف النفسي"], "rows": [["حضور الكاتب", "لا يُعير الموصوف شيئًا من شخصه", "تمتزج فيه أحاسيس النفس"], ["الخيال", "وصف واقعي", "يستعين كثيرًا بالخيال"], ["مثال الغروب", "ألوان الشفق على الآفاق", "الانقباض والكآبة من مرأى الشمس الشاحبة"]]}, "tip": "💡 موضوعات الكتاب: رحلة بحرية على قارب صغير في بلدة السوادي تهبّ فيها العواصف، أو رحلة فضائية إلى أحد الكواكب، أو وصف طواعية القلم لصاحبه انطلاقًا من بيت أبي تمام.", "keyPoints": ["الوصف يعتمد على قوة الملاحظة وإمعان التأمل.", "نوعاه: المجرد (واقعي) والنفسي (أحاسيس وخيال).", "طرق الترتيب: القريب ثم البعيد، أو كالتصوير، أو الكلي ثم الجزئي.", "البحتري في إيوان كسرى: بدأ بالصورة العامة ثم الجزئيات.", "إشغال الحواس كلها يزيد الوصف تنوعًا وتوسعًا."], "check": [{"q": "أيّ نوعي الوصف يستعين كثيرًا بالخيال؟", "opts": ["الوصف المجرد", "الوصف النفسي", "كلاهما بالقدر نفسه"], "a": 1, "explain": "الوصف النفسي تمتزج فيه أحاسيس النفس، ويستعين كثيرًا بالخيال؛ أما المجرد فوصف واقعي."}, {"q": "الطريقة التي سلكها البحتري في وصف إيوان كسرى:", "opts": ["الابتداء بالوصف الكلي ثم الجزئيات", "من القريب إلى البعيد", "الوصف كالتصوير بأبرز الأشياء"], "a": 0, "explain": "بدأ بالصورة العامة للإيوان، ثم تناول أحد أجزائه الفخمة، ثم صورة من الصور المعلقة على جدرانه."}]}, {"type": "اقرأ واستمتع", "title": "إليكم معشر الكتاب", "page": 211, "hook": "رسالة عمرها قرون إلى أصحاب القلم: من أنتم؟ وكيف تكونون؟", "about": "رسالة عبد الحميد الكاتب إلى أهل صناعة الكتابة، يبيّن فيها منزلتهم، والصفات التي ينبغي أن يتحلّوا بها، والعلوم والآداب التي عليهم أن يأخذوا بها.", "idea": "الكتابة صناعة شريفة، تحتاج إلى خُلق رفيع وعلم واسع.", "cards": [{"icon": "👑", "title": "منزلة الكتّاب", "text": "جعلهم الله في أشرف الجهات: أهل الأدب والمروءة والعلم والرواية، بهم تنتظم للخلافة محاسنها وتستقيم أمورها، ولا يستغني الملك عنهم.", "quote": "فموقعكم من الملوك موقع أسماعهم التي بها يسمعون، وأبصارهم التي بها يبصرون، وألسنتهم التي بها ينطقون، وأيديهم التي بها يبطشون"}, {"icon": "🖋️", "title": "صفات الكاتب", "text": "أن يكون حليمًا في موضع الحلم، فهيمًا في موضع الحكم، مقدامًا في موضع الإقدام، محجامًا في موضع الإحجام، مؤثرًا للعفاف والعدل والإنصاف، كتومًا للأسرار، وفيًّا عند الشدائد، يضع الأمور مواضعها."}, {"icon": "📚", "title": "علومه وآدابه", "text": "يبدأ بعلم كتاب الله والفرائض، ثم العربية، ثم الخط، ويروي الأشعار وأيام العرب والعجم، ولا يضيّع الحساب. ويترفّع عن المطامع والسعاية والنميمة والكبر، ويواسي من نبا به الزمان من إخوانه.", "quote": "ثم العربية فإنها ثقاف ألسنتكم، ثم أجيدوا الخط فإنه حلية كتبكم"}], "keyPoints": ["موقع الكتّاب من الملوك موقع أسماعهم وأبصارهم وألسنتهم وأيديهم.", "العربية ثقاف الألسنة، والخط حلية الكتب، والحساب قوام كتّاب الخراج.", "الكاتب كتوم للأسرار، وفيّ عند الشدائد، يضع الأمور مواضعها."], "check": [{"q": "وصف عبد الحميد العربية بأنها:", "opts": ["حلية كتبكم", "ثقاف ألسنتكم", "قوام كتّاب الخراج"], "a": 1, "explain": "قال: «ثم العربية فإنها ثقاف ألسنتكم»؛ أما الخط فحلية الكتب، والحساب قوام كتّاب الخراج."}, {"q": "قال عبد الحميد عن الخط إنه:", "opts": ["حلية كتبكم", "ثقاف ألسنتكم", "قوام كتّاب الخراج"], "a": 0, "explain": "قال: «ثم أجيدوا الخط فإنه حلية كتبكم»."}]}], "activities": [{"kind": "mcq", "lesson": 1, "q": "ما الصورتان الأكثر شيوعًا وأهمية في التجارة الإلكترونية في وقتنا الحاضر؟", "opts": ["من الحكومة إلى المستهلك، ومن الحكومة إلى الأعمال", "من الأعمال إلى المستهلك، ومن الأعمال إلى الأعمال", "من المستهلك إلى المستهلك، ومن الحكومة إلى الأعمال", "من الأعمال إلى الحكومة، ومن المستهلك إلى الأعمال"], "a": 1, "explain": "نصّ المقال على أن أبرز صور التجارة الإلكترونية وأهمها «العلاقات التجارية بين جهات الأعمال والمستهلك، وبين مؤسسات الأعمال فيما بينها، وهما الصورتان الأكثر شيوعًا وأهمية». أما صورتا الحكومة فمذكورتان في المخطط لكنهما ليستا الأشيع."}, {"kind": "order", "lesson": 1, "title": "رتّبي موضوعات تقنية المعلومات بحسب تاريخ الاهتمام بها", "items": ["حماية الحياة الخاصة من مخاطر التقنية (أواخر الستينيات)", "جرائم الكمبيوتر والملكية الفكرية (السبعينيات ومطلع الثمانينيات)", "محتوى المواقع والمعايير ومقاييس أمن المعلومات (مطلع التسعينيات)", "التجارة الإلكترونية (منتصف التسعينيات وأواخرها)"]}, {"kind": "classify", "lesson": 2, "title": "صنّفي الأسماء المقصورة بحسب ما تُقلب إليه ألفها عند التثنية", "groups": ["تُقلب ألفه ياءً", "تُقلب ألفه واوًا"], "items": [["فتى", 0], ["هدى", 0], ["عصا", 1], ["علا", 1], ["مستشفى", 0], ["مرتضى", 0], ["شذا", 1], ["ندى", 0]]}, {"kind": "fill", "lesson": 2, "q": "قال تعالى: ﴿ولا تهنوا ولا تحزنوا وأنتم ____ إن كنتم مؤمنين﴾", "opts": ["الأعليون", "الأعلون", "الأعليين"], "a": 1, "explain": "مفرد الكلمة «الأعلى» وهو اسم مقصور، وعند جمعه جمع مذكر سالمًا تُحذف ألفه وتبقى الفتحة قبلها دليلًا عليها: الأعلَون. والكلمة هنا خبر للمبتدأ «أنتم» فهي مرفوعة بالواو. وهي في دليل المعلم: «الأعلون جمع مذكر سالم مفرده الأعلى»."}, {"kind": "match", "lesson": 2, "title": "صِلي كل اسم مقصور بصيغته الصحيحة", "pairs": [["فتى (مثنى)", "فتيان"], ["عصا (مثنى)", "عصوان"], ["ملتقى (جمع مؤنث)", "ملتقيات"], ["مصطفى علم لمذكر (جمع مذكر)", "مصطفَون"], ["هدى علم لمؤنث (جمع مؤنث)", "هديات"], ["الحسنى (مثنى)", "الحسنيان"]]}, {"kind": "mcq", "lesson": 3, "q": "مثّل الدرس بمدح ابن هانئ الأندلسي لجوهر الصقلي ومدح أبي نواس على:", "opts": ["عاطفة صادقة نابعة من سبب صحيح", "عاطفة قوية هادئة رزينة", "مدح فيه رياء وملق من أجل التكسب", "ثبات العاطفة واستمرارها في القصيدة"], "a": 2, "explain": "في مقياس الصدق: إذا كان الباعث تافهًا أو زائفًا كان الأدب سطحيًّا لا أثر له، ومنه قصائد المدح لمن لا يستحقه. ووازن الدرس بين مدح صادق (أبو تمام) ومدح فيه رياء وملق من أجل التكسب (ابن هانئ وأبو نواس)."}, {"kind": "tf", "lesson": 4, "q": "الوصف النفسي هو الذي تصفين فيه الشيء كما هو دون أن تُعيريه شيئًا من شخصك وخيالك.", "a": false, "explain": "هذا تعريف الوصف المجرد (الواقعي). أما الوصف النفسي فتمتزج فيه أحاسيس النفس وما تشعر به تجاه الموصوف من ميل وإعجاب أو صدّ ونفور، ويستعين كثيرًا بالخيال."}, {"kind": "mcq", "lesson": 5, "q": "علّل عبد الحميد الكاتب دعوته الكتّاب إلى إتقان العربية بأنها:", "opts": ["حلية كتبهم", "قوام كتّاب الخراج", "ثقاف ألسنتهم", "سبيل إلى المطامع"], "a": 2, "explain": "قال عبد الحميد: «ثم العربية فإنها ثقاف ألسنتكم» أي تقوّمها كما يقوّم الثقافُ الرماح. أما «حلية كتبكم» فوصف الخط، و«قوام كتّاب الخراج» وصف الحساب، والمطامع نهاهم عنها."}], "test": [{"q": "تشير الدراسات إلى أن اللغة العربية لا تمثل من مساحة الاستخدام على شبكة الإنترنت أكثر من:", "opts": ["5%", "50%", "0.5%", "15%"], "a": 2, "lesson": 1, "explain": "في المقال: «إن اللغة العربية لا تمثل أكثر من 0.5% من مساحة الاستخدام على شبكة الإنترنت، وهذا يُعدّ عائقًا رئيسًا أمام نجاح تجارة التسوق الإلكترونية في المنطقة العربية»."}, {"q": "معنى «الإفرازات» في قوله: «أحدث إفرازات عصر المعلومات»:", "opts": ["المخرجات والنتائج", "الدوافع والمحفزات", "الأجهزة والبرمجيات", "المخاطر والجرائم"], "a": 0, "lesson": 1, "explain": "في جدول المفردات: الإفرازات من الجذر (ف ر ز) ومعناها المخرجات والنتائج. أما الدافع فمعنى «المحفّز»."}, {"q": "«وإنشاء متاجر افتراضية أو محال بيع على الإنترنت»؛ هذا النوع من المتاجر:", "opts": ["يوجد في الواقع فقط", "يوجد في الواقع وعلى الشبكة", "لا يوجد في الواقع ولا على الشبكة", "يوجد على شبكة الإنترنت فقط"], "a": 3, "lesson": 1, "explain": "المتجر «الافتراضي» ليس له وجود مادي في الواقع، وإنما هو محل بيع على الإنترنت يعرض المنتجات ويتم فيه البيع والدفع إلكترونيًّا؛ فهو يوجد على الشبكة فقط."}, {"q": "أيٌّ مما يأتي ليس من العوائق التي ذكرها المقال أمام التجارة الإلكترونية العربية؟", "opts": ["ضعف حضور اللغة العربية على الإنترنت", "ارتفاع أسعار الحواسيب", "عدم الوعي بوسائل الدفع الإلكتروني", "ضعف الثقة بالجوانب الأمنية لحماية المعلومات"], "a": 1, "lesson": 1, "explain": "ذكر المقال ثلاثة عوائق: مشكلة اللغة (لا تزيد على 0.5%)، وعدم الوعي بوسائل التجارة الإلكترونية ولا سيما وسائل الدفع، وضعف الثقة بالجوانب الأمنية. ولم يذكر أسعار الحواسيب."}, {"q": "مثنى الاسم المقصور «عصا»:", "opts": ["عصيان", "عصاان", "عصوان", "عصاوان"], "a": 2, "lesson": 2, "explain": "1) الألف في «عصا» ثالثة. 2) أصلها واو (من الجذر ع ص و). 3) القاعدة: إذا كانت الألف ثالثة أصلها الواو قُلبت واوًا عند التثنية: عصوان، وهو مثال الكتاب نفسه."}, {"q": "مثنى «مستشفى»:", "opts": ["مستشفيان", "مستشفوان", "مستشفان", "مستشفاءان"], "a": 0, "lesson": 2, "explain": "الألف في «مستشفى» سادسة (م س ت ش ف ى)، والقاعدة: إذا كانت الألف رابعة فأكثر قُلبت ياءً عند التثنية مطلقًا، فنقول: مستشفيان."}, {"q": "اختاري الصواب: ﴿وإنهم عندنا لمن ____ الأخيار﴾", "opts": ["المصطفيين", "المصطفون", "المصطفاين", "المصطفَين"], "a": 3, "lesson": 2, "explain": "مفرد الكلمة «المصطفى». عند جمعه جمع مذكر سالمًا تُحذف الألف وتبقى الفتحة قبلها، والكلمة مجرورة بـ«من» فتأتي بالياء والنون: المصطفَين. و«المصطفون» للرفع، و«المصطفيين» خطأ لبقاء الياء."}, {"q": "جمع «ليلى» (علم لمؤنث) جمع مؤنث سالمًا:", "opts": ["ليلات", "ليليات", "ليلوات", "ليالي"], "a": 1, "lesson": 2, "explain": "يُراعى في جمع المؤنث السالم ما يُراعى في التثنية، والألف في «ليلى» رابعة فتُقلب ياءً: ليليات، وهو مثال الكتاب. أما «ليالي» فجمع تكسير لكلمة ليلة."}, {"q": "إعراب «المرتقى» في قول الرجل لهشام: «لا يغرّنّك المرتقى وإن كان سهلًا»:", "opts": ["فاعل مرفوع وعلامة رفعه الضمة المقدرة على آخره منع من ظهورها التعذر", "مفعول به منصوب بالفتحة المقدرة", "مبتدأ مرفوع بالضمة الظاهرة", "فاعل مرفوع وعلامة رفعه الضمة المقدرة منع من ظهورها الثقل"], "a": 0, "lesson": 2, "explain": "الكاف في «يغرّنّك» ضمير في محل نصب مفعول به، و«المرتقى» هو الذي يغرّ فهو الفاعل، مرفوع بضمة مقدرة على الألف للتعذر لأن الألف لا تقبل الحركة (أما الثقل فيكون في المنقوص). وهذا إعراب دليل المعلم."}, {"q": "مثّل الدرس لثبات العاطفة واستمرارها بـ:", "opts": ["رثاء أبي العلاء المعري لقاضي المعرة", "حوار عروة بن الورد مع زوجه", "مدح ابن هانئ لجوهر الصقلي", "لامية العرب للشنفرى"], "a": 3, "lesson": 3, "explain": "في مقياس الثبات تأمّل الدرس لامية العرب للشنفرى (68 بيتًا): تثور العاطفة في المطلع، وتهدأ عند حديثه عن جوعه، ثم تثور معتزّة، لكن الوحدة الشعورية تبقى طيلة القصيدة. أما المعري فمثال الصدق، وعروة مثال القوة الهادئة، وابن هانئ مثال المدح الزائف."}, {"q": "المقصود بقوة العاطفة في الدرس:", "opts": ["ثورتها وحدّتها دائمًا", "أن تكون قوية مؤثرة ولو كانت هادئة رزينة، ومصدرها الأول نفس الأديب", "كثرة الأفكار العميقة في النص", "قدرة النص على إثارة الجمهور مهما كان باعثه"], "a": 1, "lesson": 3, "explain": "يقول الدرس: «ليس المراد بقوة العاطفة ثورتها وحدّتها؛ فقد تكون العاطفة هادئة رزينة»، ومصدر قوتها الأول نفس الأديب وطبيعته. والأفكار العميقة لا تكفي إن كان الأديب ضعيف الشعور، وإثارة الجمهور لا تدل حتمًا على سمو النص."}, {"q": "سلك البحتري في وصف «إيوان كسرى» طريقة:", "opts": ["ترتيب الأشياء من القريب إلى البعيد", "الوصف كالتصوير بوصف أبرز الأشياء فقط", "الابتداء بالوصف الكلي ثم الانتقال إلى الجزئيات", "الوصف المجرد الخالي من الخيال"], "a": 2, "lesson": 4, "explain": "ذكر الدرس أن البحتري بدأ بالصورة العامة للإيوان، ثم تناول أحد أجزائه الفخمة فوصفه وصفًا دقيقًا، ثم صورة من الصور المعلقة على جدرانه؛ وهذه طريقة الابتداء بالوصف الكلي ثم الانتقال إلى الجزئيات."}], "game": {"type": "shop", "q": [{"q": "مثنى «فتى»:", "opts": ["فتوان", "فتيان", "فتاان"], "a": 1}, {"q": "مثنى «عصا»:", "opts": ["عصوان", "عصيان", "عصاتان"], "a": 0}, {"q": "مثنى «هدى»:", "opts": ["هدوان", "هداان", "هديان"], "a": 2}, {"q": "مثنى «مرتضى»:", "opts": ["مرتضيان", "مرتضوان", "مرتضان"], "a": 0}, {"q": "جمع «ملتقى» جمع مؤنث سالمًا:", "opts": ["ملتقات", "ملتقيات", "ملتقوات"], "a": 1}, {"q": "جمع «مصطفى» (علم لمذكر) رفعًا:", "opts": ["مصطفيون", "مصطفاون", "مصطفَون"], "a": 2}, {"q": "جمع «سعدى» (علم لمؤنث) جمع مؤنث:", "opts": ["سعديات", "سعدوات", "سعدات"], "a": 0}, {"q": "الاسم المقصور آخره:", "opts": ["ياء لازمة", "ألف لازمة", "همزة بعد ألف"], "a": 1}, {"q": "المتجر الافتراضي يوجد:", "opts": ["في الواقع فقط", "على الإنترنت فقط", "في الواقع والشبكة"], "a": 1}, {"q": "نسبة العربية على الإنترنت لا تتجاوز:", "opts": ["0.5%", "5%", "25%"], "a": 0}, {"q": "مثال ثبات العاطفة في الدرس:", "opts": ["عروة بن الورد", "ابن هانئ", "لامية الشنفرى"], "a": 2}, {"q": "الخط عند عبد الحميد الكاتب:", "opts": ["ثقاف الألسنة", "حلية الكتب", "قوام الخراج"], "a": 1}]}}];
window.BASIRA_NOVELS=[{"id": "n1", "title": "سرّ المخطوطة الزرقاء", "genre": "غموض", "blurb": "في رفٍّ منسيّ من مكتبة جدّها في نزوى، تعثر مريم على مخطوطة بغلاف أزرق، أبياتها ناقصة وفي هامشها رسالة غامضة: «إلى التي ستجد هذا بعدي». لغزٌ يقود إلى لغز، وجدٌّ يبتسم ولا يجيب، فمن كتبت هذه الكلمات، ولمن؟", "values": ["حبّ العلم ونشره", "الوفاء للأجداد", "الصبر والتفكير قبل الحكم"], "chapters": [{"title": "الرفّ الأخير", "text": "كانت رائحة الورق القديم أوّل ما استقبل مريم حين فتحت باب الغرفة العلوية في بيت جدّها بحارة العقر في نزوى. رائحة تشبه الغبار والقهوة معًا، كأنّ الكتب نفسها شربت فناجين كثيرة في مجالس لم تعد موجودة.\n\nقال جدّها سالم وهو يتّكئ على عصاه عند العتبة: «هذه المكتبة لم يرتّبها أحد منذ عشرين سنة. إن رتّبتِها في إجازتك فلكِ أن تأخذي منها ما تشائين».\n\nابتسمت مريم. كانت في الخامسة عشرة، تحبّ الألغاز والروايات البوليسية، وترى في كلّ صندوق مغلق قصة تنتظر من يحكيها. فتحت النافذة الخشبية الصغيرة لتدخل الريح، فرأت برج حصن نزوى المستدير يلمع تحت شمس الضحى، وسمعت أصوات الباعة قادمة من السوق، وشمّت رائحة الحلوى العُمانية تتسلّل مع الهواء الدافئ. شمّرت عن ساعديها، ووضعت كمّامة على أنفها اتّقاءً للغبار.\n\nبدأت من الرفوف السفلى: كتب فقه ونحو، ودواوين شعر بأغلفة جلدية متشقّقة، ودفاتر حسابات قديمة لتجارة التمر. وحين وصلت إلى الرفّ الأخير، تحت السقف الخشبي المصنوع من جذوع النخل، لمحت شيئًا أزرق.\n\nكانت مخطوطة صغيرة، غلافها من قماش مصبوغ بلون النيل، باهت عند الأطراف، ومربوط بخيط من الصوف. فكّت الخيط بحذر، فانفتحت الصفحات على خطّ دقيق جميل، مكتوب بحبر بنّي.\n\nقرأت السطر الأول: أبيات شعر في وصف الماء والنخل. لكنّ شيئًا غريبًا لفت انتباهها؛ فكلّ بيت ينتهي بفراغ، كأنّ الكاتبة تركت الكلمة الأخيرة عمدًا لمن يقرأ بعدها. وفي الصفحة التالية ألغاز قصيرة: «أنا أمٌّ للقمح ولا أُرضِع، أدور ولا أمشي، فمن أنا؟».\n\nقلّبت الصفحات حتى الأخيرة، فتوقّف قلبها لحظة. في الهامش، بخطّ مختلف قليلًا، كُتبت جملة واحدة: «إلى التي ستجد هذا بعدي: من أكمل الأبيات وجد الباب».\n\nنزلت الدرج مسرعة، والمخطوطة بين يديها. «جدّي! انظر ماذا وجدت!».\n\nرفع الجدّ نظّارته، ونظر إلى الغلاف الأزرق طويلًا. لم يسألها أين وجدتها، ولم يمدّ يده ليأخذها. ارتجفت شفتاه قليلًا، ثم قال بصوت خافت: «لكلّ قفل مفتاح يا مريم. ابحثي».\n\nوعاد إلى مجلسه، تاركًا إيّاها واقفة في منتصف البيت، وفي رأسها سؤال واحد: ماذا يعرف جدّي ولا يريد أن يقوله؟"}, {"title": "كلمات تكمل الحكاية", "text": "في صباح اليوم التالي، كانت رحمة، صديقة مريم وجارتها منذ الطفولة، تجلس معها تحت شجرة الليمون في فناء البيت. أمامهما المخطوطة الزرقاء، ودفتر مدرسي، وقلمان، وصحن من التمر الخلاص الذي أصرّت الجدّة على تقديمه.\n\nقالت رحمة وهي تقرأ بصوت عالٍ: «يجري الماء في الفلج صافيًا، ويسقي النخل حتى يصير... ماذا؟ ظليلًا؟ طويلًا؟».\n\nفكّرت مريم ثم قالت: «انظري إلى القافية. كلّ الأبيات تنتهي براء مفتوحة بعدها ألف. حتى يصير مثمرًا؟». هزّت رحمة رأسها: «لا يستقيم الوزن. ماذا عن «تِبْرا»؟ أي ذهبًا، كأنّ التمر صار ذهبًا من كثرة الماء». صفّقت مريم: «هذه هي!».\n\nقضتا ساعتين في البحث عن الكلمات الناقصة. كانت بعض الأبيات سهلة، وبعضها احتاج إلى معجم جدّها الضخم ذي الغلاف البنّي. وكلّما وجدتا كلمة، كتبتاها في الدفتر بالترتيب. مرّت الجدّة بهما أكثر من مرّة، تحمل إبريق الماء لتسقي الريحان، وتنظر إليهما بفضول، لكنّها لم تسأل.\n\nثم انتبهت رحمة إلى شيء. «مريم، انظري إلى الحروف الأولى من الكلمات التي وجدناها: تاء، حاء، تاء، الألف، لام، راء، حاء، ألف».\n\nكتبتها مريم متّصلة، ثم شهقت: «تحت الرحى!».\n\nتذكّرت فورًا اللغز الأول: «أنا أمٌّ للقمح ولا أُرضِع، أدور ولا أمشي». إنها الرحى، الحجر الذي كانت الجدّات يطحنّ به الحبوب قبل أن تأتي المطاحن الكهربائية.\n\nركضتا إلى زاوية الفناء، حيث تستند رحى حجرية قديمة إلى الجدار، يكسوها الغبار وأوراق الليمون الجافة. لم يكن أحد يستعملها منذ زمن بعيد؛ صارت مجرّد زينة تحبّ الجدّة أن تضع عليها أصيص الريحان.\n\nحاولتا رفع الحجر العلوي، لكنّه كان ثقيلًا كأنّه جزء من الأرض. نادت مريم ابن عمّها خالد، فجاء متذمّرًا ثم تحمّس حين سمع كلمة «لغز». وبعد محاولات، انزاح الحجر قليلًا.\n\nفي التجويف الصغير تحته، ملفوفة بقطعة قماش زرقاء من اللون نفسه، كانت علبة معدنية صغيرة صدئة.\n\nفتحتها مريم بيدين مرتجفتين. في داخلها مفتاح نحاسي قديم، وورقة مطويّة كُتب عليها: «المفتاح للصندوق الذي ينام في غرفة الجدّة، وما فيه أثمن من الذهب».\n\nنظرت الفتاتان إحداهما إلى الأخرى. أيّ صندوق؟ وأيّ جدّة؟"}, {"title": "المندوس المقفل", "text": "في غرفة جدّتها، بين الخزانة الخشبية والنافذة المطلّة على النخيل، كان يقبع مندوس قديم من خشب الساج، تزيّنه مسامير نحاسية صغيرة مرصوصة على شكل نجوم. رأته مريم مئات المرّات منذ طفولتها، لكنّها لم ترَه مفتوحًا قطّ.\n\nقالت جدّتها وهي تضع يدها على صدرها: «هذا المندوس ورثه جدّك عن أمّه، وهي ورثته عن جدّتها. ضاع مفتاحه قبل أن أتزوّج، فتركناه مقفلًا. كان جدّك يقول: سيُفتح حين يأتي وقته».\n\nأخرجت مريم المفتاح النحاسي. أدخلته في القفل، فدار بصعوبة، ثم سُمعت طقّة خفيفة كأنّها تنهيدة.\n\nرفعت الغطاء ببطء. لم يكن في المندوس ذهب ولا فضّة. كانت فيه ألواح خشبية صغيرة ملساء، مرصوصة بعناية، على كلّ واحد منها حروف مكتوبة بالحبر: ألف، باء، تاء... وكلمات قصيرة بخطوط طفولية مرتعشة. وبجانبها أقلام من القصب، ودواة فخارية جفّ حبرها منذ زمن، وصرّة من القماش.\n\nهمست رحمة: «هذه ألواح كتاتيب. كان الأطفال يتعلّمون عليها القراءة».\n\nرفعت مريم أحد الألواح إلى ضوء النافذة. كانت الحروف عليه مكتوبة ثم ممسوحة ثم مكتوبة من جديد، حتى صار الخشب في وسطه أفتح لونًا من أطرافه. تخيّلت يدًا صغيرة تمسحه بخرقة مبلّلة، ثم تبدأ من الألف مرّة أخرى بصبر لا ينفد.\n\nفتحت مريم الصرّة. وجدت فيها ورقة طويلة مطويّة عدّة مرّات، مكتوبًا عليها بالخطّ الدقيق نفسه الذي في المخطوطة الزرقاء: «أسماء بناتي». وتحت العنوان قائمة طويلة: شمسة بنت علي، رية بنت حمد، زيانة بنت سعيد، عزّاء بنت ناصر... أكثر من أربعين اسمًا، وبجانب كلّ اسم تاريخ.\n\nقالت جدّتها مندهشة: «بناتها؟ لكن هؤلاء لسن أخوات! أعرف بعض هذه الأسماء، إنّهنّ من عائلات الحارة كلّها».\n\nمرّرت مريم إصبعها على القائمة حتى وصلت إلى الاسم الأخير. كان مكتوبًا بحبر أحدث قليلًا، وتحته سطر بخطّ مرتجف كخطّ امرأة كبيرة في السنّ:\n\n«مريم بنت سالم. آخر بناتي، وأحبّهنّ إلى قلبي. أوصيكم بها، وبمن يأتي بعدها».\n\nشعرت مريم بقشعريرة تسري في ذراعيها. مريم؟ مثلها تمامًا؟\n\nومن خلفها، جاء صوت جدّها هادئًا من عند الباب: «أظنّ أنّ الوقت قد حان لأحكي لكِ الحكاية كلّها»."}, {"title": "معلّمة الحارة", "text": "جلس الجدّ سالم على الحصير في الفناء، وجلست حوله مريم ورحمة والجدّة، وخالد الذي لم يعد متذمّرًا. وضعت الجدّة دلّة القهوة، وفاحت رائحة الهيل في المكان.\n\nقال الجدّ: «المخطوطة الزرقاء كتبتها جدّتي صفيّة، رحمها الله. عاشت في هذا البيت قبل أكثر من مئة عام. في ذلك الزمن، لم تكن هناك مدارس للبنات في نزوى. كان بعض الأولاد يذهبون إلى الكتاتيب، أمّا أكثر البنات فلم يكنّ يعرفن القراءة».\n\nأشار إلى شجرة الليمون. «في ظلّ شجرة كانت هنا قبل هذه، كانت جدّتي تجمع بنات الحارة كلّ عصر. تعلّمهنّ الحروف على هذه الألواح، ثم القرآن الكريم، ثم الشعر. لم تأخذ من أحد أجرًا. كان بعض الناس يستغربون، ويقولون: وما حاجة البنت إلى القراءة؟ فكانت تبتسم ولا تجادل، وتدعو أمّهاتهم ليسمعن بناتهنّ يقرأن، فيعود الجميع مقتنعين. كانت تقول: البنت التي تقرأ، تفتح بابًا لا يستطيع أحد أن يغلقه».\n\nسألت رحمة: «ولماذا الأبيات الناقصة والألغاز؟».\n\nضحك الجدّ ضحكة خفيفة. «تلك كانت طريقتها. كانت تقول إنّ الحفظ وحده لا يكفي، وإنّ البنت يجب أن تفكّر لتصل إلى الكلمة بنفسها. كانت تترك آخر كلّ بيت فارغًا، فتتسابق البنات في إكماله، ومن تُكمل الأبيات كلّها تحصل على لغز جديد».\n\nثم صمت قليلًا، ونظر إلى مريم. «ومريم بنت سالم التي في آخر القائمة هي أمّي. تعلّمت القراءة على يد جدّتها صفيّة وهي في السابعة. وحين كبرت جدّتي وضعف بصرها، خبّأت المفتاح تحت الرحى، وكتبت تلك الجملة في الهامش. قالت لأمّي: سيأتي يوم تبحث فيه بنت من بناتنا عن هذا الباب، فلا تعطوها المفتاح، دعوها تجده».\n\nقالت مريم بصوت متهدّج: «ولهذا لم تخبرني حين رأيت المخطوطة».\n\n«نعم. وعدت أمّي ألّا أفتح الباب لأحد. وسمّيتكِ مريم على اسمها، وانتظرت».\n\nساد صمت طويل، لا يقطعه إلّا صوت الماء في الفلج القريب. ثم فتحت مريم المخطوطة على صفحتها الأخيرة، فوجدت ما لم تنتبه إليه من قبل: صفحة بيضاء تمامًا، في أعلاها عنوان صغير:\n\n«درسٌ لم يُكتب بعد»."}, {"title": "درس لم يُكتب بعد", "text": "لم تنم مريم تلك الليلة. ظلّت تقلّب الألواح الخشبية تحت ضوء المصباح، وتتخيّل أصابع صغيرة تمسك بأقلام القصب، وعيونًا تلمع حين تنطق أوّل كلمة مقروءة. أربعون بنتًا، وربّما أكثر، تعلّمن هنا، في هذا الفناء نفسه.\n\nوفي الصباح، ذهبت إلى رحمة قبل أن تشرب شايها. قالت: «عندي فكرة. هل تذكرين بنات الحارة الصغيرات اللواتي يلعبن قرب المسجد كلّ عصر؟ أكثرهنّ يقضين الإجازة أمام الهواتف. ماذا لو جمعناهنّ هنا، تحت شجرة الليمون، كما كانت تفعل الجدّة صفيّة؟».\n\nاتّسعت عينا رحمة. «نعلّمهنّ القراءة؟ لكنّهنّ يعرفن القراءة».\n\n«نعلّمهنّ أن يحببنها. بالألغاز والأبيات الناقصة. لن نقرأ لهنّ، بل سنجعلهنّ يبحثن عن الكلمات بأنفسهنّ».\n\nفي العصر الأول جاءت ثلاث بنات فقط، يتلفّتن بفضول نحو المندوس المفتوح والألواح القديمة. كانت إحداهنّ، واسمها جوخة، في التاسعة، تقول إنّ القراءة مملّة وإنّ الكتب لا تتحرّك مثل الشاشات. وبعد ساعة، كانت هي أوّل من صرخت بفرح حين وجدت الكلمة الناقصة. أعطتهنّ مريم بيتًا ناقصًا من المخطوطة، وقالت: «من تُكمله تحصل على لغز». بعد أسبوع صرن عشرًا. وبعد أسبوعين، صارت أمّهاتهنّ يجلسن على الحصير يستمعن ويبتسمن، وبعضهنّ يتذكّرن أبياتًا حفظنها من جدّاتهنّ.\n\nكان الجدّ سالم يجلس في ركنه المعتاد، يراقب المشهد بصمت، وفي عينيه لمعة لم ترها مريم من قبل. قالت الجدّة ذات مساء: «لم أرَ جدّك سعيدًا هكذا منذ سنوات».\n\nفي آخر يوم من الإجازة، جلست مريم وحدها في الغرفة العلوية، والمخطوطة الزرقاء مفتوحة على الصفحة البيضاء. أمسكت قلمها، وفكّرت طويلًا، ثم كتبت أبياتًا من تأليفها عن شجرة الليمون والبنات اللواتي يتعلّمن في ظلّها، وتركت آخر كلّ بيت فارغًا.\n\nثم كتبت لغزًا جديدًا، وأخفت جوابه في مكان لا يعرفه أحد غيرها.\n\nوفي الهامش، تحت جملة جدّتها القديمة، كتبت بخطّها:\n\n«إلى التي ستجد هذا بعدي: الباب مفتوح. فقط ابحثي».\n\nأغلقت المخطوطة، وربطتها بخيط الصوف، وأعادتها إلى الرفّ الأخير. ثم نزلت الدرج، وهي تعرف أنّ أثمن ما في البيت لم يكن في المندوس، بل في الحكاية التي ستستمرّ."}], "vocab": [{"w": "مَخْطُوطَة", "m": "كتاب مكتوب باليد لا بالطباعة"}, {"w": "الرَّحَى", "m": "حجران مستديران يُطحن بهما الحَبّ يدويًّا"}, {"w": "مَنْدُوس", "m": "صندوق خشبيّ تقليديّ مزيّن بالمسامير النحاسية لحفظ الأشياء الثمينة"}, {"w": "دَوَاة", "m": "إناء صغير يوضع فيه الحبر"}, {"w": "صُرَّة", "m": "قطعة قماش تُجمع أطرافها وتُربط على ما بداخلها"}, {"w": "الكَتَاتِيب", "m": "أماكن قديمة لتعليم الأطفال القراءة والكتابة والقرآن"}, {"w": "مُتَهَدِّج", "m": "صوت متقطّع مرتجف من شدّة التأثّر"}], "quiz": [{"q": "كيف عرفت مريم ورحمة أنّ المفتاح مخبّأ تحت الرحى؟", "opts": ["أخبرهما الجدّ سالم بمكانه", "جمعتا الحروف الأولى من الكلمات الناقصة فكوّنت «تحت الرحى»", "وجدتا خريطة مرسومة في آخر المخطوطة"], "a": 1, "explain": "لاحظت رحمة أنّ الحروف الأولى للكلمات التي أكملتاها تكوّن عبارة «تحت الرحى»، ثم ربطتها مريم باللغز الأول."}, {"q": "ماذا وجدت مريم داخل المندوس؟", "opts": ["ألواحًا خشبية وأقلام قصب وقائمة بأسماء البنات", "حُليًّا من الذهب والفضّة", "رسائل من جدّها إلى جدّتها"], "a": 0, "explain": "لم يكن في المندوس ذهب، بل أدوات تعليم البنات: ألواح وأقلام قصب ودواة وقائمة «أسماء بناتي»."}, {"q": "لماذا لم يخبر الجدّ سالم حفيدته بالسرّ حين رأى المخطوطة؟", "opts": ["لأنّه نسي القصة تمامًا", "لأنّه لم يكن يعرف شيئًا عن المخطوطة", "لأنّه وعد أمّه أن يترك البنت تجد الباب بنفسها"], "a": 2, "explain": "أوصت الجدّة صفيّة ألّا يُعطى المفتاح لأحد، وأن تُترك البنت تبحث وتجده، فوفى الجدّ بوعده لأمّه."}, {"q": "ماذا فعلت مريم في آخر يوم من الإجازة؟", "opts": ["أهدت المخطوطة إلى مكتبة المدرسة", "كتبت أبياتًا ناقصة ولغزًا جديدًا في الصفحة البيضاء لمن تأتي بعدها", "باعت المندوس لتشتري كتبًا جديدة"], "a": 1, "explain": "أكملت مريم «الدرس الذي لم يُكتب بعد» بأبيات ناقصة ولغز، وكتبت رسالة لمن ستجد المخطوطة بعدها."}], "discuss": ["قالت الجدّة صفيّة: «البنت التي تقرأ تفتح بابًا لا يستطيع أحد أن يغلقه». ما الباب الذي فتحته لكِ القراءة؟", "لماذا ترين أنّ الجدّة صفيّة اختارت أن تترك المفتاح مخبّأً بدل أن تسلّمه لأحد مباشرة؟", "لو كتبتِ لغزًا لفتاة ستقرأ دفترك بعد مئة عام، فماذا ستكتبين؟"]}, {"id": "n2", "title": "نجمة فوق جبل شمس", "genre": "مغامرة", "blurb": "رحلة مدرسية إلى سقف عُمان، وصورة واحدة أرادت ريم أن تلتقطها قرب الحافة. حين تلتفت هند لا ترى المجموعة، والشمس تغرق خلف الجبال، والهاتف بلا إشارة، ولم يبقَ لها إلّا صوت جدّها وسماءٌ بدأت نجومها تظهر.", "values": ["الهدوء عند الأزمات", "التعاون وتقدير قدرات الآخرين", "قيمة المعرفة الموروثة عن الكبار"], "chapters": [{"title": "الطريق إلى سقف عُمان", "text": "كانت الحافلة تصعد الطريق المتعرّج كأنّها تتسلّق ظهر تنّين نائم. في كلّ منعطف تشهق بعض الطالبات، ويلتصقن بالنوافذ ليرين الوادي الذي يزداد عمقًا تحتهنّ، والقرى الصغيرة التي صارت بحجم حبّات الحمّص.\n\nقالت الأستاذة منى من مقدّمة الحافلة: «جبل شمس أعلى قمّة في سلطنة عُمان. ارتداء السترات إلزامي، فالحرارة هنا في فبراير قد تنزل ليلًا إلى ما يقارب الصفر».\n\nضحكت ريم، الجالسة بجوار هند، وقالت: «الصفر؟ في عُمان؟ أنتِ تمزحين يا أستاذة!». لكنّها سحبت سترتها الصوفية من الحقيبة حين نزلن ولسعهنّ الهواء البارد كإبرة.\n\nوقفت هند عند حافّة المنصّة الحجرية، وأمسكت بالسور الحديدي. أمامها كان وادي غول ينفتح كجرح هائل في الأرض، جدرانه الصخرية تهبط مئات الأمتار، وتتلوّن بالبنّي والرمادي والورديّ. كان صقر يحلّق تحتها، تحتها هي! شعرت هند أنّها تقف على حافّة العالم.\n\nاقتربت منها بشرى، وهاتفها في يدها كالعادة. «لا توجد إشارة هنا تقريبًا. كيف سأرسل الصور لأمّي؟».\n\nردّت هند وعيناها على الوادي: «أرسليها حين نعود. انظري الآن، فهذا لن يتكرّر».\n\nقرب القرية الصغيرة، كانت نساء من أهل الجبل يبعن أشغالًا يدوية من صوف الماعز: أساور ملوّنة وسلالًا صغيرة. اشترت هند سوارًا أحمر وأسود، وتذكّرت جدّها، فهو أيضًا من أهل الجبال، وكان يأخذها إلى سطح بيته في القرية ليلًا، ويشير إلى السماء ويقول: «النجوم يا هند خريطة لا تبلى. من عرفها لا يضيع».\n\nبدأت المجموعة السير على الممشى المحفور في حافّة الجبل. قالت الأستاذة: «سنمشي جنوبًا ساعة واحدة، ثم نعود إلى الحافلة قبل الغروب. لا أحد يبتعد عن الطريق».\n\nكان الممشى ضيّقًا في بعض المواضع، عن يمينه جدار الجبل وعن يساره الهاوية. مشت هند بحذر، تراقب حذاءها الرياضي على الحجارة الملساء، وتسمع ضحكات الطالبات تتردّد بين الصخور كأنّ الجبل يضحك معهنّ.\n\nفي منتصف الطريق، توقّفت المجموعة للراحة. رأت ريم صخرة بارزة أسفل الممشى بقليل، تطلّ على الوادي من زاوية مدهشة. «صورة واحدة فقط!»، قالت، ونزلت إليها. لحقت بها هند لتعيدها، ولحقت بشرى بهما.\n\nثم سمعت هند صوتًا مكتومًا، ورأت ريم تسقط على جانبها، ممسكة بكاحلها.\n\nوحين رفعت هند رأسها نحو الممشى، لم ترَ أحدًا."}, {"title": "حين يختفي الطريق", "text": "«ريم! هل أنتِ بخير؟».\n\nكانت ريم تعضّ على شفتها، ودموعها تلمع. «قدمي... التوت. لا أستطيع أن أقف عليها».\n\nصعدت بشرى إلى الممشى ونادت بأعلى صوتها: «أستاذة منى! أستاذة!». لكنّ الصدى وحده عاد إليها من جدران الوادي، مرّة ثم مرّتين ثم تلاشى. كانت المجموعة قد اختفت خلف منعطف صخري، ولم يلاحظ أحد غيابهنّ.\n\nأخرجت بشرى هاتفها بيد مرتجفة. لا إشارة. جرّبت مرّة أخرى، ورفعت الهاتف عاليًا، ثم ضغطت على رقم الطوارئ. لا شيء. بدأ صوتها يرتفع ويتسارع: «سنبقى هنا! سيحلّ الظلام! لن يجدنا أحد!».\n\nشعرت هند بالخوف يتسلّق صدرها هي أيضًا. لكنّها تذكّرت جدّها ذات ليلة، حين انطفأ المصباح وهما في المزرعة، وكانت صغيرة تبكي. أمسك يدها وقال: «الخوف يُطفئ العينين يا هند. تنفّسي أوّلًا، ثم انظري».\n\nأغمضت عينيها، وأخذت نفسًا طويلًا، ثم آخر. وحين فتحتهما، كانت قد قرّرت.\n\nقالت بهدوء لم تعرف من أين جاءها: «بشرى، اسمعيني. نحن لسنا ضائعات، نحن متأخّرات فقط. الطريق هنا، ونحن نعرف أنّه يعود إلى الحافلة. أطفئي الهاتف الآن لنحفظ البطارية، فسنحتاج إلى ضوئه لاحقًا».\n\nترددت بشرى، ثم أطفأته.\n\nجلست هند بجوار ريم، وأخرجت من حقيبتها وشاحًا إضافيًّا، ولفّته حول كاحلها بإحكام كما رأت المسعفة في المدرسة تفعل. «لا تحرّكيها كثيرًا. سنسندك أنا وبشرى».\n\nساعدتاها على الصعود إلى الممشى، ووضعت كلّ منهما ذراعًا تحت كتفها. بدأن السير ببطء شديد، خطوة ثم توقّف ثم خطوة. كانت الشمس تنحدر خلف الجبال المقابلة، تصبغ الصخور بلون النحاس، ثم بلون الدم، ثم بالرمادي.\n\nقالت ريم بصوت خافت: «آسفة. كلّ هذا بسببي وبسبب صورتي الغبيّة».\n\nردّت هند: «لا وقت للأسف الآن. وفّريه لما بعد العودة، وسأسمعه منك كاملًا».\n\nابتسمت ريم رغم الألم.\n\nكان البرد يتسلّل الآن من تحت السترات، وأنفاس الفتيات تخرج بخارًا أبيض. سمعن في البعيد نباح كلب، ثم لا شيء. صار الصمت في الجبل كثيفًا، كأنّه شيء يمكن لمسه باليد.\n\nلكن بعد نصف ساعة، حين ابتلع الظلام آخر خيط من الضوء، توقّفت هند فجأة. أمامهنّ انقسم الممرّ الصخري إلى طريقين، كلاهما يبدو متشابهًا في العتمة.\n\nوهمست بشرى: «أيّهما يا هند؟»."}, {"title": "خريطة الجدّ", "text": "لم تكن هند تعرف الجواب. حاولت أن تتذكّر شكل الطريق في النهار، لكنّها كانت مشغولة حينها بالوادي والصقر والسوار الجديد، ولم تنتبه إلى أيّ تفرّع.\n\nثم رفعت عينيها إلى السماء.\n\nلم ترَ في حياتها سماء كهذه. في المدينة، تطفئ أضواء الشوارع معظم النجوم، أمّا هنا، على ارتفاع يقارب ثلاثة آلاف متر، فقد كانت السماء مزدحمة بها كبساط مرصّع بالفضّة. حتّى بشرى نسيت خوفها لحظة، وقالت: «يا الله...».\n\nامتدّ بين النجوم شريط باهت من الضوء، كأنّ أحدًا نثر حليبًا على قماش أسود. تذكّرت هند أنّ جدّها كان يسمّيه درب التبّانة، ويقول إنّه طريق من ملايين النجوم البعيدة، لا يُرى إلّا حيث يشتدّ الظلام.\n\nقالت هند بصوت عالٍ، كأنّها تتحدّث إلى نفسها: «جدّي كان يقول: ابحثي أوّلًا عن الجبّار. ثلاث نجوم متجاورة في خطّ واحد، كأنّها حزام».\n\nمسحت السماء بعينيها، فوجدته عاليًا جهة الجنوب: النجوم الثلاث اللامعة في صفّ مستقيم، تحيط بها نجوم أكبر كأنّها كتفا رجل وركبتاه. «هذا هو! الجبّار في الجنوب، إذن الشمال خلفنا».\n\nسألت ريم: «وكيف نتأكّد؟».\n\n«بالجُدَيّ. النجم الثابت الذي لا يتحرّك. كلّ النجوم تدور حوله طوال الليل، وهو وحده يبقى في مكانه فوق الشمال».\n\nاستدارت، وبحثت في الجهة المقابلة، قريبًا من الأفق. كان جدّها يقول إنّ في عُمان لا يرتفع الجُدَيّ كثيرًا، بل يبقى منخفضًا كمصباح معلّق فوق الجبال. وجدت مجموعة من النجوم على شكل حرف دبليو مائل، تسمّيها كتب الفلك ذات الكرسي، ثم مدّت عينيها إلى جانبها، فرأته: نجمًا وحيدًا ليس الأكثر لمعانًا، لكنّه هادئ وثابت.\n\nقالت: «هذا هو الشمال. والأستاذة قالت في الصباح إنّنا سنمشي جنوبًا، ثم نعود. معنى ذلك أنّ الحافلة في الشمال».\n\nنظرت إلى الطريقين. كان أحدهما يتّجه نحو الجُدَيّ تقريبًا، والآخر ينحرف إلى الشرق، نحو منحدر لا يُرى قاعه.\n\nقالت بثقة: «اليمين».\n\nلم تجادل بشرى هذه المرّة. أمسكت ذراع ريم، ومشين ثلاثتهنّ نحو النجم الثابت، وهند تتمتم: «شكرًا يا جدّي».\n\nبعد دقائق، تجمّدت بشرى في مكانها. «اسمعا!».\n\nمن مكان ما قريب في العتمة، جاء صوت أجراس صغيرة متقطّعة، وخطوات كثيرة على الحصى، تقترب منهنّ شيئًا فشيئًا."}, {"title": "صور ريم", "text": "انكمشت الفتيات الثلاث خلف صخرة كبيرة. كانت الأجراس تقترب، والخطوات تتكاثر، ثم انبعث من العتمة صوت غريب ممطوط: «مااااع».\n\nانفجرت ريم بالضحك رغم ألمها. «ماعز! إنّه قطيع ماعز!».\n\nمرّت الماعز من أمامهنّ، عشرات منها، تقفز بخفّة بين الصخور كأنّ الظلام لا يعنيها، والأجراس في أعناقها ترنّ. وضحكت بشرى أيضًا، ضحكة طويلة مرتجفة، أخرجت معها كلّ الخوف الذي حبسته منذ الغروب.\n\nقالت هند: «الماعز تعود إلى بيوتها في القرية. هذا يعني أنّنا على الطريق الصحيح».\n\nلكنّ ريم كانت تتعب. صار وجهها شاحبًا في ضوء النجوم، وصار وزنها يثقل على كتفي صاحبتيها مع كلّ خطوة. وكانت هند تخشى أن يكون التفرّع قد خدعها، وأن يكون الطريق الذي اختارته لا يقود إلى الحافلة.\n\nثم تذكّرت ريم شيئًا. «هاتفي! صوّرت الطريق كلّه في الذهاب! كلّ صخرة غريبة وكلّ شجرة».\n\nأضاءت الشاشة، وبدأت تقلّب الصور بسرعة. صخرة على شكل رأس جمل. جدار حجري قديم مهدّم. شجرة عرعر وحيدة، جذعها ملتوٍ كأنّه حبل مفتول.\n\nقالت بشرى، وقد تحوّلت فجأة إلى شخص آخر: «سأعدّ الخطوات. مشينا في الذهاب نحو ساعة. لنبحث عن الشجرة. وسأشغّل ضوء الهاتف دقيقة كلّ خمس دقائق فقط، لنحافظ على البطارية».\n\nنظرت إليها هند بدهشة. بشرى التي كانت تصرخ قبل ساعة، صارت الآن تنظّم الوقت والضوء بدقّة. وريم التي سبّبت المشكلة بصورة، صارت صورها هي الحلّ. فكّرت هند أنّ كلّ واحدة منهنّ تحمل قطعة من الخريطة: هي تعرف النجوم، وريم تحفظ الطريق بالصور، وبشرى تعرف كيف تحسب وتنظّم. ولا قطعة تكفي وحدها.\n\nبعد عشرين دقيقة، ظهر في ضوء الهاتف الجدار الحجري المهدّم. هتفن ثلاثتهنّ في وقت واحد. وبعد عشر دقائق أخرى، ظهرت شجرة العرعر الملتوية، تمامًا كما في الصورة.\n\nقالت ريم: «من هنا كانت الحافلة على بعد خمس عشرة دقيقة فقط».\n\nلكنّها حين حاولت أن تخطو، أطلقت صرخة مكتومة وجلست على الأرض. كان كاحلها قد انتفخ حتى ضاق عليه الوشاح.\n\n«لا أستطيع. آسفة. لا أستطيع خطوة واحدة».\n\nتبادلت هند وبشرى النظرات. كان البرد يشتدّ، والطريق الباقي قصيرًا، لكنّه في الظلام مع صديقة لا تمشي، بدا بعيدًا كالقمر."}, {"title": "النجمة الثابتة", "text": "قالت هند: «لن نفترق. هذه أهمّ قاعدة. سنبقى هنا عند الشجرة، فهي علامة يعرفها الجميع على الطريق، ونجعلهم يجدوننا».\n\nأسندن ريم إلى جذع العرعر، واحتمين بصخرة كبيرة تصدّ عنهنّ الريح. لفّت هند سترتها حول قدمي ريم، وجلست بشرى ملتصقة بها لتدفئها. ثم أخرجت هند من حقيبتها ما بقي من الزاد: علبة تمر صغيرة وضعتها أمّها في الصباح، وقارورة ماء نصف ممتلئة. قسّمنها بالتساوي، تمرتين لكلّ واحدة، ورشفات صغيرة من الماء.\n\nوفجأة صاحت بشرى: «الصفّارة! نسيت أنّ معي صفّارة في حقيبتي! أعطتني إيّاها أختي الكبرى لأنّها كانت في الكشّافة».\n\nأخذت نفسًا عميقًا، ونفخت ثلاث نفخات طويلة، ثم انتظرت دقيقة، ثم ثلاثًا أخرى. قالت: «أختي علّمتني أنّ ثلاث صفّارات متتالية تعني: نحن بحاجة إلى مساعدة».\n\nوبين كلّ نداء وآخر، كانت هند تشير إلى السماء، وتحكي لهما ما حكاه لها جدّها: كيف كان البحّارة العُمانيون يهتدون بالنجوم في عرض المحيط، وكيف تعرف الثريّا، وكيف يدلّ ظهور بعض النجوم على مواسم المطر والحصاد. نسيت ريم ألمها قليلًا، ونسيت بشرى البرد.\n\nبعد الصفّارة السادسة، لمع ضوء بعيد على الطريق. ثم ضوء آخر. ثم سمعن صوتًا يعرفنه جيّدًا، صوتًا مبحوحًا من كثرة النداء: «هند! ريم! بشرى!».\n\nكانت الأستاذة منى، ومعها رجل من أهل القرية يحمل مصباحًا قويًّا، وخلفهما مشرفة الرحلة. ركضت الأستاذة إليهنّ وضمّتهنّ واحدة واحدة، ويداها ترتجفان.\n\nحمل الرجل ريم على ظهره بسهولة كأنّها طفلة، وقال وهو يمشي: «أحسنتنّ. أكثر من يضيع في الجبل يضيع لأنّه يركض في الظلام. أنتنّ بقيتنّ معًا، وبقيتنّ قرب علامة معروفة، وأسمعتمونا صوتكنّ».\n\nفي الحافلة، والدفء يعود إلى أصابعهنّ ببطء، قالت الأستاذة منى بجدّية: «ما كان يجب أن تبتعدن عن المجموعة، ولا أن نغفل نحن عن عدّكنّ. سنتعلّم جميعًا من هذا».\n\nبعد أسبوع، وقفت هند أمام طالبات المدرسة في الطابور تتحدّث عن النجوم. وكانت ريم بجانبها، بعكّاز صغير، تعرض صور الطريق. أمّا بشرى، فقد سجّلت اسمها في أوّل ورشة للإسعافات الأوّلية.\n\nوفي تلك الليلة، صعدت هند إلى سطح بيتها، وبحثت عن الجُدَيّ، فوجدته في مكانه، ثابتًا كوعدٍ لا يُخلف."}], "vocab": [{"w": "المُتَعَرِّج", "m": "الكثير الالتواء والانعطاف"}, {"w": "الجُدَيّ", "m": "النجم القطبيّ الثابت تقريبًا في جهة الشمال، يُهتدى به"}, {"w": "العَرْعَر", "m": "شجر جبليّ دائم الخضرة ينبت في المرتفعات"}, {"w": "كَاحِل", "m": "المفصل الذي يصل القدم بالساق"}, {"w": "تَتَمْتِم", "m": "تتكلّم بصوت خافت غير واضح"}, {"w": "شَاحِب", "m": "متغيّر اللون إلى الاصفرار من تعب أو مرض"}, {"w": "الزَّاد", "m": "الطعام الذي يحمله المسافر معه"}], "quiz": [{"q": "لماذا انفصلت الفتيات الثلاث عن المجموعة؟", "opts": ["لأنّ الحافلة غادرت قبل موعدها", "لأنّ ريم نزلت إلى صخرة لتلتقط صورة فالتوت قدمها", "لأنّ الأستاذة أرسلتهنّ في مهمّة"], "a": 1, "explain": "نزلت ريم إلى صخرة أسفل الممشى لتلتقط صورة، ولحقتها صديقتاها، ثم التوى كاحلها والمجموعة قد ابتعدت."}, {"q": "كيف حدّدت هند الطريق الصحيح عند التفرّع؟", "opts": ["سألت راعيًا مرّ بالمكان", "اتّبعت أصوات الحافلة", "حدّدت الشمال بالجُدَيّ، وتذكّرت أنّ الحافلة في الشمال"], "a": 2, "explain": "عرفت الجنوب بالجبّار والشمال بالجُدَيّ، وتذكّرت قول الأستاذة إنّهنّ مشين جنوبًا، فاختارت الطريق المتّجه شمالًا."}, {"q": "كيف ساعدت ريم في إيجاد الطريق رغم إصابتها؟", "opts": ["بالصور التي التقطتها للطريق في الذهاب", "بالاتّصال بأهلها", "برسم خريطة على الأرض"], "a": 0, "explain": "تذكّرت ريم أنّها صوّرت معالم الطريق في الذهاب، فقارنّ الصور بما يرينه حتّى وصلن إلى شجرة العرعر."}, {"q": "لماذا قرّرت هند البقاء عند شجرة العرعر بدل مواصلة السير؟", "opts": ["لأنّها نسيت الطريق تمامًا", "لأنّ ريم لم تعد تستطيع المشي، والشجرة علامة معروفة على الطريق", "لأنّ الأستاذة طلبت منها ذلك بالهاتف"], "a": 1, "explain": "انتفخ كاحل ريم فعجزت عن المشي، فرأت هند أنّ البقاء معًا عند علامة معروفة وإطلاق نداءات الاستغاثة أسلم."}], "discuss": ["تحوّلت بشرى من فتاة خائفة إلى منظِّمة للوقت والضوء. ما الذي يجعل الإنسان يكتشف قوّته في المواقف الصعبة؟", "قال جدّ هند: «الخوف يُطفئ العينين». هل مررتِ بموقف أفقدكِ الخوف فيه القدرة على التفكير؟ ماذا تفعلين لتستعيدي هدوءك؟", "ما المعرفة التي تعلّمتِها من أحد كبار عائلتك، وتظنّين أنّها قد تنفعك يومًا ما؟"]}, {"id": "n3", "title": "لؤلؤة جدّي", "genre": "تاريخية", "blurb": "في صندوق صغير من خشب الساج، تحفظ جدّة سلمى لؤلؤة لم يبعها أبوها الغوّاص يومًا، حتى في أقسى سنوات الجوع. وفي صور، حيث تُصنع السفن ويهدر البحر، تبدأ سلمى رحلة البحث عن جواب سؤال بسيط: لماذا؟", "values": ["برّ الوالدين والوفاء للأسرة", "تقدير تضحيات الأجداد", "القيمة الحقيقية للأشياء لا تُقاس بثمنها"], "chapters": [{"title": "الصندوق الصغير", "text": "في صور، يصل البحر إلى البيوت قبل أن تصل إليها الشمس. هكذا كانت سلمى تشعر كلّما استيقظت في بيت جدّتها زوينة، على صوت النوارس ورائحة الملح التي تتسلّل من النافذة المطلّة على الخور. في الضفّة الأخرى كانت منارة العيجة البيضاء، وتحتها قوارب الصيّادين ترسو كأطفال نائمين.\n\nكانت سلمى في الخامسة عشرة، تقضي أسبوعًا من الإجازة مع جدّتها، وتحمل معها واجبًا مدرسيًّا ثقيلًا: «مشروع عن التراث البحري العُماني، بمصادر من الأسرة». لم تكن تعرف من أين تبدأ. فكّرت في تصوير سفينة خشبية أو زيارة متحف، لكنّ معلّمتها اشترطت أن تكون المصادر من الأسرة نفسها: حكايات الأجداد وأشياؤهم. وسلمى لم تكن تعرف عن أجدادها البحّارة سوى أسماء قليلة تتردّد في المجالس.\n\nفي المساء، جلست الجدّة على السجّادة، وأمامها صينية القهوة والتمر وصحن صغير من الحلوى، وقالت: «تريدين التراث البحري؟ تعالي».\n\nقامت ببطء، وفتحت خزانتها الخشبية، وأخرجت من أعماقها صندوقًا صغيرًا من خشب الساج، بحجم الكفّ، أسود من القِدم، تزيّنه نقوش دقيقة على شكل أمواج. وضعته في حجر سلمى، وقالت: «افتحيه برفق».\n\nداخل الصندوق قطعة قماش حمراء باهتة، وحين فكّت سلمى طيّاتها، ظهرت لؤلؤة.\n\nلم تكن كبيرة كما تخيّلت، ولا مستديرة تمامًا، بل منبعجة قليلًا من جانب واحد، كقطرة ماء على وشك أن تسقط. لكنّ لونها كان غريبًا، أبيض يميل إلى الورديّ، وحين حرّكتها تحت المصباح، تلألأت كأنّ في داخلها ضوءًا صغيرًا.\n\nقالت الجدّة: «هذه لؤلؤة أبي، رحمه الله. كان غيصًا، غوّاصًا على اللؤلؤ، مثل أكثر رجال صور في زمانه».\n\n«وكم ثمنها؟».\n\nضحكت الجدّة. «لا أدري. لم يبعها قطّ. جاءه التجّار مرّات، وعرضوا عليه مالًا كثيرًا. وفي سنة شديدة، قلّ فيها الرزق حتى صار طعامنا التمر والسمك المجفّف أيّامًا متتالية، قالت له أمّي: بِعها يا خميس. فرفض».\n\n«لماذا؟».\n\nسكتت الجدّة طويلًا، وهي تنظر إلى اللؤلؤة في كفّ حفيدتها. ثم قالت بصوت فيه حيرة قديمة: «سألته هذا السؤال مئة مرّة وأنا صغيرة. وكان دائمًا يبتسم ويقول جملة واحدة لم أفهمها: هذه ليست لي يا زوينة».\n\nثم أضافت: «ومات، ولم يخبرني لمن هي»."}, {"title": "أربعة أشهر في البحر", "text": "في صباح اليوم التالي، طلبت سلمى من جدّتها أن تحكي لها كلّ شيء عن أبيها. أخرجت دفترها، وجلست قرب الجدّة على عتبة البيت، حيث يمرّ هواء البحر باردًا قبل أن تشتدّ الشمس.\n\nقالت الجدّة: «كان موسم الغوص الكبير يبدأ مع اشتداد الحرّ، ويستمرّ نحو أربعة أشهر. يخرج الرجال في سفن خشبية كبيرة إلى مغاصات اللؤلؤ البعيدة، ولا يعودون حتى نهاية الصيف. كنّا نقف على الشاطئ نودّعهم، والنساء يبكين، والنهّام يغنّي على ظهر السفينة أغاني طويلة حزينة».\n\n«ومن هو النهّام؟».\n\n«المغنّي. كان صوته يهوّن على الرجال التعب والغربة. وكان أبي غيصًا، يغوص في الماء. أمّا ابن عمّه سعيد فكان سيبًا، يبقى على ظهر السفينة ويمسك الحبل المربوط بخصر أبي. إذا هزّ أبي الحبل، سحبه سعيد إلى السطح بكلّ قوّته».\n\nوصفت الجدّة كيف كان الغيص يضع على أنفه الفطام، وهو مشبك صغير من عظم أو خشب يمنع دخول الماء، وكيف يربط في قدمه حجرًا ثقيلًا ليهبط بسرعة إلى القاع، ويعلّق في عنقه سلّة من الحبال يجمع فيها المحار. «كان يبقى تحت الماء دقيقة، وأحيانًا أكثر. ثم يصعد، ويتنفّس قليلًا، ثم يغوص مرّة أخرى. عشرات المرّات في اليوم، من الفجر حتى الغروب».\n\nكتبت سلمى بسرعة، ثم توقّفت. «ألم يكن ذلك خطرًا؟».\n\n«كان خطرًا جدًّا. كان أبي يعود في آخر كلّ موسم نحيلًا، محروق الجلد، وفي أذنيه ألم لا يزول. وكانت أمّي تقول إنّ البحر يعطي اللؤلؤ، لكنّه يأخذ ثمنه من أنفاس الرجال وأعمارهم».\n\n«وهل وجد اللؤلؤة الورديّة في أحد المواسم؟».\n\nهزّت الجدّة رأسها بحيرة. «لا أعرف. كنت أظنّ ذلك دائمًا. لكنّ اللؤلؤ الذي يُستخرج في السفينة لا يملكه الغيص وحده، فالنوخذة، قائد السفينة، يبيعه للطوّاش، تاجر اللؤلؤ، ثم يُقسَّم المال بين الجميع حسب أنصبتهم. فكيف تبقى مع أبي لؤلؤة لم تُبَع؟».\n\nفتحت سلمى الصندوق مرّة أخرى، وأخرجت القماشة الحمراء لتنظر إليها في ضوء النهار. وحين مرّرت أصابعها على طرفها، شعرت بشيء صلب خفيف، مخيط داخل الحاشية.\n\n«جدّتي... هناك شيء في القماش»."}, {"title": "الورقة المخيطة", "text": "أحضرت الجدّة مقصًّا صغيرًا ونظّارتها، وفتحت سلمى الخياطة القديمة غرزة غرزة، بحذر من يفكّ لغمًا. كانت الخيوط هشّة، تتفتّت بين الأصابع كالرماد.\n\nفي الداخل، ورقة صغيرة مطويّة طيّات كثيرة، صفراء كأوراق الخريف، وحوافّها متآكلة.\n\nفتحتها سلمى ببطء شديد. كانت الكتابة بحبر باهت وخطّ مرتّب، وفي أسفلها بصمة إبهام بنّية.\n\nقالت الجدّة: «أبي لم يكن يعرف الكتابة. لا بدّ أنّه طلب من أحد أن يكتب له، ثم بصم».\n\nقرأت سلمى بصوت مرتعش:\n\n«بسم الله الرحمن الرحيم. هذه اللؤلؤة لم أُخرجها من البحر الذي أغوص فيه، ولم يكن لنوخذة ولا لطوّاش فيها حقّ. هي هديّة من يد صغيرة، أعطتني إيّاها لأترك البحر. فلا تُباع ما دمت حيًّا، ولا بعد موتي، حتى تعود إلى صاحبتها».\n\nرفعت سلمى عينيها إلى جدّتها. كانت الجدّة تحدّق في الورقة، وشفتاها تتحرّكان كأنّها تعيد قراءة الكلمات في صمت.\n\n«يد صغيرة؟ صاحبتها؟ من تكون؟».\n\nقالت سلمى: «ربّما أمّك؟».\n\n«لا. أمّي كانت امرأة كبيرة حين تزوّجته. ولو كانت هي، لعرفتُ. كانت تحكي لي كلّ شيء».\n\n«أخت له؟ ابنة أخيه؟».\n\nهزّت الجدّة رأسها، وفي عينيها ارتباك لم تره سلمى من قبل. كانت جدّتها دائمًا تعرف الأجوبة: متى ينضج الرطب، وكيف تُطبخ المضروبة، ومن تزوّج من في حارتها قبل خمسين سنة. أمّا الآن، فقد بدت كطفلة ضائعة في سوق مزدحم.\n\nثم قالت فجأة، وهي تنهض: «شيخة».\n\n«من؟».\n\n«أختي الكبرى. هي أكبر منّي بثماني سنوات، وما زالت تعيش في البيت القديم قرب ساحة صناعة السفن. إن كان أحد يعرف، فهي».\n\nحملت سلمى الصندوق بعناية، وخرجت مع جدّتها في العصر. مرّتا بالخور، حيث كان العمّال في ورشة السفن ينحتون أضلاع سفينة خشبية جديدة، والنشارة تتطاير حولهم، ورائحة الخشب الطازج تملأ الهواء.\n\nقالت الجدّة وهي تشير إلى الورشة: «هنا عمل أبي سنوات طويلة، بعد أن ترك الغوص».\n\nتوقّفت سلمى. «ترك الغوص؟ متى؟ ولماذا؟».\n\nلكنّ الجدّة لم تجب. كانتا قد وصلتا إلى باب خشبي أزرق، وكانت جدّة أخرى أكبر سنًّا تقف على عتبته، تبتسم بفم بلا أسنان تقريبًا."}, {"title": "ذاكرة الأخت الكبرى", "text": "كانت الجدّة شيخة صغيرة الحجم، نحيلة كغصن جاف، لكنّ عينيها كانتا حادّتين لامعتين كعيني طائر. أجلستهما في الحوش، وأمرت حفيدتها الصغيرة بإحضار القهوة، ثم أمسكت الورقة بيدين ترتجفان قليلًا وقرأتها بصوت خافت.\n\nثم ضحكت. ضحكة طويلة صافية، حتى دمعت عيناها.\n\nقالت الجدّة زوينة باستغراب: «ما الذي يضحكك يا شيخة؟».\n\n«أنتِ يا زوينة! أنتِ ما زلتِ لا تعرفين؟».\n\n«أعرف ماذا؟».\n\nمسحت شيخة دموعها بطرف وشاحها، ثم التفتت إلى سلمى، وقالت: «اسمعي يا ابنتي، وسأحكي لك ما رأيته بعينيّ.\n\nكانت زوينة في الرابعة من عمرها. وكان أبي قد عاد لتوّه من موسم غوص صعب، كاد يغرق فيه حين علق حبله بصخرة في القاع، ولولا أنّ سعيدًا سحبه بكلّ قوّته لما عاد. رجع إلينا نحيلًا مريضًا، ينام وهو يرتجف، ويقول إنّ عليه دينًا للنوخذة، وإنّه سيخرج في الموسم القادم ليسدّه.\n\nفي أحد الأيّام، خرجنا مع أمّي إلى الصخور قرب المنارة وقت الجزر، نجمع الأصداف. وكانت زوينة تجري هنا وهناك بثوبها الأصفر الصغير، تلتقط كلّ ما يلمع. ثم وجدت محارة مغلقة عالقة بين صخرتين، فحملتها إلى أبي، الذي كان جالسًا على الشاطئ ينظر إلى البحر بصمت.\n\nفتحها أبي بسكّينه ليضحكها، فقط ليريها ما في داخلها. وإذا بها لؤلؤة صغيرة، ورديّة، منبعجة من جانب.\n\nصرخت زوينة من الفرح، ثم أخذتها ووضعتها في كفّ أبي، وأغلقت أصابعه عليها بيديها الصغيرتين، وقالت جملة لن أنساها ما حييت: «خذها يا أبي وبِعها، ولا تذهب إلى البحر الكبير مرّة أخرى».\n\nسكتت شيخة لحظة، ثم أضافت بصوت أخفض: «لم أرَ أبي يبكي قبلها ولا بعدها. بكى ذلك اليوم كطفل، وهو يضمّ زوينة إلى صدره».\n\nكانت الجدّة زوينة تحدّق في أختها، ويدها على فمها، والدموع تنحدر على خدّيها بصمت.\n\nهمست: «أنا؟ أنا التي أعطيته إيّاها؟».\n\n«أنتِ. كنتِ صغيرة جدًّا فنسيتِ. وهو لم يُرِد أن يذكّرك، كان يريد أن يعطيك إيّاها بنفسه يومًا ما، وأن يحكي لك القصّة. لكنّ الأيّام سبقته».\n\nسألت سلمى، وقلبها يخفق: «وهل ترك البحر فعلًا بعدها؟».\n\nنظرت شيخة إلى الخور البعيد، وقالت: «ليس فورًا»."}, {"title": "ما لا يُباع", "text": "حكت الجدّة شيخة البقيّة، وسلمى تكتب ودموعها تبلّل الصفحة.\n\nلم يبع الأب اللؤلؤة. فقد كانت صغيرة غير مستديرة، لا تكفي لسداد دينه، والأهمّ أنّه لم يستطع. كيف يبيع شيئًا أعطته له ابنته لتنقذه؟ فخرج في موسم أخير، وفي حزامه، مربوطة بخيط داخل قطعة القماش الحمراء، كانت اللؤلؤة الورديّة. قال لسعيد على ظهر السفينة: «معي ما يعيدني إلى البيت».\n\nوعاد. وسدّد دينه في ذلك الموسم. ثم جاءت سنوات صار فيها اللؤلؤ الطبيعي لا يُطلب كما كان، بعد أن ظهر في الأسواق البعيدة لؤلؤ يُزرع زراعة، رخيص الثمن. ترك كثير من الرجال الغوص، وترك أبوهما البحر الكبير إلى الأبد، وعمل في ساحة صناعة السفن، يقطع الخشب وينحته ويبني السفن التي لن يغوص منها.\n\nقالت شيخة: «كان يقول دائمًا: البحر أعطاني لؤلؤًا كثيرًا وبعته كلّه. لكنّ الشيء الوحيد الذي أبقاني حيًّا، لم يأتِ من البحر، بل من يد بنتي».\n\nوحين جاءت سنة الجوع، وطلبت منه الأمّ أن يبيعها، ذهب في الليل إلى الكاتب في الحارة، وطلب منه أن يكتب تلك الورقة، وخاطها بنفسه داخل القماش، كي لا يضعف أحد بعده فيبيعها.\n\n«هذه ليست لي يا زوينة». فهمت سلمى الجملة أخيرًا. لم يكن جدّها الأكبر يقول إنّ اللؤلؤة لغيره من الناس. كان يقول إنّها لابنته هي.\n\nفي طريق العودة، مشت الجدّة زوينة صامتة، تمسك يد سلمى بقوّة. وعند ساحة السفن توقّفت، ونظرت طويلًا إلى الأضلاع الخشبية العارية للسفينة التي لم تكتمل، كأنّها ترى أباها بينها.\n\nفي تلك الليلة، فتحت الجدّة الصندوق، وأخرجت اللؤلؤة، وتأمّلتها طويلًا. ثم أعادت لفّها، ووضعت الصندوق في يدي سلمى.\n\n«لا يا جدّتي، إنّها لكِ. الورقة تقول ذلك».\n\n«عادت إليّ أخيرًا، وعرفت قصّتها. وأنا الآن أعطيها لكِ، كما أعطيتها لأبي. لا لتبيعيها، بل لتتذكّري أنّ أغلى الأشياء هي التي لا تجدين لها ثمنًا».\n\nبعد أسبوعين، وقفت سلمى أمام صفّها تقدّم مشروعها عن التراث البحري. تحدّثت عن الغيص والسيب والنهّام والفطام، وعن الرجال الذين دفعوا أنفاسهم ثمنًا للؤلؤ. ثم أخرجت الصندوق الصغير، وفتحته، وقالت:\n\n«وهذه لؤلؤة لم تُبَع. سأحكي لكنّ لماذا»."}], "vocab": [{"w": "الخَوْر", "m": "لسان من البحر يدخل في اليابسة"}, {"w": "غَيْص", "m": "الغوّاص الذي ينزل إلى قاع البحر لجمع المحار"}, {"w": "سَيْب", "m": "البحّار الذي يبقى على السفينة ويسحب حبل الغوّاص"}, {"w": "النَّهَّام", "m": "مغنّي السفينة الذي يُنشد للبحّارة ليخفّف عنهم التعب"}, {"w": "الفِطَام", "m": "مشبك يضعه الغوّاص على أنفه ليمنع دخول الماء"}, {"w": "طَوَّاش", "m": "تاجر اللؤلؤ الذي يشتريه من السفن"}, {"w": "الجَزْر", "m": "انحسار ماء البحر عن الشاطئ"}, {"w": "مُنْبَعِجَة", "m": "غير مستوية الاستدارة، فيها انتفاخ أو تسطّح من جانب"}], "quiz": [{"q": "ماذا كان يقول الأب كلّما سُئل عن سبب عدم بيع اللؤلؤة؟", "opts": ["إنّها ستغلو بعد سنوات", "إنّها ليست له", "إنّه سيبيعها في موسم قادم"], "a": 1, "explain": "كان يكرّر لزوينة: «هذه ليست لي يا زوينة»، ولم تفهم الجملة إلّا بعد معرفة القصّة."}, {"q": "أين وجدت سلمى الورقة التي كشفت جزءًا من السرّ؟", "opts": ["في درج خزانة الجدّة", "تحت الصندوق الخشبي", "مخيطة داخل حاشية القماش الأحمر"], "a": 2, "explain": "شعرت سلمى بشيء صلب في طرف القماش، ففتحت الخياطة القديمة ووجدت الورقة المطويّة."}, {"q": "من الذي وجد اللؤلؤة في الحقيقة؟", "opts": ["زوينة حين كانت في الرابعة، في محارة بين الصخور", "سعيد السيب في موسم الغوص", "الأخت شيخة وهي تجمع الأصداف"], "a": 0, "explain": "حكت شيخة أنّ زوينة الصغيرة وجدت المحارة قرب المنارة وقت الجزر، وأعطت اللؤلؤة لأبيها ليترك الغوص."}, {"q": "لماذا كتب الأب الورقة وخاطها داخل القماش؟", "opts": ["ليُثبت ثمن اللؤلؤة للتجّار", "كي لا يضعف أحد بعده فيبيعها، ولتعود إلى صاحبتها", "لأنّ النوخذة طلب منه ذلك"], "a": 1, "explain": "في سنة الجوع طُلب منه بيعها، فكتب الورقة وخاطها بنفسه حتى لا تُباع وتعود إلى ابنته."}], "discuss": ["قالت الجدّة: «أغلى الأشياء هي التي لا تجدين لها ثمنًا». ما الشيء الذي تملكينه ولا يمكن أن تبيعيه بأيّ ثمن؟ ولماذا؟", "لماذا تظنّين أنّ الأب لم يخبر زوينة بالقصّة بنفسه وهي كبيرة؟ هل كان قراره صائبًا؟", "ما الذي تعلّمتِه عن حياة الغوّاصين قديمًا؟ وكيف تغيّر نظرتك إلى حياتنا اليوم؟"]}, {"id": "n4", "title": "الروبوت الذي تعلّم العربية", "genre": "خيال علمي", "blurb": "ثلاث طالبات، وستّة أسابيع، وروبوت اسمه «ضاد» يُفترض أن يفهم العربية. لكنّه حين سُئل «أين ذهب الكتاب؟» أجاب بثقة: «الذهب معدن ثمين رمزه Au»، فبدأت أطرف مغامرة لغوية في تاريخ المدرسة.", "values": ["الاعتزاز باللغة العربية", "العمل بروح الفريق", "تحويل الأخطاء إلى فرص للتعلّم"], "chapters": [{"title": "ضاد يفتح عينيه", "text": "«ثلاثة، اثنان، واحد... شغّلي!».\n\nضغطت رهف على الزرّ، فأضاءت عينا الروبوت بضوء أزرق دائري، ودار رأسه المصنوع من علبة بلاستيكية مطليّة باللون الفضّي، وأصدر صوتًا يشبه تنهيدة آلة غسيل. ثم قال بصوت معدني رتيب: «مرحبًا. أنا ضاد. كيف أساعدك؟».\n\nصفّقت جود حتى احمرّت كفّاها. كانت هي التي بنت جسمه خلال ثلاثة أسابيع، من محرّكات صغيرة وعجلات قديمة وذراع آلية اشترتها من مدّخراتها. أمّا رهف، عبقرية البرمجة في الصفّ العاشر، فقد قضت ليالي طويلة تكتب الأوامر التي تجعله يسمع ويفهم ويتحرّك.\n\nوأمّا ليان، فكانت تقف في الخلف، ذراعاها معقودتان، تحاول ألّا تبدو متحمّسة أكثر من اللازم. كانت تحبّ الألعاب الإلكترونية والأفلام الأجنبية، وتكتب ملاحظاتها في هاتفها بالإنجليزية، وتعدّ حصّة النحو أطول خمس وأربعين دقيقة في الأسبوع. انضمّت إلى الفريق لأنّ رهف وجود صديقتاها، لا أكثر.\n\nكان المشروع فكرة الأستاذة سميرة، معلّمة العلوم: المسابقة الوطنية للروبوتات المدرسية، وموضوعها هذا العام «روبوت يخدم مدرستي». اختارت الفتيات الثلاث أن يصنعن مساعدًا لمكتبة المدرسة، يسمع طلب الطالبة بالعربية، فيبحث عن الكتاب ويدلّها عليه.\n\nقالت الأستاذة سميرة: «جرّبنه. اسألنه سؤالًا عاديًّا».\n\nتقدّمت جود، وقالت بوضوح: «يا ضاد، أين ذهب كتاب العلوم؟».\n\nأضاءت عيناه، وطنّ قليلًا، ثم قال بفخر: «الذهب معدن ثمين، لونه أصفر، ورمزه الكيميائي Au».\n\nساد صمت قصير، ثم انفجر المختبر بالضحك. حتّى الأستاذة سميرة اضطرّت إلى الجلوس على كرسيّ وهي تمسح دموعها.\n\nقالت رهف وهي تحمرّ خجلًا: «المشكلة أنّه يقرأ الكلمات من دون حركات. «ذهب» عنده قد تكون الفعل وقد تكون المعدن، فاختار المعدن».\n\nقالت ليان من مكانها، بنبرة فيها شيء من السخرية: «ولهذا أقول دائمًا إنّ الإنجليزية أسهل. كلمة واحدة لها معنى واحد. لماذا لا نبرمجه بالإنجليزية ونرتاح؟».\n\nالتفتت إليها الأستاذة سميرة بهدوء: «لأنّ المكتبة كلّها بالعربية يا ليان، والطالبات يتكلّمن العربية. وإن لم يفهمها ضاد، فلا فائدة منه».\n\nثم أضافت جملة غيّرت الأسابيع القادمة كلّها: «وأنتِ يا ليان، أنتِ من ستعلّمينه».\n\nنظرت ليان إلى الروبوت. كانت عيناه الزرقاوان تحدّقان فيها بلا معنى، كأنّه ينتظر درسه الأوّل. وشعرت لأوّل مرّة بشيء يشبه الورطة."}, {"title": "دروس في الفوضى", "text": "في اليوم الأوّل من «التعليم»، أعدّت ليان قائمة بالكلمات التي قد تقولها الطالبات في المكتبة: كتاب، قصّة، رواية، رفّ، أين، أريد. ظنّت أنّ المهمّة ستنتهي في ساعة.\n\nبعد ساعة، كانت قد سجّلت في دفترها أربع كوارث.\n\nالكارثة الأولى: قالت رهف: «يا ضاد، أريد الكتب الجديدة». فأجاب: «من كتب؟ لا أعرف الكاتب». لقد قرأ «الكتب» على أنّها فعل «كَتَبَ».\n\nالكارثة الثانية: طلبت جود منه أن يذهب إلى المكتبة، فتحرّك بعجلاته خارج المختبر، وعبر الممرّ، ودخل بكلّ ثقة إلى مكتب مديرة المدرسة، ووقف أمامها وقال: «وصلت إلى المكتبة. ما الكتاب الذي تريدينه؟». لقد خلط بين «مكتب» و«مكتبة» لأنّهما من الجذر نفسه. ولحسن الحظّ، كانت المديرة تملك حسّ دعابة.\n\nالكارثة الثالثة: حين انتهت إحدى الطالبات من تجربته، قالت له بلطف: «يعطيك العافية». فسكت ضاد طويلًا، ثم قال بقلق: «هل أنا مريض؟ يرجى فحص البطارية».\n\nأمّا الكارثة الرابعة، فكانت الأغرب. سألته ليان: «ابحث عن كتاب فيه عين». فبدأ يعدّد: «عين الإنسان، عين الماء، عين القوم أي سيّدهم، عين الشيء أي ذاته، العين الجارية...»، ولم يتوقّف إلّا حين نزعت رهف السلك.\n\nجلست ليان على طاولة المختبر، ووضعت رأسها بين يديها. «هذه اللغة مجنونة. كلمة واحدة لها عشرة معانٍ، وكلمات مختلفة تبدو متشابهة، والحركات تغيّر كلّ شيء، ونحن نتكلّم في البيت بلهجة وفي الكتب بلغة أخرى!».\n\nقالت جود وهي تصلح عجلة ضاد: «ربّما لهذا هي جميلة».\n\n«جميلة؟ إنّها متاهة!».\n\nفي تلك الليلة، فتحت ليان حاسوبها لتبحث عن حلّ تقنيّ سريع، شيء يجعل ضاد يفهم من دون أن تضطرّ إلى دراسة النحو من جديد. لكنّها، من دون أن تقصد، وجدت نفسها تقرأ مقالًا عن الجذور في اللغة العربية.\n\nقرأت أنّ ثلاثة أحرف فقط، الكاف والتاء والباء، تلد عائلة كاملة: كَتَبَ، وكاتب، ومكتوب، وكتاب، ومكتبة، ومكتب، وكتيبة. وكلّها تدور حول معنى واحد: الجمع والضمّ والتدوين.\n\nتوقّفت ليان عن القراءة. ثم أمسكت قلمها، ورسمت في دفترها شجرة صغيرة، جذعها ثلاثة أحرف، وأغصانها كلمات.\n\nوابتسمت للمرّة الأولى منذ أيّام، لأنّها فهمت فجأة كيف ستعلّم ضاد."}, {"title": "شجرة الجذور", "text": "في صباح اليوم التالي، دخلت ليان المختبر وفي يدها لفافة ورق كبيرة. فرشتها على الطاولة أمام رهف وجود، فظهرت عشرات الأشجار المرسومة بأقلام ملوّنة.\n\nقالت بحماس لم تعرفه صاحبتاها فيها من قبل: «انظرا. بدل أن نعلّم ضاد آلاف الكلمات منفصلة، نعلّمه الجذور. كلّ جذر شجرة، وكلّ كلمة غصن. وحين يسمع كلمة، يبحث أوّلًا عن جذرها، ثم ينظر إلى الكلمات التي حولها في الجملة ليعرف أيّ غصن هو المقصود».\n\nنظرت رهف إلى الرسوم طويلًا، ثم قالت: «هذا... هذا ممكن برمجيًّا. يمكن أن نصنع له قاعدة بيانات بالجذور والأوزان».\n\n«الأوزان؟».\n\n«نعم! فاعل، مفعول، مِفعَلة... كلّ وزن يضيف معنى. «مكتبة» على وزن «مَفْعَلة»، وهو وزن يدلّ على المكان الذي يكثر فيه الشيء، مثل «مَدرسة» و«مَزرعة». أمّا «مكتب» فهو مكان الكتابة. إذا فهم ضاد الوزن، لن يدخل مكتب المديرة مرّة أخرى».\n\nضحكت جود: «المديرة ستحزن، فقد أحبّت زيارته».\n\nبدأ العمل. كانت ليان تقضي فسحتها في المكتبة الحقيقية، تفتح المعاجم القديمة التي لم تلمسها من قبل، وتكتشف أشياء صغيرة مدهشة: أنّ «الهاتف» في الأصل من يُسمع صوته ولا يُرى شخصه، وأنّ «السيّارة» وردت في القرآن الكريم بمعنى القافلة، وأنّ في العربية أسماء كثيرة للجمل ولكلّ مرحلة من عمره.\n\nوكانت تعود إلى المختبر محمّلة بالقواعد، فتحوّلها رهف إلى أوامر برمجية، وتختبرها جود على ضاد.\n\nلم يكن الأمر سهلًا. ففي يوم، علّمته الفرق بين «عَلَم» و«عِلْم»، فصار يسأل عن الحركات في كلّ جملة يسمعها. وفي يوم آخر، علّمته بعض الكلمات العامّية الشائعة مثل «وين» و«أبغى»، فصار يردّ بالعامية على الجميع، حتى على الأستاذة سميرة.\n\nلكنّه كان يتحسّن. بدأ يفهم الجمل القصيرة، ثم الطويلة. وصار حين يسمع «أين ذهب الكتاب؟» يرفع ذراعه نحو الرفّ الصحيح.\n\nوذات مساء، بينما كانت ليان تراجع درسًا مع أختها الصغيرة في البيت، صحّحت لها خطأً نحويًّا، وشرحت لها السبب. رفعت أختها حاجبيها مندهشة: «منذ متى تحبّين النحو؟».\n\nلم تجد ليان جوابًا.\n\nقبل المسابقة بأسبوع، وصلت رسالة إلى الأستاذة سميرة: «في الجولة النهائية، ستوجّه لجنة التحكيم إلى كلّ روبوت سؤالًا مفاجئًا لم يُدرَّب عليه».\n\nشحب وجه رهف. «سؤال مفاجئ؟ إذا أخطأ ضاد، سنخسر كلّ شيء»."}, {"title": "السؤال المفاجئ", "text": "كانت القاعة في مسقط مكتظّة بالطلّاب والمعلّمين وأولياء الأمور. على المنصّة، وقفت روبوتات من مدارس من محافظات مختلفة: روبوت يسقي النباتات، وآخر يفرز النفايات، وثالث يرشد الزوّار في الممرّات. وبينها وقف ضاد، بغطاء رأسه الفضّي الذي لمّعته جود صباحًا حتّى صار يعكس الأضواء.\n\nكانت ليان تشعر بقلبها يقفز في حلقها. رأت أمّها وأباها في الصفوف الخلفية، ورأت الأستاذة سميرة تبتسم لها ابتسامة مطمئنة، فحاولت أن تبتسم بدورها. كان ضاد قد سافر معهنّ في صندوق مبطّن بالإسفنج، وظلّت جود طوال الطريق تفتح الغطاء كلّ ربع ساعة لتطمئنّ عليه، كأنّه أخ صغير مريض.\n\nقدّمت رهف المشروع، وشرحت جود تصميم الجسم، ثم تقدّمت ليان لتتحدّث عن «شجرة الجذور». تكلّمت بصوت ثابت أدهشها هي نفسها، وحين انتهت، رأت أحد المحكّمين يدوّن شيئًا ويهزّ رأسه.\n\nثم جاءت اللحظة.\n\nنهضت محكّمة كبيرة في السنّ، بنظّارة رفيعة وابتسامة ماكرة، وقالت موجّهة كلامها إلى ضاد: «أريد كتابًا عن العين».\n\nشهقت رهف بصوت مسموع. كانت هذه الكلمة نفسها التي أوقعت ضاد في متاهة المعاني من قبل. أمسكت جود يد ليان بقوّة، وتمتمت: «يا ربّ».\n\nأضاءت عينا ضاد. طنّ. دار رأسه نصف دورة. ثم سكت.\n\nثانية. ثانيتان. ثلاث.\n\nكان الصمت في القاعة ثقيلًا. وفكّرت ليان: لقد انهار. سيبدأ الآن بتعداد معاني العين حتى ينطفئ.\n\nلكنّ ضاد رفع رأسه نحو المحكّمة، وقال بصوته المعدني الهادئ:\n\n«كلمة العين لها معانٍ كثيرة في اللغة العربية. هل تقصدين عين الإنسان التي نرى بها، فأدلّك على كتب العلوم والصحّة؟ أم عين الماء التي تخرج من الأرض، فأدلّك على كتب الجغرافيا؟ أم تقصدين شيئًا آخر؟».\n\nساد الصمت لحظة أخرى. ثم ضحكت المحكّمة ضحكة عالية، وصفّقت. وانفجرت القاعة بالتصفيق.\n\nقالت المحكّمة في الميكروفون: «لقد طرحت هذا السؤال على كلّ الروبوتات في المسابقة. بعضها اختار معنى عشوائيًّا، وبعضها لم يفهم شيئًا. هذا الروبوت الوحيد الذي عرف أنّه لا يعرف، فسأل. وهذا يا بناتي، أوّل درس في الفهم».\n\nنظرت ليان إلى رهف وجود. كانت عيونهنّ تلمع بالدموع.\n\nلم تكن تعرف أنّ هذا السؤال كان أصغر مفاجآت ذلك اليوم."}, {"title": "اللغة التي تعلّمتها ليان", "text": "لم يفز ضاد بالمركز الأوّل. فاز به روبوت فرز النفايات، وكان يستحقّه؛ فقد كان دقيقًا وسريعًا، وصفّقت له الفتيات الثلاث من قلوبهنّ. قالت جود وهي تحاول أن تخفي خيبتها: «على الأقلّ لم يدخل ضاد مكتب أحد هنا». فضحكن، وخفّ شيء من الثقل في صدورهنّ.\n\nلكن حين أعلن مقدّم الحفل الجوائز الخاصّة، قال: «جائزة الابتكار اللغوي تذهب إلى فريق ضاد، لأنّه أثبت أنّ الآلة يمكن أن تفهم العربية حين نفهمها نحن أوّلًا».\n\nصعدت الفتيات الثلاث إلى المنصّة، وجود تدفع ضاد أمامها. وحين أمسكت ليان بالدرع، اقتربت منها المحكّمة ذات النظّارة الرفيعة، وقالت لها بصوت منخفض: «من صاحبة فكرة الجذور؟».\n\n«أنا».\n\n«إذن أنتِ لم تعلّمي الروبوت فقط. أنتِ تعلّمتِ معه».\n\nفي الحافلة في طريق العودة، كانت رهف تخطّط لتطوير ضاد في السنة القادمة، وجود تتحدّث عن جسم جديد بعجلات أفضل. أمّا ليان، فكانت تنظر من النافذة إلى لوحات الطريق التي تمرّ بسرعة: أسماء القرى والولايات، وعبارات الترحيب، وتحذيرات المرور. وجدت نفسها، دون أن تقصد، تفكّك كلّ كلمة إلى جذرها: «مَخْرَج» من الخروج، «مَطار» من الطيران، «مُنعطَف» من الانعطاف.\n\nضحكت بصوت خافت. قبل شهرين، كانت هذه الكلمات مجرّد علامات لا تراها. أمّا الآن، فكلّ كلمة صارت شجرة صغيرة لها جذور وأغصان وحكاية.\n\nفي الأسبوع التالي، ظهر اسمها في قائمة المنضمّات إلى جماعة اللغة العربية في المدرسة. رفعت معلّمة العربية حاجبيها دهشة حين رأته، فهي تذكر جيّدًا الطالبة التي كانت تتأفّف في كلّ درس نحو.\n\nقالت ليان حين سألتها: «اكتشفت أنّ لغتنا ليست متاهة يا أستاذة. هي خريطة. كنت فقط لا أعرف كيف أقرؤها».\n\nوفي المختبر، في زاوية قرب النافذة، صار ضاد يقف على طاولة صغيرة، يرحّب بالطالبات كلّ صباح. وكانت ليان قد أضافت إليه ميزة أخيرة، لم تخبر بها أحدًا غير صاحبتيها.\n\nكلّ يوم، يختار ضاد كلمة عربية واحدة، ويعرض على شاشته الصغيرة جذرها وأغصانها، وتحتها عبارة ثابتة كتبتها ليان بنفسها:\n\n«كلمة اليوم. تعلّمتها من صديقة علّمتني لغتها، فأحبّتها أكثر».\n\nوفي أوّل يوم، كانت الكلمة: «ضاد»."}], "vocab": [{"w": "رَتِيب", "m": "على وتيرة واحدة لا يتغيّر"}, {"w": "وَرْطَة", "m": "موقف صعب يصعب الخروج منه"}, {"w": "الجَذْر", "m": "أصل الكلمة من حروفها الأصلية الثلاثة غالبًا"}, {"w": "مُكْتَظَّة", "m": "ممتلئة بالناس حتّى الازدحام"}, {"w": "مَاكِرَة", "m": "فيها دهاء وخفاء في التدبير"}, {"w": "تَتَأَفَّف", "m": "تُظهر الضجر والانزعاج بالصوت"}, {"w": "المُحَكِّمَة", "m": "عضوة لجنة التحكيم التي تقيّم المتسابقين"}], "quiz": [{"q": "لماذا أجاب ضاد عن سؤال «أين ذهب كتاب العلوم؟» بالحديث عن المعدن؟", "opts": ["لأنّ رهف برمجته على الكيمياء", "لأنّه قرأ «ذهب» بلا حركات ففهمها اسم المعدن", "لأنّ جود أخطأت في نطق السؤال"], "a": 1, "explain": "شرحت رهف أنّ ضاد يقرأ الكلمات بلا حركات، فاحتملت «ذهب» الفعل والمعدن، فاختار المعدن."}, {"q": "ما الفكرة التي اقترحتها ليان لتعليم ضاد العربية؟", "opts": ["ترجمة كلّ الكتب إلى الإنجليزية", "تعليمه آلاف الكلمات منفصلة", "تعليمه الجذور والأوزان ثم فهم الكلمة من سياق الجملة"], "a": 2, "explain": "رسمت ليان «شجرة الجذور»: كلّ جذر شجرة وكلّ كلمة غصن، ويستعين ضاد بالسياق ليعرف المعنى المقصود."}, {"q": "لماذا أُعجبت المحكّمة بإجابة ضاد عن سؤال «العين»؟", "opts": ["لأنّه أدرك تعدّد المعاني فسأل ليتأكّد بدل أن يخمّن", "لأنّه عدّد كلّ معاني العين بسرعة", "لأنّه أحضر الكتاب الصحيح فورًا"], "a": 0, "explain": "قالت المحكّمة إنّه الروبوت الوحيد الذي عرف أنّه لا يعرف، فسأل عن المعنى المقصود."}, {"q": "ما الجائزة التي حصل عليها فريق ضاد؟", "opts": ["المركز الأوّل في المسابقة", "جائزة الابتكار اللغوي", "جائزة أفضل تصميم"], "a": 1, "explain": "فاز روبوت فرز النفايات بالمركز الأوّل، ونال فريق ضاد جائزة الابتكار اللغوي."}], "discuss": ["قالت ليان في النهاية إنّ العربية «خريطة» لا «متاهة». ما الذي غيّر نظرتها؟ وهل مررتِ بتجربة غيّرت نظرتك إلى مادّة دراسية؟", "قالت المحكّمة: «عرف أنّه لا يعرف، فسأل». لماذا يُعدّ السؤال أحيانًا دليل ذكاء لا دليل ضعف؟", "اختاري كلمة عربية تحبّينها، وارسمي شجرة جذرها. ما أغرب غصن اكتشفتِه فيها؟"]}, {"id": "n5", "title": "رسائل لم تُرسَل", "genre": "صداقة", "blurb": "منذ انتقلت نوف من مسقط إلى صلالة، كتبت لصديقتها عائشة عشرات الرسائل، ولم ترسل واحدة منها. فماذا لو كانت عائشة قد نسيتها؟ وماذا لو وصلت رسالة واحدة، أصدق الرسائل كلّها، من دون أن تقرّر نوف إرسالها؟", "values": ["الصراحة في التعبير عن المشاعر", "الوفاء في الصداقة", "الانفتاح على صداقات جديدة"], "chapters": [{"title": "الرسالة الأولى", "text": "«عزيزتي عائشة،\n\nوصلنا اليوم إلى صلالة بعد اثنتي عشرة ساعة في السيّارة. لن تصدّقي ما رأيت: صحراء طويلة لا تنتهي، رمل ثم رمل ثم رمل، وحمد يسأل كلّ عشر دقائق: هل وصلنا؟ ثم فجأة، بعد ثمريت، بدأت الجبال، ونزلنا منها إلى عالم آخر. ضباب يا عائشة! ضباب حقيقي في شهر يونيو! ومطر خفيف كأنّه رشّاش عطر، وأشجار خضراء على سفوح الجبال، وجمال تمشي على الطريق كأنّها تملكه.\n\nاشتقت إليك. أشتاق إليك منذ لحظة الوداع في الموالح.\n\nصديقتك، نوف».\n\nطوت نوف الورقة مرّتين، ووضعتها في ظرف أبيض، وكتبت عليه بخطّها المستدير: «إلى عائشة». ثم نظرت إليه طويلًا.\n\nلم تضعه في حقيبة البريد. فتحت الصندوق الكرتوني الصغير الذي خبّأته تحت سريرها في غرفتها الجديدة، ووضعت الظرف فيه، وأغلقت الغطاء.\n\nكانت تعرف أنّ هذا غريب. يمكنها أن ترسل لعائشة رسالة على الهاتف في ثانية واحدة. لكنّ شيئًا ما كان يوقفها كلّ مرّة. ففي اليوم الذي غادرت فيه مسقط، رأت على حالة عائشة صورة لها مع بنات الصفّ، يضحكن في مقهى على الشاطئ. صورة عادية، لكنّها انغرست في صدر نوف كشوكة صغيرة.\n\nقالت لنفسها: لديها صديقات كثيرات. ستنساني في أسبوع. وإن أرسلت لها رسالة طويلة عن الضباب والجمال، فقد تقرؤها بعد يومين، وتردّ بكلمة واحدة: «جميل». وأنا لا أحتمل كلمة «جميل» واحدة.\n\nكانت عائشة صديقتها منذ الصفّ الأوّل. جلستا على المقعد نفسه تسع سنوات، وتقاسمتا السندويشات والأسرار والدفاتر. وكانت نوف تخشى أن يتحوّل كلّ ذلك فجأة إلى ذكرى قديمة لا يتذكّرها أحد غيرها.\n\nفي الأيّام التالية، صارت تكتب كلّ ليلة تقريبًا. عن البيت الجديد ذي النوافذ الواسعة، عن رائحة الأرض المبلّلة صباحًا، عن البائع الذي يقطع جوز الهند بالساطور على جانب الطريق، ويناولها إيّاه مثقوبًا وفيه قصبة شرب. كانت تكتب، وتطوي، وتضع الظرف في الصندوق.\n\nبعد شهر، عدّت الرسائل: سبع عشرة رسالة.\n\nوفي الليلة نفسها، اهتزّ هاتفها. رسالة من عائشة، الأولى منذ أسبوعين: «كيف حالك يا نوف؟».\n\nحدّقت نوف في الكلمات الثلاث. ثلاث كلمات فقط، بعد شهر كامل.\n\nكتبت «بخير»، وضغطت إرسال، ثم أطفأت الهاتف، وأخرجت ورقة جديدة."}, {"title": "مدينة تحت الضباب", "text": "في صلالة، كان الخريف يغطّي كلّ شيء. ليس الخريف الذي تعرفه نوف من الكتب، حيث تتساقط أوراق الشجر، بل خريف ظفار: ضباب كثيف ينزل من الجبال كلّ صباح، ورذاذ لا يتوقّف، وعشب ينبت في كلّ شقّ من الأرض، حتى على أسطح البيوت.\n\nكانت جارتهم أمّ غدير امرأة كريمة، أوّل من طرق بابهم بعد وصولهم، تحمل صحنًا من الحلوى وكيسًا صغيرًا من اللبان. قالت لأمّ نوف: «هذا لبان الحوجري، أجود أنواع اللبان. ضعيه على الجمر، وسيعرف البيت أنّكم من أهله».\n\nوبعد أيّام، جاءت ابنتها غدير. كانت في عمر نوف تقريبًا، ضاحكة الوجه، تتكلّم بسرعة، وتعرف كلّ شيء عن المدينة. قالت: «لا يمكن أن تعيشي في صلالة ولا تعرفي عين رزات، ولا المغسيل، ولا بستان الموز عند جدّي. غدًا سآخذك».\n\nترددت نوف. شعرت كأنّ قبول صداقة غدير خيانة صغيرة لعائشة. لكنّ غدير لم تترك لها خيارًا.\n\nفي الأسابيع التالية، أخذتها غدير إلى عين رزات، حيث يخرج الماء صافيًا بين الصخور، وإلى شاطئ المغسيل، حيث يقذف البحر الماء من فتحات في الصخر إلى الأعلى كنوافير عملاقة، فتصرخ نوف وتضحك كلّما بلّلها الرذاذ. وعلّمتها كلمات من اللهجة الظفارية، وأطعمتها الموز الصغير الحلو من بستان جدّها.\n\nوكانت نوف تعود كلّ مساء، وتكتب لعائشة عن كلّ ذلك. «اليوم ذهبت إلى المغسيل. كان الماء يقفز من الصخر كأنّه حوت يتنفّس. تمنّيت أن تكوني هنا». ثم تطوي الرسالة، وتضعها في الصندوق.\n\nوفي يوم، التقطت غدير صورة لهما معًا تحت المطر، والضباب يلفّ الجبل خلفهما، فوضعتها نوف على حالتها. كانت أوّل صورة تنشرها منذ انتقالها.\n\nفي تلك الليلة، رأت أنّ عائشة شاهدت الصورة. ولم تعلّق بشيء.\n\nازداد الثقل في صدر نوف. كتبت الرسالة الخامسة والعشرين، وكانت أصدق رسالة كتبتها، وأقصرها:\n\n«عزيزتي عائشة، أخاف أنّك نسيتني. وأخاف أكثر أن أسألك فتقولي نعم».\n\nلم تضعها في الظرف هذه المرّة. تركتها مفتوحة على المكتب، وخرجت لتتوضّأ لصلاة العشاء.\n\nوحين عادت، كان الباب مواربًا، وكان أخوها الصغير حمد يخرج من غرفتها مسرعًا، وفي عينيه نظرة من يخفي شيئًا."}, {"title": "ساعي البريد الصغير", "text": "«حمد! ماذا كنت تفعل في غرفتي؟».\n\n«لا شيء! كنت أبحث عن شاحن الهاتف».\n\nنظرت نوف إلى المكتب. كانت الأوراق والأقلام في مكانها، فظنّت أنّه صادق، ونسيت الأمر.\n\nبعد يومين، كانت أمّها تجهّز صندوقًا كبيرًا في الصالة: لبان حوجري، ومبخرة فخارية ظفارية ملوّنة، وعلبة من الحلوى، وأكياس من جوز الهند المجفّف. قالت وهي تلصق الشريط: «هديّة لأمّ عائشة. لقد وقفت معنا وقفة لا تُنسى أيّام الانتقال، ولا بدّ أن أردّ لها شيئًا من جميلها».\n\nكان حمد يساعدها بحماس غير معتاد، يرتّب الأكياس داخل الصندوق، ويصرّ على أن يضع آخر شيء فيه بنفسه.\n\nفي المساء، حين جلست نوف لتكتب رسالة جديدة، بحثت عن الرسالة الخامسة والعشرين لتضعها في الصندوق مع أخواتها. لم تجدها. قلبت المكتب، والأدراج، وتحت السرير.\n\nثم فهمت.\n\nركضت إلى غرفة حمد. كان جالسًا على سريره يلعب، فرفع رأسه وابتسم ابتسامة بريئة جدًّا.\n\n«حمد. أين الورقة التي كانت على مكتبي؟».\n\nتردّد قليلًا، ثم قال بفخر: «أرسلتها! وضعتها في صندوق الهدايا لعائشة. أنتِ تكتبين لها كلّ ليلة ولا ترسلين شيئًا، وأمّي قالت إنّ الرسائل يجب أن تصل. فساعدتك».\n\nشعرت نوف بالأرض تميد تحت قدميها. الرسالة الأصدق. الرسالة الأضعف. الرسالة التي كانت تقول فيها كلّ ما تخاف منه. أصبحت الآن في طريقها إلى مسقط، داخل صندوق مليء باللبان.\n\nقضت الأيّام التالية في عذاب. كانت تفتح هاتفها كلّ ساعة. وصل الصندوق، وأرسلت أمّ عائشة رسالة شكر طويلة لأمّها، فيها قلوب وورود. أمّا عائشة، فلا شيء. يوم. يومان. أربعة أيّام.\n\nقالت نوف لنفسها وهي تحاول ألّا تبكي: لقد قرأتها، وضحكت عليّ، وقرّرت ألّا تردّ. هذا هو الجواب.\n\nوكانت غدير تلاحظ شرودها، فتسألها: «ما بك؟»، فتقول نوف: «لا شيء»، وتنظر إلى الضباب كأنّها تبحث فيه عن جواب لا يأتي.\n\nوفي اليوم السادس، دخلت أمّها غرفتها والهاتف في يدها، وقالت بسعادة: «خبر جميل! عائلة عائشة قادمة إلى صلالة الأسبوع القادم ليقضوا أيّام الخريف. وأمّ عائشة تقول إنّ عائشة طلبت شيئًا واحدًا: أن تلتقي بكِ في وادي دربات، وحدكما».\n\nلم تعرف نوف أتفرح أم تخاف."}, {"title": "شلّالات دربات", "text": "كان وادي دربات في الخريف أجمل من أيّ صورة رأتها نوف من قبل. الجبال مكسوّة بالأخضر حتى قممها، والشلّالات تنحدر بيضاء من الصخور العالية، والماء يتجمّع في بحيرة هادئة يحيط بها العشب، والأبقار ترعى على ضفّتها في الضباب كأنّها في حلم.\n\nوقفت نوف قرب السور الخشبي، تراقب الطريق، ويداها باردتان رغم الجوّ المعتدل. كانت أمّها وأمّ عائشة جالستين بعيدًا تحت مظلّة، تشربان الشاي بالحليب وتتحدّثان، وحمد يركض حولهما. كانت نوف قد قضت الليلة الماضية تتدرّب على ما ستقوله: اعتذارًا، ثم شرحًا، ثم مزحة صغيرة تكسر الجليد. لكنّ كلّ الجمل تبخّرت الآن من رأسها كالضباب.\n\nثم رأتها.\n\nكانت عائشة تمشي نحوها ببطء، بالعباءة الكحلية نفسها التي كانت ترتديها في المدرسة، وفي يدها حقيبة قماشية. توقّفت على بعد خطوتين.\n\nلم تقل أيّ منهما شيئًا. كان صوت الشلّال يملأ الفراغ. لاحظت نوف أنّ عائشة صارت أطول قليلًا، وأنّ في معصمها سوارًا لم تره من قبل. شهران فقط، لكنّهما كافيان ليتغيّر شيء صغير في الإنسان. وتساءلت: هل تغيّر فيها شيء أكبر لا يُرى؟\n\nثم قالت عائشة بصوت خافت: «وصلتني رسالتك».\n\nاحمرّ وجه نوف حتى أذنيها. «لم أكن أنوي إرسالها. حمد هو...».\n\n«أعرف. أمّك أخبرت أمّي». ثم سكتت، وفتحت حقيبتها القماشية، وأخرجت منها رزمة سميكة من الأوراق، مربوطة بشريط أزرق، وناولتها لنوف.\n\n«ما هذه؟».\n\n«افتحيها».\n\nفكّت نوف الشريط. كانت ظروفًا، كثيرة جدًّا، كلّ ظرف عليه بخطّ عائشة المائل: «إلى نوف». وعلى كلّ ظرف تاريخ.\n\nهمست نوف: «كم واحدة؟».\n\n«ثلاث وعشرون. كتبتها منذ يوم سفرك. ولم أرسل واحدة».\n\nرفعت نوف عينيها إليها، مذهولة. «لماذا؟».\n\nنظرت عائشة إلى الشلّال، وقالت: «لأنّك منذ وصلتِ لم تكتبي لي إلّا «بخير». ثم رأيت صورتك مع تلك الفتاة تحت المطر، وأنتِ تضحكين ضحكة لم أرها منذ زمن. فقلت: لقد وجدت صديقة جديدة في مدينة جديدة، ولم تعد بحاجة إليّ. وإن أرسلت لها رسائلي، ستقرؤها وتقول: جميل».\n\nلم تستطع نوف أن تتكلّم. كانت الكلمة نفسها، الكلمة التي خافت منها هي أيضًا.\n\nفتحت الظرف الأوّل بأصابع مرتجفة. كان مؤرّخًا بيوم سفرها نفسه. وأوّل سطر فيه:\n\n«عزيزتي نوف، أخاف أنّك ستنسينني»."}, {"title": "رسائل أُرسلت أخيرًا", "text": "جلست الصديقتان على صخرة مسطّحة قرب البحيرة، والظروف بينهما، كومة لنوف وكومة لعائشة. فقد ركضت نوف إلى السيّارة وأحضرت صندوقها الكرتوني، الذي كانت قد وضعته في حقيبتها في اللحظة الأخيرة دون أن تعرف لماذا.\n\nقالت عائشة: «نقرأ بالتناوب. رسالة منك، ورسالة منّي، بحسب التاريخ».\n\nقرأتا. وكان الأمر غريبًا ومضحكًا ومؤلمًا في آن واحد.\n\nفي اليوم الذي كتبت فيه نوف عن الضباب الأوّل، كتبت عائشة عن مقعد نوف الفارغ في الصفّ، وكيف رفضت أن يجلس فيه أحد. وفي اليوم الذي كتبت فيه نوف عن جوز الهند، كتبت عائشة عن صورة المقهى: «خرجت مع البنات لأنّهنّ أصررن، لكنّي لم أضحك إلّا للكاميرا. كان المكان ناقصًا». وفي اليوم الذي كتبت فيه نوف رسالتها الخامسة والعشرين الخائفة، كتبت عائشة رسالتها الحادية والعشرين، وفيها جملة واحدة: «لماذا لا أرسل هذه الرسائل؟ لأنّي جبانة يا نوف».\n\nضحكت نوف حتى دمعت عيناها، وبكت عائشة حتى ضحكت.\n\nقالت عائشة وهي تمسح وجهها بكمّ عباءتها: «كم كنّا غبيّتين. شهران كاملان، وكلّ واحدة منّا تكتب للأخرى، وتخاف منها».\n\nقالت نوف: «لم نكن غبيّتين. كنّا خائفتين. والخوف يجعلنا نصمت حين نريد أن نتكلّم أكثر».\n\nفي تلك اللحظة، ظهرت غدير على الطريق، تحمل كيسًا من الذرة المشويّة، فقد كانت قد وعدت نوف أن تمرّ. توقّفت حين رأتهما، وقالت بتردّد: «أعتذر، هل أزعجتكما؟».\n\nنظرت نوف إلى عائشة. وابتسمت عائشة، ومدّت يدها: «أنتِ غدير؟ أنا عائشة. نوف كتبت عنك في سبع رسائل».\n\nضحكت غدير، وجلست معهما، ووزّعت الذرة. وفي الساعة التالية، كانت الثلاث يتبادلن الحكايات عن مسقط وصلالة كأنّهنّ يعرفن بعضهنّ منذ سنوات.\n\nقبل أن تعود عائشة إلى مسقط بأيّام، اتّفقت الصديقتان على قاعدة واحدة، كتبتاها على ورقة ووقّعتا عليها كعقد رسمي: «لا رسائل غير مرسلة بعد اليوم. إذا خفنا، نرسلها أوّلًا، ثم نخاف».\n\nوبعد أسبوع من عودة عائشة، ذهبت نوف إلى مكتب البريد في صلالة لأوّل مرّة في حياتها. اشترت طابعًا، وألصقته على ظرف أبيض، وكتبت عليه عنوان عائشة في مسقط.\n\nكانت الرسالة قصيرة:\n\n«عزيزتي عائشة، هذه أوّل رسالة أرسلها حقًّا. الضباب ما زال هنا، وأنا ما زلت أشتاق إليك. لكنّي لم أعد أخاف».\n\nوأسقطت الظرف في الصندوق، ولم تنظر خلفها."}], "vocab": [{"w": "رَذَاذ", "m": "مطر خفيف ناعم القطرات"}, {"w": "اللُّبَان", "m": "صمغ شجرة تُعرف بها ظفار، يُحرق بخورًا"}, {"w": "السَّاطُور", "m": "سكّين كبيرة عريضة تُقطع بها الأشياء الصلبة"}, {"w": "مُوَارَبًا", "m": "مفتوحًا قليلًا غير مغلق تمامًا"}, {"w": "تَمِيد", "m": "تتحرّك وتضطرب"}, {"w": "رِزْمَة", "m": "مجموعة من الأوراق مضمومة بعضها إلى بعض"}, {"w": "بِالتَّنَاوُب", "m": "واحدة بعد الأخرى بالدور"}], "quiz": [{"q": "لماذا لم ترسل نوف رسائلها إلى عائشة؟", "opts": ["لأنّها لا تعرف عنوان عائشة", "لأنّها خافت أن تكون عائشة قد نسيتها مع صديقاتها الجديدات", "لأنّ أمّها منعتها من ذلك"], "a": 1, "explain": "رأت نوف صورة عائشة مع بنات الصفّ، فظنّت أنّها ستنساها، وخافت أن تردّ على رسائلها بكلمة باردة."}, {"q": "كيف وصلت الرسالة الخامسة والعشرون إلى عائشة؟", "opts": ["أرسلتها نوف بالبريد", "سلّمتها غدير لعائشة", "وضعها حمد في صندوق الهدايا المرسل إلى أمّ عائشة"], "a": 2, "explain": "رأى حمد أنّ أخته تكتب ولا ترسل، فوضع الرسالة في صندوق الهدايا ظنًّا أنّه يساعدها."}, {"q": "ماذا اكتشفت نوف عند شلّالات دربات؟", "opts": ["أنّ عائشة كانت تكتب لها رسائل ولا ترسلها أيضًا", "أنّ عائشة غاضبة منها بسبب غدير", "أنّ عائشة ستنتقل إلى صلالة"], "a": 0, "explain": "أعطتها عائشة ثلاثًا وعشرين رسالة كتبتها منذ يوم السفر ولم ترسلها خوفًا من الشيء نفسه."}, {"q": "ما القاعدة التي اتّفقت عليها الصديقتان في النهاية؟", "opts": ["ألّا تكتبا رسائل ورقية مرّة أخرى", "أن ترسلا الرسالة أوّلًا حتى لو خافتا", "أن تلتقيا كلّ خريف في دربات"], "a": 1, "explain": "كتبتا عقدًا: «لا رسائل غير مرسلة بعد اليوم. إذا خفنا، نرسلها أوّلًا، ثم نخاف»."}], "discuss": ["قالت نوف: «الخوف يجعلنا نصمت حين نريد أن نتكلّم أكثر». هل حدث أن صمتِّ عن شيء مهمّ خوفًا من ردّ الطرف الآخر؟", "هل كان تصرّف حمد صحيحًا حين أرسل رسالة أخته دون إذنها؟ كيف كنتِ ستتصرّفين لو كنتِ مكان نوف؟", "هل يمكن أن نكسب صديقة جديدة دون أن نخسر صديقة قديمة؟ كيف تعاملت نوف وعائشة مع غدير؟"]}, {"id": "n6", "title": "حارسة السلاحف", "genre": "بيئة", "blurb": "في ليالي رأس الجنز، تتعلّم شيماء أن وميضًا واحدًا قد يُفسد رحلةً بدأت في عرض المحيط. فهل تستطيع فتاةٌ في الخامسة عشرة أن تغيّر عادات زوّارٍ لا يسمعون التحذيرات؟", "values": ["احترام الطبيعة", "الإقناع باللطف", "المبادرة والمسؤولية"], "chapters": [{"title": "ضوءٌ أحمر في العتمة", "text": "لم تكن شيماء تعرف أن البحر يتنفّس، حتى وقفت تلك الليلة على شاطئ رأس الجنز، وسمعت الموج يعلو ويهبط كصدرِ نائمٍ كبير.\n\nكانت الساعة قد تجاوزت التاسعة، والرمل باردًا تحت قدميها رغم حرّ النهار الذي ما زال عالقًا في الهواء. وإلى جوارها وقفت خالتها نوال، المرشدة البيئية في المحمية، تحمل مصباحًا صغيرًا يرسل ضوءًا أحمرَ خافتًا لا يكاد يُرى.\n\nهمست الخالة: «السلحفاة لا ترى هذا اللون جيدًا، لذلك لا يزعجها. أما الضوء الأبيض فيُربكها، وقد يجعلها تعود إلى البحر دون أن تضع بيضها.»\n\nهزّت شيماء رأسها، وشعرت بشيءٍ من الفخر. فهذه أول ليلة تتطوّع فيها مع خالتها بعد إلحاحٍ دام شهرًا كاملًا. وكانت قد وعدت أمّها في صور أن تحمل دفترها، وأن تكتب فيه كل ما تتعلّمه.\n\nكانت قد سمعت عن السلاحف منذ طفولتها، فأهل صور يتحدثون عنها كما يتحدثون عن جيرانٍ قدامى يزورونهم كل صيف. لكن الحكايات شيء، والليلة شيءٌ آخر: رائحة الملح والطحالب، ونسيمٌ رطب يلفح الوجه، وسماءٌ مزدحمة بالنجوم حتى ظنّت أن أحدًا نثر عليها سكّرًا ناعمًا.\n\nمشى خلفهما نحو عشرين زائرًا في صفٍّ متعرّج، بعضهم يتحدث بصوتٍ منخفض، وبعضهم لا يكفّ عن الضحك. ثم توقّفت الخالة فجأة، ورفعت يدها.\n\nعلى بُعد خطوات، كانت كتلةٌ داكنة ضخمة تتحرك ببطء فوق الرمل: سلحفاةٌ خضراء بحجم طاولةٍ صغيرة، تدفع جسدها الثقيل بزعانفها الأمامية، وتترك وراءها أثرًا عريضًا يشبه أثر عجلات جرّار.\n\nحبست شيماء أنفاسها. رأت السلحفاة تتوقف، ثم تبدأ الحفر بزعانفها الخلفية، بحركةٍ صبورة متقنة، كأنها تعرف ما تفعله منذ آلاف السنين. وكانت عيناها تلمعان بسائلٍ شفاف.\n\n«هل تبكي؟» سألت شيماء.\n\n«إنها تتخلّص من الملح الزائد في جسمها. لكن الناس يحبّون أن يقولوا إنها تبكي.»\n\nوفي تلك اللحظة، انطلق من خلفهما وميضٌ أبيض حادّ، أضاء الشاطئ كله لثانيةٍ واحدة.\n\nتجمّدت السلحفاة في مكانها. وشهق أحد الأطفال، والتفتت الخالة بسرعةٍ نحو مصدر الضوء.\n\nثم سمعت شيماء صوت شابٍّ يقول بمرح: «لحظة، لم تظهر الصورة جيدًا، سأعيدها!»"}, {"title": "عشرون زائرًا ومشكلة واحدة", "text": "لم ترفع الخالة نوال صوتها. اقتربت من الشاب بهدوء، وقالت له بكلماتٍ قليلة إن الوميض يخيف السلحفاة، وإن عليه أن يطفئ الكاميرا حتى نهاية الجولة. احمرّ وجهه قليلًا، وأخفى هاتفه في جيبه، وتمتم بشيءٍ يشبه الاعتذار.\n\nمرّت دقائق طويلة. وقف الجميع في صمتٍ ثقيل، وشيماء تراقب الكتلة الداكنة ولا تجرؤ على الحركة. هل ستعود السلحفاة إلى البحر؟ هل أفسد وميضٌ واحد رحلةً بدأت من مكانٍ بعيد في المحيط؟\n\nثم تحرّكت الزعانف الخلفية من جديد. عادت السلحفاة إلى الحفر، ببطءٍ أشدّ هذه المرة، وبعد وقتٍ بدأت تضع بيضها في الحفرة العميقة: كراتٌ بيضاء لامعة بحجم كرة تنس الطاولة، تسقط واحدةً بعد أخرى.\n\nحاولت شيماء أن تعدّها، ثم توقّفت. شعرت أن في العدّ شيئًا من قلة الاحترام، كأنها تحصي أنفاس أحد. فاكتفت بالنظر، وبالدعاء في سرّها أن يكبر هؤلاء الصغار جميعًا.\n\nهمست الخالة: «قد تضع مئة بيضةٍ أو أكثر. وبعد نحو شهرين يفقس الصغار، ويخرجون ليلًا، ويركضون نحو البحر.»\n\nفي الليالي التالية، بدأت شيماء تملأ دفترها بملاحظاتٍ لم تكن تتوقعها. لم تكن المشكلة في السلاحف، بل في الناس. في الليلة الثانية، ركض طفلان بين الأعشاش وهاتفاهما يضيئان الرمل كالمصابيح الكاشفة. وفي الليلة الثالثة، وجدت قارورتي ماءٍ فارغتين قرب الكثبان. وفي الليلة الرابعة، رأت الشاب نفسه، بقبعته الحمراء، يحاول التقاط صورةٍ من زاويةٍ قريبة جدًا، قبل أن تلمحه الخالة.\n\nفي طريق العودة إلى المركز، سألت شيماء خالتها: «ألا يُغضبك هذا؟»\n\nتنهّدت الخالة: «أقول القواعد نفسها كل ليلة في بداية الجولة: لا ضوء أبيض، ولا تصوير، ولا ضجيج، ولا اقتراب. يهزّون رؤوسهم موافقين، ثم ينسون كل شيء بعد خمس دقائق.»\n\n«ولماذا ينسون؟»\n\n«لأن الناس لا يتذكرون قائمةً من الممنوعات. يتذكرون ما يشعرون به.»\n\nبقيت الجملة تدور في رأس شيماء طوال الطريق، وحتى بعد أن أطفأت نور غرفتها في بيت خالتها. نظرت إلى السقف المظلم، وفكّرت: ماذا لو لم نقل للزوّار ما يجب ألّا يفعلوه... بل أعطيناهم شيئًا يفعلونه؟\n\nجلست فجأةً في سريرها، وأشعلت المصباح الصغير، وفتحت علبة أقلامها."}, {"title": "عهد الحارس", "text": "قضت شيماء صباح اليوم التالي كله على أرض الصالة، بين أوراقٍ ملوّنة ومقصٍّ وممحاةٍ كبيرة. كانت خالتها تمرّ بها بين حينٍ وآخر، فترى أكوام البطاقات تتزايد، دون أن تفهم شيئًا.\n\nعند الظهر، ذهبت مع ابن خالتها إلى دكانٍ صغير في صور، واشترت لفّةً من الورق الشفاف الأحمر الذي تُغلَّف به الهدايا، وكيسًا من الأربطة المطاطية. وفي المساء، عرضت فكرتها على خالتها وقلبها يخفق.\n\nقالت: «بدل أن نقول للزوّار ممنوعاتٍ ينسونها، نجعل كل واحدٍ منهم حارسًا. حارس الضوء يتأكد أن كل مصباحٍ مغطًّى بالورق الأحمر. وحارس الصمت يذكّر من حوله بالهمس. وحرّاس الأثر، وهم الأطفال، يمشون في آثار أقدامك فلا يدوسون على عشٍّ مدفون. وحارس الشاطئ يجمع أي نفايةٍ يراها في طريق العودة.»\n\nثم أخرجت الممحاة التي نحتت عليها بعنايةٍ شكل سلحفاةٍ صغيرة، وغمستها في الحبر، وطبعتها على بطاقةٍ كُتب عليها: «كنتُ حارسًا لسلاحف رأس الجنز».\n\n«وفي نهاية الجولة، يأخذ كل حارسٍ ختمه.»\n\nنظرت الخالة إلى البطاقة طويلًا. «والقصة؟ رأيتُكِ تكتبين شيئًا عن قصة.»\n\nاحمرّ وجه شيماء. «قبل أن نبدأ، أحكي لهم دقيقةً واحدة فقط بلسان السلحفاة: كيف سبحت آلاف الكيلومترات لتعود إلى الشاطئ الذي وُلدت فيه، وكيف تحفر بزعانف لم تُخلق للمشي... أريدهم أن يشعروا بها قبل أن يروها.»\n\nابتسمت الخالة ابتسامةً فيها شكٌّ وفيها إعجاب. «الزوّار يأتون للمتعة يا شيماء، لا لتوزيع المهام. قد يرون الأمر طفوليًا.»\n\n«جرّبيها ليلةً واحدة فقط.»\n\nثم أضافت بسرعة، قبل أن تتراجع شجاعتها: «وإن لم تنجح، أعدكِ ألّا أتكلم في الأمر مرةً أخرى، وأن أكتفي بحمل السلّة.»\n\nصمتت الخالة قليلًا، ثم قالت: «ليلة واحدة.»\n\nفي التاسعة إلا ربعًا، وقفت شيماء أمام مجموعة الليلة، تحمل سلّةً فيها البطاقات وقطع الورق الأحمر، وتحاول أن تمنع ركبتيها من الارتجاف. كانت تعدّ الوجوه بعينيها: أسرةٌ معها ثلاثة أطفال، وسيدتان مسنّتان، ومجموعةٌ من طالبات الجامعة، وزوجان من بلدٍ بعيد...\n\nثم توقّفت عيناها عند آخر الصف.\n\nقبعةٌ حمراء.\n\nكان الشاب نفسه، يحمل هاتفه في يده، ويبتسم كأنه جاء ليصطاد الصورة التي فاتته."}, {"title": "حارس الضوء", "text": "تردّدت شيماء لحظة. كان بإمكانها أن تنبّه خالتها إليه، أو أن تتجاهله وتتمنّى أن يلتزم هذه المرة. لكنها تذكّرت ما قالته الخالة: الناس يتذكرون ما يشعرون به.\n\nبدأت قصتها. قالت بصوتٍ خافت إنها سلحفاةٌ عمرها أكثر من ثلاثين سنة، خرجت من بيضةٍ صغيرة على هذا الشاطئ نفسه، وركضت إلى البحر وهي بحجم كفّ طفل، وعاشت كل تلك السنين في الماء الواسع، ثم عادت الليلة لأن شيئًا في داخلها يعرف الطريق. وحين انتهت، كان الأطفال الثلاثة يحدّقون فيها بأفواهٍ مفتوحة، وإحدى السيدتين تمسح عينيها.\n\nثم وزّعت المهام. وحين وصلت إلى آخر الصف، رفعت قطعة الورق الأحمر نحو الشاب وقالت: «أحتاج إلى حارسٍ للضوء الليلة، ومهمّته أصعب المهام: ألّا يخرج ضوءٌ أبيض واحد من هذه المجموعة. هل تقبلها؟»\n\nنظر إليها بدهشة، ثم ضحك ضحكةً قصيرة. «أنا؟ متأكدة؟»\n\n«متأكدة.»\n\nأخذ الورقة، ولفّها على مصباح هاتفه، وثبّتها بالرباط المطاطي. ثم قال وهو يعدّل قبعته: «اسمي هيثم. وحارس الضوء جاهز.»\n\nما حدث بعد ذلك فاجأ شيماء أكثر مما فاجأ خالتها. فحين نسي أحد الزوجين وأشعل مصباح هاتفه، كان هيثم أول من وصل إليه، فغطّاه بكفّه واعتذر له همسًا بلطف. وحين تعالت ضحكات الطالبات، التفتت إليهن «حارسة الصمت»، وهي أصغر الأطفال، ووضعت إصبعها على شفتيها بجدّيةٍ جعلتهن يكتمن الضحك. ومشى الأطفال في آثار أقدام الخالة كأنهم يمشون على حبلٍ رفيع.\n\nوضعت السلحفاة بيضها في هدوءٍ تام، ثم أهالت عليه الرمل، وزحفت عائدةً نحو الموج، والزوّار يراقبونها صامتين كأنهم في وداع.\n\nفي طريق العودة، رنّ جهاز اللاسلكي في يد الخالة. استمعت لحظة، ثم أشارت إلى الجميع بالانتظار.\n\n«هناك عشٌّ عمره نحو شهرين في الجهة الشمالية. يبدو أن الصغار بدؤوا يخرجون الآن.»\n\nعلت همسات الفرح، لكن وجه الخالة لم يكن فرحًا تمامًا. فعلى الطريق الترابي القريب من تلك الجهة، كانت سيارةٌ متأخرة قد توقّفت للتو، ومصابيحها الأمامية القوية مسلّطة نحو الرمل.\n\nركضت شيماء خلف خالتها، ورأت مشهدًا سيبقى في ذاكرتها طويلًا: عشرات السلاحف الصغيرة، كل واحدةٍ أصغر من الكفّ، تزحف مسرعةً... في الاتجاه الخطأ، نحو الضوء."}, {"title": "الطريق إلى البحر", "text": "«لا أحد يلمسها!» قالت الخالة بصوتٍ حازمٍ لكنه منخفض. «إن حملناها بأيدينا قد نؤذيها، وهي تحتاج إلى أن تمشي الطريق بنفسها. نحتاج فقط إلى أن ينطفئ ذلك الضوء.»\n\nقبل أن تكمل جملتها، كان هيثم قد انطلق. رأته شيماء يركض في الظلام نحو السيارة، ويلوّح بيديه للسائق، ويتحدث إليه بسرعة. ومرّت ثوانٍ بدت كأنها دقائق، ثم انطفأت المصابيح فجأة، وغرق الشاطئ في عتمةٍ رقيقة لا يضيئها إلا القمر وانعكاسه على الماء.\n\nقالت الخالة: «الآن، يقف الجميع ساكنين. لا مصباح، ولا حتى الأحمر.»\n\nوقف عشرون شخصًا كأنهم تماثيل. وفي العتمة، رأت شيماء ما لم تره من قبل: السلاحف الصغيرة تتوقف، وترفع رؤوسها الدقيقة، ثم تستدير ببطء. كانت تبحث عن أكثر الجهات إضاءة، وصارت تلك الجهة هي البحر، حيث يلمع الأفق الباهت تحت ضوء القمر.\n\nثم بدأ السباق. زعانف صغيرة تضرب الرمل بعجلة، وأجسادٌ لا تكاد تُرى تتعثّر وتنهض، وموجةٌ تأتي فتحمل ثلاثًا منها دفعةً واحدة. كان الأطفال يعدّون همسًا، وشيماء تعدّ معهم، حتى وصلوا إلى ثلاثٍ وستين.\n\nحين ابتلع البحر آخرها، صفّق الأطفال بأطراف أصابعهم حتى لا يُحدثوا صوتًا.\n\nسألت إحدى الطالبات: «كم واحدةً منها ستكبر؟»\n\nأجابت الخالة: «يقول العلماء إن واحدةً من كل ألفٍ تقريبًا تبلغ سنّ البلوغ. وإن كانت أنثى، فقد تعود بعد عشرين أو ثلاثين سنة إلى هذا الشاطئ بالذات لتضع بيضها.»\n\nقال هيثم وهو ينظر إلى الموج: «أي أن إحداها قد تأتي يومًا ويراها أطفالي.»\n\nضحكت الخالة: «إن لم يُطلق عليها أحدٌ وميضًا.»\n\nعند المركز، طبعت شيماء السلحفاة على بطاقات الجميع. وحين جاء دور هيثم، طلب ثلاث بطاقاتٍ إضافية، وقال: «لأصدقائي. سيأتون الأسبوع القادم، وأريد أن أختبرهم في مهمة حارس الضوء.»\n\nبعد أسبوعين، عادت شيماء إلى صور لتستعد للمدرسة. وفي أول مساء، أرسلت إليها خالتها صورةً لسلّةٍ جديدة، فيها بطاقاتٌ مطبوعة بعناية، ولفائف من الورق الأحمر، وختمٌ حقيقي على شكل سلحفاة، وتحتها رسالةٌ قصيرة:\n\n«زملائي المرشدون صاروا يستعملون عهد الحارس في جولاتهم. والزوّار يسألون عن البنت التي اخترعته.»\n\nفتحت شيماء دفترها، وكتبت في الصفحة الأخيرة: «البحر يتنفّس. وعلينا فقط أن نخفض أصواتنا لنسمعه.»"}], "vocab": [{"w": "الزَّعانِف", "m": "أطراف السلحفاة العريضة المسطّحة، تسبح بها وتحفر"}, {"w": "يُرْبِكُها", "m": "يُحيّرها ويُفقدها اتجاهها"}, {"w": "مُتَعَرِّج", "m": "ملتوٍ غير مستقيم"}, {"w": "تَمْتَمَ", "m": "تكلّم بصوتٍ خافتٍ غير واضح"}, {"w": "الكُثْبان", "m": "تلال الرمل"}, {"w": "أَهالَتْ", "m": "صبّت الرمل أو التراب وغطّت به الشيء"}, {"w": "حازِم", "m": "قويّ ثابت لا تردّد فيه"}, {"w": "الأُفُق", "m": "الموضع الذي تبدو فيه السماء ملتقيةً بالأرض أو البحر"}], "quiz": [{"q": "لماذا تستعمل الخالة نوال مصباحًا أحمر في الجولة؟", "opts": ["لأنه أجمل في الصور", "لأن السلحفاة لا تراه جيدًا فلا يزعجها", "لأنه يجذب الصغار إلى البحر"], "a": 1, "explain": "قالت الخالة إن السلحفاة لا ترى اللون الأحمر جيدًا، أما الضوء الأبيض فيُربكها."}, {"q": "ما سبب نسيان الزوّار للقواعد بحسب الخالة؟", "opts": ["لأن الناس يتذكرون ما يشعرون به لا قوائم الممنوعات", "لأن القواعد تُقال بلغةٍ أجنبية", "لأن الجولة طويلة جدًا"], "a": 0, "explain": "قالت الخالة: «الناس لا يتذكرون قائمةً من الممنوعات. يتذكرون ما يشعرون به»، ومن هذه الجملة وُلدت فكرة شيماء."}, {"q": "كيف تعاملت شيماء مع هيثم حين رأته في جولة التجربة؟", "opts": ["طلبت من خالتها إخراجه من الجولة", "تجاهلته وتمنّت أن يلتزم", "منحته مهمة حارس الضوء"], "a": 2, "explain": "اختارته لأصعب مهمة، فصار أكثر الزوّار حرصًا على منع الضوء الأبيض."}, {"q": "لماذا اتجهت السلاحف الصغيرة إلى البحر بعد انطفاء مصابيح السيارة؟", "opts": ["لأن الخالة حملتها بيديها", "لأنها تتجه إلى أكثر الجهات إضاءة، فصار الأفق فوق البحر هو الأضوأ", "لأن الأطفال صفّقوا لها"], "a": 1, "explain": "في العتمة استدارت الصغار نحو الأفق اللامع تحت ضوء القمر، ومنعت الخالة أي أحدٍ من لمسها."}], "discuss": ["لماذا نجحت فكرة «المهام» حيث فشلت قائمة الممنوعات؟ هل جرّبتِ أسلوبًا مشابهًا مع من حولك؟", "لو كنتِ مكان شيماء حين رأت هيثم أول مرة، كيف كنتِ ستتصرفين؟ ولماذا؟"]}, {"id": "n7", "title": "القرار", "genre": "مدرسية", "blurb": "صورةٌ واحدة في مجموعة الصف، يُقال إنها أسئلة اختبار الأحد، ولمسةٌ واحدة تفصل رحاب عنها. أمامها يومان فقط لتقرّر: ماذا تفعل، وماذا تقول لصديقتيها؟", "values": ["الأمانة", "الشجاعة في قول الحق", "الصداقة الصادقة"], "chapters": [{"title": "إشعارٌ في الحادية عشرة", "text": "وصلت الصورة في الحادية عشرة وسبع دقائق مساء الخميس، وكانت رحاب تحاول حلّ المسألة التاسعة للمرة الثالثة.\n\nاهتزّ الهاتف على المكتب، ثم اهتزّ ثانية، ثم صار يهتز بلا توقف كأنّ في داخله نحلةً غاضبة. مدّت يدها إليه وعيناها ما تزالان على الدفتر، فرأت اسم مجموعة الصف: «عاشر ٣». أكثر من أربعين رسالة في دقيقتين.\n\nفي أعلى المحادثة، رسالةٌ من رقمٍ غير محفوظ لديها:\n\n«أسئلة اختبار الرياضيات يوم الأحد. المصدر موثوق. احذفوها بعد الحفظ.»\n\nوتحت الرسالة صورةٌ صغيرة ضبابية لم تُحمَّل بعد، يظهر في زاويتها شعار المدرسة، وسطورٌ مطبوعة لا تُقرأ.\n\nثم انهالت الردود: «حقيقية؟!» «من أين حصلتِ عليها؟» «أنقذتِنا!» «بدأتُ أحلّها من الآن.» «لا تُخبرن أحدًا.»\n\nوضعت رحاب القلم. كانت الدوال التربيعية أصعب ما مرّ عليها هذا الفصل، ومنذ أسبوعٍ وهي تشعر أن الرسوم البيانية تسخر منها: منحنياتٌ تصعد وتهبط ولا تقول لها شيئًا. وفي الاختبار القصير الماضي، حصلت على درجةٍ جعلتها تُخفي الورقة في حقيبتها يومين قبل أن تُريها لأمّها.\n\nوالآن، على بُعد لمسةٍ واحدة من إصبعها، قد تكون الأسئلة كلها.\n\nاهتزّ الهاتف مرةً أخرى. رسالةٌ خاصة من جود، صديقتها منذ الصف الخامس:\n\n«رأيتِ؟؟ هذه فرصتنا. اتصلي بي، سنحلّها معًا الليلة!»\n\nثم رسالةٌ من أسيل، الثالثة في مجموعتهن الصغيرة، بكلماتٍ أقلّ:\n\n«لا أدري... ماذا ستفعلين أنتِ؟»\n\nنظرت رحاب إلى الصورة الضبابية. لم يكن أحدٌ يراها الآن. أمّها نائمة، وأخوها الصغير يغطّ في نومه في الغرفة المجاورة، والمصباح الوحيد المضاء في البيت هو مصباح مكتبها. لن يعرف أحدٌ إن فتحتها. ولن يعرف أحدٌ إن لم تفتحها. كان القرار لها وحدها، وهذا بالذات ما جعله ثقيلًا.\n\nاقترب إبهامها من الصورة حتى كاد يلمسها.\n\nثم توقّف.\n\nقلبت رحاب الهاتف على وجهه، فانطفأت الشاشة، وبقي الاهتزاز وحده يرنّ في خشب المكتب كطرقاتٍ خفيفة على باب.\n\nعادت إلى المسألة التاسعة، وقرأتها للمرة الرابعة، فلم تفهم منها حرفًا. فالأرقام كانت أمامها، لكن عقلها كان هناك، تحت الهاتف المقلوب.\n\nكانت تعرف أن الباب لم يُغلق بعد. فما زال أمامها يومان كاملان قبل الاختبار."}, {"title": "ستّون بالمئة", "text": "لم تنم رحاب جيدًا تلك الليلة. وفي صباح الجمعة، وجدت نفسها تفتح الدفتر على المسألة التاسعة نفسها، فتقرأ السطر الأول ثم تشرد.\n\nكانت تعرف ما يقوله الجميع، لأنها قرأته يتكرّر في المجموعة طوال الليل: «لم نسرق شيئًا، الصورة وصلتنا وحدها.» «الكل سيحلّها، فلماذا نكون نحن الخاسرات؟» «المعلمة لن تعرف.»\n\nوكان في الكلام شيءٌ مقنعٌ يزعجها. إن فتحت البنات الصورة ولم تفتحها هي، فستكون الوحيدة التي تدخل الاختبار بلا خريطة. وإن نلن الدرجات الكاملة، فستبدو درجتها، مهما اجتهدت، صغيرةً بينهن.\n\nفتحت المحادثة دون أن تقصد تقريبًا. «سأتأكد فقط إن كانت حقيقية،» قالت لنفسها. «مجرّد نظرة. لن أحلّ شيئًا.»\n\nلمست الصورة، فظهرت دائرة التحميل تدور ببطء. عشرة بالمئة. ثلاثون.\n\nوفجأةً تذكّرت وجه أبيها حين كان يعلّمها ركوب الدراجة في الحيّ قبل سنوات. كان قد وعدها أن يمسك المقعد من الخلف، ثم أفلته دون أن تعرف، فمشت وحدها مسافةً طويلة. وحين التفتت ورأته بعيدًا، لم تخف، بل صرخت من الفرح: «فعلتُها وحدي!»\n\nستّون بالمئة.\n\nضغطت رحاب على زر الإلغاء بسرعة، كأنها تسحب يدها من ماءٍ يغلي. ثم ضغطت مطوّلًا على الصورة، واختارت: «حذف لديّ». فاختفت الصورة من هاتفها، وبقي مكانها سطرٌ رماديّ صغير.\n\nتنفّست بعمق. لم تشعر بأنها بطلة، بل شعرت بشيءٍ أبسط: أنها صارت خفيفة.\n\nلكن الخفّة لم تدم طويلًا، فقد بقي أمرٌ أصعب من الحذف.\n\nفتحت المحادثة الخاصة التي تجمعها بجود وأسيل، وكتبت ومسحت، وكتبت ومسحت، ثم أرسلت أخيرًا:\n\n«حذفتُ الصورة دون أن أفتحها. لا أريد أن أدخل الاختبار بإجاباتٍ ليست لي. ولا أريدكما أن تعتمدا عليها، فنحن لا نعرف حتى إن كانت صحيحة. إن أردتما، تعالَيا نذاكر معًا غدًا في بيتي.»\n\nظهرت علامتا القراءة بعد ثوانٍ. ثم ظهرت عبارة «جود تكتب الآن...» واختفت. ثم ظهرت من جديد، واختفت مرةً أخرى، كأن جود تكتب رسالةً طويلة ثم تمحوها. وكانت رحاب تراقب الشاشة وهي تعضّ طرف قلمها، وتتمنى لو أنها لم ترسل شيئًا.\n\nوأخيرًا وصل الرد:\n\n«يعني ماذا؟ تقصدين أننا غشّاشات؟»"}, {"title": "من يقف وحده", "text": "حدّقت رحاب في الشاشة. لم تكن تقصد ذلك، أو لعلها لم تقصده بهذه الكلمات. كتبت بسرعة:\n\n«لا. أنا لا أحكم عليكما. أنا أقول ما سأفعله أنا فقط.»\n\nلكن جود كانت قد بدأت، فتدفّقت رسائلها واحدةً بعد أخرى: إن رحاب تحب دائمًا أن تبدو أفضل من غيرها. وإن الصورة وصلت إلى الصف كله، فلماذا تُحمَّل هي وأسيل الذنب؟ وإن من لا يريد الفرصة فليتركها لغيره بصمت، بدل أن يُلقي المحاضرات.\n\nثم كتبت: «اتركيني أذاكر.» وخرجت من المحادثة.\n\nجلست رحاب على طرف سريرها والهاتف في حجرها. كانت تظن أن الحذف هو الجزء الصعب، فإذا بالصعب الحقيقي هو هذا: أن تكون على حقّ، وأن تكون وحيدة.\n\nلم تكتب أسيل شيئًا طوال المساء.\n\nوفي صباح السبت، وبينما كانت رحاب ترسم منحنى دالةٍ للمرة الخامسة، رنّ جرس البيت. فتحت أمّها الباب، ثم نادت: «رحاب! صديقتك.»\n\nكانت أسيل واقفةً عند الباب، تحمل كتاب الرياضيات وعلبةً صغيرة من كعك التمر. قالت وهي تنظر إلى الأرض: «فتحتُ الصورة أمس. لكني لم أفهم الحلول، وشعرت أني أحفظ أرقامًا لا معنى لها. ثم فكّرت: ماذا لو لم تكن صحيحة؟ هل ما زال عرضكِ قائمًا؟»\n\nابتسمت رحاب لأول مرة منذ يومين. «ادخلي.»\n\nذاكرتا حتى العصر. وحدث ما لم تتوقعه رحاب: فحين وصلتا إلى رسم المنحنيات، أخذت أسيل القلم وقالت: «انظري، لا تحفظي شكل الرسم. ابحثي أولًا عن الرأس، ثم اسألي: هل الفتحة إلى الأعلى أم إلى الأسفل؟ والباقي يأتي وحده.» وفجأةً، صارت المنحنيات التي سخرت من رحاب أسبوعًا كاملًا تتكلم.\n\nفي المساء، بعد أن ذهبت أسيل، بقي سؤالٌ أخير يطرق رأس رحاب. إن كانت الصورة حقيقية، فالاختبار لن يكون عادلًا لأحد: لا لمن فتحها، ولا لمن رفضها. ألا يحقّ للمعلمة أن تعرف؟\n\nلكنها إن أخبرتها، فهل تكون قد خانت صفّها؟\n\nقلّبت الفكرة طويلًا، وهي تطوي ملابس المدرسة وتعدّ حقيبتها. تخيّلت نظرات البنات لو عرفن، وتخيّلت أيضًا وجه أسيل وهي تقول: «شعرت أني أحفظ أرقامًا لا معنى لها». ثم قرّرت أخيرًا شيئًا واحدًا: لن تذكر اسم أحد. لكنها لن تسكت أيضًا.\n\nوصباح الأحد، قبل الطابور بربع ساعة، كانت رحاب واقفةً أمام باب غرفة المعلمات، ويدها مرفوعة لتطرق، وقلبها يطرق قبلها."}, {"title": "ورقةٌ لم يرها أحد", "text": "فتحت الأستاذة سعاد الباب، وفي يدها كوب شاي ورزمةٌ من الأوراق المطوية. «رحاب؟ ما زال على الاختبار ساعة.»\n\n«أعرف يا أستاذة. أريد أن أقول لكِ شيئًا، ولن يأخذ وقتًا.»\n\nقالتها رحاب دفعةً واحدة، كي لا تتراجع: هناك صورةٌ تنتشر منذ الخميس، يُقال إنها أسئلة اختبار اليوم. هي لم تفتحها، ولا تعرف إن كانت صحيحة، ولا تعرف من أرسلها أول مرة، ولن تذكر اسم أحد. لكنها رأت أن من حقّ المعلمة أن تعرف.\n\nصمتت الأستاذة سعاد لحظةً طويلة، تنظر إلى رحاب نظرةً لم تستطع أن تفهمها: لا غضب فيها ولا مفاجأة. ثم قالت بهدوء: «شكرًا يا رحاب. اذهبي إلى قاعتك الآن.»\n\nهذا كل شيء. لا سؤال، ولا تعليق.\n\nمشت رحاب إلى القاعة وهي تشعر أنها أفرغت حجرًا ثقيلًا من حقيبتها، لكنها لم تعرف أين سقط.\n\nفي القاعة، كان الهمس يملأ المكان. بنتٌ في الصف الأول تراجع ورقةً صغيرة ثم تخفيها بسرعة في المقلمة. وأخرى تتمتم بأرقامٍ كأنها تحفظ رقم هاتف. أما جود، فكانت تجلس في الصف الثالث، تنظر أمامها، ولم تلتفت حين دخلت رحاب.\n\nوُزّعت الأوراق. قلبت رحاب ورقتها، وقرأت السؤال الأول.\n\nثم السؤال الثاني.\n\nثم رفعت رأسها، فرأت المشهد نفسه يتكرر في القاعة كلها: وجوهٌ تقرأ، ثم تتجمّد، ثم تعود فتقرأ من جديد كأنها تبحث عن شيءٍ لا تجده. كانت الأسئلة مختلفة. لم تكن صعبة، لكنها لم تكن تشبه شيئًا يتحدث عنه أحدٌ منذ الخميس.\n\nعرفت رحاب ذلك دون أن ترى الصورة أصلًا: من صوت الأقلام التي توقّفت، ومن أنفاسٍ تُحبس، ومن بنتٍ في الخلف وضعت جبهتها على الطاولة لحظة.\n\nانحنت على ورقتها. في السؤال الرابع، كان عليها أن ترسم منحنى دالة. فسمعت صوت أسيل في رأسها: «ابحثي أولًا عن الرأس.» ورسمته.\n\nحين انتهى الوقت وخرجت البنات إلى الممر، انفجرت الأصوات دفعةً واحدة:\n\n«الصورة كانت كذبة!»\n\n«من أرسلها؟»\n\n«ضيّعتُ يومين أحفظ أرقامًا!»\n\nبحثت رحاب بعينيها عن جود. رأتها في آخر الممر، تمشي مسرعةً نحو الدرج، ورأسها منخفض، وورقة الأسئلة مطويةٌ في قبضتها.\n\nأرادت أن تلحق بها، لكن قدميها لم تتحركا. ماذا ستقول لها؟ «ألم أقل لكِ؟» لا، هذه آخر جملةٍ تريد أن تقولها.\n\nوفي تلك اللحظة، مرّت الأستاذة سعاد بجانبها، وقالت دون أن تتوقف: «غدًا، في الحصة الأولى، سأخبركنّ من أين جاءت تلك الصورة.»"}, {"title": "ما كان في الصورة", "text": "جلست البنات في الحصة الأولى صامتاتٍ على غير العادة. دخلت الأستاذة سعاد، ووضعت الأوراق المصحّحة على الطاولة، ثم أخرجت من حقيبتها ورقةً قديمة صفراء الأطراف.\n\n«هذه هي الصورة التي كنتنّ تتداولنها،» قالت، ورفعت الورقة. «إنها اختبار العام الماضي. كتبته بيدي، وصحّحته بيدي، وأعرفه كما أعرف خطّي. يبدو أن أختًا كبيرة لإحداكنّ احتفظت به، فصوّره أحدهم، وقصّ التاريخ من أعلاه، وأرسله على أنه سرٌّ خطير.»\n\nساد الصمت. ثم أكملت: «أنا أكتب اختبارًا جديدًا كل عام. ولم يكن في تلك الصورة ما ينفع أحدًا، لكنها أضرّت بمن صدّقها، لأنها أخذت منها يومين كان يمكن أن تفهم فيهما الدرس.»\n\nثم نظرت إلى الصف كله، لا إلى رحاب تحديدًا: «وصباح أمس، جاءتني إحداكنّ وأخبرتني بالأمر قبل الاختبار، وهي لا تعرف أن الصورة قديمة. لم تذكر اسم أحد، ولم تطلب شيئًا. أريدكنّ أن تعرفن أن ما فعلته يحتاج من الشجاعة أكثر مما يحتاجه أصعب سؤالٍ في هذه الورقة.»\n\nلم تلتفت إليها أي بنت، فلا أحد يعرف. وأحسّت رحاب بحرارةٍ في وجهها، فأنزلت عينيها إلى طاولتها.\n\nوُزّعت الدرجات. حصلت رحاب على سبع عشرة من عشرين، وهي أعلى درجةٍ نالتها في الرياضيات هذا العام. وحصلت أسيل على ثماني عشرة، فصفّقت لها رحاب تحت الطاولة. أما جود، فطوت ورقتها بسرعة، ولم تُرِها أحدًا.\n\nفي الفسحة، جلست رحاب وحدها على درج المختبر. وبعد دقائق، جلست جود إلى جانبها دون أن تقول شيئًا. ثم قالت أخيرًا:\n\n«كنتِ تعرفين أنها قديمة؟»\n\n«لا. لم أكن أعرف.»\n\n«إذن لماذا لم تفتحيها؟»\n\nفكّرت رحاب قليلًا. «لأني أردت أن تكون الدرجة لي، حتى لو كانت صغيرة.»\n\nسكتت جود طويلًا، ثم مدّت ورقتها المطوية. كانت الدرجة تسعةً من عشرين. «أسيل تقول إنكِ صرتِ تفهمين المنحنيات. وأنا لا أفهمها أبدًا.»\n\n«أسيل هي التي أفهمتني.»\n\n«إذن...» تردّدت جود، ثم ابتسمت ابتسامةً صغيرة متعبة. «وما قلتُه لكِ يوم الجمعة... كنت غاضبةً من نفسي، لا منكِ. هل يتّسع بيتك لثلاثٍ يوم السبت القادم؟»\n\n«يتّسع لعشر.»\n\nفي المساء، اهتزّ هاتف رحاب. رسالةٌ جديدة في مجموعة «عاشر ٣» من رقمٍ غير محفوظ: «عندي أسئلة الاختبار النهائي!»\n\nضحكت رحاب، وضغطت على «كتم الإشعارات»، ثم فتحت دفترها على المسألة العاشرة."}], "vocab": [{"w": "ضَبابِيّة", "m": "غير واضحة، كأن عليها ضبابًا"}, {"w": "انْهالَتْ", "m": "تتابعت بكثرةٍ وسرعة"}, {"w": "تَشْرُد", "m": "يذهب ذهنها بعيدًا عمّا أمامها"}, {"w": "المُنْحَنى", "m": "الخط المقوّس في الرسم البياني"}, {"w": "قَلَّبَتِ الفِكْرة", "m": "نظرت فيها من جوانبها كلها قبل أن تقرّر"}, {"w": "رِزْمة", "m": "مجموعة من الأوراق مضمومٌ بعضها إلى بعض"}, {"w": "تَتَداوَلْنَها", "m": "تنقلنها من واحدةٍ إلى أخرى"}], "quiz": [{"q": "لماذا لم تفتح رحاب الصورة؟", "opts": ["لأن أمّها منعتها", "لأن هاتفها لم يكن متصلًا بالإنترنت", "لأنها أرادت أن تكون درجتها من جهدها"], "a": 2, "explain": "قالت لجود: «أردت أن تكون الدرجة لي، حتى لو كانت صغيرة»، وتذكّرت فرحتها حين ركبت الدراجة وحدها."}, {"q": "ماذا فعلت أسيل صباح السبت؟", "opts": ["جاءت تذاكر مع رحاب بعد أن شكّت في الصورة", "أخبرت المعلمة باسم من أرسلت الصورة", "خرجت من مجموعة الصف"], "a": 0, "explain": "جاءت إلى بيت رحاب تحمل كتاب الرياضيات، وقالت إنها شعرت أنها تحفظ أرقامًا لا معنى لها."}, {"q": "ما حقيقة الصورة التي انتشرت في مجموعة الصف؟", "opts": ["أسئلة اختبار الأحد بعد تعديلها", "اختبار العام الماضي بعد قصّ تاريخه", "تمارين من آخر الكتاب"], "a": 1, "explain": "كشفت الأستاذة سعاد أنها اختبار العام الماضي، وأنها تكتب اختبارًا جديدًا كل عام."}, {"q": "ما الذي ساعد رحاب في سؤال رسم المنحنى؟", "opts": ["مساعدة المعلمة أثناء الاختبار", "تذكّرها حلّ الصورة", "تذكّرها نصيحة أسيل بالبحث عن الرأس أولًا"], "a": 2, "explain": "سمعت صوت أسيل في رأسها: «ابحثي أولًا عن الرأس»، فرسمت المنحنى."}], "discuss": ["قالت رحاب إن الصعب الحقيقي أن تكوني على حقّ وأن تكوني وحيدة. هل مررتِ بموقفٍ مشابه؟ كيف تعاملتِ معه؟", "هل كان قرار رحاب بإخبار المعلمة دون ذكر الأسماء صائبًا؟ ما الفرق بين الأمانة والوشاية في رأيك؟"]}, {"id": "n8", "title": "خريف صلالة", "genre": "أسرة", "blurb": "لم تُرد ميّ من خريف صلالة إلا أن ينتهي سريعًا. لكن جدّتها تخبّئ في قطعة قماشٍ قديمة أداةً صغيرة، وقصةً لم يسمعها أحدٌ كاملة.", "values": ["الإصغاء لكبار السنّ", "الاعتزاز بالتراث", "الصبر"], "chapters": [{"title": "ألفُ كيلومترٍ من الملل", "text": "قالت ميّ إنها لن ترفع عينيها عن الهاتف حتى تصل إلى صلالة، وكانت تعني ما تقول.\n\nانطلقت السيارة من مسقط قبل الفجر، وأبوها يردّد للمرة العاشرة أن الطريق طويل، وأن عليهم أن يقطعوا معظمه قبل أن يشتدّ الحر. وفي المقعد الخلفي، كان أخوها أحمد، ذو التسع سنوات، يسأل كل نصف ساعة: «هل وصلنا؟» فتجيبه أمّها بصبرٍ لا ينفد: «بقي القليل.» ولم يكن قد بقي القليل أبدًا.\n\nمرّت الساعات على ميّ كأنها صفحةٌ واحدة تتكرر: رمالٌ صفراء، وسرابٌ يرتجف فوق الإسفلت، ومحطة وقودٍ صغيرة بعد أخرى. عند هيماء، أشار مقياس الحرارة في السيارة إلى سبعٍ وأربعين درجة. وكانت صديقاتها يتبادلن في المجموعة صورًا من المجمّعات المكيّفة في مسقط، فكتبت لهن: «أنا في منتصف اللاشيء.»\n\nلم تكن ميّ تكره صلالة. كانت تحب جدّتها سالمة، أمّ أمّها، وتحب بيتها الواسع ذا الفناء. لكن الزيارة تعني شهرًا كاملًا من الجلوس مع الكبار، وأحاديث طويلة عن أناسٍ لا تعرفهم، وأسئلةً مكرّرة عن المدرسة.\n\nبعد ثمريت، بدأ الطريق يصعد. ثم، بعد منعطفٍ واحد، حدث شيءٌ جعل ميّ ترفع رأسها رغمًا عنها.\n\nانطفأت الشمس.\n\nلم تغرب، بل اختفت خلف غطاءٍ رماديٍّ كثيف نزل على الجبال كأنه صوفٌ مبلول. وظهرت على زجاج السيارة قطراتٌ صغيرة، ثم المزيد. فتح أبوها النافذة قليلًا، فدخل هواءٌ باردٌ رطب له رائحة العشب.\n\nنظرت ميّ إلى المقياس: أربعٌ وعشرون درجة.\n\nوعلى جانبي الطريق، كانت الجبال التي تذكرها بنّيةً جرداء في زياراتهم الشتوية، قد صارت خضراء كأن أحدًا طلاها في الليل. وانحدرت من بين الصخور خيوطٌ بيضاء رفيعة من الماء. وفجأةً، خرجت من الضباب ناقةٌ تمشي على الطريق بهدوءٍ تام، فضغط أبوها على المكابح، وضحك أحمد حتى سعل.\n\nقالت أمّها بصوتٍ فيه شيءٌ يشبه الحنين: «أهلًا بكم في الخريف.»\n\nوصلوا إلى بيت الجدّة مع العصر. وقبل أن تطرق ميّ الباب، استقبلتها رائحةٌ دافئة تعرفها منذ طفولتها: رائحة اللبان.\n\nفتحت الجدّة سالمة الباب، وضمّتها طويلًا، ثم أمسكت وجهها بكفّيها وقالت:\n\n«كبرتِ. جيد. قريبًا، مع الفجر، ستأتين معي.»\n\n«إلى أين يا جدّتي؟»\n\nابتسمت الجدّة: «إلى حيث لا يصل الخريف.»"}, {"title": "المجمرة والإشعارات", "text": "امتلأ المساء الأول بالزوار. جاءت الخالات وأبناؤهن، وامتلأ الفناء بالأصوات، وتحت شجرة النارجيل العالية وُضعت صحون الموز الصغير الحلو، وأكواب ماء جوز الهند الذي اشتراه أبوها من الأكشاك المنتشرة على الطريق. وكان الرذاذ يتساقط ناعمًا على الفناء، فلا يبلّل أحدًا، لكنه يجعل كل شيءٍ يلمع.\n\nوفي وسط المجلس، جلست الجدّة سالمة أمام مجمرةٍ فخارية بيضاء مزيّنة بخطوطٍ ملوّنة، تتوهّج في قلبها جمراتٌ صغيرة. أخرجت من صُرّةٍ قماشية حبّاتٍ بلون العسل الفاتح، ووضعت واحدةً منها على الجمر. فارتفع خيطٌ أبيض من الدخان، والتفّ في الهواء الرطب، وملأ المكان برائحةٍ تشبه الليمون والخشب معًا.\n\nقالت الجدّة وهي تقرّب المجمرة من ميّ: «هذا حوجري، من أجود اللبان. لا يُشترى من أي مكان.»\n\n«ممم.» ردّت ميّ، وعيناها على الشاشة. كانت صديقتها ريم قد أرسلت مقطعًا مضحكًا، وكانت تكتب لها ردًّا.\n\nاستمرّت الجدّة في الكلام بصوتها الهادئ المتمهّل. قالت شيئًا عن الأشجار، وعن أبيها، وعن موسمٍ ما. وكانت ميّ تهزّ رأسها بين حينٍ وآخر، كما يفعل من يستمع إلى المذياع في سيارة.\n\nثم توقّفت الجدّة فجأة.\n\nرفعت ميّ عينيها حين طال الصمت. كانت جدّتها تنظر إليها، بلا عتابٍ تقريبًا.\n\n«ماذا قلتُ الآن يا ميّ؟»\n\nاحمرّ وجه ميّ. فتحت فمها، ثم أغلقته. لم تكن تعرف.\n\nلم تغضب الجدّة. أعادت ربط الصُّرّة بهدوء، وقالت: «لا بأس. الكلام الذي لا يُسمَع يرجع إلى صاحبه، ويبقى عنده.»\n\nثم التفتت إلى إحدى بناتها، وتحدّثت في أمرٍ آخر.\n\nشعرت ميّ بشيءٍ صغيرٍ حادٍّ في صدرها، لم تعرف له اسمًا. وضعت الهاتف على حجرها، وحاولت أن تلتقط بقية الحديث، لكن الحديث كان قد انتقل إلى الطرق المزدحمة بالسيّاح، وأسعار الفنادق، وعين الماء التي فاضت هذا العام أكثر من كل عام.\n\nفي الليل، حين كانت تستعدّ للنوم في الغرفة المطلّة على الفناء، سمعت طرقًا خفيفًا. دخلت الجدّة تحمل شيئًا ملفوفًا بقطعة قماشٍ قديمة باهتة اللون، ووضعته على الطاولة دون أن تفتحه.\n\n«هذا كان لأبي. غدًا، إن استمعتِ جيدًا، سأخبركِ ما هو.»\n\nثم خرجت، وأغلقت الباب خلفها بهدوء، وتركت ميّ تحدّق في القماش الملفوف، وقد نسيت هاتفها تمامًا."}, {"title": "حيث لا يصل الخريف", "text": "انطلقوا قبل شروق الشمس، والأب يقود السيارة بحذرٍ في الضباب الكثيف. جلست الجدّة في المقعد الأمامي، وميّ خلفها، والقماش الملفوف في حجر الجدّة.\n\nصعدت السيارة الجبال، والمصابيح الأمامية لا تكشف أكثر من خطواتٍ قليلة. كانت الأشجار تظهر من الرمادي ثم تختفي، كأنها أشباحٌ خضراء. ثم حدث ما وعدت به الجدّة: انتهى الضباب دفعةً واحدة، كأن أحدًا أزاح ستارًا.\n\nسطعت الشمس. واختفى الأخضر. وامتدّت أمامهم أرضٌ صخرية جافة بلون القهوة بالحليب، ودخلت من النافذة ريحٌ حارة خفيفة.\n\nقالت الجدّة: «هنا تنتهي الجبال ويبدأ النجد. الخريف لا يعبر هذه القمم.»\n\nتوقّفوا عند وادٍ واسع تنتشر فيه أشجارٌ صغيرة، أقصر من قامة الرجل أحيانًا، ملتوية الجذوع، كأنها تنحني لتسمع شيئًا من الأرض. قشرها رقيقٌ يتقشّر كالورق، وأوراقها صغيرةٌ مجعّدة.\n\n«هذه أشجار اللبان؟» سألت ميّ، وفي صوتها شيءٌ من خيبة الأمل. «ظننتها أكبر.»\n\nضحكت الجدّة، ومشت نحو أقرب شجرة، ووضعت يدها على جذعها كما يضع المرء يده على كتف صديقٍ قديم.\n\n«العظيم لا يكون كبيرًا دائمًا يا بنتي. هذه الشجرة الصغيرة جعلت أرضنا معروفةً في الدنيا منذ آلاف السنين. كانوا يحملون لبانها على الجمال إلى ميناء سمهرم عند خور روري، ومن هناك تبحر به السفن إلى بلادٍ بعيدة. وكان بعض الناس يعدّونه ثمينًا كالذهب.»\n\nثم أشارت إلى ندبةٍ صغيرة على الجذع، قد جفّت عليها قطرةٌ بيضاء معتمة. «هنا جرحها جامع اللبان بلطف. يكشط القشرة قليلًا، فتُخرج الشجرة دمعةً بيضاء كالحليب. وبعد أيام تجفّ وتصير حبّة لبان.»\n\n«ألا يؤذيها ذلك؟»\n\nنظرت إليها الجدّة نظرةً فيها رضا. «هذا أول سؤالٍ حقيقي تسألينه منذ وصلتِ.»\n\nكانت ميّ تصوّر بهاتفها طوال الوقت: الشجرة، ويد الجدّة، والضوء الذهبي على الصخور. لكنها حين سمعت تلك الجملة، أنزلت الهاتف قليلًا.\n\nأجابت الجدّة: «يؤذيها إن جرحها الطمّاع كثيرًا، أو عميقًا. والشجرة المتعبة تحتاج إلى أن ترتاح سنوات. ولهذا عندي قصة.»\n\nثم فكّت القماش الملفوف ببطء، فظهرت أداةٌ صغيرة: مقبضٌ خشبيٌّ قديم أملس من كثرة الاستعمال، ونصلٌ عريض قصير يشبه ملعقةً حادّة الطرف.\n\n«هذا المِنقف. كان لأبي. وبه ارتكبتُ أكبر خطأٍ في طفولتي.»"}, {"title": "مقطعٌ بلا صوت", "text": "لكن القصة لم تُحكَ هناك. فقد اتصل خال ميّ بأبيها يطلب منهم العودة، لأن العائلة كلها ستجتمع على الغداء. لفّت الجدّة المنقف من جديد، وقالت: «في المساء إذن.»\n\nفي طريق العودة، وبينما كانت السيارة تغوص في الضباب من جديد، جلست ميّ تعمل على المقطع. اختارت أجمل اللقطات: الجذع الملتوي، والدمعة البيضاء، ويد الجدّة المجعّدة على القشر، والشمس. ثم وجدت أن صوت الريح وصوت الجدّة يملآن الخلفية، فحذفتهما، ووضعت مكانهما مقطوعةً موسيقية هادئة يستعملها الجميع هذه الأيام. وكتبت تحته: «شجرة اللبان... كنز ظفار.»\n\nونشرته.\n\nحين اجتمعت العائلة في المساء، كان المقطع قد تجاوز ألف مشاهدة. وانهالت التعليقات: «جميلٌ جدًا!» «أين هذا المكان؟» «أريد أن أذهب!» وكانت ميّ تقرؤها بشيءٍ من الزهو.\n\nجلست الجدّة في صدر المجلس، والمجمرة أمامها، والمنقف في حجرها. وحين هدأت الأصوات، قالت: «وعدتُ ميّ بقصة. وأظن الصغار يحبون أن يسمعوها أيضًا.»\n\nوبدأت تحكي: «كان عمري عشر سنوات، وكان أبي يقضي موسم الجني قرب الأشجار، ينام تحت السماء أسابيع...»\n\nاهتزّ هاتف ميّ في يدها. إشعار: المقطع وصل إلى ألفين. التفتت إلى ابنة خالتها بجانبها، وأرتها الشاشة، فشهقت الأخرى بصوتٍ عالٍ، فالتفت ابن خالها، ثم آخر، وامتدّت الرؤوس نحو الهاتف، وبدأ الضحك والتعليق.\n\nوتوقّف صوت الجدّة.\n\nقالت ميّ بحماسة، ورفعت الهاتف نحوها: «جدّتي! انظري! ألفا مشاهدةٍ لشجرتك!»\n\nنظرت الجدّة إلى الشاشة. شاهدت المقطع كله بصمت، والموسيقى الهادئة تنبعث منه. رأت يدها على الشجرة، ولم تسمع صوتها.\n\nثم ابتسمت ابتسامةً صغيرة جدًا، وقالت: «جميلٌ يا بنتي.» ولفّت المنقف في قماشه، ونهضت ببطء. «أنا متعبةٌ قليلًا. أُكمل القصة يومًا آخر.»\n\nوخرجت من المجلس.\n\nلم يقل أحدٌ شيئًا. لكن ميّ رأت عيني أمّها، ورأت فيهما ما هو أصعب من العتاب.\n\nأعادت تشغيل المقطع وحدها. الشجرة، واليد، والضوء، والموسيقى. كان جميلًا، وكان فارغًا تمامًا. لا شيء فيه عن الدمعة التي تجفّ، ولا عن الشجرة المتعبة، ولا عن ميناءٍ قديم ترحل منه السفن.\n\nلقد حذفت جدّتها من مقطعٍ صُنع كله من يديها وكلماتها.\n\nوبعد أن انصرف الضيوف، وهدأ البيت، وقفت ميّ أمام باب غرفة الجدّة، والهاتف في يدها، وأخذت نفسًا طويلًا، ثم طرقت."}, {"title": "ما لا يحفظه الهاتف", "text": "كانت الجدّة جالسةً على سجّادتها، والمصباح الصغير مضاء. لم تبدُ نائمة، ولا غاضبة.\n\nجلست ميّ على الأرض أمامها، ولم تعرف من أين تبدأ. ثم مدّت الهاتف، وقالت بصوتٍ خافت: «حذفتُ صوتكِ من المقطع يا جدّتي، ووضعتُ موسيقى بدلًا منه. ولم أنتبه إلى ما فعلت إلا الآن.»\n\nصمتت الجدّة قليلًا. ثم قالت: «والآن؟»\n\n«والآن أريد القصة. كلها. من أولها.» وتوقّفت، ثم أضافت: «وسأطفئ هذا.» وأطفأت الهاتف، ووضعته بعيدًا على الطاولة.\n\nفكّت الجدّة القماش، ووضعت المنقف بينهما، وبدأت.\n\nحكت عن طفلةٍ في العاشرة رافقت أباها إلى الأشجار في موسم الجني. كان يكشط القشرة كشطًا خفيفًا، ثم ينتظر. وكانت هي تكره الانتظار. وذات صباح، حين انشغل عنها، أخذت المنقف، واختارت شجرةً صغيرة، وجرحتها جرحًا عميقًا، لتخرج دمعةٌ كبيرة دفعةً واحدة.\n\nلم يصرخ أبوها حين رأى ما فعلت. جلس قرب الشجرة، وأجلسها إلى جانبه، وقال: «الآن ننتظر معها.» وبقيا هناك حتى العصر. فلم يخرج من الجرح إلا قطراتٌ قليلة شاحبة، لا تشبه اللبان الجيد.\n\n«ثم قال لي جملةً لم أنسها: الشجرة تعطي من يصبر عليها، لا من يستعجلها. وربط على جذعها خيطًا أحمر، وقال إن أحدًا لن يقترب منها ثلاث سنوات.»\n\n«وماذا حدث لها؟»\n\nابتسمت الجدّة. «بعد سنواتٍ طويلة، حين صرتُ أمًّا، ذهبتُ إليها. كان الخيط قد اختفى، والندبة قد التأمت، وكانت تعطي من أجمل لبانٍ في ذلك الوادي.»\n\nظلّت ميّ تصغي حتى وقتٍ متأخر. وحين انتهت القصة، جاءت قصةٌ أخرى، ثم أخرى: عن قوافل، وعن سنةٍ تأخّر فيها المطر، وعن أعراسٍ قديمة. وقبل أن تقوم، سألت: «هل تسمحين أن أسجّل صوتكِ غدًا؟ لا لأنشره، بل لي أنا.»\n\nقالت الجدّة: «لكِ أنتِ؟ إذن نعم.»\n\nفي آخر يومٍ من الشهر، وضعت الجدّة في يد ميّ صُرّةً صغيرة من الحوجري. وحين نظرت ميّ إلى المنقف، هزّت الجدّة رأسها: «هذا يبقى هنا، لكي تعودي وتسألي عنه.»\n\nوفي طريق العودة الطويل، حين انتهى الضباب وعادت الصحراء الصفراء، أخرجت ميّ هاتفها، ووضعت إحدى سمّاعتيها في أذن أحمد.\n\n«من هذه التي تتكلم؟» سأل.\n\nقالت ميّ: «جدّتي. اسمع، ولا تقاطعها.»"}], "vocab": [{"w": "السَّراب", "m": "ما يُرى في الصحراء وقت الحرّ كأنه ماءٌ وليس بماء"}, {"w": "المِجْمَرة", "m": "إناءٌ يوضع فيه الجمر ويُحرق عليه البخور واللبان"}, {"w": "صُرّة", "m": "قطعة قماشٍ تُجمع فيها أشياء صغيرة وتُربط"}, {"w": "النَّجْد", "m": "الأرض المرتفعة، وفي ظفار: المنطقة الجافة خلف الجبال"}, {"w": "يَكْشِط", "m": "يُزيل الطبقة الخارجية بأداةٍ حادّة"}, {"w": "نَدْبة", "m": "أثر الجرح بعد أن يجفّ"}, {"w": "الزَّهْو", "m": "الإعجاب بالنفس والفخر"}, {"w": "الْتَأَمَتْ", "m": "التحم الجرح وشُفي"}], "quiz": [{"q": "ماذا قصدت الجدّة بقولها: «إلى حيث لا يصل الخريف»؟", "opts": ["النجد خلف الجبال، حيث الأرض جافة وتنمو أشجار اللبان", "شاطئ البحر في صلالة", "مدينة مسقط"], "a": 0, "explain": "حين انتهى الضباب قالت الجدّة: «هنا تنتهي الجبال ويبدأ النجد. الخريف لا يعبر هذه القمم»."}, {"q": "لماذا خرجت الجدّة من المجلس قبل أن تكمل قصتها؟", "opts": ["لأن المقطع لم يحصل على مشاهدات كافية", "لأن الضيوف تأخروا في الحضور", "لأن ميّ ومن حولها انشغلوا بالهاتف، ورأت المقطع بلا صوتها"], "a": 2, "explain": "انشغل الصغار بالمقطع فتوقّف صوتها، ثم رأت يدها على الشجرة ولم تسمع صوتها."}, {"q": "ما الخطأ الذي ارتكبته الجدّة في طفولتها؟", "opts": ["أضاعت منقف أبيها", "جرحت شجرةً صغيرة جرحًا عميقًا لتستعجل اللبان", "باعت اللبان بثمنٍ قليل"], "a": 1, "explain": "كانت تكره الانتظار، فجرحت الشجرة عميقًا، فلم تُخرج إلا قطراتٍ شاحبة."}, {"q": "لماذا لم تُعطِ الجدّة المنقف لميّ؟", "opts": ["لأنه مكسور", "لأنه ملكٌ لخال ميّ", "لكي تعود ميّ وتسأل عنه"], "a": 2, "explain": "قالت الجدّة: «هذا يبقى هنا، لكي تعودي وتسألي عنه»."}], "discuss": ["حذفت ميّ صوت جدّتها من المقطع دون أن تنتبه. ما الذي يضيع منّا حين نصوّر اللحظات وننسى أن نصغي إليها؟", "اختاري شخصًا كبيرًا في عائلتك، واكتبي ثلاثة أسئلة تودّين أن تسأليه إيّاها عن طفولته."]}, {"id": "n9", "title": "المكتبة التي لا تنام", "genre": "خيال", "blurb": "حين أُغلقت المكتبة على بشرى بالخطأ، لم تكن تعلم أن الحروف تستيقظ إذا انطفأت الأنوار. والليلة، كلمةٌ عربية جميلة على وشك أن تختفي إلى الأبد.", "values": ["حبّ اللغة العربية", "الشجاعة", "الوفاء بالوعد"], "chapters": [{"title": "ليلُ المكتبة", "text": "لم يخبر أحدٌ بشرى أن للمكتبة ليلًا خاصًا بها، يبدأ حين تُطفأ أنوارها، حتى لو كانت الشمس في الخارج لم تغب بعد.\n\nكانت الحصة الأخيرة يوم الأربعاء حصة مطالعة، وكانت بشرى قد اختارت كعادتها الركن الضيق بين رفّ الموسوعات والنافذة، حيث لا يراها أحد، ويصل إليها ضوءٌ دافئ من بين الستائر. فتحت كتابًا قديمًا عن الرحّالة، وقرأت صفحة، ثم صفحتين، ثم بدأت السطور تتمايل أمام عينيها كأنها مراكب صغيرة على ماءٍ هادئ.\n\nآخر ما تذكّرته صوت الجرس، بعيدًا جدًا، كأنه يرنّ في مدرسةٍ أخرى.\n\nحين فتحت عينيها، كان المكان معتمًا. الستائر مُسدلة بالكامل، والمصابيح مطفأة، وصمتٌ ثقيل يملأ القاعة. نهضت بسرعة، فاصطدم كتفها بالرفّ، وسقط الكتاب من حجرها.\n\n«أستاذة حمدة؟»\n\nلا جواب.\n\nركضت إلى الباب، وأدارت المقبض. مقفل. طرقت عليه بكفّها، ثم بقبضتها، ونادت. لكن الممرّ في الخارج كان خاليًا، والمدرسة كلها قد انصرفت. وتذكّرت أن هاتفها في البيت، لأن الهواتف ممنوعةٌ في المدرسة، وأن أمّها تأتي لتأخذها كل يوم بعد الدوام بنصف ساعة لأنها تخرج من عملها متأخرة. لكنها لا تعرف كم الساعة الآن.\n\nجلست على الأرض، وظهرها إلى الباب، تحاول أن تتنفّس ببطء كما تعلّمت في درس الإسعافات الأولية: شهيق، ثم زفير. «سيأتي أحد. ستسأل أمّي عنّي. سيأتي أحد.»\n\nثم سمعت الصوت.\n\nحفيفٌ خفيف، كأن أحدًا يقلّب صفحة. ثم حفيفٌ آخر من الجهة المقابلة. ثم عشرات الحفيفات معًا، من كل الرفوف، كأن المكتبة كلها تتثاءب.\n\nتجمّدت بشرى في مكانها. ورأت، في الضوء الشحيح المتسرّب من تحت الباب، الكتاب الذي سقط منها ينفتح وحده على الأرض. ومن بين سطوره، انزلق حرفٌ صغير، حرف راء، وتمدّد على البلاط كقطٍّ يستيقظ من قيلولة، ثم زحف مبتعدًا تحت الرف.\n\nفركت عينيها. «ما زلتُ نائمة.»\n\n«لا، لستِ نائمة،» قال صوتٌ رفيع قريبٌ جدًا من أذنها. «لكنكِ نمتِ في الوقت المناسب تمامًا.»\n\nالتفتت بشرى ببطء. على كتفها، كانت تقف نقطةٌ سوداء صغيرة، بحجم حبّة عدس، لها عينان لامعتان، وكانت تقفز في مكانها من الحماسة.\n\n«أخيرًا!» قالت النقطة. «إنسانة! ننتظر واحدةً منذ سنوات!»"}, {"title": "المعجم الذي يتنفّس", "text": "قالت النقطة إن اسمها «نُقَيطة»، وإنها أسرع من في المكتبة، لأنها لا تنتمي إلى حرفٍ واحد. «أكون نقطة الباء صباحًا، ونقطة النون ظهرًا، وإذا مللتُ قفزتُ إلى الخاء.» ثم ضحكت ضحكةً تشبه طقطقة قلم.\n\nقادت نقيطة بشرى بين الرفوف. وكانت المكتبة قد صارت مكانًا آخر: حروفٌ تخرج من الكتب وتتجوّل على الرفوف، وبعضها يتسابق على حافة الطاولات، وفي ركن الروايات مجموعةٌ من الكلمات تتجادل بصوتٍ خافت حول أيّها أجمل. ومرّت بجانبهما فاصلةٌ عجوز منحنية الظهر، تمشي على مهل، وتتوقف بعد كل خطوة.\n\n«هذا العمّ فاصلة،» همست نقيطة. «لا تستعجليه. إنه يتوقف، دائمًا، في المكان، المناسب.»\n\nوصلتا إلى منصّةٍ خشبية في آخر القاعة، عليها معجمٌ ضخم بغلافٍ بنيٍّ متشقق، لم ترَه بشرى يُفتح يومًا. وكان المعجم... يتنفّس. ترتفع صفحاته وتهبط ببطء، كصدر جدٍّ نائم.\n\nقالت نقيطة: «يا شيخ المعاجم، جئتُ بالإنسانة.»\n\nانفتح المعجم وحده، وتقلّبت صفحاته حتى توقّفت عند صفحةٍ تغطيها طبقةٌ رمادية ناعمة كالرماد. وخرج منه صوتٌ عميق بطيء، كأنه قادمٌ من قاع بئر:\n\n«أهلًا بكِ يا ابنتي. انظري إلى هذا الموضع.»\n\nانحنت بشرى. وفي وسط الصفحة، تحت الغبار الرمادي، رأت مكانًا فارغًا، كأن كلمةً كانت هناك ثم اقتُلعت. وبجانبه سطرٌ باهت يكاد يختفي: «... فتورٌ يسبق النوم، وأوّله.»\n\n«هذه كلمة الوَسَن،» قال المعجم. «كلمةٌ قديمة جميلة، تصف اللحظة التي يثقل فيها الجفن ولم يأتِ النوم بعد. لكن أحدًا لم يستعملها منذ زمنٍ طويل. وحين تُهجَر الكلمة، يغطّيها غبار النسيان طبقةً بعد طبقة. والليلة صار الغبار ثقيلًا، فانفلتت حروفها الثلاثة من الصفحة، وتفرّقت في المكتبة.»\n\n«وماذا يحدث إن لم نجدها؟»\n\n«مع أول ضوءٍ يدخل هذه القاعة، تختفي الكلمة من كل كتابٍ فيها. ولا تعود.»\n\nنظرت بشرى إلى نقيطة. «ولماذا تحتاجونني أنا؟ أنتم تتحركون في كل مكان.»\n\nقالت نقيطة بصوتٍ أخفض: «لأن الحروف التائهة لا تعود بأمر حرفٍ مثلها. تعود فقط إذا ناداها من يتكلّم بها. وأنتِ يا بشرى... نمتِ هنا اليوم فوق كتابٍ قديم، وأنتِ تقاومين الوسن نفسه.»\n\nسرت في جسد بشرى قشعريرة. ثم سمعت المعجم يقول:\n\n«الواو في رفّ الشعر. والسين رأيتُها تهرب نحو كتب الرياضيات. أما النون، فلا أعرف أين ذهبت. أسرعي.»"}, {"title": "واوٌ وسين", "text": "كان رفّ الشعر أكثر الرفوف ضجيجًا. فالأبيات هناك لا تكفّ عن التمايل، والقوافي ترنّ كأجراسٍ صغيرة. وفي وسط ديوانٍ مفتوح، وجدت بشرى الواو: كانت قد علقت بين شطرين، وتتأرجح عليهما كأنهما حبلا أرجوحة، مغمضةَ العينين من المتعة.\n\nنادتها بشرى بلطف: «يا واو! الوسن يحتاجكِ.»\n\nفتحت الواو عينًا واحدة. «الوسن؟ لا أحد يتذكره. هنا على الأقل يردّدني الشعراء.»\n\nفكّرت بشرى لحظة. ثم قالت: «أنتِ واو العطف، تجمعين الأشياء معًا. فكيف تتركين أختيكِ وحدهما؟»\n\nتوقّفت الأرجوحة. نظرت الواو طويلًا إلى بشرى، ثم قفزت إلى كفّها، دافئةً كحبّة رملٍ في الظهيرة.\n\nأما السين، فوجدتاها في المكان الذي لم تتوقعه بشرى أبدًا: في كتاب الجبر للصف التاسع. كانت جالسةً في منتصف معادلةٍ طويلة، منتفخة الصدر، والأرقام تحيط بها من كل جانب.\n\nقالت السين بفخرٍ قبل أن يسألها أحد: «أنا هنا المجهول! الكل يبحث عني، والكل يريد أن يعرف قيمتي. أما في الوسن، فكنتُ حرفًا منسيًا في كلمةٍ منسية. فلماذا أعود؟»\n\nابتسمت بشرى رغمًا عنها. فهي تعرف هذه السين جيدًا، وقد قضت معها ليالي كثيرة تحاول أن تعرف قيمتها.\n\nقالت: «لن يمنعكِ أحدٌ من البقاء هنا. يمكنكِ أن تكوني مجهولًا في الجبر، ومعروفةً في الوسن. لكن إن اختفت الكلمة، ستفقدين بيتًا من بيوتك إلى الأبد.»\n\nسكتت السين. ثم قالت: «بشرط: أعود إلى هنا كل صباح.»\n\n«اتفقنا.»\n\nوضعت بشرى الواو والسين في جيب مريولها، فأحسّت بهما يتحرّكان كسمكتين صغيرتين. وقالت نقيطة: «بقيت النون.»\n\nبحثن في كل مكان: بين كتب التاريخ، وتحت طاولة الإعارة، وفي صندوق المجلات القديمة. ومرّ العمّ فاصلة بجانبهن، فتوقّف، وقال: «النون... رأيتُها، تصعد، نحو، الأعلى.»\n\nرفعت بشرى رأسها. في أعلى رفٍّ في المكتبة، الرفّ الذي لا يصل إليه أحدٌ دون السُّلّم الخشبي، كان هناك كتابٌ واحد لم ترَه قبل الليلة. كان رماديًا كله، كأنه منحوتٌ من الغبار نفسه. ومن بين صفحاته، يتسلّل ضوءٌ خافتٌ جدًا، يرتعش كشمعةٍ في الريح.\n\nقالت نقيطة بخوف: «ذلك كتابٌ لم يستعره أحدٌ منذ زمنٍ بعيد. والغبار هناك... لا يحب الزوّار.»\n\nوفي تلك اللحظة، سمعت بشرى من بعيد، خلف الباب، في آخر الممرّ، صوتًا تعرفه جيدًا: رنين مفاتيح."}, {"title": "غبار النسيان", "text": "«أسرعي!» صاحت نقيطة.\n\nجرّت بشرى السلّم الخشبي إلى الرف، وبدأت تصعد. كانت درجاته تئنّ تحت قدميها، وصوت المفاتيح في الممرّ يقترب ثم يبتعد، كأن صاحبه يبحث عن الباب الصحيح.\n\nحين وصلت إلى الرف الأعلى، مدّت يدها إلى الكتاب الرمادي، فارتفعت منه سحابةٌ ناعمة من الغبار ولامست وجهها.\n\nوفجأةً، ثقلت أجفانها.\n\nلم يكن نعاسًا عاديًا. كان شيئًا يشبه النسيان: نسيت لحظةً لماذا صعدت، ونسيت اسم النقطة التي على كتفها، وكادت تنسى اسمها هي. كانت الكلمات تتساقط من رأسها كما تتساقط حبّات الرمل من قبضةٍ مفتوحة.\n\n«بشرى! بشرى!» كانت نقيطة تقفز على أذنها. «لا تسكتي! الغبار يعيش على الصمت! تكلّمي! اقرئي!»\n\nاقرئي. تمسّكت بشرى بالكلمة كمن يتمسّك بحبل. فتحت الكتاب الرمادي بيدٍ مرتجفة، ونظرت في السطر الأول، وقرأت بصوتٍ مسموع، متقطّعٍ أولًا، ثم أوضح فأوضح.\n\nكان كتابًا قديمًا عن رحلات الصيادين في بحر العرب، فيه وصفٌ لليالٍ طويلة في القوارب، ولرياحٍ يعرفون أسماءها، ولنجومٍ يهتدون بها. ومع كل جملةٍ تقرؤها، كان الغبار ينفضّ عن الصفحة، ويتطاير في الهواء، ثم يتلاشى. وكانت الحروف تحته تلمع كأنها غُسلت للتو. وشيئًا فشيئًا، ارتخى النعاس عن جفنيها، وعاد إليها اسمها، واسم نقيطة، وسبب صعودها، كأن أحدًا يعيد الكتب إلى رفوفها داخل رأسها.\n\nوفي الصفحة الثالثة، وجدتها.\n\nكانت النون متكوّرةً في الهامش، تحت جملةٍ عن صيادٍ صغير يحرس الشباك تحت القمر حتى أوشك أن يغفو. كانت باهتةً جدًا، لا يكاد يُرى منها إلا قوسٌ رفيع ونقطةٌ مرتجفة، كأنها آخر ما بقي من الكلمة في المكتبة كلها.\n\nقالت بشرى بهدوء: «تعالي. أختاكِ تنتظرانكِ.»\n\nرفعت النون رأسها. ثم قفزت إلى كفّ بشرى، وكلما اقتربت من الواو والسين ازداد لونها سوادًا.\n\nنزلت بشرى السلّم وقلبها يدقّ، والحروف الثلاثة في يدها، وركضت نحو المعجم.\n\nلكن صوت المفاتيح كان قد توقّف عند الباب تمامًا. وسمعت بشرى المفتاح يدخل في القفل، ويدور مرة...\n\nقال المعجم بصوته العميق، دون عجلة: «ضعيها في مكانها. لكن اعلمي يا ابنتي: إعادة الحروف تنقذ الكلمة الليلة فقط. أما لتعيش، فلا بدّ أن يستعملها أحد. هل تَعِدين؟»"}, {"title": "وعد بشرى", "text": "«أعِد،» قالت بشرى بسرعة.\n\nوضعت الحروف الثلاثة في الفراغ الذي في الصفحة: الواو أولًا، ثم السين، ثم النون. وما إن استقرّت حتى أضاءت الكلمة بلونٍ ذهبيٍّ هادئ، وتطاير ما بقي من الغبار عن الصفحة كلها. وخرج من المعجم نفَسٌ طويل مرتاح، كأنه شيخٌ ألقى عن ظهره حملًا.\n\n«الوَسَن،» قرأت بشرى بصوتٍ مسموع. وشعرت بالكلمة دافئةً في فمها.\n\nوفي اللحظة نفسها، انفتح الباب.\n\nغمر ضوء الممرّ المكتبة، فإذا كل شيءٍ في مكانه: الكتب مصفوفة، والحروف نائمة في سطورها، والسلّم الخشبي مسنودٌ إلى الجدار كأن أحدًا لم يلمسه. ووقفت في الباب الأستاذة حمدة، أمينة المكتبة، وخلفها حارس المدرسة يحمل المفاتيح، وخلفهما أمّ بشرى بوجهٍ شاحب.\n\n«بشرى!» ركضت أمّها إليها وضمّتها. «اتصلتُ بالمدرسة حين لم أجدكِ عند البوابة!»\n\nقالت الأستاذة حمدة وهي تنظر إلى ساعتها بحيرة: «لم أقفل المكتبة إلا قبل خمسٍ وعشرين دقيقة. كيف لم أرَكِ؟»\n\nخمسٌ وعشرون دقيقة. نظرت بشرى إلى ساعة الحائط، ثم إلى المعجم المغلق على منصّته. كانت متأكدة أنها عاشت ليلةً كاملة.\n\nفي السيارة، لم تقل لأمّها شيئًا. لكنها حين فتحت كفّها، رأت على طرف إصبعها نقطةً سوداء صغيرة بحجم حبّة عدس، لم تستطع أن تمسحها. وبدا لها، إن لم تكن تتخيّل، أنها غمزت.\n\nفي اليوم التالي، طلبت معلمة اللغة العربية من الطالبات أن يكتبن فقرةً تصف لحظةً لا تُنسى. فكتبت بشرى عن فتاةٍ نامت في مكتبة، وبدأت فقرتها هكذا: «غلبني الوَسَن فوق كتابٍ قديم، وحين أفقتُ، كانت الحروف قد استيقظت قبلي.»\n\nتوقّفت المعلمة عند الكلمة، وسألت الصف عن معناها، فلم تعرفه أي طالبة. فشرحتها بشرى، ثم رأت شيئًا لم تتوقعه: أعجبت الكلمة البنات. وفي الفسحة، سمعت إحداهن تقول لصديقتها: «أصابني الوسن في حصة الكيمياء!» فضحكت الأخرى، وأعادت الكلمة.\n\nوفي الأسبوع التالي، اقترحت بشرى على الأستاذة حمدة أن تعلّق لوحةً صغيرة عند باب المكتبة، عنوانها: «كلمةٌ تنتظر من يتذكّرها». وكتبت تحتها أول كلمة: الوَسَن.\n\nوأحيانًا، حين تمرّ بالمكتبة بعد انصراف الطالبات، تسمع بشرى من خلف الباب حفيفًا خفيفًا، كأن أحدًا يقلّب صفحة، وضحكةً تشبه طقطقة قلم.\n\nفتبتسم، وتنظر إلى إصبعها، وتكتب في دفترها كلمةً أخرى تنتظر من ينقذها."}], "vocab": [{"w": "مُسْدَلة", "m": "مُرخاةٌ نازلةٌ إلى أسفل"}, {"w": "حَفيف", "m": "صوت الورق أو أوراق الشجر حين تتحرك"}, {"w": "الشَّحيح", "m": "القليل جدًا"}, {"w": "الوَسَن", "m": "فتورٌ يسبق النوم، وأوّل النوم"}, {"w": "قُشَعْريرة", "m": "رعشةٌ تصيب الجسد من خوفٍ أو برد"}, {"w": "تَئِنّ", "m": "تُصدر صوتًا يشبه الأنين"}, {"w": "يَنْفَضّ", "m": "يتفرّق ويزول"}, {"w": "مُتَكَوِّرة", "m": "منطويةٌ على نفسها كالكرة"}], "quiz": [{"q": "لماذا احتاجت الحروف إلى بشرى تحديدًا؟", "opts": ["لأنها أطول من الحروف وتصل إلى الرفوف العالية", "لأنها تحمل مفتاح المكتبة", "لأن الحروف التائهة لا تعود إلا إذا ناداها من يتكلّم بها"], "a": 2, "explain": "قالت نقيطة: «الحروف التائهة لا تعود بأمر حرفٍ مثلها. تعود فقط إذا ناداها من يتكلّم بها»."}, {"q": "أين وجدت بشرى حرف السين؟", "opts": ["في كتاب الجبر، حيث كان يمثّل المجهول", "في ديوان شعرٍ بين شطرين", "في المعجم الكبير"], "a": 0, "explain": "كانت السين في معادلةٍ بكتاب الجبر، فخورةً بأن الجميع يبحث عن قيمتها."}, {"q": "كيف تغلّبت بشرى على غبار النسيان؟", "opts": ["مسحته بكُمّ مريولها", "قرأت من الكتاب بصوتٍ مسموع", "أغمضت عينيها وانتظرت"], "a": 1, "explain": "صاحت نقيطة إن الغبار يعيش على الصمت، فقرأت بشرى بصوتٍ مسموع، فانفضّ الغبار."}, {"q": "ما الذي يجعل الكلمة تعيش حقًّا بحسب شيخ المعاجم؟", "opts": ["أن يستعملها الناس", "أن تُكتب بخطٍّ جميل", "أن توضع في أعلى رف"], "a": 0, "explain": "قال المعجم إن إعادة الحروف تنقذ الكلمة ليلةً فقط، أما لتعيش فلا بدّ أن يستعملها أحد."}], "discuss": ["اختاري كلمةً عربية جميلة قلّ استعمالها، واكتبي جملةً من حياتك اليومية تعيدها إلى الحياة.", "قالت السين إنها تفضّل أن تكون «المجهول» في الجبر. ماذا يعني أن يكون للإنسان أكثر من «بيت» ينتمي إليه؟"]}, {"id": "n10", "title": "فلج القرية", "genre": "مجتمع", "blurb": "حين تجفّ الساقية الشرقية في عزّ الصيف، تمتلئ السبلة بالاتهامات، ويطلب العريف ثلاثة أيامٍ فقط. ومعه حفيدته غالية، ودفتر، وعودٌ من جريد النخل.", "values": ["العدل", "الصبر وقوة الملاحظة", "التعاون"], "chapters": [{"title": "الساقية العطشى", "text": "أول من لاحظ أن الساقية الشرقية جفّت كانت عنزة.\n\nوقفت عند حافة القناة الحجرية الضيقة، وأنزلت رأسها لتشرب كما تفعل كل صباح، ثم رفعته ونظرت حولها بحيرة، وأطلقت ثغاءً طويلًا جعل غالية تترك سلّة الليمون وتركض نحوها.\n\nكانت القناة فارغة. لا ماء فيها، بل طينٌ رطب في قاعها، وأوراقٌ يابسة عالقة بين حجارتها. نظرت غالية إلى أعلى، حيث تنحدر الساقية من بين البيوت الطينية المتدرّجة على كتف الجبل، ثم إلى أسفل، حيث المدرّجات الخضراء التي تسقيها: نخيلٌ قصير، وأشجار ليمونٍ ورمّان، وحقلٌ صغير من البرسيم. كلها تنتظر.\n\nومن خلفها جاء صوت أمّ سعيد، جارتهم، عاليًا قلقًا: «جفّت؟ في نوبتنا؟ اليوم بالذات؟»\n\nبحلول الظهر، كانت القرية كلها تعرف. وبعد صلاة العصر، امتلأت السبلة بالرجال، واجتمعت النساء في البيت المجاور، والأبواب مفتوحة، فوصلت الأصوات إلى الجميع.\n\nجلست غالية قرب الباب، تحمل دلّة القهوة لجدّها. فجدّها حمد عريف الفلج منذ أكثر من ثلاثين سنة: يعرف نوبة كل بيت، ويفتح الماء ويغلقه، ويقرّر متى يُنظَّف الفلج ومتى يُصلَح.\n\nقال أبو سعيد بصوتٍ مرتفع: «الماء لا يختفي وحده! الساقية الشرقية تمرّ تحت مزارع بيت راشد. ومن يأخذ الماء ليلًا لا يراه أحد.»\n\nارتفعت همهمة. ونهض راشد، ووجهه محمرّ: «أتتّهمني يا أبا سعيد؟ ثلاثون سنة لم آخذ قطرةً ليست لي!»\n\n«فأين ذهب الماء إذن؟»\n\nارتفعت الأصوات وتداخلت، حتى صار الكلام كله ضجيجًا. وغالية تنظر إلى جدّها، الذي ظلّ جالسًا صامتًا، يحرّك حبّات مسبحته ببطء.\n\nثم رفع يده. فسكت الجميع.\n\nقال بهدوء: «لا نتّهم أحدًا بشيءٍ لم نره. أمهلوني ثلاثة أيام.»\n\nوفي طريق العودة إلى البيت، قال لغالية دون أن يلتفت إليها: «ستأتين معي غدًا قبل الفجر. وأحضري دفترك.»\n\nفي تلك الليلة، لم تستطع غالية أن تنام. صعدت إلى السطح تتأمل النجوم، كما تفعل في ليالي الصيف، والهواء الجبلي البارد يحمل رائحة النخيل المبلول. وبينما هي هناك، رأت ضوءًا صغيرًا يتحرك في الظلام، بين الأشجار، قرب الموضع الذي ينقسم عنده ماء الفلج.\n\nفانوس. وشخصٌ ينحني فوق الماء.\n\nحبست أنفاسها. كان الضوء آتيًا من جهة مزارع بيت راشد."}, {"title": "حقُّ الماء", "text": "حين أخبرت غالية جدّها بما رأت، لم يتفاجأ. قال فقط: «سنرى.»\n\nمشيا مع أول خيوط الضوء صعودًا، نحو المكان الذي يخرج منه الماء من بطن الجبل. كان الفلج هناك يجري في قناةٍ محفورة في الصخر، صافيًا باردًا، له صوتٌ يشبه حديثًا هامسًا لا ينقطع.\n\nتوقّف الجدّ عند أول موضعٍ تملأ منه النساء أوانيهن. «هذه الشريعة. أول الماء للشرب، قبل أي شيء. لا يُسقى نخلٌ ولا زرعٌ قبل أن يشرب الناس.»\n\nثم مشيا قليلًا، ومرّا بالمغاسل، ثم بمسجد القرية حيث يتوضأ المصلّون. «بعد الشرب، الطهارة. ثم الزرع. هذا ترتيبٌ لا يتغيّر، ولا يجادل فيه أحد.»\n\nجلست غالية على حجر، وفتحت دفترها، وصارت تكتب. وكان جدّها يتكلّم كمن يفتح خزانةً قديمة يعرف كل ما فيها: الماء مقسومٌ على البيوت بالأثر، والأثر نحو نصف ساعة، ولكل بيتٍ عددٌ من الآثار في كل دورة. في النهار، يعرف العريف الوقت بظلّ عودٍ مغروس في الأرض. وفي الليل، بالنجوم.\n\n«بالنجوم؟»\n\n«حين يطلع نجمٌ معيّن من خلف ذلك الجبل، تنتهي نوبة بيتٍ وتبدأ نوبة آخر. علّمني ذلك أبي، وعلّمه أبوه.» ثم أضاف: «وللفلج نفسه حصصٌ موقوفة، تؤجَّر كل سنة، ويُصرف ثمنها على صيانته. فالفلج مثل أهله: يأكل من تعبه.»\n\nوصلا أخيرًا إلى حجرٍ كبير مسطّح، ينقسم عنده الماء إلى ساقيتين: غربية وشرقية. هنا رأت غالية الفانوس البارحة.\n\nانحنى الجدّ، وتفحّص الحجارة الصغيرة التي توجّه الماء، ثم تفحّص الطين حولها. «لم يحرّكها أحد. والماء يدخل الشرقية كاملًا.»\n\nوكان صادقًا: رأت غالية الماء يندفع في الساقية الشرقية غزيرًا كما ينبغي.\n\nفي تلك اللحظة، ظهر من بين الأشجار فتى يحمل فانوسًا مطفأً. كان ناصر، ابن راشد، الذي يكبرها بسنتين.\n\nقال بارتباك: «يا عمّي العريف، جئتُ البارحة وجئتُ اليوم. أردتُ أن أتأكد بنفسي أن أحدًا لم يمسّ القسمة. أبي لم ينم من الهمّ.»\n\nربت الجدّ على كتفه: «بارك الله فيك. والآن عرفنا أمرًا مهمًا: الماء يخرج من هنا سليمًا.»\n\nنظرت غالية إلى الساقية الشرقية، وهي تبتعد بين الصخور نحو مدرّجات أبي سعيد، ثم سألت السؤال الذي كان يدور في رؤوس الثلاثة:\n\n«إذا كان الماء يدخلها كاملًا... فأين يختفي قبل أن يصل؟»"}, {"title": "ما تقوله الأرض", "text": "قال الجدّ: «الجواب في الطريق بين هنا وهناك. والطريق لا يتكلّم إلا مع من يصبر عليه.»\n\nثم عاد إلى القرية لشأنٍ آخر، وترك غالية مع دفترها وعودٍ طويل من جريد النخل.\n\nكانت فكرتها بسيطة: أن تقيس. مشت مع الساقية، وكل عشرين خطوة تغمس العود في الماء، وتعلّم بظفرها مكان سطحه، ثم تكتب ما تجده في الدفتر. عند القسمة، غطّى الماء ثلاثة أصابع من العود. وبعد مئة خطوة، ثلاثة أصابع أيضًا. وبعد مئتين، ثلاثة.\n\nوعند منعطفٍ تظلّله سدرةٌ عجوز ضخمة، صار الماء إصبعين. وبعد ذلك، إصبعًا واحدًا. ثم لا شيء تقريبًا: خيطٌ رفيع يلمع بين الحصى ثم يغوص.\n\nجلست غالية عند السدرة. كان الحرّ قد اشتدّ، والذباب يحوم، ولم يكن هناك ما يُرى: قناةٌ من الحجارة والصاروج، نصفها مغطّى بأوراق السدر اليابسة، والماء يجري فيها ثم يقلّ. لا ثقب، ولا شقّ، ولا شيء.\n\nكادت تنهض وتعود. لكنها تذكّرت جدّها جالسًا في السبلة، يحرّك مسبحته، لا يقول شيئًا والجميع يصرخون. فبقيت.\n\nمرّت ساعة. ثم أخرى. أكلت تمرتين من جيبها، وشربت من قارورتها، وراقبت.\n\nوبدأت ترى أشياء لم ترها في الدقائق الأولى.\n\nرأت أن الأوراق اليابسة التي تطفو على الماء تجري مستقيمةً حتى السدرة، ثم تدور قليلًا في موضعٍ واحد، كأن شيئًا تحت الماء يجذبها، ثم تكمل طريقها.\n\nورأت، أسفل الساقية، على المنحدر الصخري الجاف الذي لا يسقيه أحد، بقعةً صغيرة خضراء: عشبًا طريًّا، وسرخسًا صغيرًا، وطحالب على الصخر. خضرةٌ لا معنى لها في مكانٍ لا ماء فيه.\n\nنزلت إليها بحذر. كانت الأرض تحت قدميها رطبة، لها رائحة الطين بعد المطر، مع أن السماء لم تمطر منذ شهرين. وقفزت ضفدعةٌ صغيرة من بين العشب، واختفت بين الحجارة.\n\nرفعت غالية رأسها نحو السدرة. كانت جذورها الغليظة تمتدّ تحت الساقية كأصابع يدٍ ضخمة تقبض عليها. ومن بين جذرين، تحت حافة القناة، رأت شقًّا رفيعًا مظلمًا يكاد لا يُرى، وسمعت منه صوتًا خافتًا جدًا.\n\nصوت ماءٍ يقطر في الظلام.\n\nفتحت دفترها بأصابع مرتجفة، ورسمت السدرة، والشقّ، والبقعة الخضراء، ووصلت بينها بسهم."}, {"title": "شاهدٌ لا يكذب", "text": "ركضت غالية إلى القرية، ودفترها في يدها، ووجدت جدّها في السبلة. ولم يكن وحده: كان أبو سعيد هناك، وراشد، وعددٌ من الرجال، والكلام قد عاد يعلو.\n\n«ثلاثة أيام؟» كان أبو سعيد يقول. «زرعي سيموت قبل ذلك! أقترح أن نغلق ساقية بيت راشد حتى يظهر الماء.»\n\nقال راشد بغضب: «وبأي حقٍّ تغلق مائي؟»\n\nاقتربت غالية من جدّها، وهمست في أذنه. فاستمع، ثم نظر في الدفتر، وقلّب صفحاته ببطء، وتوقّف عند الأرقام والرسم. ثم أغلقه، ونهض.\n\nقال: «لا حاجة إلى ثلاثة أيام. تعالوا معي. كلّكم.»\n\nمشى الرجال خلفه، وبعضهم يتذمّر، حتى وصلوا إلى السدرة العجوز. وهناك، وقف الجدّ جانبًا، وقال: «أريهم يا غالية.»\n\nشعرت غالية بكل العيون عليها. أخذت نفسًا، وتذكّرت أن الأرقام في دفترها لا تخاف. التقطت حفنةً من أوراق السدر اليابسة، وألقتها في الماء عند أعلى المنعطف. فجرت الأوراق، ثم دارت عند الموضع نفسه، وانجذبت إحداها إلى حافة القناة والتصقت بها.\n\n«هنا يدخل الماء،» قالت غالية بصوتٍ أقوى مما توقّعت. «جذور السدرة شقّت الصاروج تحت القناة، والماء يتسرّب إلى داخل الجبل.» ثم أشارت إلى أسفل المنحدر. «وهناك يخرج.»\n\nنظر الرجال إلى البقعة الخضراء الغريبة على الصخر الجاف. ونزل أحدهم إليها، ثم صاح: «الأرض مبلولة!»\n\nثم فتحت الدفتر: «قِستُ الماء كل عشرين خطوةً من القسمة إلى هنا. لا ينقص شيءٌ حتى السدرة، ثم يذهب كله تقريبًا.»\n\nساد صمتٌ طويل، لم يُسمع فيه إلا صوت الماء يقطر في الشق.\n\nقال الجدّ أخيرًا: «الماء لم يسرقه أحد. شربه الجبل.»\n\nالتفت أبو سعيد ببطء إلى راشد. كان وجهه قد تغيّر، وصار فيه شيءٌ من الخجل. ثم تقدّم إليه، ومدّ يده: «يا راشد... سامحني. العطش يُعمي.»\n\nتردّد راشد لحظةً، ثم أمسك يده، وضمّه. «سامحك الله. ولو كنتُ مكانك، لربما قلتُ أكثر.»\n\nووقف ناصر خلف أبيه، ونظر إلى غالية، وابتسم ابتسامةً فيها شكرٌ كثير.\n\nلكن الجدّ كان قد انحنى عند الجذور، يتفحّص الشقّ بأصابعه. ثم قال بجدّية: «الشقّ أكبر مما يبدو، والجذر الذي صنعه أكبر من الشق. هذا عملٌ لا يقوم به رجلٌ واحد.»\n\nورفع رأسه نحو الجميع: «غدًا بعد الفجر، فزعة.»"}, {"title": "الفزعة", "text": "لم يتأخّر أحد.\n\nمع أول ضوء، كانت القرية كلها عند السدرة: الرجال يحملون المعاول والمجارف وأكياس الصاروج، والشباب يحملون الماء والحجارة، والنساء أعددن القهوة والتمر وقدرًا كبيرة من الهريس. حتى الأطفال جاؤوا، يجمعون الأوراق اليابسة من القناة.\n\nأغلق الجدّ الماء عن الساقية الشرقية من عند القسمة، وحوّله كله إلى الغربية مؤقتًا، بعد أن استأذن أصحابها. «سنردّ لكم ما أخذنا من نوبةٍ قادمة،» قال، فهزّوا رؤوسهم موافقين.\n\nثم بدأ العمل. كشفوا الشق، فإذا هو يمتدّ تحت القناة أطول من ذراع، وجذر السدرة الغليظ قد التفّ تحته كأفعى نائمة.\n\nقال أحد الشباب: «نقطع السدرة كلها، ونرتاح.»\n\nلكن الجدّ هزّ رأسه. «هذه السدرة أقدم من أبي، وظلّها على الساقية يحفظ الماء من الشمس. نقطع الجذر الذي آذى القناة، ونترك الشجرة.»\n\nفقطعوا الجذر بحذر، ونظّفوا الشق، ثم ملؤوه بالحجارة الصغيرة، وطلوه بالصاروج الطري، طبقةً بعد طبقة. وكانت غالية تناولهم الماء، وتراقب يد جدّها وهي تمسح الصاروج بخبرة سنين طويلة. ورأت أبا سعيد وراشد يحملان حجرًا كبيرًا معًا، ويضحكان من شيءٍ قاله أحدهما.\n\nعند العصر، فتح الجدّ الماء من جديد.\n\nوقفت غالية بجانب السدرة تنتظر. وسمعت الماء قبل أن تراه: الصوت الهامس نفسه، يقترب بين الصخور. ثم ظهر، ومرّ فوق الصاروج الجديد دون أن يدور أو يتوقف، وأكمل طريقه نحو المدرّجات.\n\nغمست عود الجريد. ثلاثة أصابع.\n\nصفّق الأطفال، وكبّر بعض الرجال، وأطلقت عنزةٌ في الأسفل ثغاءً طويلًا، فضحك الجميع.\n\nفي تلك الليلة، صعدت غالية مع جدّها إلى السطح. كانت السماء صافية، والنجوم كثيفةً كأنها حبّات ملحٍ منثورة على قماشٍ أسود. قال الجدّ: «رأيتِ ما لم يره الرجال، لأنكِ لم تستعجلي. والعريف لا يحتاج إلى صوتٍ عالٍ، بل إلى عينٍ صبورة، وقلبٍ لا يميل إلى أحد.»\n\nثم أشار إلى نجمٍ يطلّ من خلف الجبل: «انظري. حين يرتفع هذا فوق تلك القمة، تنتهي نوبة بيت راشد، وتبدأ نوبة بيت أبي سعيد.»\n\nفتحت غالية دفترها على صفحةٍ جديدة، وكتبت تحت ضوء القمر عنوانًا كبيرًا: «جدول ماء القرية». ثم رسمت الجبل، ورسمت فوقه النجمة الأولى."}], "vocab": [{"w": "ثُغاء", "m": "صوت الماعز والغنم"}, {"w": "المُدَرَّجات", "m": "أراضٍ زراعية على هيئة درجاتٍ في سفح الجبل"}, {"w": "السَّبْلة", "m": "مجلسٌ عام يجتمع فيه أهل القرية للتشاور والضيافة"}, {"w": "الشَّريعة", "m": "الموضع الذي يُؤخذ منه ماء الشرب من الفلج قبل أي استعمال آخر"}, {"w": "الأَثَر", "m": "وحدةٌ زمنية يُوزَّع بها ماء الفلج، مقدارها نحو نصف ساعة"}, {"w": "الصّاروج", "m": "مادة بناءٍ عُمانية تقليدية من طينٍ محروقٍ مطحون، تُبطَّن بها الأفلاج"}, {"w": "السَّرْخَس", "m": "نباتٌ ينمو في الأماكن الرطبة، أوراقه تشبه الريش"}, {"w": "الفَزْعة", "m": "اجتماع الناس لمساعدة بعضهم في عملٍ كبير"}], "quiz": [{"q": "بأي ترتيبٍ يُوزَّع ماء الفلج كما شرح الجدّ؟", "opts": ["الزرع أولًا، ثم الشرب، ثم الطهارة", "الشرب أولًا، ثم الطهارة، ثم الزرع", "الطهارة أولًا، ثم الزرع، ثم الشرب"], "a": 1, "explain": "قال الجدّ عند الشريعة: «أول الماء للشرب»، ثم الطهارة، ثم الزرع، وهذا ترتيبٌ لا يتغيّر."}, {"q": "لماذا كان ناصر يحمل فانوسًا عند القسمة ليلًا؟", "opts": ["ليتأكد أن أحدًا لم يمسّ القسمة، فيطمئن أباه", "ليحوّل الماء إلى مزرعتهم", "ليبحث عن عنزةٍ ضائعة"], "a": 0, "explain": "قال ناصر للعريف إنه أراد أن يتأكد بنفسه أن أحدًا لم يمسّ القسمة، لأن أباه لم ينم من الهمّ."}, {"q": "ما الدليل الذي دلّ غالية على أن الماء يخرج أسفل السدرة؟", "opts": ["ضوء الفانوس ليلًا", "ثغاء العنزة", "بقعةٌ خضراء رطبة على منحدرٍ جاف لا يسقيه أحد"], "a": 2, "explain": "لاحظت عشبًا وسرخسًا وأرضًا رطبة في مكانٍ لم يمطر منذ شهرين، فعرفت أن الماء المتسرّب يخرج هناك."}, {"q": "لماذا رفض الجدّ قطع السدرة كلها؟", "opts": ["لأنها قديمة، وظلّها يحفظ ماء الساقية من الشمس", "لأنها ملكٌ لبيت راشد", "لأن قطعها يحتاج إلى أيامٍ كثيرة"], "a": 0, "explain": "قال الجدّ: «هذه السدرة أقدم من أبي، وظلّها على الساقية يحفظ الماء من الشمس»، فاكتفوا بقطع الجذر المؤذي."}], "discuss": ["قال الجدّ: «لا نتّهم أحدًا بشيءٍ لم نره». كيف كانت ستنتهي القصة لو أُغلقت ساقية بيت راشد؟", "ما الذي يجعل نظام توزيع ماء الفلج عادلًا في رأيك؟ وأين يمكن أن نطبّق فكرة «الحقّ قبل القوة» في حياتنا المدرسية؟"]}, {"id": "n11", "title": "ساعة بلا هاتف", "genre": "أسرة", "blurb": "ساعة واحدة كل مساء بلا هواتف… بدت لملاك عقوبة لا تُحتمل. لكنّ الصمت الذي خافت منه كان يخبّئ أسرارًا عن أهلها، ودفترًا أزرق لم يره أحد.", "values": ["التواصل الأسري", "الإصغاء للآخرين", "الشجاعة في إظهار الموهبة"], "chapters": [{"title": "سلّة من سعف", "text": "لم تكن ملاك تعرف أن جملةً واحدة يقولها أبوها بين لقمتين ستقلب أمسياتها رأسًا على عقب. كانت عيناها على شاشة هاتفها، وإبهامها يقفز بين الرسائل، حين وضع أبوها ملعقته جانبًا وقال بصوت هادئ: «ابتداءً من الليلة، عندنا تحدٍّ عائلي».\n\nرفعت ملاك رأسها ببطء، كما يرفع المرء رأسه حين يشمّ رائحة خطر. كانت أمها تبتسم ابتسامة من يعرف السرّ مسبقًا، وأخوها يوسف ذو الأعوام الثمانية منشغل بتقطيع حبة طماطم إلى مكعبات صغيرة متساوية.\n\nأكمل الأب: «ساعة كل مساء، من الثامنة إلى التاسعة، بلا هواتف. لا هاتف ولا جهاز لوحي ولا تلفاز. نضعها كلها في هذه». وأخرج من تحت الطاولة سلّة من سعف النخيل، من تلك التي تبيعها النساء في سوق نزوى صباح الجمعة.\n\nعرفت ملاك السلّة فورًا؛ كانت جدّتها قد أهدتها لأمها، وظلّت معلّقة في المطبخ سنوات فارغة لا يُوضع فيها شيء.\n\n«ساعة كاملة؟» قالت ملاك، وكأنها تقول: سنة كاملة؟ «يا أبي، مجموعة الصف تتناقش في مشروع العلوم كل مساء، وصديقاتي سيظنّن أنني اختفيت!»\n\n«سيعرفن أنك بخير إذا أخبرتِهنّ قبل الثامنة» قالت الأم وهي تصبّ الشاي بالحليب في الأكواب. «وأنا أيضًا سأضع هاتفي. وأبوك سيضع هاتفه، مع أن هاتفه هو الأصعب فراقًا».\n\nضحك الأب وأومأ معترفًا. أما يوسف فقد رفع يده كما يفعل في الفصل وسأل: «وماذا نفعل في الساعة؟»\n\n«هذا ما سنكتشفه معًا» قال الأب.\n\nلم تقتنع ملاك. أمضت ما بقي من العشاء تحسب في رأسها: ساعة في اليوم، يعني سبع ساعات في الأسبوع، يعني نحو ثلاثين ساعة في الشهر، تضيع في... في ماذا؟ في التحديق في الجدران؟\n\nفي الثامنة إلا دقيقة، وقفت أمام السلّة وهاتفها في يدها. كان على الشاشة إشعار جديد من صديقتها شهد: «لن تصدّقي ما حدث اليوم!» نظرت إلى الإشعار، ثم إلى السلّة، ثم إلى أبيها الذي وضع هاتفه أولًا بحركة مسرحية، كأنه يسلّم سيفه في نهاية معركة.\n\nأسقطت ملاك هاتفها في السلّة كمن يودّع صديقًا على رصيف ميناء، وجلست على الكنبة وذراعاها معقودتان على صدرها. ودقّت ساعة الحائط ثماني دقّات.\n\nوبدأت أطول ساعة في حياتها."}, {"title": "القفزة فوق الفلج", "text": "مرّت الدقائق الأولى ثقيلة كأنها تمشي حافية على رمل الظهيرة. عدّت ملاك بلاطات الأرض: أربع وعشرون. عدّت النقوش على الستارة. وسمعت للمرة الأولى طنين المكيّف الخفيف، وصوت عقرب الثواني يتقدّم كأنه يتعمّد البطء.\n\n«أنا أشعر بالملل» أعلنت بصوت عالٍ، لعلّ أحدًا يرحمها ويعيد إليها هاتفها.\n\nلكن أمها كانت قد عادت من غرفة التخزين تحمل لوح «الكيرم» الخشبي الكبير، وقد علاه غبار خفيف. «متى آخر مرة لعبنا هذه؟»\n\nفكّر الأب ثم قال: «قبل أن يولد يوسف، على ما أظن».\n\nوُضع اللوح على السجادة، ورُشّ عليه مسحوق ناعم لتنزلق الأقراص، واصطفّت الأقراص السوداء والبيضاء في الوسط. لم تكن ملاك تنوي اللعب، لكنها وجدت نفسها تصحّح لأبيها طريقة إمساكه بالقرص الضارب، لأنه كان يمسكه «كمن يمسك قلم رصاص» كما قالت.\n\nوفي منتصف الجولة الثانية، حين أخطأ الأب ضربة سهلة، قالت الأم ضاحكة: «يداك ترتجفان مثل يوم سقطتَ في الفلج».\n\nتوقّف كل شيء. «سقط في الفلج؟» صاحت ملاك ويوسف معًا.\n\nتنهّد الأب تنهيدة من انكشف سرّه، ثم حكى. كان في العاشرة، في قريته قرب الحمراء، وكان يتباهى أمام أولاد الحارة بأنه يستطيع القفز فوق ساقية الفلج من أوسع موضع فيها. أخذ مسافة طويلة، وركض، وقفز... وهبط في منتصف الماء تمامًا، بجوار عمّه الذي كان جالسًا على الحافة يتوضّأ.\n\n«ابتلّ عمّي حتى عمامته» قال الأب، فانفجر الجميع ضحكًا. «ولم يغضب، بل قال لي: يا ولد، الفلج لا يُقفز عليه، الفلج يُحترم. ثم ألزمني أن أنظّف الساقية معه أسبوعًا كاملًا، من أول الحارة إلى آخرها».\n\nضحكت ملاك حتى دمعت عيناها. لم تتخيّل يومًا أن أباها، بنظّارته ووقاره واجتماعاته التي لا تنتهي، كان طفلًا مبلّلًا يحمل مكنسة من سعف ويكنس الطحالب من قاع ساقية.\n\nحين دقّت الساعة التاسعة، انتبهت ملاك أنها لم تنظر إليها منذ نصف ساعة على الأقل. ركضت إلى السلّة وأخرجت هاتفها، ثم التفتت لتقول شيئًا ليوسف، فلم تجده.\n\nكان قد انسلّ من الغرفة دون أن يشعر به أحد، وعلى الكنبة حيث كان يجلس، ترك دفترًا صغيرًا بغلاف أزرق."}, {"title": "الوجه الناقص", "text": "لم تكن ملاك من النوع الذي يقرأ دفاتر غيرها. حملت الدفتر الأزرق لتعيده إلى غرفة يوسف، لكنه انزلق من يدها وانفتح على الأرض، فرأت وجهها.\n\nكان رسمًا بقلم الرصاص لفتاة جالسة على الكنبة، ركبتاها مضمومتان، ورأسها منحنٍ نحو مستطيل صغير بين يديها. الظلال تحت عينيها، والخصلة التي تفلت دائمًا من شعرها، حتى الجورب المثقوب عند الإصبع الكبير... كل شيء كان هناك. لكن الغريب أن الوجه لم يكن مرسومًا بالكامل؛ كان نصفه مضاءً بضوء الشاشة، ونصفه الآخر فارغًا، كأن الرسّام لم يرَه قط.\n\nأغلقت الدفتر بسرعة، وقلبها يدقّ. ذهبت إلى غرفة يوسف، فوجدته يرتّب سيّاراته الصغيرة في صفّ مستقيم.\n\n«يوسف، دفترك سقط مني وانفتح. رأيت صفحة واحدة فقط، أعدك. هل... هل تسمح لي أن أرى الباقي؟»\n\nاحمرّت أذناه، وتردّد طويلًا، ثم هزّ كتفيه: «إذا لم تضحكي».\n\nجلست بجانبه على السرير، وقلّبت الصفحات ببطء. كان في الدفتر أكثر من أربعين رسمًا. أبوها نائمًا على الكرسي وهاتفه على صدره. أمها في المطبخ تقلّب القدر بيد وتكتب رسالة باليد الأخرى. جدّتهم في زيارتها الأخيرة، تحدّق في تلفاز بلا صوت. وقطّة الجيران على السور. كلها مرسومة بإتقان لا يُصدَّق لطفل في الصف الثالث: الخطوط واثقة، والظلال ناعمة، والتفاصيل الصغيرة صادقة إلى حدّ مؤلم.\n\n«منذ متى ترسم؟»\n\n«منذ زمن» قال يوسف وهو ينظر إلى سيّاراته. «حين تكونون كلكم على هواتفكم، لا يكلّمني أحد، فأرسمكم. أنتم لا تتحرّكون كثيرًا، وهذا يسهّل الرسم».\n\nقالها ببساطة، بلا عتاب، لكن الجملة نزلت على قلب ملاك كحجر يسقط في بئر عميقة. تذكّرت كم مرة جاءها يسألها شيئًا فقالت له «لاحقًا» دون أن ترفع عينيها عن الشاشة.\n\n«ولماذا وجهي غير مكتمل؟»\n\nنظر إليها أخيرًا. «لأنني لا أراه. أنتِ دائمًا تنظرين إلى الأسفل».\n\nلم تجد ملاك ما تقوله. ظلّت صامتة لحظة طويلة، ثم رفعت رأسها، وجلست مستقيمة، ونظرت إليه مباشرة، كما لم تنظر إليه منذ شهور.\n\n«ارسمه الآن إذن».\n\nابتسم يوسف ابتسامة واسعة كشفت عن سنّه المكسورة، وأخرج قلمه من جيبه. وفي تلك الليلة، لم تفتح ملاك هاتفها مرة أخرى قبل النوم."}, {"title": "صوت في شريط قديم", "text": "في الأمسيات التالية، صارت الساعة الثامنة موعدًا ينتظره الجميع، وإن لم تعترف ملاك بذلك. كانت لا تزال تتأفّف قليلًا وهي تضع هاتفها في السلّة، لكن تأفّفها صار أقصر، وخطواتها نحو الكنبة أسرع.\n\nفي الليلة الخامسة، قالت الأم: «الليلة دوري في الحكايات». ودخلت غرفتها، ثم عادت بصندوق معدني قديم عليه صورة باهتة لزهور. فتحته، فإذا فيه أشرطة كاسيت مرتّبة، ومسجّل صغير بلون فضّي.\n\n«ما هذا؟» سأل يوسف، وهو يقلّب شريطًا بين أصابعه كأنه قطعة أثرية من متحف.\n\n«هذا ما كنا نسجّل فيه أصواتنا قبل الهواتف» قالت الأم، ثم أضافت بنبرة فيها خجل: «كنتُ مذيعة الإذاعة المدرسية ثلاث سنوات متتالية».\n\nلم تصدّق ملاك. أمها الهادئة، التي تتحدث بصوت خفيض في المجالس، كانت تقف كل صباح أمام مئات الطالبات؟\n\nضغطت الأم زرّ التشغيل، فخرج صوت فتاة واثق يملؤه الحماس: «صباح الخير يا مدرستي الحبيبة! فقرتنا الأولى: هل تعلمين؟ هل تعلمين أن الجمل يستطيع أن يشرب أكثر من مئة لتر من الماء في عشر دقائق؟» ثم سكت الصوت لحظة، وتابع بارتباك: «عفوًا، أقصد... في عشر ثوانٍ!» وانطلقت ضحكات الطالبات في الخلفية.\n\nانقلب يوسف على ظهره من الضحك، والأم تغطّي وجهها بيديها: «والمصيبة أن المعلومة الأولى هي الصحيحة! صحّحتُ الصواب إلى خطأ أمام المدرسة كلها. لهذا خبّأت الشريط عشرين سنة».\n\nلكن قبل أن ينتهي الشريط، جاء صوت آخر، صوت رجل عميق ودافئ: «أحسنتِ يا بنتي. صوتك نور». كان جدّهم، رحمه الله، قد سجّل الجملة في آخر الشريط ذات مساء، كما شرحت الأم بصوت خافت، وظلّت هي تعيد سماعها كلما خافت من شيء.\n\nساد صمت دافئ. مدّت ملاك يدها وأمسكت يد أمها. لم تكن تعرف أن أمها خافت من شيء يومًا.\n\nوفي آخر السهرة، أخذت ملاك أباها جانبًا وأخرجت ورقة مطويّة: إعلان عن مسابقة رسم لطلاب المدارس في الولاية، آخر موعد للمشاركة بعد أسبوعين. «يوسف يجب أن يشارك» همست.\n\nلكن يوسف كان قد سمع. وقف عند الباب، ووجهه شاحب، وقال بصوت مرتجف: «لا. لن يرى أحد رسوماتي. أبدًا»."}, {"title": "الصفقة", "text": "لم يكلّم يوسف أحدًا في اليوم التالي. وحين جاءت الساعة الثامنة، جلس في زاوية الكنبة يضمّ دفتره إلى صدره كأن أحدًا سيخطفه منه.\n\nفهمت ملاك خوفه أكثر مما توقّعت. فهي أيضًا تخبّئ شيئًا: مقالات قصيرة تكتبها في مذكّرة هاتفها، لم يقرأها أحد قط، لأن فكرة أن يقرأها أحد ثم يصمت كانت تخيفها أكثر من أي امتحان.\n\nجلست بجانبه وقالت: «أعرف شعورك. هل نعقد صفقة؟»\n\nنظر إليها بطرف عينه.\n\n«تشارك أنت في المسابقة برسمة واحدة فقط، تختارها بنفسك. وأنا أقرأ أحد مقالاتي في الإذاعة المدرسية يوم الأحد. أمام الجميع».\n\nسمعت شهقة خفيفة من المطبخ، وأدركت أن أمها كانت تصغي. أما يوسف ففكّر طويلًا، طويلًا جدًا، ثم مدّ يده الصغيرة: «صفقة. لكن أنا أختار الرسمة، ولا يتدخّل أحد».\n\nطوال الأسبوعين التاليين، كان يوسف يرسم خلال ساعة المساء، ويغطّي الورقة بذراعه كلما اقترب أحد. وكانت ملاك تتدرّب على مقالها بصوت مرتفع أمام المرآة، وأمها تعلّمها أين تتنفّس وأين تتمهّل، وتقول لها: «الخوف لا يختفي يا ملاك، لكنه يقبل أن يجلس في المقعد الخلفي».\n\nيوم الأحد، وقفت ملاك أمام الميكروفون في الطابور الصباحي، وركبتاها ترتجفان، وقرأت مقالها: «الأشياء التي لا نراها لأننا لا نرفع رؤوسنا». لم يصمت أحد بعدها. صفّقت الطالبات، وجاءت معلمة اللغة العربية تطلب نسخة منه لمجلة المدرسة.\n\nوبعد ثلاثة أسابيع، وقفت الأسرة كلها في قاعة المركز الثقافي بالولاية، أمام لوحة صغيرة معلّقة بين عشرات اللوحات، وتحتها بطاقة كُتب عليها: «الساعة الثامنة — يوسف، الصف الثالث — تنويه خاص من لجنة التحكيم».\n\nفي اللوحة، أربعة أشخاص يجلسون حول لوح كيرم، يضحكون، ورؤوسهم مرفوعة، ينظر بعضهم إلى بعض. وفي الزاوية سلّة من سعف النخيل تمتلئ بهواتف مطفأة. وكان وجه الفتاة في اللوحة مكتملًا تمامًا، بعينين لامعتين وابتسامة واسعة.\n\nوقف الأب أمام اللوحة طويلًا دون أن يقول شيئًا، ثم خلع نظّارته ومسحها، مع أنها لم تكن متّسخة. أما يوسف فكان يشدّ طرف ثوب أخته ويهمس: «رأيتِ؟ وجهك هذه المرة كامل».\n\nفي تلك الليلة، اهتزّ هاتف ملاك داخل السلّة في الثامنة والنصف. نظرت إليه لحظة، ثم عادت إلى لوح الكيرم.\n\n«دورك يا أبي. وأمسك القرص جيدًا هذه المرة»."}], "vocab": [{"w": "سَعَف", "m": "أوراق النخل وجريدها، تُصنع منها السلال والحُصُر"}, {"w": "الفَلَج", "m": "قناة ماء تقليدية في عُمان تنقل الماء إلى القرى والمزارع"}, {"w": "سَاقِيَة", "m": "مجرى صغير مكشوف يسير فيه الماء"}, {"w": "وَقَار", "m": "رزانة وهيبة وهدوء في السلوك"}, {"w": "تَأَفُّف", "m": "إظهار الضيق والتذمّر بالصوت"}, {"w": "انْسَلَّ", "m": "خرج خفيةً وبهدوء دون أن يُلحظ"}, {"w": "بَاهِتَة", "m": "ذهب لونها أو ضعف"}, {"w": "تَنْوِيه", "m": "إشادة وذكر بالثناء"}], "quiz": [{"q": "لماذا كان وجه ملاك في رسمة يوسف غير مكتمل؟", "opts": ["لأن يوسف لم يكمل الرسمة لضيق الوقت", "لأن ملاك كانت دائمًا تنظر إلى الأسفل نحو هاتفها", "لأن القلم انكسر أثناء الرسم"], "a": 1, "explain": "قال يوسف: «لأنني لا أراه. أنتِ دائمًا تنظرين إلى الأسفل»."}, {"q": "ما الخطأ المضحك الذي وقعت فيه الأم في الإذاعة المدرسية؟", "opts": ["صحّحت معلومة صحيحة فحوّلتها إلى خطأ", "نسيت اسم المدرسة", "قرأت الفقرة نفسها مرتين"], "a": 0, "explain": "قالت إن الجمل يشرب أكثر من مئة لتر في عشر دقائق، ثم «صحّحتها» إلى عشر ثوانٍ، والأولى هي الصحيحة."}, {"q": "ما الصفقة التي عقدتها ملاك مع يوسف؟", "opts": ["أن تعيد إليه هاتفه إن رسمها", "أن يلعبا الكيرم كل ليلة", "أن يشارك في المسابقة وتقرأ هي مقالها في الإذاعة"], "a": 2, "explain": "اتّفقا على أن يشارك يوسف برسمة يختارها، وتقرأ ملاك مقالها أمام الجميع."}, {"q": "ماذا فعلت ملاك حين اهتزّ هاتفها في السلّة في آخر الرواية؟", "opts": ["ركضت إليه فورًا", "نظرت إليه لحظة ثم عادت إلى اللعب", "أطفأته وغادرت الغرفة"], "a": 1, "explain": "نظرت إليه لحظة ثم عادت إلى لوح الكيرم، علامة على تغيّرها."}], "discuss": ["قال يوسف إنه يرسم أهله لأنهم «لا يتحرّكون كثيرًا». ماذا تكشف هذه الجملة البسيطة عن مشاعره؟ وهل يوجد في أسرتك من يحتاج إلى من يرفع رأسه إليه؟", "قالت الأم: «الخوف لا يختفي، لكنه يقبل أن يجلس في المقعد الخلفي». ما معنى ذلك؟ وهل مررتِ بموقف تجاوزتِ فيه خوفك دون أن يزول تمامًا؟"]}, {"id": "n12", "title": "طريق البخور", "genre": "تاريخية", "blurb": "قبل قرون، تخرج زهرة مع أبيها تاجر اللبان في قافلة تشقّ الرمال شمالًا من ظفار. وحين تمحو العاصفة كل أثر، وتعجز أعين الرجال عن الطريق، لا يبقى إلا ما تعلّمته زهرة من السماء.", "values": ["دقّة الملاحظة", "الثقة بالمعرفة", "التعاون وقت الشدة"], "chapters": [{"title": "دموع الشجرة", "text": "للّبان رائحة لا تشبه شيئًا آخر، وكانت زهرة تقول إنها رائحة الصبر. فشجرة اللبان لا تعطي كنزها دفعة واحدة؛ يكشط التاجر قشرتها بالمِنقَف كشطًا خفيفًا، ثم ينتظر أيامًا حتى تسيل منها قطرات بيضاء كالدموع، وتجفّ تحت الشمس حبّاتٍ تلمع كالفضّة.\n\nفي ذلك الصباح، كانت زهرة تمشي خلف أبيها مسلّم بين أشجار النجد الملتوية، تجمع الحبّات في سلّة صغيرة وتفرز أنقاها جانبًا. كانت قد تعلّمت أن تميّز «الحوجري» من بين مئة حبّة: أصفاها لونًا، وأطيبها رائحة إذا وُضع على الجمر. وكان أبوها يقول إن التجّار في البلاد البعيدة يدفعون فيه ما لا يدفعونه في الذهب، لأنه يُحرق في البيوت والمجالس، ويُداوى به، ويُستقبل بدخانه الضيوف.\n\n«هذا العام موسمه مبارك» قال أبوها وهو يقلّب حبّة في ضوء الشمس. «إذا طلع سهيل، خرجت القافلة إلى الشمال».\n\nتوقّفت زهرة عن الجمع. «خذني معك يا أبي».\n\nضحك أبوها ضحكة قصيرة، ثم رأى وجهها فكفّ عن الضحك. «الطريق طويل يا ابنتي، أيام من الرمل لا ترين فيها شجرة».\n\n«لكنني أعرف السماء. جدّتي علّمتني النجوم كلها، من سطح بيتنا، ليلةً بعد ليلة».\n\nلم يجب أبوها، لكن جدّتها التي كانت تسمع من عتبة البيت حين عادا، قالت كلمتها الأخيرة بهدوء من لا يقبل الردّ: «خذها يا مسلّم. هذه البنت تقرأ السماء أحسن مما يقرأ رجالك الأرض».\n\nوهكذا، في فجر بارد بعد انقضاء الخريف، وقفت زهرة بين ثلاثين جملًا محمّلة بأكياس اللبان والتمر وقِرب الماء. وكان على رأس القافلة رجل نحيل طويل اللحية اسمه عوض، دليل الطريق الذي قطع الرمال أكثر من أربعين مرة. نظر إليها من فوق جمله نظرة طويلة، ثم قال: «الصحراء يا بنت لا تؤذي من يراقبها. تؤذي من يظنّ أنه يعرفها».\n\nلم تفهم زهرة كلامه تمامًا، لكنها حفظته.\n\nوفي الليلة الأولى، حين خيّموا عند أطراف الرمل الذي لا ينتهي، رفعت زهرة رأسها إلى القمر، فرأت حوله هالة واسعة شاحبة، كخاتم من دخان. تذكّرت صوت جدّتها: «إذا تحلّق القمر، فاحذري الريح».\n\nنظرت حولها. كان الرجال يضحكون حول النار، ولم يرفع أحد منهم رأسه إلى السماء."}, {"title": "لغة الرمل", "text": "في الأيام التالية، اكتشفت زهرة أن الرمل ليس صامتًا كما يبدو. كان الدليل عوض يقرأه كما يقرأ الفقيه كتابه. يتوقّف فجأة، وينحني فوق أثر خفيف، ويقول: «جمل وحيد، مرّ أمس عند العصر، وكان عطشان». فتسأله زهرة كيف عرف، فيشير إلى عمق الخفّ في الرمل، وإلى طريقة تعثّره، وإلى ريح الأمس التي لم تمحُ الأثر تمامًا.\n\nلاحظ عوض أن البنت لا تملّ من الأسئلة، فصار يحدّثها وهو يسير. علّمها أن الكثبان تشبه أمواجًا تجمّدت، وأن جانبها الذي تضربه الريح صلب، وجانبها الآخر ليّن تغوص فيه الأقدام. وعلّمها أن الطيور التي تراها عند الفجر لا تطير بلا سبب.\n\nوفي المقابل، كانت زهرة تريه في الليل ما حفظته عن جدّتها: الجدي، النجم الثابت الذي لا يتحرّك في جهة الشمال، وبنات نعش تدور حوله كأنها تطوف، وسهيل الذي يطلع في الجنوب قبيل الفجر لامعًا منخفضًا.\n\nقال لها عوض ذات ليلة وهو يشير بعصاه: «انظري. طريقنا إلى بئر السَّمُر يكون والجدي أمامنا، مائلًا قليلًا إلى يمين الناقة. احفظي هذا».\n\nلكن ليس كل رجال القافلة أحبّوا أسئلة زهرة. كان حمد، تاجر من الساحل يحمل أكبر الحمولات، يضحك كلما رآها تحدّق في السماء، ويقول لأبيها بصوت عالٍ: «جئتَ بفلكيّة يا مسلّم؟ أخبرها أن النجوم لا تسقي العطشان».\n\nكانت زهرة تبتلع غيظها وتصمت. لكنها في كل ليلة، قبل أن تنام، كانت تقف بعيدًا عن النار، وتمدّ ذراعها نحو الجدي كما علّمها عوض، وتنظر إلى أين تشير رؤوس الجمال، كأنها تحفظ درسًا لن يسألها عنه أحد.\n\nفي اليوم الخامس، أصابت عوضًا حمّى شديدة. صار يرتجف تحت الشمس، ويغفو فوق جمله، ويستيقظ ليسأل: «أين نحن؟» فيطمئنه الرجال ويسقونه الماء. لم يقلق أحد كثيرًا، فالبئر لم تعد بعيدة، يومان أو ثلاثة على الأكثر.\n\nثم جاء عصر اليوم السادس.\n\nكانت زهرة أول من انتبه. سكنت الريح فجأة سكونًا غريبًا، وتوقّفت الجمال عن المضغ ورفعت رؤوسها كلها نحو الجنوب. والتفتت زهرة، فرأت في الأفق جدارًا عاليًا بلون الحنّاء، يبتلع السماء شيئًا فشيئًا، ويزحف نحوهم أسرع من أي جمل.\n\n«عاصفة!» صرخت، وهذه المرة لم يضحك أحد."}, {"title": "الجدار الأصفر", "text": "تحرّك الرجال بسرعة من اعتاد الخطر. أُنيخت الجمال في دائرة متلاصقة، رؤوسها إلى الداخل وظهورها إلى الريح، وشُدّت الحبال على الأحمال، ولفّ كل رجل لثامه على وجهه حتى لم يبقَ منه إلا عيناه. أمسك أبو زهرة بيدها وجرّها إلى جوار ناقته، ثم بسط عباءته فوق رأسيهما.\n\nثم وصل الجدار.\n\nلم تكن زهرة قد سمعت صوتًا كهذا من قبل. كان الرمل يصفر ويعوي ويطرق العباءة كأن ألف يد تضربها. اختفى الضوء، فصار النهار ليلًا بلون النحاس، ولم تعد ترى يدها أمام وجهها. كانت تشعر بالرمل يتسلّل إلى أذنيها وبين أسنانها، وتسمع أباها يردّد الأذكار بصوت هادئ ثابت، فتردّد معه.\n\nلا تدري كم مرّ من الوقت. ساعات ربما. وحين هدأت الريح أخيرًا، رفع أبوها العباءة، فانهال عليهما الرمل كالماء.\n\nكانت الصحراء قد تغيّرت. الكثبان التي عرفوها انتقلت من أماكنها، والآثار كلها امّحت كأن أحدًا لم يمرّ من هنا قط. وحين عدّ الرجال ما بقي، وجدوا أن ثلاث قِرب قد انشقّت تحت الأحمال وسال ماؤها في الرمل. ما بقي من الماء لا يكفي القافلة أكثر من يومين.\n\nوكان عوض ممدّدًا قرب جمله، وقد اشتدّت عليه الحمّى، يهذي بكلمات غير مفهومة.\n\nوقف الرجال في دائرة قلقة. قال أحدهم: «من يعرف الطريق غير عوض؟» فساد الصمت.\n\nثم تقدّم حمد بثقة وأشار نحو الشرق: «البئر هناك. أنا متأكد. رأيت تلك التلّة قبل العاصفة».\n\n«التلال تتحرّك يا حمد» قال أحد الرجال بتردّد.\n\n«وهل عندك أفضل؟» ردّ حمد بحدّة.\n\nكانت الشمس تغيب خلف غبار ما زال معلّقًا في الهواء، فلا تُرى إلا قرصًا باهتًا مشوّشًا، ولا يُعرف منها شرق من غرب بدقّة. وأحسّت زهرة بقلبها ينقبض: لو ساروا في الاتجاه الخطأ يومًا واحدًا، فلن يكفيهم الماء للعودة.\n\nالتفت أبوها إليها فجأة، أمام الرجال جميعًا، وسألها بصوت واضح: «يا زهرة، ماذا تقول السماء؟»\n\nرفعت زهرة رأسها. كانت السماء ما تزال مغطّاة بستار بنّيّ كثيف، لا نجم فيه ولا قمر.\n\n«لا تقول شيئًا بعد» همست. «علينا أن ننتظر الليل»."}, {"title": "أهدى من القطا", "text": "لم ينم أحد تلك الليلة. جلس الرجال صامتين حول نار صغيرة، وحمد يكرّر بين حين وآخر أن الانتظار تضييع للماء والوقت. أما زهرة فجلست بعيدًا عن النار، حيث العتمة أعمق، وعيناها لا تفارقان السماء.\n\nقرب منتصف الليل، هبّت نسمة باردة من الشمال، وبدأ الغبار ينقشع كستارة تُرفع. ظهرت نجمة، ثم أخرى، ثم امتلأت السماء فجأة بنجوم لا تُحصى، كأنها غُسلت.\n\nبحثت زهرة عن بنات نعش أولًا، كما علّمتها جدّتها، فلم تجدها؛ كانت في هذه الساعة من ليالي الخريف قد انحدرت خلف الأفق. لم تيأس، وتذكّرت الوصية الأخرى: «إذا غابت بنات نعش، فابحثي عن ذات الكرسي». ووجدتها عالية فوق الشمال، خمس نجمات متعرّجة كأنها خطّ مكسور، فقاست منها بعينها حتى وصلت إلى نجم وحيد هادئ لا يتحرّك. «الجدي» قالت وقلبها يخفق. ثم وقفت ونادت أباها.\n\nاجتمع الرجال حولها. وقفت زهرة وظهرها إلى النار، ورفعت ذراعها نحو الجدي، ثم أمالتها قليلًا إلى اليسار. «قال لي عوض: طريقنا والجدي أمامنا، مائلًا قليلًا إلى يمين الناقة. إذن البئر من هنا». وكانت يدها تشير إلى الشمال، بعيدًا جدًا عن الشرق الذي أراده حمد.\n\n«كلام بنت!» قال حمد. «ونراهن بأرواحنا على نجمة؟»\n\nلكن صوتًا ضعيفًا جاء من خلفهم. كان عوض قد رفع رأسه عن الرمل، وعيناه نصف مفتوحتين. «البنت... صادقة» قال بصعوبة. «الجدي لا يكذب».\n\nومع ذلك، تردّد الرجال. فالدليل مريض يهذي منذ ساعات، والبنت صغيرة لم تقطع الرمل من قبل.\n\nوعند أول الفجر، حين صار الأفق رماديًا، سمعت زهرة صوتًا تعرفه: رفرفة سريعة، وصياحًا متقطّعًا. رفعت رأسها، فرأت سربًا من القطا يمرّ فوقهم في خطّ مستقيم، ثم سربًا ثانيًا، ثم ثالثًا، كلها تطير في الاتجاه نفسه.\n\nتذكّرت كلام عوض في اليوم الثالث: «الطيور التي ترينها عند الفجر لا تطير بلا سبب». والقطا، كما يعرف كل بدوي، يطير في الصباح الباكر إلى الماء، حتى قالت العرب في أمثالها: «أهدى من القطا».\n\nوكانت الأسراب كلها تطير نحو الشمال، حيث أشارت يدها في الليل.\n\nنظر الرجال إلى السماء، ثم إلى زهرة، ثم بعضهم إلى بعض. حتى حمد ظلّ صامتًا.\n\n«حمّلوا الجمال» قال أبوها.\n\nوسارت القافلة خلف القطا والجدي. لكن الشمس ارتفعت، واشتدّ الحرّ، وفرغت القربة قبل الأخيرة عند الظهر، ولم يظهر في الأفق شيء غير الرمل."}, {"title": "بئر في قلب الرمل", "text": "بعد الظهر بساعة، بدأ الشكّ يزحف إلى القافلة كما زحفت العاصفة. صار الرجال يسيرون مطرقين لا يتكلّمون، والجمال تجرّ أخفافها في الرمل الساخن. وكانت زهرة تسمع في رأسها صوت حمد: «ونراهن بأرواحنا على نجمة؟» فتشدّ قبضتها على الرسن وتسير.\n\nثم حدث شيء غريب. رفعت ناقة أبيها رأسها فجأة، وفتحت منخريها، وأسرعت في مشيتها دون أن يحثّها أحد. وتبعتها ناقة ثانية، ثم ثالثة، حتى صارت القافلة كلها تمشي بخطى أسرع.\n\n«شمّت الماء!» صاح أحد الرجال.\n\nصعدت زهرة على كثيب صغير، ونظرت أمامها. وهناك، في البعيد، رأت شيئًا لم يكن رملًا: بقعة داكنة في الأرض، وبجوارها بقايا جدران حجرية قديمة، وبضع شجيرات خضراء تهتزّ في الحرّ كأنها حلم.\n\nكانت بئر السَّمُر.\n\nلم تتذكّر زهرة بعد ذلك كيف نزلت عن الكثيب، ولا كيف وصلت. تتذكّر فقط صوت الدلو يرتطم بالماء في الأسفل، وصيحات الرجال، والجمال تبرك حول الحوض وتشرب طويلًا، ووجه أبيها وهو يغرف لها بكفّيه أول شربة. كان الماء فاترًا، فيه طعم الطين والحجر، لكنها أقسمت فيما بعد أنها لم تذق في حياتها أعذب منه.\n\nوفي غمرة الفرح، لم ينسَ الرجال دليلهم؛ حملوا قربة ممتلئة إلى عوض، وسقوه على مهل، ورفعوا رأسه بأيديهم كما يُرفع رأس الأب.\n\nفي تلك الليلة، استعاد عوض شيئًا من عافيته بعد أن شرب وأكل ونام. ودعا زهرة إلى جانبه، وأمام الرجال جميعًا قال: «أربعون رحلة قطعتُ هذا الرمل، ولم ينقذني فيها أحد غير هذه البنت». ثم أخرج من كيس جلدي عتيق عصًا قصيرة محفورًا عليها خطوط ونقاط. «هذه عصا الطرق. فيها كل محطّة وكل بئر. سأعلّمك قراءتها في طريق العودة».\n\nوتقدّم حمد بعد تردّد، ووضع أمامها صرّة صغيرة. «لبان من أجود ما عندي» قال، دون أن ينظر في عينيها. «النجوم لا تسقي العطشان... لكنها تدلّه على من يسقيه. أخطأتُ يا بنت مسلّم».\n\nابتسمت زهرة، وأخذت حبّة من الصرّة، ووضعتها على جمر النار. تصاعد الدخان الأبيض رقيقًا، ملتفًّا، يحمل رائحة النجد والأشجار البعيدة، وارتفع حتى بدا كأنه يلامس الجدي في أعلى السماء.\n\nرائحة الصبر، فكّرت زهرة. والآن عرفت أنها أيضًا رائحة الطريق."}], "vocab": [{"w": "المِنْقَف", "m": "أداة حديدية صغيرة يُكشط بها لحاء شجرة اللبان ليسيل منها الصمغ"}, {"w": "الكُثْبَان", "m": "تلال الرمل التي تكوّنها الريح، مفردها كثيب"}, {"w": "أُنِيخَت", "m": "أُبركت الجمال على الأرض"}, {"w": "لِثَام", "m": "قماش يُلفّ على الوجه فيغطّي الفم والأنف"}, {"w": "القِرَب", "m": "أوعية من الجلد يُحمل فيها الماء، مفردها قِربة"}, {"w": "يَهْذِي", "m": "يتكلّم بكلام غير مفهوم من شدّة المرض"}, {"w": "القَطَا", "m": "طائر صحراوي يطير إلى الماء في الصباح الباكر، يُضرب به المثل في الاهتداء"}, {"w": "الرَّسَن", "m": "الحبل الذي يُقاد به البعير"}], "quiz": [{"q": "ما العلامة التي جعلت زهرة تتوقّع هبوب الريح في الليلة الأولى؟", "opts": ["هالة شاحبة حول القمر", "غياب النجوم كلها", "صوت الجمال في الليل"], "a": 0, "explain": "رأت حول القمر هالة واسعة، فتذكّرت قول جدّتها: «إذا تحلّق القمر، فاحذري الريح»."}, {"q": "لماذا لم يستطع الرجال تحديد الاتجاه بالشمس بعد العاصفة؟", "opts": ["لأن الشمس كانت قد غابت تمامًا", "لأن الغبار المعلّق جعلها قرصًا باهتًا لا يُعرف منه الاتجاه بدقّة", "لأن الدليل منعهم من النظر إليها"], "a": 1, "explain": "كانت الشمس تغيب خلف غبار معلّق، فلا تُرى إلا قرصًا باهتًا مشوّشًا."}, {"q": "ما الدليل الثاني الذي أكّد صحة اتجاه زهرة عند الفجر؟", "opts": ["أثر جمل قديم", "دخان نار بعيدة", "أسراب القطا الطائرة نحو الشمال"], "a": 2, "explain": "القطا يطير في الصباح الباكر إلى الماء، وكانت أسرابه كلها تتّجه نحو الشمال كما أشارت زهرة."}, {"q": "كيف عرف الرجال أنهم اقتربوا من البئر قبل أن يروها؟", "opts": ["سمعوا صوت الماء", "أسرعت الجمال في مشيتها لأنها شمّت الماء", "رأوا سربًا جديدًا من الطيور"], "a": 1, "explain": "رفعت الناقة رأسها وأسرعت دون أن يحثّها أحد، فصاح أحد الرجال: «شمّت الماء!»."}], "discuss": ["قال عوض: «الصحراء لا تؤذي من يراقبها، تؤذي من يظنّ أنه يعرفها». كيف تحقّق هذا القول في أحداث الرواية؟ ومن الشخصية التي ظنّت أنها تعرف؟", "لم يقتنع الرجال بكلام زهرة إلا بعد أن رأوا القطا. هل كان تردّدهم مفهومًا في رأيك؟ وكيف يمكن للمرء أن يثبت صواب رأيه حين لا يصدّقه الآخرون؟"]}, {"id": "n13", "title": "الخطّاطة الصغيرة", "genre": "فن ومثابرة", "blurb": "تحبّ أسيل الحروف العربية حبًّا لا تبادلها إياه الحروف؛ فخطّها، كما كتبت معلمتها بالأحمر، «يحتاج إلى عناية». وفي دكّان صغير بين أزقّة مطرح، ينتظرها رجل مسنّ وقصبة وألف نقطة.", "values": ["المثابرة", "الصبر على التعلّم", "الاعتذار وتحمّل المسؤولية"], "chapters": [{"title": "الأحمر في الهامش", "text": "كانت أسيل تحبّ الحروف حبًّا لا تبادلها إياه الحروف. كانت تقف في المسجد بعد صلاة الجمعة تتأمّل الآيات المكتوبة على الجدار حول المحراب، حروفًا تلتفّ وتصعد وتتعانق كأنها أغصان شجرة، وتشعر بشيء في صدرها يشبه الشوق. ثم تعود إلى البيت، وتفتح دفترها، فتجد حروفها هي مائلة متعثّرة، كأنها مشت تحت المطر.\n\nفي ذلك الصباح، أعادت معلمة اللغة العربية دفاتر التعبير. فتحت أسيل دفترها، فوجدت تحت موضوعها درجة جيدة، وتحت الدرجة سطرًا بالأحمر: «أفكارك جميلة، لكن خطّك يحتاج إلى عناية كبيرة».\n\nأغلقت الدفتر بسرعة، لكن جارتها في المقعد، ميثاء، كانت قد رأت.\n\nكانت أسيل قد جرّبت كل شيء: الدفاتر ذات السطور المزدوجة التي يستعملها أطفال الصف الأول، والأقلام الغالية ذات الرؤوس العريضة، ومقاطع التعليم على الهاتف. لكن يدها كانت تعصيها دائمًا، كمُهرة لا تعرف صاحبها.\n\nفي الفسحة، علّقت مشرفة الأنشطة إعلانًا ملوّنًا على اللوحة: «معرض الفنون السنوي بعد ثلاثة أشهر. الأقسام: الرسم، التصوير، الأشغال اليدوية، الخطّ العربي». وقفت أسيل أمام الكلمتين الأخيرتين طويلًا، حتى سمعت ضحكة ميثاء خلفها.\n\n«لا تقولي إنك تفكّرين في الخطّ يا أسيل! معلمة العربي نفسها لا تستطيع قراءة دفترك».\n\nضحكت البنات، وضحكت أسيل معهن، لأن الضحك أسهل من البكاء أمام الناس. لكنها في طريق العودة، لم تأخذ الشارع الواسع على الكورنيش كعادتها، بل دخلت الأزقّة الضيّقة خلف سوق مطرح، حيث رائحة البخور والهيل تتسرّب من الأبواب، وحيث لا يراها أحد.\n\nهناك، بين محلّ قديم للنحاسيات ومحلّ يبيع الأقمشة، رأت دكّانًا صغيرًا لم تنتبه إليه من قبل. كان بابه الخشبي مفتوحًا، وفوقه لوحة باهتة كُتب عليها بخطّ بديع: «حمدان للخطّ والتصميم».\n\nوفي الداخل، تحت ضوء مصباح أصفر، كان رجل مسنّ بلحية بيضاء يجلس إلى طاولة مائلة، وفي يده قصبة رفيعة. رأته أسيل يغمسها في الحبر، ثم يرفعها، ثم يكتب بحركة واحدة طويلة حرف نون كبيرًا، مستديرًا كهلال، دون أن ترتجف يده لحظة.\n\nتجمّدت أسيل عند الباب. ورفع الرجل عينيه إليها من فوق نظّارته، كأنه كان ينتظرها."}, {"title": "ألف نقطة", "text": "«ادخلي يا ابنتي، الشمس حارّة في الخارج» قال الرجل، وأشار إلى كرسي خشبي صغير.\n\nكان الدكّان أضيق من غرفة أسيل، لكنه بدا لها كعالم كامل. أوراق معلّقة على الجدران بخطوط لا تعرف أسماءها، وأقلام قصب في أكواب نحاسية، ودويّات حبر صغيرة، ورائحة غريبة تمتزج فيها رائحة الحبر برائحة الصمغ والورق القديم.\n\n«أنا حمدان» قال الرجل. «وأنتِ؟»\n\n«أسيل. أنا... أريد أن أتعلّم الخطّ. لكن خطّي سيّئ جدًا».\n\n«أريني».\n\nترددت، ثم أخرجت دفتر التعبير وفتحته على الصفحة ذات السطر الأحمر. توقّعت أن يضحك، أو أن يهزّ رأسه بأسف. لكنه تأمّل الصفحة بهدوء، كما يتأمّل الطبيب صورة أشعّة، ثم قال: «اليد لا تكذب يا أسيل. يدك ليست سيّئة، يدك غير مدرّبة. وهذا أحسن خبر يمكن أن تسمعيه».\n\n«لماذا؟»\n\n«لأن السيّئ لا يُصلَح، أما غير المدرّب فيُدرَّب».\n\nثم أخرج قصبة جديدة وسكّينًا صغيرة، ووضعهما أمامها. «الدرس الأول: الخطّاط يبري قلمه بيده. لا أحد يبريه عنه».\n\nعلّمها كيف تقشط القصبة وتشقّ رأسها شقًّا صغيرًا، ثم تضعها على قطعة صلبة من العظم يسمّيها «المِقَطّة»، وتقطع رأسها قطعة مائلة واحدة حاسمة. أفسدت أسيل ثلاث قصبات قبل أن تنجح في الرابعة، وفي كل مرة كان حمدان يناولها قصبة جديدة دون كلمة لوم، كأن إفساد القصب جزء من الدرس لا خروج عنه. ثم أراها الدواة، وفي داخلها خيوط من الحرير مبلّلة بالحبر، اسمها «اللِّيقة»، تمنع القلم من أن يشرب أكثر من حاجته.\n\nوحين ظنّت أسيل أنها ستكتب أخيرًا حرفًا، رسم لها على الورقة شكلًا صغيرًا: معيّنًا أسود، كحبّة شعير واقفة على رأسها.\n\n«هذه النقطة. منها يُقاس كل حرف في الخطّ العربي: الألف بعدد من النقاط، والباء بعدد آخر. من لا يتقن النقطة لا يتقن شيئًا».\n\n«وكم نقطة أكتب؟»\n\nابتسم حمدان ابتسامة صغيرة. «ألفًا. وحين تنتهين، عودي إليّ».\n\nخرجت أسيل من الدكّان والقصبة ملفوفة في منديل داخل حقيبتها، وفي رأسها رقم واحد يتردّد: ألف. ألف نقطة سوداء صغيرة، قبل حرف واحد.\n\nفكّرت أن المعرض بعد ثلاثة أشهر، وأن الوقت لا يكفي لكل هذا الصبر."}, {"title": "الحبر المسكوب", "text": "كتبت أسيل الألف نقطة في تسعة أيام. كانت النقاط الأولى منتفخة كالبقّ، أو نحيلة كالشوك، أو مائلة كأنها تهرب من الورقة. لكنها في اليوم السابع لاحظت شيئًا: صارت يدها تعرف الزاوية وحدها، قبل أن تفكّر. وفي اليوم التاسع، رأت أمها الأوراق المبعثرة على السرير، وكلها نقاط سوداء صغيرة في صفوف طويلة، فسألتها مازحة: «هل تعدّين حبّات الرمل؟» فأجابت أسيل دون أن ترفع رأسها: «تقريبًا».\n\nحين عادت إلى الدكّان بأوراقها، قلّبها حمدان صفحةً صفحة، ثم قال: «الآن نبدأ».\n\nفي الأسابيع التالية، صار الدكّان محطّتها اليومية بعد المدرسة. كان حمدان يكتب لها في أعلى الورقة حرفًا واحدًا، ويسمّي ذلك «المشق»، وعليها أن تقلّده سطرًا بعد سطر. الألف أولًا، مستقيمة كرمح. ثم الباء، ممدودة كقارب. ثم الحاء، والدال، والراء... ولم يكن يسمح لها بالانتقال إلى حرف جديد قبل أن يقول كلمته المقتضبة: «طيّب».\n\nلكن الصبر لم يكن من طبع أسيل. وفي إحدى الليالي، بعد أن رأت على هاتفها لوحة بخطّ الثلث لخطّاط مشهور، قرّرت أن تختصر الطريق. جلست حتى منتصف الليل تحاول أن تكتب جملة كاملة بالثلث، أصعب الخطوط وأجملها. وفي الصباح، حين نظرت إلى ما كتبت، وجدت حروفًا متشابكة كالأسلاك، لا يُعرف رأسها من ذيلها. مزّقت الورقة ورمتها في السلّة دون أن تخبر أحدًا، وقد أحسّت بحرارة الخجل في وجهها، كأن الحروف نفسها تضحك منها.\n\nبعد يومين، دخلت الدكّان متعجّلة، فوجدت حمدان قد خرج يصلّي العصر، وعلى طاولته المائلة لوحة طويلة شبه مكتملة: «مخبز الوادي». كانت أسيل تعرف أنها أول طلب يأتيه منذ أسابيع، فقد صار أكثر الناس يطبعون لافتاتهم بالآلات.\n\nاقتربت لتنظر إلى الحروف عن قرب. كانت الكاف ممدودة كجناح، والزاي... لم تنتبه إلى الدواة على حافة الطاولة. اصطدم بها مرفقها.\n\nكان الصوت خفيفًا جدًا، مجرّد «طق» صغيرة، ثم سال الحبر الأسود على الورقة كبقعة ليل، وابتلع كلمة «الوادي» كلها.\n\nوقفت أسيل لا تتنفّس. ثم سمعت خطوات حمدان تقترب من الباب، فحملت حقيبتها، وخرجت من الباب الخلفي، وركضت في الأزقّة دون أن تلتفت."}, {"title": "صندوق الأوراق الخائبة", "text": "مرّ أسبوع ولم تعد أسيل إلى الدكّان. كانت تأخذ الشارع الواسع على الكورنيش في طريق العودة، وتمشي بسرعة كأن أحدًا يلاحقها. وحين تمرّ قرب مدخل الأزقّة، كانت تنظر إلى البحر.\n\nحاولت أن تتدرّب وحدها في البيت لأجل المعرض، لكن شيئًا انكسر في يدها. كانت كل نقطة تذكّرها ببقعة الحبر، وكل حرف يذكّرها بالباب الخلفي.\n\nفي الليلة الثامنة، وجدتها أمها جالسة أمام ورقة بيضاء، والقصبة في يدها، دون أن تكتب. جلست الأم إلى جوارها، فحكت لها أسيل كل شيء، والكلمات تخرج متقطّعة.\n\nصمتت الأم قليلًا، ثم قالت: «الحبر المسكوب يُمسح يا أسيل. أما الهرب فيبقى». ثم أضافت: «والاعتذار جزء من أي حرفة. لا يتعلّم أحد شيئًا دون أن يفسد شيئًا».\n\nفي اليوم التالي، أخذت أسيل كل مدّخراتها من علبة معدنية، وذهبت إلى الدكّان بقلب يدقّ كطبل. وجدت حمدان في مكانه، يكتب كأن شيئًا لم يحدث.\n\nوضعت النقود على الطاولة، وقالت ورأسها منخفض: «أنا التي سكبت الحبر. وهربت. أنا آسفة. هذا ثمن اللوحة».\n\nنظر حمدان إلى النقود، ثم دفعها نحوها بإصبعه. «أعرف أنك أنتِ. لا أحد غيرك يدخل الدكّان في ذلك الوقت. انتظرتك لأعرف إن كنتِ ستعودين».\n\nثم قام إلى رفّ عالٍ، وأنزل صندوقًا خشبيًا قديمًا، ونفخ عنه الغبار. فتحه، فإذا فيه أوراق مصفرّة كثيرة، عليها حروف مرتجفة، وبقع حبر، وخطوط حمراء كثيرة في الهوامش.\n\n«هذه أوراقي حين كنت في الثانية عشرة» قال. «والأحمر خطّ أستاذي رحمه الله. كان يحتفظ لكل تلميذ بصندوق كهذا، ويسمّيه صندوق الأوراق الخائبة. ثم يعطيه له يوم يجيزه، ويقول: لا تنسَ من أين بدأت».\n\nقلّبت أسيل الأوراق بدهشة. كانت بعض حروفه أسوأ من حروفها. ضحكت رغمًا عنها، فضحك حمدان معها، وكانت أول مرة تسمع ضحكته: ضحكة قصيرة خشنة، كصوت القصبة حين تمشي على الورق.\n\nثم أشار حمدان إلى الجدار، فرأت لوحة «مخبز الوادي» معلّقة، مكتوبة من جديد. «كتبتها ثانية. وصاحب المخبز يقول إنها أجمل من الأولى. والحقّ أنها كذلك».\n\nثم ناولها قصبتها التي تركتها في الدكّان. «بقي على المعرض شهر. وأمامنا عمل كثير»."}, {"title": "الحرف المائل", "text": "اختارت أسيل لِلَوحتها مَثلًا قصيرًا: «من سار على الدرب وصل». واقترح عليها حمدان أن تكتبه بخطّ النسخ، لا بالثلث الذي كانت تحلم به.\n\n«الثلث سيأتي يومه» قال. «اكتبي اليوم بالخطّ الذي تعرفه يدك، لا بالخطّ الذي تتمنّاه عينك».\n\nكتبت الجملة أربعين مرة في أربعة أسابيع. في كل مرة كان حمدان يضع دائرة صغيرة بالأحمر حول حرف واحد، ولا يقول إلا: «هنا». فتعود وتكتب. وكانت أمها تجد في سلّة غرفتها كل مساء أوراقًا جديدة، فلا ترميها، بل تجمعها في صندوق كرتوني صغير كتبت عليه: «صندوق أسيل».\n\nفي الليلة الأخيرة قبل موعد التسليم، كتبت أسيل المحاولة الحادية والأربعين. كانت أجمل ما كتبت قط: الميم مستديرة، والسين مسنّنة كموج هادئ، والدال واثقة. لكن حين رفعت الورقة إلى الضوء، رأت أن الراء في كلمة «سار» مائلة قليلًا، أكثر مما ينبغي.\n\nكادت تبكي. لم يعد هناك وقت لمحاولة أخرى. جلست تنظر إلى الراء طويلًا، وفكّرت أن تنسحب من المعرض كله. ثم تذكّرت الباب الخلفي، والحبر المسكوب، والأسبوع الذي ضاع في الهرب، فلفّت اللوحة بعناية ووضعتها في حقيبتها.\n\nفي يوم المعرض، علّقت اللوحة في قسم الخطّ العربي، بين لوحات طالبات كتبن منذ سنوات. وقفت إلى جانبها متوتّرة، تنتظر أن يكتشف أحد الراء المائلة. ومرّت ميثاء، فتوقّفت أمام اللوحة طويلًا، ثم قالت بصوت منخفض لم تعهده أسيل منها: «هل أنتِ من كتب هذه؟ كيف؟»\n\nلم تجد أسيل جوابًا إلا: «بألف نقطة... وأكثر».\n\nثم رأته عند باب القاعة. حمدان، في دشداشة بيضاء نظيفة، وعلى رأسه كمّة مطرّزة، يتوكّأ على عصاه ويتلفّت باحثًا. أسرعت إليه وقادته إلى اللوحة.\n\nتأمّلها طويلًا من خلف نظّارته، ثم مدّ إصبعه المرتجف، وأشار مباشرة إلى الراء المائلة.\n\nانقبض قلب أسيل. «أعرف. لم يكن عندي وقت لأصلحها».\n\n«هذا حرفي المفضّل في اللوحة» قال حمدان بهدوء.\n\n«لماذا؟»\n\n«لأن الحروف الكاملة تقول لي: انتهينا. أما هذا الحرف فيقول: هناك لوحة قادمة».\n\nوفي اليوم التالي، حين دخلت أسيل الدكّان، وجدت على طاولتها ورقة جديدة، وفي أعلاها مشق بخطّ حمدان، لحرف واحد بخطّ الثلث.\n\nوتحته، بالأحمر: «الدرس التالي»."}], "vocab": [{"w": "المِحْرَاب", "m": "التجويف في جدار المسجد الذي يقف فيه الإمام جهة القبلة"}, {"w": "يَبْرِي", "m": "ينحت القلم ويسوّي رأسه ليصلح للكتابة"}, {"w": "المِقَطّة", "m": "قطعة صلبة يوضع عليها رأس القلم عند قطّه"}, {"w": "اللِّيقَة", "m": "خيوط حرير توضع في الدواة لتنظيم ما يحمله القلم من حبر"}, {"w": "المَشْق", "m": "نموذج يكتبه الأستاذ ليقلّده التلميذ في تعلّم الخطّ"}, {"w": "مُقْتَضَبَة", "m": "قصيرة موجزة"}, {"w": "يُجِيزُه", "m": "يمنحه الإجازة، أي الشهادة بإتقانه الخطّ وأهليّته لتعليمه"}, {"w": "يَتَوَكَّأ", "m": "يعتمد ويستند"}], "quiz": [{"q": "ماذا قال حمدان حين رأى خطّ أسيل أول مرة؟", "opts": ["إن يدها غير مدرّبة، وغير المدرّب يُدرَّب", "إنها لا تصلح لتعلّم الخطّ", "إن عليها أن تبدأ بخطّ الثلث"], "a": 0, "explain": "قال: «يدك ليست سيّئة، يدك غير مدرّبة... السيّئ لا يُصلَح، أما غير المدرّب فيُدرَّب»."}, {"q": "ما الخطأ الذي ارتكبته أسيل بعد سكب الحبر على اللوحة؟", "opts": ["أنها كذبت على أمها", "أنها حاولت إصلاح اللوحة بنفسها", "أنها هربت من الباب الخلفي ولم تعتذر"], "a": 2, "explain": "خرجت من الباب الخلفي وركضت، وغابت أسبوعًا، فقالت لها أمها: «أما الهرب فيبقى»."}, {"q": "لماذا أخرج حمدان «صندوق الأوراق الخائبة»؟", "opts": ["ليبيع الأوراق القديمة", "ليريها أنه بدأ هو أيضًا بأخطاء كثيرة", "ليطلب منها أن ترتّبه"], "a": 1, "explain": "فيه أوراقه حين كان في الثانية عشرة، بحروف مرتجفة وتصحيحات أستاذه، وبعضها أسوأ من حروفها."}, {"q": "لماذا كانت الراء المائلة حرف حمدان المفضّل؟", "opts": ["لأنه كتبها بنفسه", "لأنها أوضح حروف اللوحة", "لأنها تدلّ على أن هناك لوحة قادمة وتعلّمًا مستمرًا"], "a": 2, "explain": "قال: «الحروف الكاملة تقول: انتهينا. أما هذا الحرف فيقول: هناك لوحة قادمة»."}], "discuss": ["قال حمدان: «اكتبي بالخطّ الذي تعرفه يدك، لا بالخطّ الذي تتمنّاه عينك». ما الفرق بين الحلم والقدرة الحالية؟ وكيف نوازن بينهما حين نتعلّم مهارة جديدة؟", "لماذا في رأيك احتفظ الأستاذ القديم لكل تلميذ بصندوق من أوراقه الخائبة، وأعطاه له يوم أجازه؟ وماذا يمكن أن تضعي أنتِ في «صندوقك» لو كان لك واحد؟"]}, {"id": "n14", "title": "المناظرة", "genre": "مدرسية", "blurb": "رنا لا ترفع يدها في الفصل حتى حين تعرف الجواب، فكيف وُضع اسمها في فريق المناظرة؟ خطأ صغير في قائمة معلّقة يضعها أمام أصعب امتحان: أن تقف وتتكلّم.", "values": ["الثقة بالنفس", "الإعداد الجيد", "حسن الإصغاء"], "chapters": [{"title": "الاسم في القائمة", "text": "كان لرنا مكان سرّي في المدرسة: الزاوية الأخيرة في المكتبة، خلف رفّ الموسوعات القديمة، حيث لا يصل صوت الساحة ولا تراها عين. كانت تقضي فيه الفسحة كل يوم، مع شطيرة جبن وكتاب، وتشعر أن العالم هناك بحجمها تمامًا.\n\nلم تكن رنا تكره الناس. كانت فقط تكره أن ينظروا إليها جميعًا في وقت واحد. في الفصل، كانت تعرف الجواب في أغلب الأحيان، وتهمس به لنفسها، ثم تسمع طالبة أخرى تقوله بصوت عالٍ فتُمدح. ولم يكن ذلك يزعجها كثيرًا؛ كان أهون من أن ترفع يدها، فتلتفت إليها الرؤوس، فيحمرّ وجهها، فتتلعثم. وكانت معلمة الرياضيات قد كتبت في تقريرها الأخير عنها: «طالبة متميّزة، لكنها لا تشارك». قرأت رنا الجملة مرتين، ولم تعرف أيّ نصفيها يصفها أكثر.\n\nفي ذلك الصباح، اقتحمت شمّا المكتبة لاهثة، وجاءت مباشرة إلى الزاوية، فلم يكن أحد غيرها يعرف المكان.\n\n«رنا! اسمك على لوحة الإعلانات!»\n\n«أيّ إعلانات؟»\n\n«فريق المناظرة! الأستاذة نوال علّقت أسماء الفريق الذي سيمثّل المدرسة في مسابقة المحافظة. واسمك الثالث!»\n\nضحكت رنا ضحكة قصيرة. «لا بدّ أنك قرأتِ خطأ».\n\nلكن شمّا جرّتها من يدها عبر الممرّ، حتى وقفتا أمام اللوحة الخضراء قرب غرفة المعلمات. وهناك، تحت عنوان مكتوب بخطّ عريض: «فريق المناظرة»، ثلاثة أسماء:\n\nهند علي.\n\nشمّا خالد.\n\nرنا سالم.\n\nأحسّت رنا بالأرض تميل تحت قدميها. هند علي كانت أشهر طالبة في الصف العاشر، صوتها يُسمع من آخر الساحة، وتقدّم الإذاعة المدرسية كأنها وُلدت أمام الميكروفون. وشمّا، صديقتها الوحيدة، تضحك بسهولة وتتكلّم بسهولة. أما هي...\n\n«مستحيل» قالت. «أنا لم أتقدّم أصلًا. لم أكتب اسمي في أيّ ورقة».\n\nكانت بعض الطالبات قد تجمّعن خلفهما، وسمعت رنا همسًا وضحكة خافتة. التفتت فرأت هند نفسها تنظر إلى القائمة، ثم إليها، بحاجبين مرفوعين، كأنها ترى قطّة في سباق خيل.\n\nرنّ الجرس. ومشت رنا إلى فصلها بخطوات ثقيلة، وفي رأسها فكرة واحدة: بعد الحصة الأخيرة، ستذهب إلى الأستاذة نوال، وتصحّح هذا الخطأ قبل أن يكبر.\n\nلم تكن تعرف أن الخطأ كان قد كبر فعلًا."}, {"title": "رنا الأخرى", "text": "كانت الأستاذة نوال تصحّح أوراقًا في غرفة الأنشطة حين طرقت رنا الباب. رفعت المعلمة رأسها، ونظرت إليها لحظة، ثم إلى قائمة أمامها، ثم عادت إليها، وفهمت رنا من تلك النظرة كل شيء قبل أن تنطق المعلمة بكلمة.\n\n«أنتِ رنا سالم، من العاشر الثالث؟»\n\n«نعم يا أستاذة. وأظنّ أن هناك خطأ».\n\nتنهّدت الأستاذة نوال وابتسمت ابتسامة معتذرة. «هناك خطأ فعلًا. كنت أقصد رنا سعيد، من العاشر الأول. كتبت الاسم على عجل». ثم أضافت: «لكن رنا سعيد اعتذرت هذا الصباح؛ ستشارك في أولمبياد العلوم، والموعدان متقاربان».\n\nسادت لحظة صمت. ثم قالت المعلمة شيئًا لم تتوقّعه رنا: «المسابقة بعد ستة أسابيع، ولا وقت عندي للبحث من جديد. ما رأيك أن تحضري تدريبًا واحدًا، ثم تقرّري بنفسك؟»\n\nلم تعرف رنا لماذا قالت «حسنًا». ربما لأن قول «لا» أمام المعلمة كان يحتاج إلى شجاعة أكبر.\n\nفي التدريب الأول، جلست الفتيات الثلاث حول طاولة مستديرة. شرحت الأستاذة نوال القواعد: فريقان، أحدهما يؤيّد القضية والآخر يعارضها، لكل متحدّثة دقائق محدّدة، ثم كلمة ختامية يسمّونها «الردّ»، تلخّص المعركة كلها وتكشف ضعف الخصم.\n\nثم أعطتهنّ قضية للتمرين، وطلبت من كل واحدة أن تتحدّث دقيقة واحدة.\n\nتحدّثت هند كأنها شلّال: سريعة، واثقة، تلوّح بيديها. وتحدّثت شمّا وهي تضحك، لكنها قالت أفكارًا جميلة. ثم جاء دور رنا.\n\nوقفت. فتحت فمها. ولم يخرج شيء.\n\nكانت الأفكار كلها في رأسها، مرتّبة كالكتب على رفّ، لكن الطريق بين رأسها وفمها كان مسدودًا. مرّت عشر ثوانٍ، ثم عشرون، وهي تسمع دقّات قلبها في أذنيها. وأخيرًا جلست.\n\nزفرت هند بصوت مسموع، وقالت دون أن تقصد الإيذاء تمامًا: «سنخسر من الجولة الأولى».\n\nبعد التدريب، جمعت رنا أغراضها بسرعة، وقد قرّرت أن تعتذر غدًا. لكن الأستاذة نوال استوقفتها عند الباب، وناولتها دفترًا صغيرًا بغلاف أصفر.\n\n«قبل أن تقرّري، أطلب منك شيئًا واحدًا. في التدريب القادم، لا تتكلّمي أبدًا. فقط اكتبي في هذا الدفتر كل ما تقوله الأخريات».\n\nنظرت رنا إلى الدفتر بحيرة. «وما فائدة ذلك؟»\n\n«ستعرفين» قالت المعلمة، وأغلقت الباب."}, {"title": "الدفتر الأصفر", "text": "في التدريب الثاني، جلست رنا في طرف الطاولة، والدفتر الأصفر مفتوح أمامها، والقلم في يدها. لم يطلب منها أحد أن تتكلّم، فشعرت براحة غريبة، كأن حجرًا رُفع عن صدرها.\n\nكانت القضية: «ينبغي أن تُدرَّس الرياضة مادةً أساسية لها درجات كالرياضيات». وقفت هند مؤيّدة، وانطلقت كعادتها. وكانت رنا تكتب: كل حجّة، وكل رقم، وكل مثال. وحين لا تفهم شيئًا، تضع بجانبه علامة استفهام صغيرة.\n\nبعد عشرين دقيقة، سألت الأستاذة نوال: «حسنًا. من لاحظت شيئًا في كلام هند؟»\n\nقالت شمّا إن هند تتكلّم بسرعة. وقالت هند إنها كانت مقنعة جدًا، وضحكت.\n\nثم التفتت المعلمة إلى رنا. «وأنتِ؟ لا تقومي. اقرئي من الدفتر فقط».\n\nخفضت رنا عينيها إلى الصفحة، وقرأت بصوت منخفض: «في الدقيقة الأولى، قالت هند إن الرياضة يجب أن تُقيَّم بالدرجات لكي تأخذها الطالبات بجدّية. وفي الدقيقة الرابعة، قالت إن الدرجات تسبّب ضغطًا يُفقد الطالبات متعة التعلّم. فإذا كانت الدرجات تقتل المتعة... فلماذا نضعها على المادة الوحيدة التي نستمتع بها؟»\n\nساد صمت. نظرت هند إلى رنا بفم مفتوح قليلًا. ثم ضحكت شمّا وصفّقت.\n\nابتسمت الأستاذة نوال، كأنها وجدت أخيرًا ما تبحث عنه. «هذا يا رنا نصف المناظرة. الصوت العالي يلفت الأسماع، لكن الإصغاء هو الذي يكسب الحكّام. أغلب المتناظرين لا يسمعون خصومهم، بل ينتظرون دورهم في الكلام».\n\nفي الأسابيع التالية، صار للفريق شكل جديد. كانت هند الصوت، وشمّا الحماسة، ورنا العقل الذي يعمل في الظلّ. كانت تقضي الفسحة في زاويتها في المكتبة كعادتها، لكنها الآن تقرأ الدراسات والمقالات، وتجمع الأرقام، وتكتب لكل قضية محتملة قائمة بالحجج وما يقابلها. وسألت جدّها، المعلّم المتقاعد، عن طلابه قبل أربعين سنة، فأعطاها أمثلة لم تجدها في أيّ كتاب، وكان يقول لها ضاحكًا: «في زماننا كنّا نحلّ الواجب على ضوء الفانوس، ولا يجرؤ أحد أن يقول إنه كثير».\n\nحتى هند تغيّرت. في البداية كانت تأخذ أوراق رنا دون تعليق. ثم صارت تسألها قبل كل تدريب: «ماذا وجدتِ؟»\n\nلكن رنا لم تقف ولم تتكلّم أمام أحد بعد. وكانت تعرف أن هذا لن يدوم طويلًا."}, {"title": "جدّتي لا تسمع الصراخ", "text": "في نصف النهائي، واجه الفريق مدرسة من ولاية مجاورة. جلست رنا على المنصة لأن القواعد تفرض ثلاث متحدّثات، لكن الأستاذة نوال رتّبت الأمر بحيث تتكلّم هند وشمّا، وتكتفي رنا بكلمة ترحيب قصيرة حفظتها عن ظهر قلب، قالتها وعيناها على الورقة.\n\nثم بدأت المعركة الحقيقية، فبدأ قلم رنا يجري. كلما قالت متحدّثة الخصم شيئًا متناقضًا، كتبت رنا ملاحظة سريعة على ورقة صغيرة، ودفعتها بهدوء نحو هند. وكانت هند تنظر إلى الورقة، ثم تقف، فتحوّل الملاحظة الصغيرة إلى هجوم كاسح.\n\nفاز الفريق بفارق واضح. وفي الحافلة، جلست هند بجانب رنا، وقالت دون أن تنظر إليها: «نصف ما قلته اليوم كان من أوراقك». كانت تلك أول مرة تشكرها.\n\nفي اليوم التالي، جمعتهنّ الأستاذة نوال وأعلنت: «النهائي بعد أسبوع، والقضية: ينبغي إلغاء الواجبات المنزلية. ونحن في جهة المعارضة». ثم التفتت إلى رنا. «وخطاب الردّ في النهائي لكِ».\n\n«أنا؟» قالت رنا، وشعرت بالدم يهرب من وجهها.\n\n«الردّ تقوله من أصغت إلى المناظرة كلها. ولا أحد في هذه المدرسة يُصغي مثلك».\n\nفي تلك الليلة، حاولت رنا أن تتدرّب أمام المرآة، فرأت فتاة شاحبة تتلعثم. حاولت أمام أمها، فأشفقت عليها أمها وقالت: «يكفي، ارتاحي». ثم دخلت غرفة جدّتها لتقول لها تصبحين على خير، فطلبت منها الجدّة أن تقرأ عليها ما تكتب.\n\nكانت جدّتها ثقيلة السمع منذ سنوات. بدأت رنا تقرأ بصوت مرتفع، فرفعت الجدّة يدها: «لا تصرخي يا بنتي، الصراخ يصلني ضجّة. تكلّمي ببطء، وانظري في وجهي، وأخرجي الحروف من مخارجها».\n\nفأبطأت رنا. نظرت في عيني جدّتها، ونطقت كل كلمة واضحة كاملة، بصوت عادي، وتوقّفت بين الجمل. وكانت الجدّة تهزّ رأسها، وتفهم كل شيء، وتسألها أسئلة ذكية.\n\nتدرّبت رنا هكذا سبع ليالٍ. لم تصبح أعلى صوتًا، لكنها صارت أوضح.\n\nوفي الليلة الأخيرة، قالت لها جدّتها: «الناس يا رنا لا يسمعون من يصرخ أكثر، بل يسمعون من يستحقّ أن يُسمع».\n\nنامت رنا تلك الليلة نومًا متقطّعًا، وحلمت بقاعة كبيرة كل مقاعدها فارغة إلا مقعدًا واحدًا."}, {"title": "ثلاث ثوانٍ من الصمت", "text": "كانت قاعة النهائي أكبر مما تخيّلت رنا. مئات المقاعد، ولجنة تحكيم من ثلاثة، وأضواء بيضاء تحرق العينين. وفي الصفّ الثاني، رأت أمها وأباها، وبينهما جدّتها بعباءتها السوداء، تلوّح لها بيد صغيرة.\n\nكان فريق الخصم قويًا جدًا. وقفت متحدّثتهم الأولى، وقالت إن الواجبات المنزلية تسرق وقت الطالبات وتسبّب لهن الضغط والتوتّر، واستشهدت بدراسة تقول إن الطالبات اللواتي يقضين أكثر من ثلاث ساعات يوميًا في الواجبات يعانين من قلّة النوم. ثم وقفت الثانية، وقالت إن الطالبة يجب أن تتعلّم أن تتعلّم وحدها، دون أن تُلقَّن كل شيء في الفصل.\n\nكانت رنا تكتب بلا توقّف. وقبل ثلاث دقائق من دورها، رسمت دائرة حول جملتين في دفترها، ثم أخرى حول رقم.\n\nتكلّمت هند ببراعة، وتكلّمت شمّا بحماسة. لكن الحكّام كانوا يدوّنون بوجوه لا تكشف شيئًا. وكانت النتيجة متعلّقة بخيط.\n\nثم نادى المقدّم: «خطاب الردّ لفريق المعارضة».\n\nوقفت رنا. مشت إلى المنبر. ونظرت إلى القاعة.\n\nثلاث ثوانٍ مرّت دون أن تقول شيئًا. سمعت همسًا في الصفوف الخلفية. ثم بحثت بعينيها عن الصفّ الثاني، فوجدت وجه جدّتها، وتذكّرت: ببطء، وانظري في الوجه، وأخرجي الحروف.\n\nوبدأت.\n\nلم يكن صوتها عاليًا. كان صوتًا عاديًا، هادئًا، واضحًا. ولاحظت شيئًا عجيبًا: القاعة كلها صمتت لتسمعها، والناس في الصفوف الخلفية مالوا إلى الأمام.\n\n«قالت زميلتنا إن الدراسة تتحدّث عن ثلاث ساعات يوميًا. وهذا صحيح. لكن هذا دليل على أن الواجبات الكثيرة مشكلة، لا على أن الواجبات كلها مشكلة. فهم يطلبون الإلغاء، ودليلهم لا يطلب إلا التقليل». ثم قلّبت الصفحة. «وقالت زميلتهنّ الثانية إن الطالبة يجب أن تتعلّم وحدها. ونحن نتّفق تمامًا. ولكن... أين تتعلّم الطالبة وحدها، إن لم يكن في واجبها؟»\n\nحين عادت إلى مقعدها، كانت يداها ترتجفان، وهند تضغط على كتفها.\n\nفاز الفريق بفارق نقطة واحدة. وقالت رئيسة اللجنة في كلمتها إن خطاب الردّ هو الذي حسم المناظرة.\n\nبعد شهور، علّقت الأستاذة نوال ورقة جديدة على اللوحة الخضراء: «التسجيل في فريق المناظرة للعام القادم».\n\nوكان أول اسم فيها مكتوبًا بخطّ صاحبته: رنا سالم."}], "vocab": [{"w": "تَتَلَعْثَم", "m": "تتردّد في الكلام وتتعثّر فيه من الخجل أو الخوف"}, {"w": "لاهِثَة", "m": "تتنفّس بسرعة وصعوبة من التعب أو الركض"}, {"w": "كاسِح", "m": "قويّ شامل يزيل ما أمامه"}, {"w": "مُتَنَاقِض", "m": "يقول الشيء وضدّه في الوقت نفسه"}, {"w": "ثَقِيلَة السَّمْع", "m": "ضعيفة السمع لا تسمع جيدًا"}, {"w": "مَخَارِجِهَا", "m": "مواضع خروج الحروف من الفم والحلق عند النطق"}, {"w": "تُلَقَّن", "m": "تُعطى المعلومة جاهزة لتحفظها دون جهد منها"}, {"w": "حَسَم", "m": "قطع الأمر وأنهاه بنتيجة واضحة"}], "quiz": [{"q": "كيف وُضع اسم رنا سالم في فريق المناظرة؟", "opts": ["كتبت المعلمة اسمها خطأً وهي تقصد رنا سعيد", "سجّلت شمّا اسمها دون علمها", "طلبت هي الانضمام سرًّا"], "a": 0, "explain": "اعترفت الأستاذة نوال بأنها كانت تقصد رنا سعيد من العاشر الأول، وكتبت الاسم على عجل."}, {"q": "لماذا طلبت الأستاذة نوال من رنا ألّا تتكلّم في التدريب الثاني؟", "opts": ["لأنها لا تريدها في الفريق", "لتكتشف قدرتها على الإصغاء وتسجيل حجج الأخريات", "لأن هند اشتكت منها"], "a": 1, "explain": "أعطتها الدفتر الأصفر لتكتب كل ما يُقال، فاكتشفت رنا تناقضًا في كلام هند، وقالت المعلمة: «هذا نصف المناظرة»."}, {"q": "ماذا علّمت الجدّة رنا حين تدرّبت أمامها؟", "opts": ["أن ترفع صوتها حتى يسمعها الجميع", "أن تحفظ الخطاب كلمة كلمة", "أن تتكلّم ببطء ووضوح وتنظر في الوجوه دون صراخ"], "a": 2, "explain": "قالت الجدّة: «لا تصرخي... تكلّمي ببطء، وانظري في وجهي، وأخرجي الحروف من مخارجها»."}, {"q": "ما الثغرة التي كشفتها رنا في دليل الفريق الخصم؟", "opts": ["أن الدراسة قديمة جدًا", "أن الدراسة تدلّ على مشكلة الواجبات الكثيرة لا على وجوب إلغائها كلها", "أن الدراسة لا تتحدّث عن الطالبات"], "a": 1, "explain": "قالت رنا: «هم يطلبون الإلغاء، ودليلهم لا يطلب إلا التقليل»."}], "discuss": ["قالت الأستاذة نوال إن أغلب المتناظرين «لا يسمعون خصومهم، بل ينتظرون دورهم في الكلام». هل يحدث هذا في نقاشاتنا اليومية؟ كيف يتغيّر الحوار حين نُصغي فعلًا؟", "لم تصبح رنا أعلى صوتًا، لكنها صارت أوضح. ما الفرق بين الثقة والصوت العالي؟ وهل تعرفين شخصًا هادئًا يُصغي إليه الجميع؟"]}, {"id": "n15", "title": "تحدّي الخمسين كتابًا", "genre": "صداقة", "blurb": "ضحكت تسنيم حين أعلنت صديقتها أنها ستقرأ خمسين كتابًا في سنة، ثم راهنتها وهي واثقة من الفوز. لكنها لم تحسب حساب كتاب قديم في صندوق منسيّ، تملأ هوامشَه كتابةُ يدٍ تعرفها جيدًا.", "values": ["حبّ القراءة", "فهم الوالدين", "التحرّر من الأحكام المسبقة على النفس"], "chapters": [{"title": "خمسون؟!", "text": "قالت تسنيم إن أحدًا لا يقرأ خمسين كتابًا في سنة، إلا إذا كان لا يملك هاتفًا ولا صديقات ولا حياة. قالتها بصوت عالٍ في مقصف المدرسة، فضحكت البنات حول الطاولة، وضحكت رحمة أيضًا، لكنها لم تُغلق دفترها.\n\nكان دفترًا صغيرًا بغلاف بنفسجي، كتبت رحمة في صفحته الأولى بخطّ مرتّب: «خمسون كتابًا — من يناير إلى ديسمبر». وتحت العنوان خمسون سطرًا مرقّمًا، لم يُملأ منها إلا السطر الأول: «ساعي بريد القمر — انتهيت منه في الثالث من يناير».\n\n«أربعة كتب في الشهر تقريبًا» قالت رحمة بهدوء. «كتاب كل أسبوع. ليس مستحيلًا».\n\n«ليس مستحيلًا؟» ضحكت تسنيم. «أنتِ لم تكملي مسلسلًا واحدًا في حياتك!»\n\n«لأن المسلسلات مملّة».\n\nتعالت ضحكات البنات من جديد، لكن هذه المرة لم تكن تسنيم هي التي أضحكتهن. شعرت بوخزة صغيرة، فقالت قبل أن تفكّر: «حسنًا. نتراهن».\n\nرفعت رحمة حاجبيها. «على ماذا؟»\n\n«إذا لم تكملي الخمسين قبل آخر يوم في السنة، تشترين لي كوب كرك كل يوم، شهرًا كاملًا».\n\n«وإذا أكملتها؟»\n\nتردّدت تسنيم لحظة. ثم قالت بثقة من يعرف أنه لن يخسر: «أقرأ أنا عشرة كتب».\n\n«وتكتبين عن كل كتاب جملة واحدة» أضافت رحمة، وفتحت دفترها على الصفحة الأخيرة، «هنا، في دفتري. بخطّ يدك».\n\nتصافحتا، والبنات شهود. وعادت تسنيم إلى فصلها وهي تبتسم، وتحسب في رأسها: ثلاثون كوب كرك بالزعفران من المقهى المجاور للمدرسة. يا له من شهر!\n\nلكن في المساء، وهي مستلقية على سريرها، تذكّرت شيئًا لم تخبر به أحدًا قط. في الصف السادس، أعادت إليها المعلمة اختبار القراءة وعليه درجة منخفضة، وقالت أمام الطالبات: «تسنيم ليست من النوع الذي يقرأ». قالتها بلا قسوة، كأنها تصف لون حجابها. ومنذ ذلك اليوم، صدّقت تسنيم الجملة، وصارت تقولها عن نفسها قبل أن يقولها أحد، وأحيانًا تقولها ضاحكة، كأنها نكتة.\n\nأطفأت النور، وقالت لنفسها: لا يهمّ. رحمة لن تكمل الخمسين.\n\nلكنها لم تستطع أن تنام بسرعة تلك الليلة."}, {"title": "الصندوق في المخزن", "text": "مرّ يناير، ثم فبراير، ثم مارس. وكانت رحمة تقرأ في كل مكان: في الحافلة، وفي طابور المقصف، وفي انتظار أمها عند باب المدرسة. وكلما التقت بها تسنيم، رفعت الدفتر البنفسجي في الهواء كأنها ترفع كأسًا، وقالت رقمًا جديدًا: «تسعة!»، «ستة عشر!»، «اثنان وعشرون!».\n\nفي يونيو، مع نهاية العام الدراسي، كان الرقم ثمانية وعشرين. جلست تسنيم تلك الليلة بآلة حاسبة، وحسبت مرة، ومرتين، وثلاثًا. لم يكن هناك شكّ: إذا استمرّت رحمة بهذه السرعة، فستكمل الخمسين قبل نوفمبر.\n\nقرّرت أن تبدأ مبكرًا، كي لا تُفضح في ديسمبر. استعارت من رحمة كتابًا قالت إنه «سهل جدًا»: «سبع ليالٍ في سوق الحافة». قرأت الصفحة الأولى، ثم الثانية، ثم نامت على الصفحة الثانية عشرة والكتاب على وجهها. وحين حاولت في اليوم التالي، وجدت أنها نسيت أسماء الشخصيات كلها، فأغلقته وأعادته.\n\n«قلت لك» قالت لنفسها. «لستُ من النوع الذي يقرأ».\n\nفي أغسطس، قبل العيد بأيام، طلبت منها أمها أن تُنزل من المخزن صندوق أواني الضيافة الكبيرة. كان المخزن غرفة صغيرة خانقة فوق السطح، تفوح منها رائحة الغبار والتمر القديم. وبينما كانت تزيح الصناديق، سقط صندوق كرتوني صغير من الرفّ العلوي، وانفتح على الأرض.\n\nكتب. نحو عشرين كتابًا قديمًا، أغلفتها باهتة، وأطرافها منتفخة من الرطوبة.\n\nالتقطت تسنيم أقربها إليها. كان غلافه أخضر متشقّقًا، وعليه بخطّ ذهبيّ باهت: «كليلة ودمنة». سمعت باسمه في درس العربية، كتاب قديم جدًا فيه حكايات على ألسنة الحيوانات.\n\nفتحت الغلاف، فوجدت على الصفحة الأولى بقلم أزرق، بخطّ بنت مراهقة مستدير وواثق: «هذا الكتاب ملك مريم. عمري خمس عشرة سنة، وسأقرؤه للمرة الثالثة».\n\nمريم. اسم أمها.\n\nقلّبت تسنيم الصفحات، فتوقّف قلبها لحظة. لم تكن هناك صفحة واحدة بلا كتابة. الهوامش كلها مملوءة بالقلم الأزرق: تعليقات، وأسئلة، ورسوم صغيرة، وأسهم، وعلامات تعجّب.\n\nأمها، التي لم ترها تمسك كتابًا قط، كانت تتحدّث مع هذا الكتاب طوال صفحاته.\n\nأخفت تسنيم الكتاب تحت قميصها، ونزلت بصندوق الأواني، كأنها تحمل سرًّا مسروقًا."}, {"title": "امرأة في الهوامش", "text": "قرأت تسنيم «كليلة ودمنة» في أربع ليالٍ. لم يحدث ذلك لأن الحكايات سهلة؛ كانت لغتها قديمة، وجملها طويلة، وفيها كلمات اضطرّت إلى البحث عن معانيها. لكنها لم تكن تقرأ الكتاب وحده. كانت تقرأ أمها.\n\nفي باب الأسد والثور، حيث يحيك دمنة مكائده ليفرّق بين صديقين، كتبت أمها في الهامش: «دمنة يذكّرني ببعض بنات فصلنا! يبتسم في وجهك ويحفر لك في الخفاء». وتحتها رسم صغير لوجه مبتسم بأنياب. ضحكت تسنيم بصوت عالٍ في منتصف الليل، ثم وضعت يدها على فمها.\n\nوفي باب القرد والغيلم، كتبت: «القرد أذكى، لكن الغيلم أطيب. أيّهما أريد أن أكون؟ ربما نحتاج إلى الاثنين: قلب الغيلم وعقل القرد».\n\nوفي باب الحمامة المطوّقة، حيث تقع الحمامات في شبكة الصيّاد فيأتي الجرذ ويقرض الشبكة ليحرّرها، كتبت بخطّ أصغر: «جميل أن يكون لك صديق يقرض شبكتك. لكن ماذا لو كانت الشبكة لا يراها أحد غيرك؟»\n\nتوقّفت تسنيم عند هذه الجملة طويلًا، ولم تفهمها تمامًا.\n\nوكانت هناك تعليقات أخرى كثيرة. أسئلة لا تعرف تسنيم إجاباتها، وأمثال شعبية تقارن بها حكايات الكتاب، وفي الهامش الأسفل لإحدى الصفحات جملة مكتوبة بخطّ عريض وتحتها خطّان: «الكتاب لا يسأل القارئ عن درجاته».\n\nقرأت تسنيم الجملة ثلاث مرات. ثم أغمضت عينيها، ورأت المعلمة في الصف السادس، والورقة ذات الدرجة المنخفضة.\n\nوعلى الصفحة الأخيرة من الكتاب، بعد أن انتهت الحكايات كلها، وجدت تسنيم فقرة كاملة بخطّ أمها:\n\n«حين أصبح معلّمة للغة العربية، سأقرأ هذا الكتاب مع طالباتي، فصلًا بعد فصل. وسأسألهنّ في آخر كل حكاية: من منكنّ دمنة؟ ومن منكنّ الجرذ؟ وسأجعلهنّ يكتبن في الهوامش، لأن الكتاب الذي لا نكتب فيه، لا يكتب فينا».\n\nأغلقت تسنيم الكتاب ببطء.\n\nأمها لم تصبح معلّمة. أمها تعمل في البيت، تخيط ثياب بنات الحيّ بماكينة قديمة في الغرفة المجاورة للمطبخ، وتطبخ، وترتّب، وتتابع الواجبات. لم تسمعها تسنيم يومًا تتحدّث عن كتاب، أو عن حلم، أو عن شيء تريده لنفسها.\n\nماذا حدث لمريم ذات الخمسة عشر عامًا، صاحبة القلم الأزرق؟\n\nفي الصباح، حملت تسنيم الكتاب، ونزلت إلى المطبخ."}, {"title": "الشبكة", "text": "كانت أمها واقفة أمام الصاج، تفرد عجينة الخبز الرخال بكفّها في دوائر رقيقة كالورق، ورائحة الخبز الساخن تملأ المطبخ. وضعت تسنيم الكتاب على الطاولة دون كلمة.\n\nالتفتت الأم، ورأت الغلاف الأخضر، فتوقّفت يدها في الهواء. ثم أطفأت النار بهدوء، ومسحت يديها بطرف ثوبها، وجلست.\n\n«من أين جئتِ به؟»\n\n«من صندوق في المخزن. قرأته يا أمي. قرأته كله... وقرأت ما كتبتِ».\n\nلمست الأم الغلاف بأطراف أصابعها كأنها تلمس وجه صديقة قديمة. ثم ابتسمت ابتسامة متعبة. «كنت أظنّ أنني رميت هذه الكتب منذ زمن».\n\n«لماذا لم تصبحي معلّمة؟»\n\nصمتت الأم طويلًا. ثم حكت.\n\nكانت الأولى على مدرستها في الثانوية، وكانت قد قُبلت في الجامعة لتدرس اللغة العربية. لكن في ذلك الصيف مرضت جدّة تسنيم مرضًا طويلًا، وكان إخوة مريم الصغار خمسة، فبقيت في البيت ترعى أمها وإخوتها. «قلت: سنة واحدة فقط، ثم أعود». لكن السنة صارت سنتين، ثم ثلاثًا، ثم تزوّجت وجاءت تسنيم.\n\n«وتوقّفتِ عن القراءة أيضًا؟»\n\n«قالت لي قريبة لنا مرة، وهي ترى كتابًا في يدي: ما فائدة القراءة لامرأة لن تكمل دراستها؟ فوضعت الكتاب، ولم أرفعه بعدها. صرت أقول لنفسي: أنا لست من النوع الذي يكمل».\n\nارتجفت تسنيم. «لست من النوع الذي...» الجملة نفسها تقريبًا. الجملة التي تسكن رأسها منذ الصف السادس.\n\nوهنا فهمت أخيرًا هامش الحمامة المطوّقة: الشبكة التي لا يراها أحد غيرك. لم تكن شبكة أمها بيتًا ولا مرضًا ولا مسؤوليات، فهذه كانت تحتملها راضية. كانت الشبكة جملة صغيرة صدّقتها عن نفسها.\n\nأخبرت تسنيم أمها عن معلمة الصف السادس، وعن الرهان، وعن الكتاب الذي نامت عليه في الصفحة الثانية عشرة. ثم فتحت «كليلة ودمنة» على الهامش ذي الخطّين، ووضعت إصبعها تحته: «الكتاب لا يسأل القارئ عن درجاته».\n\n«أنتِ كتبتِ هذا يا أمي. وأنا أحتاجه. وأظنّ أنك تحتاجينه أيضًا».\n\nضحكت الأم، وفي عينيها دموع. «أتريدين أن تكوني الجرذ يا تسنيم؟»\n\n«أريد أن نقرض الشبكة معًا».\n\nفي تلك الليلة، حين قامت تسنيم لتشرب ماء بعد منتصف الليل، رأت ضوءًا خافتًا تحت باب غرفة الخياطة. اقتربت ونظرت. كانت أمها جالسة إلى ماكينتها المطفأة، وفي يدها كتاب آخر من الصندوق، وقلم أزرق."}, {"title": "الكتاب الخمسون", "text": "في سبتمبر، عادت تسنيم إلى المدرسة بحقيبة أثقل من المعتاد. كان فيها، إلى جانب الكتب المدرسية، كتاب من صندوق أمها، وقلم رصاص للهوامش.\n\nلم تصبح قارئة سريعة. كانت تقرأ ببطء، وتعيد بعض الصفحات، وتتوقّف لتكتب في الهوامش أسئلة وتعليقات ورسومًا صغيرة، كما علّمتها مريم ذات الخمسة عشر عامًا. واكتشفت أن الكتاب يصير أسهل حين تتحدّث معه، وأن الشخصيات لا تُنسى حين تكتب عنها شيئًا.\n\nوكانت تتبادل الكتب مع أمها. تقرأ الأم كتابًا وتكتب فيه بالأزرق، ثم تقرؤه تسنيم وتردّ على أمها بالرصاص في الهامش نفسه. وصارت الكتب رسائل بينهما، تتجادلان فيها وتضحكان، وتكتشف كلٌّ منهما في الأخرى شخصًا لم تعرفه من قبل.\n\nوفي أكتوبر، فتحت الأم حاسوب تسنيم، وسألتها بتردّد كيف تبحث عن برامج الدراسة المسائية في الجامعة. ثم ملأت الاستمارة بيد مرتجفة، كما قالت هي ضاحكة، «كطالبة في أول يوم».\n\nفي الحادي والثلاثين من ديسمبر، اجتمعت البنات في بيت رحمة. كان الدفتر البنفسجي مفتوحًا على الطاولة، وفيه تسعة وأربعون سطرًا مملوءًا.\n\n«بقي كتاب واحد» قالت رحمة. «وأريد أن يكون الخمسون كتابًا مختلفًا».\n\nأخرجت تسنيم من حقيبتها كتابًا بغلاف أخضر متشقّق، ووضعته أمام صديقتها. «هذا. لكن بشرط: أن تكتبي في هوامشه أنتِ أيضًا. هناك مكان بعد أمي وبعدي».\n\nقلّبت رحمة الصفحات المملوءة بالأزرق والرصاص، وفتحت عينيها دهشة. «هذا ليس كتابًا. هذا بيت يسكنه ناس».\n\nثم فتحت تسنيم الدفتر البنفسجي على الصفحة الأخيرة، حيث الأسطر المخصّصة للرهان. كانت قد كتبت فيها حتى ذلك اليوم ثلاث عشرة جملة، عن ثلاثة عشر كتابًا. أكثر من العشرة التي خسرتها.\n\nوفي السطر الأخير، كتبت جملة أخيرة:\n\n«لم أخسر الرهان يا رحمة. خسرتُ جملة قديمة كانت تسكن رأسي، وربحتُ أمّي».\n\nبعد أسبوعين، وصلت رسالة من الجامعة. قرأتها الأم في المطبخ، ثم جلست، ثم قامت، ثم جلست مرة أخرى، ثم ضحكت. «قُبلت. البرنامج المسائي. اللغة العربية».\n\nفي تلك الليلة، فتحت تسنيم «كليلة ودمنة» على الصفحة الأخيرة، تحت فقرة أمها القديمة، وكتبت بقلم الرصاص:\n\n«أمّي، حين تصبحين معلّمة، أريد أن أكون أول طالبة في فصلك. وأعدك أن أكتب في الهوامش»."}], "vocab": [{"w": "وَخْزَة", "m": "إحساس مؤلم خفيف كالطعنة الصغيرة"}, {"w": "هَوَامِش", "m": "المساحات الفارغة على أطراف الصفحة، مفردها هامش"}, {"w": "مَكَائِد", "m": "خطط خفيّة يُدبَّر بها الإيقاع بالآخرين، مفردها مكيدة"}, {"w": "الغَيْلَم", "m": "ذكر السلحفاة، وهو بطل إحدى حكايات كليلة ودمنة مع القرد"}, {"w": "يَقْرِض", "m": "يقطع الشيء بأسنانه شيئًا فشيئًا"}, {"w": "الصَّاج", "m": "صفيحة حديدية مستديرة يُخبز عليها الخبز الرقيق"}, {"w": "الرُّخَال", "m": "خبز عُماني رقيق جدًا يُخبز على الصاج"}, {"w": "اسْتِمَارَة", "m": "ورقة أو نموذج يُملأ بالبيانات لطلب شيء"}], "quiz": [{"q": "ما الذي تلتزم به تسنيم إن أكملت رحمة الخمسين كتابًا؟", "opts": ["أن تشتري لرحمة كوب كرك يوميًا", "أن تقرأ عشرة كتب وتكتب عن كل واحد جملة في دفتر رحمة", "أن تقرأ خمسين كتابًا في السنة التالية"], "a": 1, "explain": "قالت تسنيم: «أقرأ أنا عشرة كتب»، وأضافت رحمة أن تكتب عن كل كتاب جملة في دفترها."}, {"q": "ما الجملة التي ظلّت تسنيم تصدّقها عن نفسها منذ الصف السادس؟", "opts": ["«تسنيم ليست من النوع الذي يقرأ»", "«تسنيم لا تحبّ المدرسة»", "«تسنيم لا تكمل ما تبدؤه»"], "a": 0, "explain": "قالت المعلمة أمام الطالبات: «تسنيم ليست من النوع الذي يقرأ»، فصدّقتها وصارت تكرّرها."}, {"q": "ما المقصود بـ«الشبكة التي لا يراها أحد» كما فهمتها تسنيم؟", "opts": ["مرض الجدّة الطويل", "مسؤوليات البيت والخياطة", "حكم صغير صدّقته الأم عن نفسها فأوقفها"], "a": 2, "explain": "أدركت تسنيم أن شبكة أمها كانت «جملة صغيرة صدّقتها عن نفسها»: «أنا لست من النوع الذي يكمل»."}, {"q": "ما الكتاب الذي صار الخمسين في قائمة رحمة؟", "opts": ["«كليلة ودمنة» بهوامش الأم وتسنيم", "«ساعي بريد القمر»", "«سبع ليالٍ في سوق الحافة»"], "a": 0, "explain": "قدّمت لها تسنيم النسخة الخضراء من «كليلة ودمنة» بشرط أن تكتب في هوامشها أيضًا."}], "discuss": ["كتبت الأم في شبابها: «الكتاب الذي لا نكتب فيه، لا يكتب فينا». ماذا تعني هذه الجملة في رأيك؟ وهل جرّبتِ أن تحاوري كتابًا بالكتابة في هوامشه أو في دفتر جانبي؟", "جملة واحدة قالتها معلمة، وجملة قالتها قريبة، غيّرتا حياة شخصيتين في الرواية. هل هناك جملة سمعتِها عن نفسك وصدّقتِها؟ وكيف يمكن أن «نقرض» مثل هذه الشبكة؟"]}];
